import type { BankQuestion } from "@/lib/bank";

/** Computer Awareness (Computer Awareness): 500 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"comp-awareness-1","question":"Which part is called the brain of the computer?","options":["RAM","Hard disk","CPU","Monitor"],"answer":2,"explanation":"The CPU (Central Processing Unit) processes all instructions.","difficulty":"easy","questionHi":"कंप्यूटर का मस्तिष्क किस भाग को कहा जाता है?","optionsHi":["RAM","हार्ड डिस्क","CPU","मॉनीटर"],"explanationHi":"CPU (केंद्रीय प्रसंस्करण इकाई) सभी निर्देशों को प्रोसेस करती है।"},
  {"id":"comp-awareness-2","question":"1 byte is equal to:","options":["4 bits","8 bits","16 bits","1024 bits"],"answer":1,"explanation":"A byte is a group of 8 bits, enough to store one ASCII character. 4 bits is a nibble, and 1024 confuses the byte with the kilo prefix (1 KB = 1024 bytes).","difficulty":"easy","questionHi":"1 बाइट बराबर होता है:","optionsHi":["4 बिट","8 बिट","16 बिट","1024 बिट"],"explanationHi":"एक बाइट 8 बिट का समूह होता है, जो एक ASCII अक्षर संग्रहीत करने के लिए पर्याप्त है। 4 बिट को निबल कहते हैं, और 1024 भ्रम पैदा करता है क्योंकि वह किलो उपसर्ग (1 KB = 1024 बाइट) से जुड़ा है।"},
  {"id":"comp-awareness-3","question":"Which of the following is an input device?","options":["Monitor","Printer","Keyboard","Speaker"],"answer":2,"explanation":"A keyboard sends data into the computer; the others are output devices.","difficulty":"easy","questionHi":"निम्नलिखित में से कौन-सा इनपुट डिवाइस है?","optionsHi":["मॉनीटर","प्रिंटर","कीबोर्ड","स्पीकर"],"explanationHi":"कीबोर्ड कंप्यूटर में डेटा भेजता है; शेष आउटपुट डिवाइस हैं।"},
  {"id":"comp-awareness-4","question":"Which type of memory is volatile?","options":["ROM","RAM","Hard disk","Flash drive"],"answer":1,"explanation":"RAM is volatile: it needs continuous power and loses its contents when the computer is switched off. ROM, hard disks and flash drives are non-volatile and keep data without power.","difficulty":"moderate","questionHi":"किस प्रकार की मेमोरी वाष्पशील (वोलेटाइल) होती है?","optionsHi":["ROM","RAM","हार्ड डिस्क","फ्लैश ड्राइव"],"explanationHi":"RAM वाष्पशील है: इसे लगातार बिजली चाहिए और कंप्यूटर बंद करते ही इसकी सामग्री मिट जाती है। ROM, हार्ड डिस्क और फ्लैश ड्राइव अवाष्पशील हैं और बिना बिजली के भी डेटा रखते हैं।"},
  {"id":"comp-awareness-5","question":"HTTP stands for:","options":["HyperText Transfer Protocol","High Transfer Text Protocol","HyperText Transmission Process","Hyper Transfer Text Program"],"answer":0,"explanation":"HTTP is the HyperText Transfer Protocol, the rule set browsers and web servers use to exchange web pages. The traps swap Transfer with Transmission or Protocol with Process/Program, so check each word.","difficulty":"moderate","questionHi":"HTTP का पूर्ण रूप है:","optionsHi":["HyperText Transfer Protocol","High Transfer Text Protocol","HyperText Transmission Process","Hyper Transfer Text Program"],"explanationHi":"HTTP हाइपरटेक्स्ट ट्रांसफर प्रोटोकॉल है, यानी वह नियम-समूह जिससे ब्राउज़र और वेब सर्वर वेब पेज का आदान-प्रदान करते हैं। गलत विकल्पों में Transfer की जगह Transmission या Protocol की जगह Process/Program रख दिया गया है, इसलिए हर शब्द जाँचें।"},
  {"id":"comp-awareness-6","question":"Which shortcut copies selected text in most programs?","options":["Ctrl + V","Ctrl + C","Ctrl + X","Ctrl + P"],"answer":1,"explanation":"Ctrl + C copies the selection to the clipboard without removing it. Ctrl + X cuts (removes and copies), Ctrl + V pastes, and Ctrl + P opens the print dialog.","difficulty":"moderate","questionHi":"अधिकांश प्रोग्रामों में चयनित पाठ को कॉपी करने का शॉर्टकट कौन-सा है?","optionsHi":["Ctrl + V","Ctrl + C","Ctrl + X","Ctrl + P"],"explanationHi":"Ctrl + C चयन को हटाए बिना क्लिपबोर्ड पर कॉपी करता है। Ctrl + X कट करता है (हटाकर कॉपी करता है), Ctrl + V पेस्ट करता है और Ctrl + P प्रिंट डायलॉग खोलता है।"},
  {"id":"comp-awareness-7","question":"1 kilobyte (KB) equals:","options":["1000 bits","1024 bytes","1024 bits","8 bytes"],"answer":1,"explanation":"In binary computing 1 KB = 2¹⁰ = 1024 bytes. 1024 bits is a kilobit (Kb), the usual trap, and 1000 is the decimal (SI) kilo used by disk makers, not bits.","difficulty":"hard","questionHi":"1 किलोबाइट (KB) बराबर होता है:","optionsHi":["1000 बिट","1024 बाइट","1024 बिट","8 बाइट"],"explanationHi":"बाइनरी कंप्यूटिंग में 1 KB = 2¹⁰ = 1024 बाइट होता है। 1024 बिट किलोबिट (Kb) है, जो सामान्य जाल है, और 1000 दशमलव (SI) किलो है जिसे डिस्क निर्माता प्रयोग करते हैं, वह बिट के लिए नहीं है।"},
  {"id":"comp-awareness-8","question":"Which of these is an operating system?","options":["MS Word","Linux","Google Chrome","Oracle"],"answer":1,"explanation":"Linux is an operating system; the others are application software.","difficulty":"hard","questionHi":"इनमें से कौन-सा एक ऑपरेटिंग सिस्टम है?","optionsHi":["MS Word","Linux","Google Chrome","Oracle"],"explanationHi":"Linux एक ऑपरेटिंग सिस्टम है; शेष एप्लिकेशन सॉफ्टवेयर हैं।"},
  {"id":"comp-awareness-9","question":"Which memory is the fastest?","options":["Hard disk","RAM","Cache","ROM"],"answer":2,"explanation":"Cache memory sits closest to the CPU and is faster than RAM.","difficulty":"hard","questionHi":"कौन-सी मेमोरी सबसे तेज़ होती है?","optionsHi":["हार्ड डिस्क","RAM","कैश","ROM"],"explanationHi":"कैश मेमोरी CPU के सबसे निकट होती है और RAM से भी तेज़ होती है।"},
  {"id":"comp-awareness-10","question":"The binary equivalent of the decimal number 10 is:","options":["1001","1010","1100","1011"],"answer":1,"explanation":"Divide by 2 repeatedly or use place values: 10 = 8 + 2 = 1×2³ + 0×2² + 1×2¹ + 0×2⁰ = 1010. 1001 is 9 and 1011 is 11, the off-by-one traps.","difficulty":"very-hard","questionHi":"दशमलव संख्या 10 का बाइनरी समतुल्य है:","optionsHi":["1001","1010","1100","1011"],"explanationHi":"बार-बार 2 से भाग दें या स्थानीय मान लें: 10 = 8 + 2 = 1×2³ + 0×2² + 1×2¹ + 0×2⁰ = 1010। 1001 का मान 9 और 1011 का मान 11 है, जो एक कम या एक अधिक वाले जाल हैं।"},
  {"id":"comp-awareness-11","question":"Which protocol is used to send email?","options":["HTTP","FTP","SMTP","POP3"],"answer":2,"explanation":"SMTP (Simple Mail Transfer Protocol) sends mail; POP3 and IMAP retrieve it.","difficulty":"very-hard","questionHi":"ईमेल भेजने के लिए कौन-सा प्रोटोकॉल प्रयोग किया जाता है?","optionsHi":["HTTP","FTP","SMTP","POP3"],"explanationHi":"SMTP (सिंपल मेल ट्रांसफर प्रोटोकॉल) मेल भेजता है; POP3 और IMAP उसे प्राप्त करने के लिए प्रयोग होते हैं।"},
  {"id":"comp-awareness-12","question":"Which number system uses base 16?","options":["Binary","Octal","Decimal","Hexadecimal"],"answer":3,"explanation":"Hexadecimal is base 16, using 0–9 and A–F (A = 10 … F = 15). Binary is base 2, octal base 8 and decimal base 10.","difficulty":"very-hard","questionHi":"कौन-सी संख्या पद्धति आधार 16 का प्रयोग करती है?","optionsHi":["बाइनरी","ऑक्टल","दशमलव","हेक्साडेसिमल"],"explanationHi":"हेक्साडेसिमल का आधार 16 है और यह 0–9 तथा A–F (A = 10 … F = 15) का प्रयोग करता है। बाइनरी का आधार 2, ऑक्टल का 8 और दशमलव का 10 है।"},
  {"id":"comp-awareness-13","question":"The “brain” of the computer is the:","options":["RAM","CPU","Hard disk","Monitor"],"answer":1,"explanation":"The CPU (Central Processing Unit) fetches, decodes and executes instructions, so it is called the brain of the computer. RAM is working memory that only holds data for the CPU.","difficulty":"easy","source":"IBPS Clerk · RRB NTPC","questionHi":"कंप्यूटर का “मस्तिष्क” कहलाता है:","optionsHi":["RAM","CPU","हार्ड डिस्क","मॉनीटर"],"explanationHi":"CPU (केंद्रीय प्रसंस्करण इकाई) निर्देशों को लाती, डिकोड करती और निष्पादित करती है, इसलिए इसे कंप्यूटर का मस्तिष्क कहते हैं। RAM कार्यकारी मेमोरी है जो केवल CPU के लिए डेटा रखती है।"},
  {"id":"comp-awareness-14","question":"Which of these is an output device?","options":["Keyboard","Mouse","Printer","Scanner"],"answer":2,"explanation":"A printer outputs; keyboard, mouse and scanner are input devices.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"इनमें से कौन-सा आउटपुट डिवाइस है?","optionsHi":["कीबोर्ड","माउस","प्रिंटर","स्कैनर"],"explanationHi":"प्रिंटर आउटपुट देता है; कीबोर्ड, माउस और स्कैनर इनपुट डिवाइस हैं।"},
  {"id":"comp-awareness-15","question":"1 gigabyte (GB) equals:","options":["1,024 KB","1,024 MB","1,024 TB","1,000 bytes"],"answer":1,"explanation":"Each unit is 1,024 times the previous one: KB → MB → GB → TB, so 1 GB = 1,024 MB. 1,024 KB is only 1 MB, and 1,024 GB (not TB) make 1 TB.","difficulty":"moderate","source":"IBPS PO · SBI Clerk","questionHi":"1 गीगाबाइट (GB) बराबर होता है:","optionsHi":["1,024 KB","1,024 MB","1,024 TB","1,000 बाइट"],"explanationHi":"प्रत्येक इकाई पिछली इकाई की 1,024 गुनी होती है: KB → MB → GB → TB, इसलिए 1 GB = 1,024 MB। 1,024 KB केवल 1 MB के बराबर है, और 1 TB में 1,024 GB (TB नहीं) होते हैं।"},
  {"id":"comp-awareness-16","question":"In MS Excel, the shortcut key to save a workbook is:","options":["Ctrl + P","Ctrl + S","Ctrl + V","Ctrl + N"],"answer":1,"explanation":"Ctrl + S saves the workbook (F12 opens Save As). Ctrl + P prints, Ctrl + V pastes and Ctrl + N opens a new blank workbook.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"MS Excel में वर्कबुक सेव करने की शॉर्टकट कुंजी है:","optionsHi":["Ctrl + P","Ctrl + S","Ctrl + V","Ctrl + N"],"explanationHi":"Ctrl + S वर्कबुक सेव करता है (F12 से Save As खुलता है)। Ctrl + P प्रिंट करता है, Ctrl + V पेस्ट करता है और Ctrl + N नई खाली वर्कबुक खोलता है।"},
  {"id":"comp-awareness-17","question":"Which memory is volatile, losing its contents when power is switched off?","options":["ROM","RAM","Hard disk","Flash drive"],"answer":1,"explanation":"RAM is volatile because its cells need continuous power to hold charge, so its contents vanish when the computer is switched off. ROM, hard disks and flash drives are non-volatile storage.","difficulty":"hard","source":"IBPS PO · SSC CHSL","questionHi":"कौन-सी मेमोरी वाष्पशील है, जिसकी सामग्री बिजली बंद होने पर मिट जाती है?","optionsHi":["ROM","RAM","हार्ड डिस्क","फ्लैश ड्राइव"],"explanationHi":"RAM वाष्पशील है क्योंकि इसके सेल को आवेश बनाए रखने के लिए लगातार बिजली चाहिए, इसलिए कंप्यूटर बंद करने पर इसकी सामग्री मिट जाती है। ROM, हार्ड डिस्क और फ्लैश ड्राइव अवाष्पशील संग्रहण हैं।"},
  {"id":"comp-awareness-18","question":"The protocol used to send e-mail from a client to a mail server is:","options":["HTTP","FTP","SMTP","POP3"],"answer":2,"explanation":"SMTP (Simple Mail Transfer Protocol) pushes mail from the client to the server and between servers. POP3 and IMAP are used to retrieve mail, so POP3 is the tempting but wrong choice.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"क्लाइंट से मेल सर्वर तक ई-मेल भेजने के लिए प्रयोग किया जाने वाला प्रोटोकॉल है:","optionsHi":["HTTP","FTP","SMTP","POP3"],"explanationHi":"SMTP (सिंपल मेल ट्रांसफर प्रोटोकॉल) मेल को क्लाइंट से सर्वर तक और सर्वरों के बीच भेजता है। POP3 और IMAP मेल प्राप्त करने के लिए हैं, इसलिए POP3 आकर्षक किंतु गलत विकल्प है।"},
  {"id":"comp-awareness-19","question":"Which of these is NOT an operating system?","options":["Linux","Windows","Oracle Database","macOS"],"answer":2,"explanation":"Oracle Database is a relational database management system that runs on top of an operating system. Linux, Windows and macOS are operating systems that manage hardware and run applications.","difficulty":"hard","questionHi":"इनमें से कौन-सा ऑपरेटिंग सिस्टम नहीं है?","optionsHi":["Linux","Windows","Oracle Database","macOS"],"explanationHi":"Oracle Database एक रिलेशनल डेटाबेस प्रबंधन प्रणाली है जो ऑपरेटिंग सिस्टम के ऊपर चलती है। Linux, Windows और macOS ऑपरेटिंग सिस्टम हैं जो हार्डवेयर का प्रबंधन करते और एप्लिकेशन चलाते हैं।"},
  {"id":"comp-awareness-20","question":"The hexadecimal number 1F equals which decimal number?","options":["15","31","30","16"],"answer":1,"explanation":"Each hex place is a power of 16: 1F = 1 × 16 + F(15) × 1 = 31. Reading F as 14 gives 30, and taking only the F digit gives 15.","difficulty":"hard","questionHi":"हेक्साडेसिमल संख्या 1F किस दशमलव संख्या के बराबर है?","optionsHi":["15","31","30","16"],"explanationHi":"हर हेक्स स्थान 16 की घात है: 1F = 1 × 16 + F(15) × 1 = 31। F को 14 मानने पर 30 आता है, और केवल F अंक लेने पर 15।"},
  {"id":"comp-awareness-21","question":"Which layer of the OSI model handles routing of packets between networks?","options":["Data link","Network","Transport","Session"],"answer":1,"explanation":"The network layer (layer 3) routes packets using IP addresses.","difficulty":"very-hard","questionHi":"OSI मॉडल की कौन-सी परत नेटवर्कों के बीच पैकेटों की रूटिंग संभालती है?","optionsHi":["डेटा लिंक","नेटवर्क","ट्रांसपोर्ट","सेशन"],"explanationHi":"नेटवर्क परत (परत 3) IP पतों का प्रयोग करके पैकेटों को रूट करती है।"},
  {"id":"comp-awareness-22","question":"Which order lists memory from fastest to slowest?","options":["Registers, cache, RAM, hard disk","Cache, registers, RAM, hard disk","RAM, cache, registers, hard disk","Registers, RAM, cache, hard disk"],"answer":0,"explanation":"Registers sit inside the CPU, then cache, then main memory, then storage.","difficulty":"very-hard","questionHi":"कौन-सा क्रम मेमोरी को सबसे तेज़ से सबसे धीमी की ओर सही दर्शाता है?","optionsHi":["रजिस्टर, कैश, RAM, हार्ड डिस्क","कैश, रजिस्टर, RAM, हार्ड डिस्क","RAM, कैश, रजिस्टर, हार्ड डिस्क","रजिस्टर, RAM, कैश, हार्ड डिस्क"],"explanationHi":"रजिस्टर CPU के भीतर होते हैं, फिर कैश, फिर मुख्य मेमोरी और उसके बाद संग्रहण।"},
  {"id":"comp-awareness-23","question":"How many of these statements are correct? I. One byte is eight bits. II. A nibble is four bits. III. ROM is non-volatile memory. IV. Cache memory sits between the CPU and the main memory.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: a byte is eight bits, a nibble four, ROM keeps its contents without power, and cache memory sits between the CPU and main memory.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. एक बाइट आठ बिट का होता है। II. एक निबल चार बिट का होता है। III. ROM अवाष्पशील मेमोरी है। IV. कैश मेमोरी CPU और मुख्य मेमोरी के बीच स्थित होती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चारों कथन सही हैं: एक बाइट आठ बिट का, एक निबल चार बिट का होता है, ROM बिना बिजली के भी सामग्री रखती है, और कैश मेमोरी CPU तथा मुख्य मेमोरी के बीच होती है।"},
  {"id":"comp-awareness-24","question":"How many of these statements are correct? I. HTTP uses port 80 by default. II. HTTPS uses port 443 by default. III. FTP is the protocol used to send e-mail.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. E-mail is sent with SMTP; FTP transfers files.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. HTTP डिफ़ॉल्ट रूप से पोर्ट 80 का प्रयोग करता है। II. HTTPS डिफ़ॉल्ट रूप से पोर्ट 443 का प्रयोग करता है। III. FTP वह प्रोटोकॉल है जिससे ई-मेल भेजा जाता है।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"केवल I और II सही हैं। ई-मेल SMTP से भेजा जाता है; FTP फ़ाइलें स्थानांतरित करता है।"},
  {"id":"comp-awareness-25","question":"How many of these statements are correct? I. RAM is volatile memory. II. Cache memory is faster than RAM. III. ROM loses its contents when the power is switched off.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. ROM is non-volatile and keeps its contents without power.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. RAM वाष्पशील मेमोरी है। II. कैश मेमोरी RAM से तेज़ होती है। III. बिजली बंद होने पर ROM अपनी सामग्री खो देती है।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"केवल I और II सही हैं। ROM अवाष्पशील है और बिना बिजली के भी अपनी सामग्री रखती है।"},
  {"id":"comp-awareness-26","question":"What is the binary number 101101 in decimal?","options":["45","43","47","53"],"answer":0,"explanation":"Place values from the left are 32, 16, 8, 4, 2, 1: 32 + 8 + 4 + 1 = 45. Using the 2s place instead of the 4s gives 43, counting the 2s place as well gives 47, and 53 (110101) comes from swapping two bits.","difficulty":"very-hard","questionHi":"बाइनरी संख्या 101101 का दशमलव मान क्या है?","optionsHi":["45","43","47","53"],"explanationHi":"बाईं ओर से स्थानीय मान 32, 16, 8, 4, 2, 1 हैं: 32 + 8 + 4 + 1 = 45। 4 के स्थान की जगह 2 का स्थान लेने पर 43 आता है, 2 का स्थान भी जोड़ने पर 47, और 53 (110101) दो बिटों की अदला-बदली से बनता है।"},
  {"id":"comp-awareness-27","question":"Which layer of the OSI model routes packets between networks?","options":["Network layer","Transport layer","Data link layer","Session layer"],"answer":0,"explanation":"The network layer (layer 3) handles logical addressing and routing; IP works here.","difficulty":"very-hard","questionHi":"OSI मॉडल की कौन-सी परत नेटवर्कों के बीच पैकेटों को रूट करती है?","optionsHi":["नेटवर्क परत","ट्रांसपोर्ट परत","डेटा लिंक परत","सेशन परत"],"explanationHi":"नेटवर्क परत (परत 3) तार्किक पता-निर्धारण और रूटिंग संभालती है; IP इसी परत पर काम करता है।"},
  {"id":"comp-awareness-28","question":"What is the sum of the hexadecimal number 2A and the binary number 1011, written in decimal?","options":["53","51","47","55"],"answer":0,"explanation":"2A = 2 × 16 + 10 = 42 and 1011 = 8 + 2 + 1 = 11, so the sum is 53.","difficulty":"very-hard","source":"IBPS Clerk · SSC CGL","questionHi":"हेक्साडेसिमल संख्या 2A और बाइनरी संख्या 1011 का योग दशमलव में क्या होगा?","optionsHi":["53","51","47","55"],"explanationHi":"2A = 2 × 16 + 10 = 42 और 1011 = 8 + 2 + 1 = 11, इसलिए योग 53 है।"},
  {"id":"comp-awareness-29","question":"How many of these statements are correct? I. A compiler translates a whole program at once, while an interpreter translates it line by line. II. Linux is an open-source operating system. III. A firewall is used to block unauthorised access to a network. IV. Standard ASCII uses 16 bits for each character.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Standard ASCII is a 7-bit code (128 characters), stored in 8-bit bytes; Unicode UTF-16 uses 16 bits.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk","questionHi":"इनमें से कितने कथन सही हैं? I. कंपाइलर पूरे प्रोग्राम को एक साथ अनुवादित करता है, जबकि इंटरप्रेटर उसे पंक्ति-दर-पंक्ति अनुवादित करता है। II. Linux एक ओपन-सोर्स ऑपरेटिंग सिस्टम है। III. फ़ायरवॉल का प्रयोग नेटवर्क में अनधिकृत पहुँच को रोकने के लिए किया जाता है। IV. मानक ASCII प्रत्येक अक्षर के लिए 16 बिट का प्रयोग करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। मानक ASCII 7-बिट कोड (128 अक्षर) है, जो 8-बिट बाइट में संग्रहीत होता है; Unicode UTF-16 में 16 बिट का प्रयोग होता है।"},
  {"id":"comp-awareness-30","question":"URL stands for:","options":["Uniform Resource Locator","Universal Reference Link","Unified Resource Link","Universal Resource Language"],"answer":0,"explanation":"A URL (Uniform Resource Locator) is the address of a resource on the web, such as https://example.com/page.","difficulty":"easy","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"URL का पूर्ण रूप है:","optionsHi":["Uniform Resource Locator","Universal Reference Link","Unified Resource Link","Universal Resource Language"],"explanationHi":"URL (यूनिफ़ॉर्म रिसोर्स लोकेटर) वेब पर किसी संसाधन का पता होता है, जैसे https://example.com/page।"},
  {"id":"comp-awareness-31","question":"In MS Word, the shortcut key to make selected text bold is:","options":["Ctrl + I","Ctrl + B","Ctrl + U","Ctrl + D"],"answer":1,"explanation":"In MS Word, Ctrl + B toggles bold, Ctrl + I italic and Ctrl + U underline. Ctrl + D opens the Font dialog box rather than applying a style directly.","difficulty":"easy","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"MS Word में चयनित पाठ को बोल्ड (गहरा) करने की शॉर्टकट कुंजी है:","optionsHi":["Ctrl + I","Ctrl + B","Ctrl + U","Ctrl + D"],"explanationHi":"MS Word में Ctrl + B बोल्ड, Ctrl + I इटैलिक और Ctrl + U अंडरलाइन को चालू-बंद करता है। Ctrl + D सीधे शैली लागू करने के बजाय Font डायलॉग बॉक्स खोलता है।"},
  {"id":"comp-awareness-32","question":"WWW stands for:","options":["World Web Wire","Wide World Web","World Wide Web","World Wide Wire"],"answer":2,"explanation":"The World Wide Web, invented by Tim Berners-Lee in 1989, is the system of linked hypertext documents accessed over the internet.","difficulty":"easy","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"WWW का पूर्ण रूप है:","optionsHi":["World Web Wire","Wide World Web","World Wide Web","World Wide Wire"],"explanationHi":"वर्ल्ड वाइड वेब का आविष्कार 1989 में टिम बर्नर्स-ली ने किया था; यह इंटरनेट पर पहुँचे जा सकने वाले आपस में जुड़े हाइपरटेक्स्ट दस्तावेज़ों की प्रणाली है।"},
  {"id":"comp-awareness-33","question":"Which generation of computers was based on transistors?","options":["First","Second","Third","Fourth"],"answer":1,"explanation":"First generation used vacuum tubes, second transistors, third integrated circuits and fourth microprocessors.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"कंप्यूटरों की कौन-सी पीढ़ी ट्रांजिस्टर पर आधारित थी?","optionsHi":["प्रथम","द्वितीय","तृतीय","चतुर्थ"],"explanationHi":"प्रथम पीढ़ी में निर्वात नलिकाएँ, द्वितीय में ट्रांजिस्टर, तृतीय में एकीकृत परिपथ (IC) और चतुर्थ में माइक्रोप्रोसेसर प्रयोग हुए।"},
  {"id":"comp-awareness-34","question":"Which of these is a non-volatile storage device?","options":["RAM","Cache memory","Hard disk","CPU registers"],"answer":2,"explanation":"A hard disk keeps data when power is off; RAM, cache and registers are volatile and lose their contents.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"इनमें से कौन-सा अवाष्पशील संग्रहण उपकरण है?","optionsHi":["RAM","कैश मेमोरी","हार्ड डिस्क","CPU रजिस्टर"],"explanationHi":"हार्ड डिस्क बिजली बंद होने पर भी डेटा रखती है; RAM, कैश और रजिस्टर वाष्पशील हैं और अपनी सामग्री खो देते हैं।"},
  {"id":"comp-awareness-35","question":"The smallest unit of data in a computer is a:","options":["Byte","Nibble","Bit","Word"],"answer":2,"explanation":"A bit (binary digit) is 0 or 1; a nibble is 4 bits and a byte 8 bits.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"कंप्यूटर में डेटा की सबसे छोटी इकाई है:","optionsHi":["बाइट","निबल","बिट","वर्ड"],"explanationHi":"बिट (बाइनरी अंक) 0 या 1 होता है; निबल 4 बिट का और बाइट 8 बिट का होता है।"},
  {"id":"comp-awareness-36","question":"Which of the following is application software?","options":["Windows 11","Linux","MS Excel","Device driver"],"answer":2,"explanation":"MS Excel is an application used for a specific task (spreadsheets); operating systems and device drivers are system software.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"निम्नलिखित में से कौन-सा एप्लिकेशन सॉफ्टवेयर है?","optionsHi":["Windows 11","Linux","MS Excel","डिवाइस ड्राइवर"],"explanationHi":"MS Excel किसी विशिष्ट कार्य (स्प्रेडशीट) के लिए प्रयोग होने वाला एप्लिकेशन है; ऑपरेटिंग सिस्टम और डिवाइस ड्राइवर सिस्टम सॉफ्टवेयर हैं।"},
  {"id":"comp-awareness-37","question":"In MS Excel, the cell address B3 refers to:","options":["Row B, column 3","Column B, row 3","The third sheet","Block 3"],"answer":1,"explanation":"Excel addresses cells by column letter followed by row number, so B3 is the cell in column B and row 3.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"MS Excel में सेल पता B3 का अर्थ है:","optionsHi":["पंक्ति B, स्तंभ 3","स्तंभ B, पंक्ति 3","तीसरी शीट","ब्लॉक 3"],"explanationHi":"Excel सेल को स्तंभ के अक्षर और उसके बाद पंक्ति संख्या से पहचानता है, इसलिए B3 स्तंभ B और पंक्ति 3 का सेल है।"},
  {"id":"comp-awareness-38","question":"The device that lets a computer send digital data over a telephone line is a:","options":["Router","Modem","Switch","Repeater"],"answer":1,"explanation":"A modem (modulator–demodulator) converts digital signals to analogue for the telephone line and back again.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"वह उपकरण जो कंप्यूटर को टेलीफोन लाइन पर डिजिटल डेटा भेजने देता है:","optionsHi":["राउटर","मॉडेम","स्विच","रिपीटर"],"explanationHi":"मॉडेम (मॉड्यूलेटर–डिमॉड्यूलेटर) डिजिटल सिग्नल को टेलीफोन लाइन के लिए एनालॉग में और फिर वापस डिजिटल में बदलता है।"},
  {"id":"comp-awareness-39","question":"The octal equivalent of the binary number 110101 is:","options":["53","65","35","71"],"answer":1,"explanation":"Group the bits in threes from the right: 110 101 → 6 5, so 110101₂ = 65₈ (= 53 in decimal).","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"बाइनरी संख्या 110101 का ऑक्टल समतुल्य है:","optionsHi":["53","65","35","71"],"explanationHi":"दाईं ओर से तीन-तीन बिटों के समूह बनाएँ: 110 101 → 6 5, इसलिए 110101₂ = 65₈ (= दशमलव में 53)।"},
  {"id":"comp-awareness-40","question":"Which protocol automatically assigns IP addresses to devices on a network?","options":["DNS","FTP","DHCP","SMTP"],"answer":2,"explanation":"The Dynamic Host Configuration Protocol leases IP addresses to devices; DNS resolves names, FTP transfers files and SMTP sends mail.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"कौन-सा प्रोटोकॉल नेटवर्क पर उपकरणों को स्वचालित रूप से IP पते देता है?","optionsHi":["DNS","FTP","DHCP","SMTP"],"explanationHi":"डायनेमिक होस्ट कॉन्फ़िगरेशन प्रोटोकॉल उपकरणों को IP पते पट्टे पर देता है; DNS नामों को हल करता है, FTP फ़ाइलें स्थानांतरित करता है और SMTP मेल भेजता है।"},
  {"id":"comp-awareness-41","question":"An IPv4 address is how many bits long?","options":["16 bits","32 bits","64 bits","128 bits"],"answer":1,"explanation":"IPv4 uses 32-bit addresses written as four octets (e.g. 192.168.1.1); IPv6 uses 128-bit addresses.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"एक IPv4 पता कितने बिट लंबा होता है?","optionsHi":["16 बिट","32 बिट","64 बिट","128 बिट"],"explanationHi":"IPv4 में 32-बिट पते होते हैं जिन्हें चार ऑक्टेट में लिखा जाता है (जैसे 192.168.1.1); IPv6 में 128-बिट पते होते हैं।"},
  {"id":"comp-awareness-42","question":"Cache memory in a computer is typically built from:","options":["DRAM","SRAM","EEPROM","Magnetic cores"],"answer":1,"explanation":"Cache uses static RAM, which is faster (no refresh needed) but costlier than the dynamic RAM used for main memory.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"कंप्यूटर में कैश मेमोरी सामान्यतः किससे बनाई जाती है?","optionsHi":["DRAM","SRAM","EEPROM","मैग्नेटिक कोर"],"explanationHi":"कैश में स्टैटिक RAM प्रयोग होती है, जो अधिक तेज़ (रिफ़्रेश की आवश्यकता नहीं) पर मुख्य मेमोरी में प्रयुक्त डायनेमिक RAM से महँगी होती है।"},
  {"id":"comp-awareness-43","question":"The hexadecimal equivalent of the decimal number 255 is:","options":["FF","EE","F0","100"],"answer":0,"explanation":"255 = 15 × 16 + 15, and 15 is F in hexadecimal, so 255 = FF₁₆; 100₁₆ would be 256.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"दशमलव संख्या 255 का हेक्साडेसिमल समतुल्य है:","optionsHi":["FF","EE","F0","100"],"explanationHi":"255 = 15 × 16 + 15, और हेक्साडेसिमल में 15 को F लिखते हैं, इसलिए 255 = FF₁₆; 100₁₆ का मान 256 होता।"},
  {"id":"comp-awareness-44","question":"Which program translates assembly language into machine code?","options":["Compiler","Interpreter","Assembler","Loader"],"answer":2,"explanation":"An assembler converts mnemonic assembly instructions into machine code; compilers and interpreters work on high-level languages.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"कौन-सा प्रोग्राम असेंबली भाषा को मशीन कोड में अनुवादित करता है?","optionsHi":["कंपाइलर","इंटरप्रेटर","असेंबलर","लोडर"],"explanationHi":"असेंबलर निमोनिक असेंबली निर्देशों को मशीन कोड में बदलता है; कंपाइलर और इंटरप्रेटर उच्च-स्तरीय भाषाओं पर काम करते हैं।"},
  {"id":"comp-awareness-45","question":"The default port number used by FTP for control connections is:","options":["20","21","23","25"],"answer":1,"explanation":"FTP uses port 21 for commands (and 20 for data); Telnet uses 23 and SMTP 25.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"FTP द्वारा नियंत्रण कनेक्शन के लिए प्रयोग किया जाने वाला डिफ़ॉल्ट पोर्ट नंबर है:","optionsHi":["20","21","23","25"],"explanationHi":"FTP कमांड के लिए पोर्ट 21 (और डेटा के लिए 20) का प्रयोग करता है; Telnet 23 और SMTP 25 का प्रयोग करते हैं।"},
  {"id":"comp-awareness-46","question":"In which network topology are all nodes connected to a central hub or switch?","options":["Bus","Ring","Star","Mesh"],"answer":2,"explanation":"In a star topology each device has its own link to a central device, so one cable failure does not bring down the whole network.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"किस नेटवर्क टोपोलॉजी में सभी नोड एक केंद्रीय हब या स्विच से जुड़े होते हैं?","optionsHi":["बस","रिंग","स्टार","मेश"],"explanationHi":"स्टार टोपोलॉजी में प्रत्येक उपकरण का केंद्रीय उपकरण से अपना अलग लिंक होता है, इसलिए एक केबल के खराब होने से पूरा नेटवर्क ठप नहीं होता।"},
  {"id":"comp-awareness-47","question":"The Domain Name System (DNS) is used to:","options":["Encrypt web traffic","Translate domain names into IP addresses","Assign MAC addresses","Compress web pages"],"answer":1,"explanation":"DNS maps human-readable names such as example.com to numeric IP addresses that routers use.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"डोमेन नेम सिस्टम (DNS) का प्रयोग किसलिए होता है?","optionsHi":["वेब ट्रैफ़िक को एन्क्रिप्ट करने के लिए","डोमेन नामों को IP पतों में बदलने के लिए","MAC पते निर्धारित करने के लिए","वेब पेजों को संपीड़ित करने के लिए"],"explanationHi":"DNS example.com जैसे मानव-पठनीय नामों को उन संख्यात्मक IP पतों से जोड़ता है जिन्हें राउटर प्रयोग करते हैं।"},
  {"id":"comp-awareness-48","question":"How many of these statements about computer generations are correct? I. First-generation computers used transistors. II. Second-generation computers used integrated circuits. III. Third-generation computers used microprocessors. IV. The fifth generation is associated with artificial intelligence.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only IV is correct. First-generation machines used vacuum tubes, the second generation transistors, the third integrated circuits, and microprocessors mark the fourth generation, so I, II and III are wrong.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"कंप्यूटर की पीढ़ियों के बारे में इनमें से कितने कथन सही हैं? I. प्रथम पीढ़ी के कंप्यूटरों में ट्रांजिस्टर प्रयोग हुए। II. द्वितीय पीढ़ी के कंप्यूटरों में एकीकृत परिपथ प्रयोग हुए। III. तृतीय पीढ़ी के कंप्यूटरों में माइक्रोप्रोसेसर प्रयोग हुए। IV. पाँचवीं पीढ़ी कृत्रिम बुद्धिमत्ता से जुड़ी है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल IV सही है। प्रथम पीढ़ी की मशीनों में निर्वात नलिकाएँ, द्वितीय में ट्रांजिस्टर और तृतीय में एकीकृत परिपथ थे, तथा माइक्रोप्रोसेसर चतुर्थ पीढ़ी की पहचान हैं, इसलिए I, II और III गलत हैं।"},
  {"id":"comp-awareness-49","question":"Assertion (A): Cache memory makes the CPU work faster. Reason (R): Cache keeps frequently used data and instructions close to the CPU, so fewer slow accesses to main memory are needed.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Cache hits avoid the long wait for main memory, so the processor spends less time idle; R is the mechanism behind A.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"अभिकथन (A): कैश मेमोरी CPU को तेज़ी से काम करने योग्य बनाती है। कारण (R): कैश बार-बार प्रयुक्त डेटा और निर्देशों को CPU के पास रखती है, इसलिए मुख्य मेमोरी तक धीमी पहुँच की आवश्यकता कम पड़ती है।","optionsHi":["A और R दोनों सही हैं और R, A की व्याख्या करता है","A और R दोनों सही हैं, परंतु R, A की व्याख्या नहीं करता","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"कैश हिट से मुख्य मेमोरी की लंबी प्रतीक्षा बच जाती है, इसलिए प्रोसेसर कम समय निष्क्रिय रहता है; R ही A के पीछे की कार्यविधि है।"},
  {"id":"comp-awareness-50","question":"Match the protocol with its default port: 1. SMTP 2. HTTP 3. HTTPS 4. DNS; a. 443 b. 53 c. 80 d. 25","options":["1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-a, 4-b","1-d, 2-a, 3-c, 4-b","1-b, 2-c, 3-a, 4-d"],"answer":0,"explanation":"Default ports: SMTP 25, HTTP 80, HTTPS 443 and DNS 53, giving 1-d, 2-c, 3-a, 4-b. The usual trap swaps HTTP (80) and HTTPS (443).","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"प्रोटोकॉल का उसके डिफ़ॉल्ट पोर्ट से मिलान कीजिए: 1. SMTP 2. HTTP 3. HTTPS 4. DNS; a. 443 b. 53 c. 80 d. 25","optionsHi":["1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-a, 4-b","1-d, 2-a, 3-c, 4-b","1-b, 2-c, 3-a, 4-d"],"explanationHi":"डिफ़ॉल्ट पोर्ट: SMTP 25, HTTP 80, HTTPS 443 और DNS 53, जिससे 1-d, 2-c, 3-a, 4-b बनता है। आम जाल HTTP (80) और HTTPS (443) को आपस में बदल देना है।"},
  {"id":"comp-awareness-51","question":"How many bits are there in 2 KB of data (1 KB = 1024 bytes)?","options":["2,048","8,192","16,384","20,480"],"answer":2,"explanation":"2 KB = 2 × 1024 = 2,048 bytes, and each byte has 8 bits, so 2,048 × 8 = 16,384 bits. Stopping at 2,048 gives bytes, not bits; 20,480 wrongly uses 10 bits per byte.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"2 KB डेटा में कितने बिट होते हैं (1 KB = 1024 बाइट)?","optionsHi":["2,048","8,192","16,384","20,480"],"explanationHi":"2 KB = 2 × 1024 = 2,048 बाइट, और प्रत्येक बाइट में 8 बिट होते हैं, इसलिए 2,048 × 8 = 16,384 बिट। 2,048 पर रुकने से बाइट मिलते हैं, बिट नहीं; 20,480 गलती से प्रति बाइट 10 बिट मानता है।"},
  {"id":"comp-awareness-52","question":"Which of the following is NOT an input device?","options":["Light pen","Joystick","Plotter","Scanner"],"answer":2,"explanation":"A plotter draws output on paper; light pens, joysticks and scanners feed data into the computer.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"निम्नलिखित में से कौन-सा इनपुट डिवाइस नहीं है?","optionsHi":["लाइट पेन","जॉयस्टिक","प्लॉटर","स्कैनर"],"explanationHi":"प्लॉटर कागज़ पर आरेख बनाकर आउटपुट देता है; लाइट पेन, जॉयस्टिक और स्कैनर कंप्यूटर में डेटा भेजते हैं।"},
  {"id":"comp-awareness-53","question":"How many of these statements are correct? I. The TCP/IP model has four layers. II. ARPANET, the forerunner of the internet, began in 1969. III. HTML is a programming language. IV. Tim Berners-Lee proposed the World Wide Web in 1989.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. III is wrong: HTML is a markup language that describes page structure; it has no logic or control flow of its own.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. TCP/IP मॉडल में चार परतें होती हैं। II. इंटरनेट का पूर्वज ARPANET 1969 में शुरू हुआ। III. HTML एक प्रोग्रामिंग भाषा है। IV. टिम बर्नर्स-ली ने 1989 में वर्ल्ड वाइड वेब का प्रस्ताव रखा।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। III गलत है: HTML एक मार्कअप भाषा है जो पेज की संरचना बताती है; इसमें अपना कोई तर्क या नियंत्रण प्रवाह नहीं होता।"},
  {"id":"comp-awareness-54","question":"Arrange these programming languages in the order they appeared, earliest first: 1. Java 2. COBOL 3. FORTRAN 4. C","options":["3, 2, 4, 1","2, 3, 4, 1","3, 4, 2, 1","2, 3, 1, 4"],"answer":0,"explanation":"FORTRAN (1957) came first, then COBOL (1959), C (1972) and Java (1995), so the order is 3, 2, 4, 1. The trap is putting COBOL before FORTRAN because both are 1950s business/science languages.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"इन प्रोग्रामिंग भाषाओं को उनके आने के क्रम में, सबसे पहले वाली से, व्यवस्थित कीजिए: 1. Java 2. COBOL 3. FORTRAN 4. C","optionsHi":["3, 2, 4, 1","2, 3, 4, 1","3, 4, 2, 1","2, 3, 1, 4"],"explanationHi":"FORTRAN (1957) सबसे पहले आई, फिर COBOL (1959), C (1972) और Java (1995), इसलिए क्रम 3, 2, 4, 1 है। जाल यह है कि COBOL को FORTRAN से पहले रख दिया जाता है, क्योंकि दोनों 1950 के दशक की व्यावसायिक/वैज्ञानिक भाषाएँ हैं।"},
  {"id":"comp-awareness-55","question":"Assertion (A): The BIOS of a computer is stored in ROM. Reason (R): ROM retains its contents even when the power is switched off.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Start-up firmware must survive power-off so the machine can boot, which is why it lives in non-volatile ROM (flash) rather than RAM.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"अभिकथन (A): कंप्यूटर का BIOS ROM में संग्रहीत होता है। कारण (R): बिजली बंद होने पर भी ROM अपनी सामग्री बनाए रखती है।","optionsHi":["A और R दोनों सही हैं और R, A की व्याख्या करता है","A और R दोनों सही हैं, परंतु R, A की व्याख्या नहीं करता","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"स्टार्ट-अप फ़र्मवेयर का बिजली बंद होने पर भी बने रहना आवश्यक है ताकि मशीन बूट हो सके, इसीलिए यह RAM के बजाय अवाष्पशील ROM (फ्लैश) में रहता है।"},
  {"id":"comp-awareness-56","question":"Match the MS Word shortcut with its function: 1. Ctrl + Z 2. Ctrl + Y 3. Ctrl + U 4. Ctrl + P; a. Print b. Underline c. Redo d. Undo","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":0,"explanation":"Ctrl + Z undo, Ctrl + Y redo, Ctrl + U underline, Ctrl + P print.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"MS Word के शॉर्टकट का उसके कार्य से मिलान कीजिए: 1. Ctrl + Z 2. Ctrl + Y 3. Ctrl + U 4. Ctrl + P; a. प्रिंट b. अंडरलाइन c. रीडू d. अनडू","optionsHi":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b"],"explanationHi":"Ctrl + Z अनडू, Ctrl + Y रीडू, Ctrl + U अंडरलाइन और Ctrl + P प्रिंट के लिए है।"},
  {"id":"comp-awareness-57","question":"How many of these statements are correct? I. The Linux kernel was created by Linus Torvalds. II. An operating system is a type of application software. III. Python is an interpreted language. IV. Open-source software must always be distributed free of cost.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong (an OS is system software) and IV is wrong: open source means the source code is available under a licence; it may still be sold.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. Linux कर्नेल का निर्माण लिनस टोरवाल्ड्स ने किया। II. ऑपरेटिंग सिस्टम एक प्रकार का एप्लिकेशन सॉफ्टवेयर है। III. Python एक इंटरप्रेटेड भाषा है। IV. ओपन-सोर्स सॉफ्टवेयर को सदैव निःशुल्क वितरित करना आवश्यक है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। II गलत है (OS सिस्टम सॉफ्टवेयर है) और IV भी गलत है: ओपन सोर्स का अर्थ है कि स्रोत कोड लाइसेंस के अंतर्गत उपलब्ध है; उसे फिर भी बेचा जा सकता है।"},
  {"id":"comp-awareness-58","question":"Which of the following numbers has the largest value?","options":["1F in hexadecimal","11111 in binary","37 in octal","32 in decimal"],"answer":3,"explanation":"1F₁₆ = 31, 11111₂ = 31 and 37₈ = 3 × 8 + 7 = 31, so 32 in decimal is the largest.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"निम्नलिखित में से किस संख्या का मान सबसे अधिक है?","optionsHi":["हेक्साडेसिमल में 1F","बाइनरी में 11111","ऑक्टल में 37","दशमलव में 32"],"explanationHi":"1F₁₆ = 31, 11111₂ = 31 और 37₈ = 3 × 8 + 7 = 31, इसलिए दशमलव में 32 सबसे बड़ा है।"},
  {"id":"comp-awareness-59","question":"Which pair of term and description is NOT correctly matched?","options":["Phishing – fraudulent messages that trick users into revealing passwords","Trojan – malware disguised as a legitimate program","Worm – malware that needs a host file to spread","Firewall – system that filters network traffic"],"answer":2,"explanation":"A worm is self-replicating and spreads on its own across networks; it is a virus that attaches itself to a host file or program.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL","questionHi":"शब्द और उसके विवरण का कौन-सा युग्म सही सुमेलित नहीं है?","optionsHi":["फ़िशिंग – ऐसे कपटपूर्ण संदेश जो उपयोगकर्ताओं को पासवर्ड बताने के लिए बहकाते हैं","ट्रोजन – वैध प्रोग्राम का वेश धारण करने वाला मैलवेयर","वर्म – ऐसा मैलवेयर जिसे फैलने के लिए किसी होस्ट फ़ाइल की आवश्यकता होती है","फ़ायरवॉल – नेटवर्क ट्रैफ़िक को फ़िल्टर करने वाली प्रणाली"],"explanationHi":"वर्म स्वयं की प्रतिकृति बनाने वाला है और नेटवर्क पर अपने आप फैलता है; जो किसी होस्ट फ़ाइल या प्रोग्राम से जुड़कर फैलता है वह वायरस है।"},
  {"id":"comp-awareness-60","question":"In MS Word, which shortcut selects all the text in a document?","options":["Ctrl + S","Ctrl + A","Ctrl + L","Ctrl + E"],"answer":1,"explanation":"Ctrl + A selects all. Ctrl + S saves, Ctrl + L left-aligns and Ctrl + E centres the text.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk","questionHi":"MS Word में कौन-सा शॉर्टकट दस्तावेज़ का पूरा पाठ चयनित करता है?","optionsHi":["Ctrl + S","Ctrl + A","Ctrl + L","Ctrl + E"],"explanationHi":"Ctrl + A सब कुछ चयनित करता है। Ctrl + S सेव करता है, Ctrl + L पाठ को बाईं ओर संरेखित करता है और Ctrl + E उसे मध्य में करता है।"},
  {"id":"comp-awareness-61","question":"PDF, a common file format for documents, stands for:","options":["Printable Document File","Public Data Format","Portable Document Format","Personal Document Folder"],"answer":2,"explanation":"Portable Document Format was developed by Adobe so that a document looks the same on any device or operating system.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"दस्तावेज़ों का सामान्य फ़ाइल फ़ॉर्मैट PDF का पूर्ण रूप है:","optionsHi":["Printable Document File","Public Data Format","Portable Document Format","Personal Document Folder"],"explanationHi":"पोर्टेबल डॉक्यूमेंट फ़ॉर्मैट को Adobe ने विकसित किया ताकि दस्तावेज़ किसी भी डिवाइस या ऑपरेटिंग सिस्टम पर एक जैसा दिखे।"},
  {"id":"comp-awareness-62","question":"Which of the following is a web browser?","options":["MS Excel","Mozilla Firefox","Oracle","Python"],"answer":1,"explanation":"Firefox, Chrome, Edge and Safari are browsers. Excel is a spreadsheet, Oracle a database and Python a programming language.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"निम्नलिखित में से कौन-सा वेब ब्राउज़र है?","optionsHi":["MS Excel","Mozilla Firefox","Oracle","Python"],"explanationHi":"Firefox, Chrome, Edge और Safari ब्राउज़र हैं। Excel स्प्रेडशीट है, Oracle डेटाबेस है और Python प्रोग्रामिंग भाषा है।"},
  {"id":"comp-awareness-63","question":"In Windows, which key combination opens the Task Manager directly?","options":["Ctrl + Alt + Tab","Alt + F4","Ctrl + Shift + Esc","Windows + D"],"answer":2,"explanation":"Ctrl + Shift + Esc opens Task Manager straight away. Alt + F4 closes the active window and Windows + D shows the desktop.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"Windows में कौन-सा कुंजी संयोजन सीधे टास्क मैनेजर खोलता है?","optionsHi":["Ctrl + Alt + Tab","Alt + F4","Ctrl + Shift + Esc","Windows + D"],"explanationHi":"Ctrl + Shift + Esc सीधे टास्क मैनेजर खोलता है। Alt + F4 सक्रिय विंडो बंद करता है और Windows + D डेस्कटॉप दिखाता है।"},
  {"id":"comp-awareness-64","question":"In MS Excel, every formula must begin with the symbol:","options":["+","#","@","="],"answer":3,"explanation":"Typing = tells Excel that what follows is a formula, e.g. =SUM(A1:A5). Without it the entry is treated as text or a number.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk","questionHi":"MS Excel में प्रत्येक सूत्र (फ़ॉर्मूला) किस प्रतीक से शुरू होना चाहिए?","optionsHi":["+","#","@","="],"explanationHi":"= टाइप करने से Excel समझता है कि आगे सूत्र है, जैसे =SUM(A1:A5)। इसके बिना प्रविष्टि को पाठ या संख्या माना जाता है।"},
  {"id":"comp-awareness-65","question":"Which device connects different networks and forwards data packets between them using IP addresses?","options":["Hub","Repeater","Router","Switch"],"answer":2,"explanation":"A router works at the network layer and chooses paths between networks. A switch connects devices within one network using MAC addresses.","difficulty":"moderate","source":"IBPS PO · SBI PO","questionHi":"कौन-सा उपकरण विभिन्न नेटवर्कों को जोड़ता है और IP पतों का प्रयोग करके उनके बीच डेटा पैकेट आगे भेजता है?","optionsHi":["हब","रिपीटर","राउटर","स्विच"],"explanationHi":"राउटर नेटवर्क परत पर काम करता है और नेटवर्कों के बीच मार्ग चुनता है। स्विच MAC पतों का प्रयोग करके एक ही नेटवर्क के भीतर उपकरणों को जोड़ता है।"},
  {"id":"comp-awareness-66","question":"In most Windows programs, which function key opens Help?","options":["F1","F2","F5","F12"],"answer":0,"explanation":"F1 opens Help. F2 renames a selected file, F5 refreshes, and F12 opens Save As in MS Office.","difficulty":"moderate","source":"SSC CHSL · IBPS Clerk","questionHi":"अधिकांश Windows प्रोग्रामों में कौन-सी फ़ंक्शन कुंजी हेल्प खोलती है?","optionsHi":["F1","F2","F5","F12"],"explanationHi":"F1 हेल्प खोलती है। F2 चयनित फ़ाइल का नाम बदलती है, F5 रिफ़्रेश करती है, और F12 MS Office में Save As खोलती है।"},
  {"id":"comp-awareness-67","question":"The octal number 17 is equal to which decimal number?","options":["17","15","13","7"],"answer":1,"explanation":"Octal places are powers of 8: 17₈ = 1 × 8 + 7 = 15. Reading it as the decimal 17 ignores the base, which is the main trap.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk","questionHi":"ऑक्टल संख्या 17 किस दशमलव संख्या के बराबर है?","optionsHi":["17","15","13","7"],"explanationHi":"ऑक्टल के स्थान 8 की घात होते हैं: 17₈ = 1 × 8 + 7 = 15। इसे दशमलव 17 पढ़ना आधार की उपेक्षा है, जो मुख्य जाल है।"},
  {"id":"comp-awareness-68","question":"Which protocol provides secure, encrypted remote login to another computer?","options":["Telnet","SSH","FTP","SNMP"],"answer":1,"explanation":"SSH (Secure Shell, port 22) encrypts the session. Telnet does the same job but sends everything, including passwords, as plain text.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"किसी अन्य कंप्यूटर में सुरक्षित, एन्क्रिप्टेड रिमोट लॉगिन कौन-सा प्रोटोकॉल देता है?","optionsHi":["Telnet","SSH","FTP","SNMP"],"explanationHi":"SSH (सिक्योर शेल, पोर्ट 22) सत्र को एन्क्रिप्ट करता है। Telnet वही काम करता है, पर पासवर्ड सहित सब कुछ सादे पाठ में भेजता है।"},
  {"id":"comp-awareness-69","question":"In MS Excel, which function counts only the cells in a range that contain numbers?","options":["COUNTA","COUNT","SUM","COUNTBLANK"],"answer":1,"explanation":"COUNT counts numeric cells only. COUNTA counts all non-empty cells, including text, and COUNTBLANK counts empty cells.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"MS Excel में कौन-सा फ़ंक्शन किसी रेंज में केवल उन सेल को गिनता है जिनमें संख्याएँ हों?","optionsHi":["COUNTA","COUNT","SUM","COUNTBLANK"],"explanationHi":"COUNT केवल संख्यात्मक सेल गिनता है। COUNTA पाठ सहित सभी अरिक्त सेल गिनता है, और COUNTBLANK खाली सेल गिनता है।"},
  {"id":"comp-awareness-70","question":"Which type of memory must be refreshed thousands of times a second to keep its data?","options":["SRAM","DRAM","ROM","Flash memory"],"answer":1,"explanation":"DRAM stores each bit as charge on a tiny capacitor that leaks, so it needs constant refreshing. SRAM uses flip-flops and needs no refresh, which is why it is faster and used for cache.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"किस प्रकार की मेमोरी को अपना डेटा बनाए रखने के लिए प्रति सेकंड हज़ारों बार रिफ़्रेश करना पड़ता है?","optionsHi":["SRAM","DRAM","ROM","फ्लैश मेमोरी"],"explanationHi":"DRAM प्रत्येक बिट को एक सूक्ष्म संधारित्र (कैपेसिटर) पर आवेश के रूप में रखती है जो रिसता रहता है, इसलिए उसे लगातार रिफ़्रेश करना पड़ता है। SRAM फ्लिप-फ्लॉप का प्रयोग करती है और रिफ़्रेश नहीं माँगती, इसीलिए वह अधिक तेज़ है और कैश में प्रयुक्त होती है।"},
  {"id":"comp-awareness-71","question":"Virtual memory in a computer is:","options":["Memory built into the CPU registers","A part of the hard disk used as an extension of RAM","A type of ROM chip","Memory available only on cloud servers"],"answer":1,"explanation":"When RAM is full, the operating system moves less-used pages to a space on the disk (page file or swap), letting programs use more memory than is physically present, but more slowly.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"कंप्यूटर में वर्चुअल मेमोरी क्या है?","optionsHi":["CPU रजिस्टरों में निर्मित मेमोरी","हार्ड डिस्क का वह भाग जो RAM के विस्तार के रूप में प्रयोग होता है","ROM चिप का एक प्रकार","केवल क्लाउड सर्वरों पर उपलब्ध मेमोरी"],"explanationHi":"RAM भर जाने पर ऑपरेटिंग सिस्टम कम प्रयुक्त पेजों को डिस्क के एक स्थान (पेज फ़ाइल या स्वैप) में भेज देता है, जिससे प्रोग्राम भौतिक रूप से उपलब्ध मेमोरी से अधिक का प्रयोग कर पाते हैं, पर अपेक्षाकृत धीमी गति से।"},
  {"id":"comp-awareness-72","question":"A CAPTCHA on a website is used to:","options":["Speed up page loading","Tell human users apart from automated bots","Encrypt passwords","Store browsing history"],"answer":1,"explanation":"CAPTCHA stands for Completely Automated Public Turing test to tell Computers and Humans Apart; it blocks automated sign-ups and spam.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk","questionHi":"किसी वेबसाइट पर CAPTCHA का प्रयोग किसलिए किया जाता है?","optionsHi":["पेज लोड होने की गति बढ़ाने के लिए","मानव उपयोगकर्ताओं को स्वचालित बॉट से अलग पहचानने के लिए","पासवर्ड एन्क्रिप्ट करने के लिए","ब्राउज़िंग इतिहास संग्रहीत करने के लिए"],"explanationHi":"CAPTCHA का पूर्ण रूप Completely Automated Public Turing test to tell Computers and Humans Apart है; यह स्वचालित साइन-अप और स्पैम को रोकता है।"},
  {"id":"comp-awareness-73","question":"Spooling is most commonly used in computers for:","options":["Compressing files","Queuing print jobs so that the CPU need not wait for the printer","Scanning for viruses","Defragmenting the hard disk"],"answer":1,"explanation":"Spooling (Simultaneous Peripheral Operations On-Line) places jobs in a buffer on disk so that a slow device like a printer can take them one by one while the CPU continues working.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"कंप्यूटर में स्पूलिंग का सबसे सामान्य प्रयोग किसके लिए होता है?","optionsHi":["फ़ाइलों को संपीड़ित करने के लिए","प्रिंट कार्यों को कतार में रखने के लिए ताकि CPU को प्रिंटर की प्रतीक्षा न करनी पड़े","वायरस की जाँच के लिए","हार्ड डिस्क को डीफ़्रैग्मेंट करने के लिए"],"explanationHi":"स्पूलिंग (Simultaneous Peripheral Operations On-Line) कार्यों को डिस्क के बफ़र में रखती है ताकि प्रिंटर जैसा धीमा उपकरण उन्हें एक-एक करके ले सके और CPU अपना काम जारी रखे।"},
  {"id":"comp-awareness-74","question":"The binary equivalent of the decimal number 156 is:","options":["10011100","10011010","11001100","10101100"],"answer":0,"explanation":"156 = 128 + 16 + 8 + 4, so the bits for 128, 16, 8 and 4 are 1: 10011100.","difficulty":"very-hard","source":"IBPS Clerk · SBI Clerk","questionHi":"दशमलव संख्या 156 का बाइनरी समतुल्य है:","optionsHi":["10011100","10011010","11001100","10101100"],"explanationHi":"156 = 128 + 16 + 8 + 4, इसलिए 128, 16, 8 और 4 के बिट 1 होंगे: 10011100।"},
  {"id":"comp-awareness-75","question":"How many files of 4 MB each can be stored on a 2 GB pen drive? (1 GB = 1024 MB)","options":["500","512","256","2048"],"answer":1,"explanation":"2 GB = 2 × 1024 = 2048 MB. 2048 ÷ 4 = 512 files. 500 is the trap of taking 1 GB as 1000 MB.","difficulty":"very-hard","source":"IBPS Clerk · SBI Clerk","questionHi":"2 GB की पेन ड्राइव में प्रत्येक 4 MB की कितनी फ़ाइलें संग्रहीत की जा सकती हैं? (1 GB = 1024 MB)","optionsHi":["500","512","256","2048"],"explanationHi":"2 GB = 2 × 1024 = 2048 MB। 2048 ÷ 4 = 512 फ़ाइलें। 500 वाला विकल्प 1 GB को 1000 MB मान लेने का जाल है।"},
  {"id":"comp-awareness-76","question":"How many of these statements are correct? I. A MAC address is 32 bits long. II. A switch works at the physical layer of the OSI model. III. A hub sends incoming data only to the intended device. IV. Bluetooth is an example of a personal area network technology.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only IV is correct. A MAC address is 48 bits (32 bits is an IPv4 address); a switch works at the data link layer, not the physical layer; and a hub broadcasts to every port rather than to the intended device.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"इनमें से कितने कथन सही हैं? I. MAC पता 32 बिट लंबा होता है। II. स्विच OSI मॉडल की भौतिक परत पर काम करता है। III. हब आने वाला डेटा केवल इच्छित उपकरण को भेजता है। IV. ब्लूटूथ पर्सनल एरिया नेटवर्क तकनीक का एक उदाहरण है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल IV सही है। MAC पता 48 बिट का होता है (32 बिट IPv4 पता है); स्विच भौतिक परत पर नहीं, डेटा लिंक परत पर काम करता है; और हब इच्छित उपकरण के बजाय प्रत्येक पोर्ट पर डेटा प्रसारित करता है।"},
  {"id":"comp-awareness-77","question":"Assertion (A): Phishing e-mails often contain links to fake websites that look like real bank sites. Reason (R): Phishing aims to steal sensitive data such as passwords and card details by pretending to be a trusted organisation.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The fake site is the tool used to trick users into entering their details, so R explains A.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"अभिकथन (A): फ़िशिंग ई-मेल में अक्सर नकली वेबसाइटों के लिंक होते हैं जो असली बैंक साइट जैसी दिखती हैं। कारण (R): फ़िशिंग का उद्देश्य किसी विश्वसनीय संगठन का रूप धरकर पासवर्ड और कार्ड विवरण जैसा संवेदनशील डेटा चुराना है।","optionsHi":["A और R दोनों सही हैं और R, A की व्याख्या करता है","A और R दोनों सही हैं, परंतु R, A की व्याख्या नहीं करता","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"नकली साइट उपयोगकर्ताओं को अपना विवरण भरने के लिए बहकाने का साधन है, इसलिए R, A की व्याख्या करता है।"},
  {"id":"comp-awareness-78","question":"Assertion (A): Data stored in RAM is lost when the power is switched off. Reason (R): RAM is made of magnetic disks.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: RAM is volatile. R is false: RAM is made of semiconductor chips; magnetic disks are used in hard disk drives, which keep data without power.","difficulty":"very-hard","source":"IBPS Clerk · SBI Clerk","questionHi":"अभिकथन (A): बिजली बंद करने पर RAM में संग्रहीत डेटा मिट जाता है। कारण (R): RAM चुंबकीय डिस्कों से बनी होती है।","optionsHi":["A और R दोनों सही हैं और R, A की व्याख्या करता है","A और R दोनों सही हैं, परंतु R, A की व्याख्या नहीं करता","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"A सही है: RAM वाष्पशील है। R गलत है: RAM अर्धचालक चिपों से बनी होती है; चुंबकीय डिस्क हार्ड डिस्क ड्राइव में प्रयुक्त होती हैं, जो बिना बिजली के भी डेटा रखती हैं।"},
  {"id":"comp-awareness-79","question":"Match the MS Word shortcut with its function: 1. Ctrl + F 2. Ctrl + H 3. Ctrl + K 4. Ctrl + N; a. New document b. Insert hyperlink c. Find d. Replace","options":["1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":1,"explanation":"Ctrl + F finds text, Ctrl + H opens Find and Replace, Ctrl + K inserts a hyperlink and Ctrl + N opens a new document.","difficulty":"very-hard","source":"IBPS Clerk · SBI Clerk","questionHi":"MS Word के शॉर्टकट का उसके कार्य से मिलान कीजिए: 1. Ctrl + F 2. Ctrl + H 3. Ctrl + K 4. Ctrl + N; a. नया दस्तावेज़ b. हाइपरलिंक जोड़ना c. खोजना d. बदलना","optionsHi":["1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"explanationHi":"Ctrl + F पाठ खोजता है, Ctrl + H खोजें और बदलें खोलता है, Ctrl + K हाइपरलिंक जोड़ता है और Ctrl + N नया दस्तावेज़ खोलता है।"},
  {"id":"comp-awareness-80","question":"Match the malware with its description: 1. Trojan 2. Ransomware 3. Spyware 4. Keylogger; a. Records the keys a user presses b. Encrypts files and demands payment c. Pretends to be useful, legitimate software d. Secretly collects information about the user","options":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-a, 4-d"],"answer":0,"explanation":"A Trojan hides inside apparently genuine software, ransomware locks files for ransom, spyware watches the user and a keylogger records keystrokes (often to steal passwords).","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"मैलवेयर का उसके विवरण से मिलान कीजिए: 1. ट्रोजन 2. रैनसमवेयर 3. स्पाइवेयर 4. कीलॉगर; a. उपयोगकर्ता द्वारा दबाई गई कुंजियों को रिकॉर्ड करता है b. फ़ाइलों को एन्क्रिप्ट करता है और भुगतान माँगता है c. उपयोगी, वैध सॉफ्टवेयर होने का दिखावा करता है d. उपयोगकर्ता की जानकारी चोरी-छिपे एकत्र करता है","optionsHi":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-a, 4-d"],"explanationHi":"ट्रोजन प्रत्यक्ष रूप से असली दिखने वाले सॉफ्टवेयर में छिपा रहता है, रैनसमवेयर फ़िरौती के लिए फ़ाइलें बंद कर देता है, स्पाइवेयर उपयोगकर्ता पर नज़र रखता है और कीलॉगर कुंजी-प्रहारों को रिकॉर्ड करता है (अक्सर पासवर्ड चुराने के लिए)।"},
  {"id":"comp-awareness-81","question":"Which of the following is NOT a valid IPv4 address?","options":["10.0.0.1","172.16.254.1","192.168.1.256","8.8.8.8"],"answer":2,"explanation":"Each of the four octets in an IPv4 address is 8 bits, so it can range only from 0 to 255. 256 is out of range.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"निम्नलिखित में से कौन-सा वैध IPv4 पता नहीं है?","optionsHi":["10.0.0.1","172.16.254.1","192.168.1.256","8.8.8.8"],"explanationHi":"IPv4 पते के चारों ऑक्टेट में से प्रत्येक 8 बिट का होता है, इसलिए उसका मान केवल 0 से 255 तक हो सकता है। 256 इस सीमा से बाहर है।"},
  {"id":"comp-awareness-82","question":"Arrange in chronological order of first release: 1. Windows 95 2. MS-DOS 3. Android 4. Linux kernel","options":["2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1","2, 4, 1, 3"],"answer":3,"explanation":"MS-DOS 1981 → Linux kernel 1991 → Windows 95 in 1995 → first commercial Android phone 2008.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"पहली बार जारी होने के कालानुक्रम में व्यवस्थित कीजिए: 1. Windows 95 2. MS-DOS 3. Android 4. Linux कर्नेल","optionsHi":["2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1","2, 4, 1, 3"],"explanationHi":"MS-DOS 1981 → Linux कर्नेल 1991 → Windows 95 वर्ष 1995 में → पहला व्यावसायिक Android फ़ोन 2008।"},
  {"id":"comp-awareness-83","question":"How many of these statements about MS Excel (2007 and later) are correct? I. $A$1 is an absolute cell reference. II. A worksheet has 1,048,576 rows. III. The last column of a worksheet is XFD. IV. The AVERAGE function ignores text in a range of cells.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: a sheet has 1,048,576 rows and 16,384 columns (A to XFD), and AVERAGE skips text and empty cells in a referenced range.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"MS Excel (2007 और उसके बाद) के बारे में इनमें से कितने कथन सही हैं? I. $A$1 एक निरपेक्ष सेल संदर्भ है। II. एक वर्कशीट में 1,048,576 पंक्तियाँ होती हैं। III. वर्कशीट का अंतिम स्तंभ XFD है। IV. AVERAGE फ़ंक्शन सेल की रेंज में पाठ की उपेक्षा करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चारों सही हैं: एक शीट में 1,048,576 पंक्तियाँ और 16,384 स्तंभ (A से XFD) होते हैं, और AVERAGE संदर्भित रेंज में पाठ तथा खाली सेल को छोड़ देता है।"},
  {"id":"comp-awareness-84","question":"Ignoring overheads, how long does it take to download a 100 MB file on an 8 Mbps connection? (1 byte = 8 bits)","options":["12.5 seconds","100 seconds","800 seconds","1 second"],"answer":1,"explanation":"100 MB = 800 megabits. Time = 800 ÷ 8 = 100 s. 12.5 s is the trap of not converting bytes to bits.","difficulty":"very-hard","source":"IBPS Clerk · SBI Clerk","questionHi":"अतिरिक्त भार (ओवरहेड) की उपेक्षा करने पर, 8 Mbps कनेक्शन पर 100 MB की फ़ाइल डाउनलोड होने में कितना समय लगेगा? (1 बाइट = 8 बिट)","optionsHi":["12.5 सेकंड","100 सेकंड","800 सेकंड","1 सेकंड"],"explanationHi":"100 MB = 800 मेगाबिट। समय = 800 ÷ 8 = 100 s। 12.5 s वाला विकल्प बाइट को बिट में न बदलने का जाल है।"},
  {"id":"comp-awareness-85","question":"Who is known as the ‘father of the computer’ for designing the Analytical Engine?","options":["John von Neumann","Blaise Pascal","Charles Babbage","Alan Turing"],"answer":2,"explanation":"Charles Babbage designed the Difference Engine and the programmable Analytical Engine in the 19th century. Pascal built an early mechanical calculator, and Turing laid the theoretical foundations of computing.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk · SSC CHSL","questionHi":"एनालिटिकल इंजन की रचना करने के कारण ‘कंप्यूटर का जनक’ किसे कहा जाता है?","optionsHi":["जॉन वॉन न्यूमैन","ब्लेज़ पास्कल","चार्ल्स बैबेज","एलन ट्यूरिंग"],"explanationHi":"चार्ल्स बैबेज ने 19वीं सदी में डिफ़रेंस इंजन और प्रोग्राम योग्य एनालिटिकल इंजन की रचना की। पास्कल ने एक प्रारंभिक यांत्रिक कैलकुलेटर बनाया, और ट्यूरिंग ने कंप्यूटिंग की सैद्धांतिक नींव रखी।"},
  {"id":"comp-awareness-86","question":"In MS PowerPoint, which key starts the slide show from the first slide?","options":["F12","F1","F7","F5"],"answer":3,"explanation":"F5 starts the show from the beginning and Shift + F5 from the current slide. F1 opens Help, F7 runs the spelling check and F12 opens Save As.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk · SSC CHSL","questionHi":"MS PowerPoint में कौन-सी कुंजी स्लाइड शो को पहली स्लाइड से शुरू करती है?","optionsHi":["F12","F1","F7","F5"],"explanationHi":"F5 शो को शुरू से और Shift + F5 वर्तमान स्लाइड से शुरू करती है। F1 हेल्प खोलती है, F7 वर्तनी जाँच चलाती है और F12 Save As खोलती है।"},
  {"id":"comp-awareness-87","question":"In e-mail, ‘BCC’ stands for:","options":["Bulk Copy Command","Backup Carbon Copy","Blind Carbon Copy","Basic Carbon Copy"],"answer":2,"explanation":"Addresses in the BCC field receive the message but are hidden from all other recipients, unlike addresses in the To and CC fields.","difficulty":"easy","source":"IBPS Clerk · SBI Clerk · SSC CHSL","questionHi":"ई-मेल में ‘BCC’ का पूर्ण रूप है:","optionsHi":["Bulk Copy Command","Backup Carbon Copy","Blind Carbon Copy","Basic Carbon Copy"],"explanationHi":"BCC क्षेत्र के पते संदेश प्राप्त करते हैं पर अन्य सभी प्राप्तकर्ताओं से छिपे रहते हैं, To और CC क्षेत्र के पतों के विपरीत।"},
  {"id":"comp-awareness-88","question":"Which logic gate is called a ‘universal gate’ because any other gate can be built from it alone?","options":["AND","NAND","OR","XOR"],"answer":1,"explanation":"NAND (and also NOR) is universal: NOT, AND and OR can all be made using only NAND gates. AND, OR and XOR cannot do this on their own.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"किस लॉजिक गेट को ‘सार्वभौमिक गेट’ कहा जाता है, क्योंकि केवल उसी से अन्य कोई भी गेट बनाया जा सकता है?","optionsHi":["AND","NAND","OR","XOR"],"explanationHi":"NAND (और NOR भी) सार्वभौमिक है: NOT, AND और OR सभी केवल NAND गेटों से बनाए जा सकते हैं। AND, OR और XOR अकेले ऐसा नहीं कर सकते।"},
  {"id":"comp-awareness-89","question":"Which character-encoding standard is designed to represent the characters of almost all the world’s writing systems, including Devanagari?","options":["ASCII","BCD","Unicode","EBCDIC"],"answer":2,"explanation":"Unicode assigns a unique code point to over a hundred thousand characters from scripts worldwide. ASCII covers only 128 basic Latin characters, and EBCDIC is an old IBM code.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"कौन-सा कैरेक्टर-एन्कोडिंग मानक देवनागरी सहित विश्व की लगभग सभी लेखन प्रणालियों के वर्णों को निरूपित करने के लिए बनाया गया है?","optionsHi":["ASCII","BCD","Unicode","EBCDIC"],"explanationHi":"Unicode विश्व भर की लिपियों के एक लाख से अधिक वर्णों को अद्वितीय कोड बिंदु देता है। ASCII केवल 128 मूल लैटिन वर्णों को समेटता है, और EBCDIC IBM का पुराना कोड है।"},
  {"id":"comp-awareness-90","question":"In database systems, SQL stands for:","options":["System Query Library","Standard Question Language","Sequential Query Logic","Structured Query Language"],"answer":3,"explanation":"SQL is the standard language for creating, querying and updating relational databases, with commands such as SELECT, INSERT, UPDATE and DELETE.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk · SSC CHSL","questionHi":"डेटाबेस प्रणालियों में SQL का पूर्ण रूप है:","optionsHi":["System Query Library","Standard Question Language","Sequential Query Logic","Structured Query Language"],"explanationHi":"SQL रिलेशनल डेटाबेस बनाने, उनसे क्वेरी करने और उन्हें अद्यतन करने की मानक भाषा है, जिसके कमांड SELECT, INSERT, UPDATE और DELETE हैं।"},
  {"id":"comp-awareness-91","question":"Moore’s law, stated by Gordon Moore, predicts that:","options":["Hard disk size grows tenfold every decade","Computer prices halve every year","The number of transistors on a chip doubles about every two years","Internet speed doubles every six months"],"answer":2,"explanation":"In 1965 Moore observed that transistor counts were doubling regularly, later revised to about every two years; this trend drove the rapid rise in computing power.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"गॉर्डन मूर द्वारा बताया गया मूर का नियम भविष्यवाणी करता है कि:","optionsHi":["हार्ड डिस्क का आकार प्रत्येक दशक में दस गुना हो जाता है","कंप्यूटर की कीमतें प्रत्येक वर्ष आधी हो जाती हैं","चिप पर ट्रांजिस्टरों की संख्या लगभग प्रत्येक दो वर्ष में दोगुनी हो जाती है","इंटरनेट की गति प्रत्येक छह महीने में दोगुनी हो जाती है"],"explanationHi":"1965 में मूर ने देखा कि ट्रांजिस्टरों की संख्या नियमित रूप से दोगुनी हो रही है, जिसे बाद में लगभग प्रत्येक दो वर्ष किया गया; इसी प्रवृत्ति ने कंप्यूटिंग शक्ति की तीव्र वृद्धि को गति दी।"},
  {"id":"comp-awareness-92","question":"A file with the extension .xlsx is created by default in:","options":["MS Access","MS Excel","MS PowerPoint","MS Word"],"answer":1,"explanation":".xlsx is the default workbook format of Excel 2007 and later. Word uses .docx, PowerPoint .pptx and Access .accdb.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk · SSC CHSL","questionHi":"एक्सटेंशन .xlsx वाली फ़ाइल डिफ़ॉल्ट रूप से किसमें बनती है?","optionsHi":["MS Access","MS Excel","MS PowerPoint","MS Word"],"explanationHi":".xlsx, Excel 2007 और उसके बाद का डिफ़ॉल्ट वर्कबुक फ़ॉर्मैट है। Word .docx, PowerPoint .pptx और Access .accdb का प्रयोग करते हैं।"},
  {"id":"comp-awareness-93","question":"The IEEE 802.11 family of standards defines:","options":["Ethernet (wired LAN)","Bluetooth","Wi-Fi (wireless LAN)","USB"],"answer":2,"explanation":"IEEE 802.11 covers wireless LANs, marketed as Wi-Fi. Wired Ethernet is IEEE 802.3, and Bluetooth was originally standardised as IEEE 802.15.1.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"IEEE 802.11 मानक परिवार किसे परिभाषित करता है?","optionsHi":["ईथरनेट (वायर्ड LAN)","ब्लूटूथ","Wi-Fi (वायरलेस LAN)","USB"],"explanationHi":"IEEE 802.11 वायरलेस LAN को कवर करता है, जिसे Wi-Fi नाम से बेचा जाता है। वायर्ड ईथरनेट IEEE 802.3 है, और ब्लूटूथ मूल रूप से IEEE 802.15.1 के रूप में मानकीकृत हुआ था।"},
  {"id":"comp-awareness-94","question":"The 4-bit two’s complement of the binary number 0101 is:","options":["1101","1010","0110","1011"],"answer":3,"explanation":"Two’s complement = one’s complement + 1: invert 0101 to 1010 and add 1 to get 1011, which represents −5. Stopping at 1010 gives only the one’s complement.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"बाइनरी संख्या 0101 का 4-बिट टू’ज़ कॉम्प्लिमेंट है:","optionsHi":["1101","1010","0110","1011"],"explanationHi":"टू’ज़ कॉम्प्लिमेंट = वन’ज़ कॉम्प्लिमेंट + 1: 0101 को उलटकर 1010 बनाएँ और 1 जोड़ें तो 1011 मिलता है, जो −5 को दर्शाता है। 1010 पर रुकने से केवल वन’ज़ कॉम्प्लिमेंट मिलता है।"},
  {"id":"comp-awareness-95","question":"Which MS Excel function looks for a value in the first column of a table and returns a value from another column in the same row?","options":["INDEX","MATCH","VLOOKUP","HLOOKUP"],"answer":2,"explanation":"VLOOKUP searches vertically down the first column; HLOOKUP searches along the first row. MATCH returns only the position of a value, and INDEX returns the value at a given position.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"MS Excel का कौन-सा फ़ंक्शन तालिका के पहले स्तंभ में किसी मान को खोजता है और उसी पंक्ति के किसी अन्य स्तंभ से मान लौटाता है?","optionsHi":["INDEX","MATCH","VLOOKUP","HLOOKUP"],"explanationHi":"VLOOKUP पहले स्तंभ में ऊर्ध्वाधर खोज करता है; HLOOKUP पहली पंक्ति में खोज करता है। MATCH केवल मान की स्थिति लौटाता है, और INDEX दी गई स्थिति का मान लौटाता है।"},
  {"id":"comp-awareness-96","question":"Which of the following is an example of Software as a Service (SaaS)?","options":["Google App Engine","A company’s own on-premises server","Google Docs","Amazon EC2 virtual machines"],"answer":2,"explanation":"With SaaS the user simply uses a finished application in the browser, such as Google Docs or Gmail. EC2 rents raw computing (IaaS) and App Engine gives a platform for building apps (PaaS).","difficulty":"hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"निम्नलिखित में से कौन-सा सॉफ्टवेयर एज़ ए सर्विस (SaaS) का उदाहरण है?","optionsHi":["Google App Engine","किसी कंपनी का अपना ऑन-प्रिमाइसेस सर्वर","Google Docs","Amazon EC2 वर्चुअल मशीनें"],"explanationHi":"SaaS में उपयोगकर्ता ब्राउज़र में बने-बनाए एप्लिकेशन का सीधे प्रयोग करता है, जैसे Google Docs या Gmail। EC2 कच्ची कंप्यूटिंग किराये पर देता है (IaaS) और App Engine ऐप बनाने का प्लेटफ़ॉर्म देता है (PaaS)।"},
  {"id":"comp-awareness-97","question":"In a CPU, the program counter holds:","options":["The result of the last calculation","The address of the next instruction to be fetched","The number of programs being run","The instruction now being decoded"],"answer":1,"explanation":"After each fetch the program counter is updated to point to the next instruction. The instruction being decoded sits in the instruction register, and results go to the accumulator or other registers.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"CPU में प्रोग्राम काउंटर क्या रखता है?","optionsHi":["पिछली गणना का परिणाम","लाए जाने वाले अगले निर्देश का पता","चल रहे प्रोग्रामों की संख्या","वर्तमान में डिकोड हो रहा निर्देश"],"explanationHi":"प्रत्येक फ़ेच के बाद प्रोग्राम काउंटर अगले निर्देश की ओर संकेत करने के लिए अद्यतन होता है। डिकोड हो रहा निर्देश इंस्ट्रक्शन रजिस्टर में रहता है, और परिणाम एक्युमुलेटर या अन्य रजिस्टरों में जाते हैं।"},
  {"id":"comp-awareness-98","question":"PARAM 8000, India’s first supercomputer, was built in 1991 by:","options":["BARC","C-DAC","ISRO","IIT Bombay"],"answer":1,"explanation":"The Centre for Development of Advanced Computing, Pune, built PARAM 8000 under Vijay Bhatkar after India was denied a Cray supercomputer. Later PARAM systems continue the series.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"भारत का पहला सुपरकंप्यूटर PARAM 8000 वर्ष 1991 में किसने बनाया?","optionsHi":["BARC","C-DAC","ISRO","IIT बॉम्बे"],"explanationHi":"भारत को Cray सुपरकंप्यूटर देने से इनकार किए जाने के बाद पुणे के प्रगत संगणन विकास केंद्र (C-DAC) ने विजय भटकर के नेतृत्व में PARAM 8000 बनाया। बाद के PARAM सिस्टम इसी शृंखला को आगे बढ़ाते हैं।"},
  {"id":"comp-awareness-99","question":"Restarting a computer that is already switched on, for example with the Restart option or Ctrl + Alt + Del, is called:","options":["Warm booting","Hibernation","Cold booting","Formatting"],"answer":0,"explanation":"Warm (soft) booting reloads the operating system without cutting the power. Cold booting starts the computer from a fully switched-off state.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk · SSC CHSL","questionHi":"पहले से चालू कंप्यूटर को पुनः आरंभ करना, उदाहरण के लिए Restart विकल्प या Ctrl + Alt + Del से, क्या कहलाता है?","optionsHi":["वार्म बूटिंग","हाइबरनेशन","कोल्ड बूटिंग","फ़ॉर्मैटिंग"],"explanationHi":"वार्म (सॉफ्ट) बूटिंग बिजली काटे बिना ऑपरेटिंग सिस्टम को फिर से लोड करती है। कोल्ड बूटिंग कंप्यूटर को पूरी तरह बंद अवस्था से शुरू करती है।"},
  {"id":"comp-awareness-100","question":"Which of the following is a private IPv4 address that cannot be routed on the public internet?","options":["11.0.0.1","192.168.10.5","172.32.0.1","8.8.8.8"],"answer":1,"explanation":"The private ranges are 10.0.0.0–10.255.255.255, 172.16.0.0–172.31.255.255 and 192.168.0.0–192.168.255.255. 172.32.0.1 lies just outside the 172 range, and 8.8.8.8 is Google’s public DNS server.","difficulty":"hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"निम्नलिखित में से कौन-सा निजी IPv4 पता है जिसे सार्वजनिक इंटरनेट पर रूट नहीं किया जा सकता?","optionsHi":["11.0.0.1","192.168.10.5","172.32.0.1","8.8.8.8"],"explanationHi":"निजी रेंज 10.0.0.0–10.255.255.255, 172.16.0.0–172.31.255.255 और 192.168.0.0–192.168.255.255 हैं। 172.32.0.1 172 की रेंज से ठीक बाहर है, और 8.8.8.8 Google का सार्वजनिक DNS सर्वर है।"},
  {"id":"comp-awareness-101","question":"Software that is distributed free for a trial period, after which the user is expected to pay for it, is called:","options":["Firmware","Open-source software","Shareware","Freeware"],"answer":2,"explanation":"Shareware is ‘try before you buy’. Freeware is free with no payment expected, open-source software makes its source code available, and firmware is software stored in hardware such as ROM.","difficulty":"hard","source":"IBPS Clerk · SBI Clerk · SSC CHSL","questionHi":"वह सॉफ्टवेयर जो परीक्षण अवधि के लिए निःशुल्क वितरित किया जाता है और जिसके बाद उपयोगकर्ता से उसके लिए भुगतान की अपेक्षा की जाती है, कहलाता है:","optionsHi":["फ़र्मवेयर","ओपन-सोर्स सॉफ्टवेयर","शेयरवेयर","फ़्रीवेयर"],"explanationHi":"शेयरवेयर का अर्थ है ‘पहले आज़माएँ, फिर खरीदें’। फ़्रीवेयर निःशुल्क होता है और उसमें भुगतान की अपेक्षा नहीं होती, ओपन-सोर्स सॉफ्टवेयर अपना स्रोत कोड उपलब्ध कराता है, और फ़र्मवेयर ROM जैसे हार्डवेयर में संग्रहीत सॉफ्टवेयर है।"},
  {"id":"comp-awareness-102","question":"A digital signature on an electronic document mainly ensures:","options":["That the document cannot be printed","The identity of the signer and that the document has not been altered","That the document is compressed","That the document is encrypted so nobody else can read it"],"answer":1,"explanation":"A digital signature uses the signer’s private key, and anyone can check it with the public key; it gives authenticity, integrity and non-repudiation but does not by itself keep the content secret.","difficulty":"hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"किसी इलेक्ट्रॉनिक दस्तावेज़ पर डिजिटल हस्ताक्षर मुख्य रूप से क्या सुनिश्चित करता है?","optionsHi":["कि दस्तावेज़ प्रिंट नहीं हो सकता","हस्ताक्षरकर्ता की पहचान और कि दस्तावेज़ में कोई परिवर्तन नहीं हुआ है","कि दस्तावेज़ संपीड़ित है","कि दस्तावेज़ एन्क्रिप्टेड है ताकि कोई और उसे पढ़ न सके"],"explanationHi":"डिजिटल हस्ताक्षर हस्ताक्षरकर्ता की निजी कुंजी का प्रयोग करता है, और कोई भी उसे सार्वजनिक कुंजी से जाँच सकता है; यह प्रामाणिकता, अखंडता और अस्वीकार-रोधन देता है, पर अपने आप में सामग्री को गोपनीय नहीं रखता।"},
  {"id":"comp-awareness-103","question":"How many of these statements about logic gates are correct? I. NOR is a universal gate. II. The output of an XOR gate is 1 when its two inputs are different. III. A NAND gate gives 0 only when all its inputs are 1. IV. The output of an AND gate is 1 only when all its inputs are 1.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: NOR is universal; XOR gives 1 for unequal inputs; NAND is the inverse of AND, so it is 0 only when all inputs are 1; and AND gives 1 only when all inputs are 1.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"लॉजिक गेटों के बारे में इनमें से कितने कथन सही हैं? I. NOR एक सार्वभौमिक गेट है। II. जब XOR गेट के दोनों इनपुट भिन्न होते हैं तो उसका आउटपुट 1 होता है। III. NAND गेट तभी 0 देता है जब उसके सभी इनपुट 1 हों। IV. AND गेट का आउटपुट तभी 1 होता है जब उसके सभी इनपुट 1 हों।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"सभी चारों सही हैं: NOR सार्वभौमिक है; XOR असमान इनपुट पर 1 देता है; NAND, AND का प्रतिलोम है, इसलिए वह तभी 0 होता है जब सभी इनपुट 1 हों; और AND तभी 1 देता है जब सभी इनपुट 1 हों।"},
  {"id":"comp-awareness-104","question":"The product of the binary numbers 1011 and 101 is:","options":["110111","111011","101101","110011"],"answer":0,"explanation":"1011 = 11 and 101 = 5 in decimal; 11 × 5 = 55 = 32 + 16 + 4 + 2 + 1 = 110111 in binary.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"बाइनरी संख्याओं 1011 और 101 का गुणनफल है:","optionsHi":["110111","111011","101101","110011"],"explanationHi":"दशमलव में 1011 = 11 और 101 = 5; 11 × 5 = 55 = 32 + 16 + 4 + 2 + 1 = बाइनरी में 110111।"},
  {"id":"comp-awareness-105","question":"Match the database term with its meaning: 1. Primary key 2. Foreign key 3. Tuple 4. Attribute; a. A column of a table b. A row of a table c. A field that refers to the primary key of another table d. A field that uniquely identifies each record","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a"],"answer":3,"explanation":"A primary key uniquely identifies each record; a foreign key links to another table’s primary key; in relational terms a tuple is a row (record) and an attribute is a column (field).","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"डेटाबेस शब्द का उसके अर्थ से मिलान कीजिए: 1. प्राइमरी की 2. फ़ॉरेन की 3. टपल 4. एट्रिब्यूट; a. तालिका का एक स्तंभ b. तालिका की एक पंक्ति c. ऐसा फ़ील्ड जो किसी अन्य तालिका की प्राइमरी की को संदर्भित करता है d. ऐसा फ़ील्ड जो प्रत्येक रिकॉर्ड की अद्वितीय पहचान करता है","optionsHi":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a"],"explanationHi":"प्राइमरी की प्रत्येक रिकॉर्ड की अद्वितीय पहचान करती है; फ़ॉरेन की किसी अन्य तालिका की प्राइमरी की से जुड़ती है; रिलेशनल शब्दावली में टपल पंक्ति (रिकॉर्ड) और एट्रिब्यूट स्तंभ (फ़ील्ड) होता है।"},
  {"id":"comp-awareness-106","question":"Assertion (A): A solid-state drive (SSD) usually reads and writes data much faster than a hard disk drive (HDD). Reason (R): An SSD stores data in flash memory chips and has no moving parts.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"An HDD must spin its platters and move a read–write head to the data, while an SSD reaches any location electronically, so access is far faster. R explains A.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"अभिकथन (A): सॉलिड-स्टेट ड्राइव (SSD) आमतौर पर हार्ड डिस्क ड्राइव (HDD) की तुलना में डेटा बहुत तेज़ी से पढ़ती और लिखती है। कारण (R): SSD डेटा को फ्लैश मेमोरी चिपों में संग्रहीत करती है और उसमें कोई गतिशील पुर्ज़ा नहीं होता।","optionsHi":["A और R दोनों सही हैं और R, A की व्याख्या करता है","A और R दोनों सही हैं, परंतु R, A की व्याख्या नहीं करता","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"HDD को अपनी प्लैटर घुमानी पड़ती है और रीड–राइट हेड को डेटा तक ले जाना पड़ता है, जबकि SSD किसी भी स्थान तक इलेक्ट्रॉनिक रूप से पहुँचती है, इसलिए उसकी पहुँच कहीं अधिक तेज़ है। R, A की व्याख्या करता है।"},
  {"id":"comp-awareness-107","question":"Arrange in chronological order: 1. Release of the IBM Personal Computer 2. Founding of Google 3. Unveiling of ENIAC 4. Tim Berners-Lee’s proposal for the World Wide Web","options":["1, 3, 4, 2","3, 4, 1, 2","3, 1, 2, 4","3, 1, 4, 2"],"answer":3,"explanation":"ENIAC was unveiled in 1946, the IBM PC came out in 1981, the World Wide Web was proposed in 1989 and Google was founded in 1998.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"कालक्रम में व्यवस्थित कीजिए: 1. IBM पर्सनल कंप्यूटर का जारी होना 2. Google की स्थापना 3. ENIAC का अनावरण 4. टिम बर्नर्स-ली द्वारा वर्ल्ड वाइड वेब का प्रस्ताव","optionsHi":["1, 3, 4, 2","3, 4, 1, 2","3, 1, 2, 4","3, 1, 4, 2"],"explanationHi":"ENIAC का अनावरण 1946 में हुआ, IBM PC 1981 में आया, वर्ल्ड वाइड वेब का प्रस्ताव 1989 में रखा गया और Google की स्थापना 1998 में हुई।"},
  {"id":"comp-awareness-108","question":"An uncompressed image of 1024 × 768 pixels uses 24-bit colour. Its size is (1 MB = 1024 × 1024 bytes):","options":["0.75 MB","2.25 MB","18 MB","24 MB"],"answer":1,"explanation":"Each pixel needs 24 bits = 3 bytes. Size = 1024 × 768 × 3 = 2,359,296 bytes = 2,359,296 ÷ 1,048,576 = 2.25 MB. Forgetting to convert bits to bytes gives 18 MB.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"1024 × 768 पिक्सेल की एक असंपीड़ित छवि 24-बिट रंग का प्रयोग करती है। उसका आकार है (1 MB = 1024 × 1024 बाइट):","optionsHi":["0.75 MB","2.25 MB","18 MB","24 MB"],"explanationHi":"प्रत्येक पिक्सेल को 24 बिट = 3 बाइट चाहिए। आकार = 1024 × 768 × 3 = 2,359,296 बाइट = 2,359,296 ÷ 1,048,576 = 2.25 MB। बिट को बाइट में बदलना भूलने पर 18 MB आता है।"},
  {"id":"comp-awareness-109","question":"How many of these statements about e-mail are correct? I. Recipients in the CC field are visible to all other recipients. II. Recipients in the BCC field are hidden from the other recipients. III. By default, IMAP downloads messages and deletes them from the server. IV. POP3 is the protocol used to send e-mail.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and II are correct. IMAP keeps mail on the server and syncs it across devices; downloading and deleting is typical of POP3, which is a protocol for receiving mail. Mail is sent with SMTP.","difficulty":"very-hard","source":"IBPS Clerk · SBI Clerk · SSC CHSL","questionHi":"ई-मेल के बारे में इनमें से कितने कथन सही हैं? I. CC क्षेत्र के प्राप्तकर्ता अन्य सभी प्राप्तकर्ताओं को दिखाई देते हैं। II. BCC क्षेत्र के प्राप्तकर्ता अन्य प्राप्तकर्ताओं से छिपे रहते हैं। III. डिफ़ॉल्ट रूप से IMAP संदेशों को डाउनलोड करके सर्वर से हटा देता है। IV. POP3 वह प्रोटोकॉल है जिससे ई-मेल भेजा जाता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और II सही हैं। IMAP मेल को सर्वर पर रखता है और उपकरणों में सिंक करता है; डाउनलोड करके हटाना POP3 की विशेषता है, जो मेल प्राप्त करने का प्रोटोकॉल है। मेल SMTP से भेजा जाता है।"},
  {"id":"comp-awareness-110","question":"Which of the following is NOT a function of an operating system?","options":["Compiling a program’s source code into machine code","Memory management","Scheduling processes on the CPU","Managing files and folders"],"answer":0,"explanation":"Compiling is done by a compiler, a separate language translator. The operating system manages memory, processes, files, devices and security.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"निम्नलिखित में से कौन-सा ऑपरेटिंग सिस्टम का कार्य नहीं है?","optionsHi":["प्रोग्राम के स्रोत कोड को मशीन कोड में संकलित करना","मेमोरी प्रबंधन","CPU पर प्रक्रियाओं का शेड्यूलिंग करना","फ़ाइलों और फ़ोल्डरों का प्रबंधन"],"explanationHi":"संकलन कंपाइलर करता है, जो एक अलग भाषा अनुवादक है। ऑपरेटिंग सिस्टम मेमोरी, प्रक्रियाओं, फ़ाइलों, उपकरणों और सुरक्षा का प्रबंधन करता है।"},
  {"id":"comp-awareness-111","question":"The hexadecimal number 3A is equal to which octal number?","options":["72","71","112","58"],"answer":0,"explanation":"3A₁₆ = 3 × 16 + 10 = 58 in decimal; 58 = 7 × 8 + 2, so it is 72 in octal. 58 is the decimal value, the usual trap.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"हेक्साडेसिमल संख्या 3A किस ऑक्टल संख्या के बराबर है?","optionsHi":["72","71","112","58"],"explanationHi":"3A₁₆ = 3 × 16 + 10 = दशमलव में 58; 58 = 7 × 8 + 2, इसलिए ऑक्टल में यह 72 है। 58 दशमलव मान है, जो सामान्य जाल है।"},
  {"id":"comp-awareness-112","question":"Assertion (A): Hexadecimal notation is widely used to write binary data such as memory addresses compactly. Reason (R): Each hexadecimal digit corresponds to exactly four binary digits.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because 16 = 2⁴, every group of four bits maps to one hex digit, so a 32-bit address fits in 8 hex digits and conversion is trivial. R explains A.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"अभिकथन (A): मेमोरी पतों जैसे बाइनरी डेटा को संक्षेप में लिखने के लिए हेक्साडेसिमल संकेतन का व्यापक प्रयोग होता है। कारण (R): प्रत्येक हेक्साडेसिमल अंक ठीक चार बाइनरी अंकों के संगत होता है।","optionsHi":["A और R दोनों सही हैं और R, A की व्याख्या करता है","A और R दोनों सही हैं, परंतु R, A की व्याख्या नहीं करता","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"चूँकि 16 = 2⁴, चार बिटों का प्रत्येक समूह एक हेक्स अंक से मेल खाता है, इसलिए 32-बिट पता 8 हेक्स अंकों में आ जाता है और रूपांतरण सरल होता है। R, A की व्याख्या करता है।"},
  {"id":"comp-awareness-113","question":"How many of these statements about cyber security are correct? I. A firewall can be implemented in hardware or in software. II. Two-factor authentication combines two different kinds of proof, such as a password and an OTP. III. In symmetric-key encryption the same key is used to encrypt and decrypt. IV. HTTPS sends data over the network as plain text.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: HTTPS encrypts traffic using TLS; it is plain HTTP that sends data as readable text.","difficulty":"very-hard","source":"IBPS PO · SBI PO · RRB NTPC","questionHi":"साइबर सुरक्षा के बारे में इनमें से कितने कथन सही हैं? I. फ़ायरवॉल को हार्डवेयर या सॉफ्टवेयर में लागू किया जा सकता है। II. टू-फ़ैक्टर ऑथेंटिकेशन दो भिन्न प्रकार के प्रमाणों को जोड़ता है, जैसे पासवर्ड और OTP। III. सममित-कुंजी एन्क्रिप्शन में एन्क्रिप्ट और डिक्रिप्ट करने के लिए एक ही कुंजी प्रयोग होती है। IV. HTTPS नेटवर्क पर डेटा को सादे पाठ के रूप में भेजता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: HTTPS, TLS का प्रयोग करके ट्रैफ़िक को एन्क्रिप्ट करता है; डेटा को पढ़ने योग्य पाठ के रूप में सादा HTTP भेजता है।"},
  {"id":"comp-awareness-114","question":"Match the MS Excel function with what it does: 1. SUMIF 2. CONCAT 3. TRIM 4. NOW; a. Returns the current date and time b. Removes extra spaces from text c. Joins several text strings into one d. Adds the cells that meet a given condition","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-d, 2-b, 3-c, 4-a"],"answer":2,"explanation":"SUMIF adds cells that meet a condition, CONCAT joins text, TRIM leaves only single spaces between words, and NOW returns the current date and time (TODAY returns only the date).","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"MS Excel फ़ंक्शन का उसके कार्य से मिलान कीजिए: 1. SUMIF 2. CONCAT 3. TRIM 4. NOW; a. वर्तमान दिनांक और समय लौटाता है b. पाठ से अतिरिक्त रिक्त स्थान हटाता है c. कई पाठ-स्ट्रिंग को एक में जोड़ता है d. दी गई शर्त पूरी करने वाले सेल को जोड़ता है","optionsHi":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-d, 2-b, 3-c, 4-a"],"explanationHi":"SUMIF शर्त पूरी करने वाले सेल जोड़ता है, CONCAT पाठ जोड़ता है, TRIM शब्दों के बीच केवल एक रिक्त स्थान छोड़ता है, और NOW वर्तमान दिनांक और समय लौटाता है (TODAY केवल दिनांक लौटाता है)।"},
  {"id":"comp-awareness-115","question":"Which generation of computers used integrated circuits (ICs) as the main electronic component?","options":["Fifth generation","First generation","Second generation","Third generation"],"answer":3,"explanation":"Third-generation computers (mid-1960s to early 1970s) used ICs. The first used vacuum tubes, the second transistors, and the fourth microprocessors (VLSI).","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"कंप्यूटरों की किस पीढ़ी में एकीकृत परिपथ (IC) मुख्य इलेक्ट्रॉनिक घटक के रूप में प्रयोग हुए?","optionsHi":["पाँचवीं पीढ़ी","प्रथम पीढ़ी","द्वितीय पीढ़ी","तृतीय पीढ़ी"],"explanationHi":"तृतीय पीढ़ी के कंप्यूटरों (1960 के दशक के मध्य से 1970 के दशक के आरंभ तक) में IC प्रयोग हुए। प्रथम में निर्वात नलिकाएँ, द्वितीय में ट्रांजिस्टर, और चतुर्थ में माइक्रोप्रोसेसर (VLSI) थे।"},
  {"id":"comp-awareness-116","question":"A device that works at the Data Link layer and forwards frames only to the port where the destination MAC address is connected is a:","options":["Hub","Switch","Repeater","Modem"],"answer":1,"explanation":"A switch learns MAC addresses and forwards each frame to the right port. A hub simply repeats every signal to all ports (Physical layer), as does a repeater.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"डेटा लिंक परत पर कार्य करने वाला वह उपकरण जो फ़्रेमों को केवल उसी पोर्ट पर भेजता है जहाँ गंतव्य MAC पता जुड़ा है, कहलाता है:","optionsHi":["हब","स्विच","रिपीटर","मॉडेम"],"explanationHi":"स्विच MAC पते सीखता है और प्रत्येक फ़्रेम को सही पोर्ट पर भेजता है। हब हर सिग्नल को सभी पोर्ट पर दोहरा देता है (भौतिक परत), रिपीटर भी ऐसा ही करता है।"},
  {"id":"comp-awareness-117","question":"How many layers does the OSI reference model have?","options":["7","4","5","6"],"answer":0,"explanation":"The OSI model has 7 layers: Physical, Data Link, Network, Transport, Session, Presentation and Application. The TCP/IP model is the one usually described with 4 layers.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"OSI संदर्भ मॉडल में कितनी परतें होती हैं?","optionsHi":["7","4","5","6"],"explanationHi":"OSI मॉडल में 7 परतें हैं: भौतिक, डेटा लिंक, नेटवर्क, ट्रांसपोर्ट, सेशन, प्रेजेंटेशन और एप्लिकेशन। TCP/IP मॉडल को सामान्यतः 4 परतों वाला बताया जाता है।"},
  {"id":"comp-awareness-118","question":"Which of the following storage units is the largest?","options":["1 Gigabyte","1 Terabyte","1 Petabyte","1000 Megabytes"],"answer":2,"explanation":"Order: MB < GB < TB < PB. 1 PB = 1024 TB, so it is the largest; 1000 MB is less than 1 GB.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"निम्नलिखित संग्रहण इकाइयों में सबसे बड़ी कौन-सी है?","optionsHi":["1 गीगाबाइट","1 टेराबाइट","1 पेटाबाइट","1000 मेगाबाइट"],"explanationHi":"क्रम: MB < GB < TB < PB। 1 PB = 1024 TB, इसलिए यह सबसे बड़ी है; 1000 MB, 1 GB से कम है।"},
  {"id":"comp-awareness-119","question":"What is the decimal value of the binary number 1101.101?","options":["13.625","13.5","11.625","13.3125"],"answer":0,"explanation":"Integer part 1101 = 8 + 4 + 0 + 1 = 13; fractional part .101 = 1/2 + 0/4 + 1/8 = 0.625, total 13.625. Reading .101 as decimal five-tenths gives 13.5, starting the fractional weights at 1/4 (an off-by-one) gives 13.3125, and misreading 1101 as 1011 gives 11.625.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"बाइनरी संख्या 1101.101 का दशमलव मान क्या है?","optionsHi":["13.625","13.5","11.625","13.3125"],"explanationHi":"पूर्णांक भाग 1101 = 8 + 4 + 0 + 1 = 13; भिन्न भाग .101 = 1/2 + 0/4 + 1/8 = 0.625, कुल 13.625। .101 को दशमलव का पाँच-दशांश पढ़ने पर 13.5 आता है, भिन्न के भार 1/4 से शुरू करने पर (एक स्थान की चूक) 13.3125 आता है, और 1101 को 1011 पढ़ने पर 11.625 आता है।"},
  {"id":"comp-awareness-120","question":"Convert (777)₈ into base 10.","options":["777","511","512","448"],"answer":1,"explanation":"7×64 + 7×8 + 7 = 448 + 56 + 7 = 511. It is one less than 8³ = 512, just as 999 is one less than 10³.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"(777)₈ को आधार 10 में बदलिए।","optionsHi":["777","511","512","448"],"explanationHi":"7×64 + 7×8 + 7 = 448 + 56 + 7 = 511। यह 8³ = 512 से एक कम है, ठीक वैसे ही जैसे 999, 10³ से एक कम है।"},
  {"id":"comp-awareness-121","question":"Which Boolean expression is equal to A + A·B?","options":["A·B","B","A","A + B"],"answer":2,"explanation":"By the absorption law, A + AB = A(1 + B) = A·1 = A. A + B would come from A + A'B, a different expression.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"कौन-सा बूलियन व्यंजक A + A·B के बराबर है?","optionsHi":["A·B","B","A","A + B"],"explanationHi":"अवशोषण नियम से, A + AB = A(1 + B) = A·1 = A। A + B, A + A'B से आता, जो एक भिन्न व्यंजक है।"},
  {"id":"comp-awareness-122","question":"A logic gate gives output 1 only when its two inputs are different. The gate is:","options":["OR","XNOR","NAND","XOR"],"answer":3,"explanation":"XOR (exclusive OR) is 1 for inputs 01 and 10. XNOR is its complement (1 when inputs are equal); OR is also 1 for input 11.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"कोई लॉजिक गेट केवल तभी आउटपुट 1 देता है जब उसके दोनों इनपुट भिन्न हों। वह गेट है:","optionsHi":["OR","XNOR","NAND","XOR"],"explanationHi":"XOR (एक्सक्लूसिव OR) इनपुट 01 और 10 पर 1 देता है। XNOR उसका पूरक है (इनपुट समान होने पर 1); OR इनपुट 11 पर भी 1 देता है।"},
  {"id":"comp-awareness-123","question":"In the OSI model, encryption, compression and translation of data formats are functions of which layer?","options":["Transport layer","Session layer","Application layer","Presentation layer"],"answer":3,"explanation":"The Presentation layer (layer 6) handles data representation: translation, encryption and compression. The Session layer manages dialogue/sessions; the Transport layer handles end-to-end delivery.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"OSI मॉडल में डेटा प्रारूपों का एन्क्रिप्शन, संपीड़न और अनुवाद किस परत के कार्य हैं?","optionsHi":["ट्रांसपोर्ट परत","सेशन परत","एप्लिकेशन परत","प्रेजेंटेशन परत"],"explanationHi":"प्रेजेंटेशन परत (परत 6) डेटा निरूपण संभालती है: अनुवाद, एन्क्रिप्शन और संपीड़न। सेशन परत संवाद/सत्रों का प्रबंधन करती है; ट्रांसपोर्ट परत सिरे-से-सिरे तक डिलीवरी संभालती है।"},
  {"id":"comp-awareness-124","question":"Standard ASCII uses how many bits to represent a character, and so how many characters can it represent?","options":["16 bits, 65,536 characters","8 bits, 256 characters","7 bits, 128 characters","6 bits, 64 characters"],"answer":2,"explanation":"Standard ASCII is a 7-bit code with 2⁷ = 128 characters. 8-bit/256 describes 'extended ASCII', a common trap.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"मानक ASCII किसी वर्ण को निरूपित करने के लिए कितने बिट का प्रयोग करता है, और इसलिए कितने वर्ण निरूपित कर सकता है?","optionsHi":["16 बिट, 65,536 वर्ण","8 बिट, 256 वर्ण","7 बिट, 128 वर्ण","6 बिट, 64 वर्ण"],"explanationHi":"मानक ASCII 7-बिट कोड है जिसमें 2⁷ = 128 वर्ण हैं। 8-बिट/256 ‘विस्तारित ASCII’ का वर्णन है, जो एक सामान्य जाल है।"},
  {"id":"comp-awareness-125","question":"A single-layer, single-sided DVD has a standard capacity of about:","options":["700 MB","4.7 GB","25 GB","8.5 GB"],"answer":1,"explanation":"A single-layer DVD stores about 4.7 GB. 700 MB is a CD, 25 GB a single-layer Blu-ray disc, and 8.5 GB a dual-layer DVD.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"एकल-परत, एकल-पक्षीय DVD की मानक क्षमता लगभग कितनी होती है?","optionsHi":["700 MB","4.7 GB","25 GB","8.5 GB"],"explanationHi":"एकल-परत DVD लगभग 4.7 GB संग्रहीत करती है। 700 MB CD की क्षमता है, 25 GB एकल-परत ब्लू-रे डिस्क की, और 8.5 GB द्वि-परत DVD की।"},
  {"id":"comp-awareness-126","question":"In the IPv4 address 127.0.0.1, the address refers to:","options":["The loopback address of the local computer itself","The default gateway of the network","A public web server","The broadcast address of a class A network"],"answer":0,"explanation":"The 127.0.0.0/8 block is reserved for loopback; 127.0.0.1 ('localhost') points back to the same machine. It is never a gateway or public address.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"IPv4 पता 127.0.0.1 किसे संदर्भित करता है?","optionsHi":["स्थानीय कंप्यूटर के स्वयं के लूपबैक पते को","नेटवर्क के डिफ़ॉल्ट गेटवे को","किसी सार्वजनिक वेब सर्वर को","क्लास A नेटवर्क के ब्रॉडकास्ट पते को"],"explanationHi":"127.0.0.0/8 ब्लॉक लूपबैक के लिए आरक्षित है; 127.0.0.1 (‘localhost’) उसी मशीन की ओर संकेत करता है। यह कभी गेटवे या सार्वजनिक पता नहीं होता।"},
  {"id":"comp-awareness-127","question":"What is the 8-bit two's complement representation of −5?","options":["10000101","11111010","11111011","00000101"],"answer":2,"explanation":"+5 = 00000101; one's complement = 11111010; add 1 → 11111011. 11111010 is only the one's complement, and 10000101 is the sign-magnitude form.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"−5 का 8-बिट टू’ज़ कॉम्प्लिमेंट निरूपण क्या है?","optionsHi":["10000101","11111010","11111011","00000101"],"explanationHi":"+5 = 00000101; वन’ज़ कॉम्प्लिमेंट = 11111010; 1 जोड़ने पर → 11111011। 11111010 केवल वन’ज़ कॉम्प्लिमेंट है, और 10000101 साइन-मैग्निट्यूड रूप है।"},
  {"id":"comp-awareness-128","question":"The hexadecimal number ABC is equal to which decimal number?","options":["2478","2748","2740","3020"],"answer":1,"explanation":"A=10, B=11, C=12: 10×256 + 11×16 + 12 = 2560 + 176 + 12 = 2748.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"हेक्साडेसिमल संख्या ABC किस दशमलव संख्या के बराबर है?","optionsHi":["2478","2748","2740","3020"],"explanationHi":"A=10, B=11, C=12: 10×256 + 11×16 + 12 = 2560 + 176 + 12 = 2748।"},
  {"id":"comp-awareness-129","question":"The decimal fraction 0.375 written in binary is:","options":["0.110","0.101","0.0011","0.011"],"answer":3,"explanation":"0.375×2 = 0.75 → 0; 0.75×2 = 1.5 → 1; 0.5×2 = 1.0 → 1. Reading the integer parts in order gives 0.011 (= 1/4 + 1/8).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"दशमलव भिन्न 0.375 को बाइनरी में लिखने पर प्राप्त होता है:","optionsHi":["0.110","0.101","0.0011","0.011"],"explanationHi":"0.375×2 = 0.75 → 0; 0.75×2 = 1.5 → 1; 0.5×2 = 1.0 → 1। पूर्णांक भागों को क्रम से पढ़ने पर 0.011 (= 1/4 + 1/8) मिलता है।"},
  {"id":"comp-awareness-130","question":"What is the result of the binary subtraction 11010 − 1101?","options":["1101","1011","1111","10011"],"answer":0,"explanation":"Convert to check: 11010 = 26 and 1101 = 13, so 26 − 13 = 13 = 1101. When borrowing, remember that 10₂ − 1 = 1; forgetting a borrow gives answers like 1111 or 10011.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"बाइनरी व्यवकलन 11010 − 1101 का परिणाम क्या है?","optionsHi":["1101","1011","1111","10011"],"explanationHi":"जाँचने के लिए रूपांतरण करें: 11010 = 26 और 1101 = 13, इसलिए 26 − 13 = 13 = 1101। उधार लेते समय याद रखें कि 10₂ − 1 = 1; उधार भूलने पर 1111 या 10011 जैसे उत्तर आते हैं।"},
  {"id":"comp-awareness-131","question":"The Binary Coded Decimal (8421 BCD) representation of the decimal number 59 is:","options":["0111 0011","0011 1011","0101 1010","0101 1001"],"answer":3,"explanation":"In BCD each decimal digit is coded separately in 4 bits: 5 = 0101, 9 = 1001. 0011 1011 is the pure binary of 59, a common trap.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"दशमलव संख्या 59 का बाइनरी कोडित दशमलव (8421 BCD) निरूपण है:","optionsHi":["0111 0011","0011 1011","0101 1010","0101 1001"],"explanationHi":"BCD में प्रत्येक दशमलव अंक को 4 बिट में अलग से कोडित किया जाता है: 5 = 0101, 9 = 1001। 0011 1011, 59 का शुद्ध बाइनरी रूप है, जो सामान्य जाल है।"},
  {"id":"comp-awareness-132","question":"A memory chip has 16 address lines and each location stores 1 byte. Its capacity is:","options":["32 KB","16 KB","64 KB","128 KB"],"answer":2,"explanation":"16 address lines can select 2¹⁶ = 65,536 locations; at 1 byte each, that is 65,536 bytes = 64 KB.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"एक मेमोरी चिप में 16 एड्रेस लाइनें हैं और प्रत्येक स्थान 1 बाइट संग्रहीत करता है। उसकी क्षमता है:","optionsHi":["32 KB","16 KB","64 KB","128 KB"],"explanationHi":"16 एड्रेस लाइनें 2¹⁶ = 65,536 स्थानों का चयन कर सकती हैं; प्रति स्थान 1 बाइट होने पर यह 65,536 बाइट = 64 KB है।"},
  {"id":"comp-awareness-133","question":"What is the minimum number of bits needed to give a unique binary code to 1000 different items?","options":["10","9","11","1000"],"answer":0,"explanation":"2⁹ = 512 is too small and 2¹⁰ = 1024 is enough, so 10 bits are needed.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"1000 भिन्न वस्तुओं को अद्वितीय बाइनरी कोड देने के लिए न्यूनतम कितने बिट चाहिए?","optionsHi":["10","9","11","1000"],"explanationHi":"2⁹ = 512 बहुत कम है और 2¹⁰ = 1024 पर्याप्त है, इसलिए 10 बिट चाहिए।"},
  {"id":"comp-awareness-134","question":"The range of integers that can be stored in 8 bits using two's complement is:","options":["−127 to +127","−128 to +127","0 to 255","−256 to +255"],"answer":1,"explanation":"Two's complement in n bits covers −2ⁿ⁻¹ to 2ⁿ⁻¹ − 1, i.e. −128 to +127. −127 to +127 is the range in sign-magnitude or one's complement, which have two zeros.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"टू’ज़ कॉम्प्लिमेंट में 8 बिट में संग्रहीत हो सकने वाले पूर्णांकों की रेंज है:","optionsHi":["−127 से +127","−128 से +127","0 से 255","−256 से +255"],"explanationHi":"n बिट में टू’ज़ कॉम्प्लिमेंट −2ⁿ⁻¹ से 2ⁿ⁻¹ − 1 तक आता है, अर्थात् −128 से +127। −127 से +127 साइन-मैग्निट्यूड या वन’ज़ कॉम्प्लिमेंट की रेंज है, जिनमें दो शून्य होते हैं।"},
  {"id":"comp-awareness-135","question":"By De Morgan's theorem, the complement of (A + B) is equal to:","options":["A′ + B′","A′ · B′","A · B","(A · B)′"],"answer":1,"explanation":"(A + B)′ = A′·B′, which is why a NOR gate equals an AND gate with inverted inputs. A′ + B′ is the complement of A·B, the other De Morgan law.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"डी मॉर्गन प्रमेय के अनुसार (A + B) का पूरक किसके बराबर है?","optionsHi":["A′ + B′","A′ · B′","A · B","(A · B)′"],"explanationHi":"(A + B)′ = A′·B′, इसीलिए NOR गेट उलटे इनपुट वाले AND गेट के बराबर होता है। A′ + B′, A·B का पूरक है, जो डी मॉर्गन का दूसरा नियम है।"},
  {"id":"comp-awareness-136","question":"In which situation does an operating system suffer from 'thrashing'?","options":["The hard disk develops bad sectors","Two processes wait forever for resources held by each other","A low-priority process never gets the CPU","It spends more time swapping pages between memory and disk than executing processes"],"answer":3,"explanation":"Thrashing is excessive paging when processes do not have enough frames. Processes waiting on each other is deadlock; a process never getting the CPU is starvation.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"किस स्थिति में ऑपरेटिंग सिस्टम ‘थ्रैशिंग’ से ग्रस्त होता है?","optionsHi":["हार्ड डिस्क में खराब सेक्टर आ जाते हैं","दो प्रक्रियाएँ एक-दूसरे द्वारा रखे गए संसाधनों की अनंत प्रतीक्षा करती हैं","कम प्राथमिकता वाली प्रक्रिया को कभी CPU नहीं मिलता","वह प्रक्रियाओं को निष्पादित करने की अपेक्षा मेमोरी और डिस्क के बीच पेज अदला-बदली में अधिक समय लगाता है"],"explanationHi":"थ्रैशिंग अत्यधिक पेजिंग है, जो तब होती है जब प्रक्रियाओं के पास पर्याप्त फ़्रेम नहीं होते। प्रक्रियाओं का एक-दूसरे की प्रतीक्षा करना डेडलॉक है; किसी प्रक्रिया को कभी CPU न मिलना स्टार्वेशन है।"},
  {"id":"comp-awareness-137","question":"In a class C network with subnet mask 255.255.255.0, how many usable host addresses are available?","options":["254","256","255","65,534"],"answer":0,"explanation":"A /24 mask leaves 8 host bits: 2⁸ = 256 addresses, minus the network and broadcast addresses = 254 usable hosts. Forgetting to subtract gives 256, subtracting only one gives 255, and 65,534 is the class B (/16) figure.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"सबनेट मास्क 255.255.255.0 वाले क्लास C नेटवर्क में कितने प्रयोग-योग्य होस्ट पते उपलब्ध होते हैं?","optionsHi":["254","256","255","65,534"],"explanationHi":"/24 मास्क 8 होस्ट बिट छोड़ता है: 2⁸ = 256 पते, घटाएँ नेटवर्क और ब्रॉडकास्ट पते = 254 प्रयोग-योग्य होस्ट। घटाना भूलने पर 256, केवल एक घटाने पर 255 आता है, और 65,534 क्लास B (/16) का आँकड़ा है।"},
  {"id":"comp-awareness-138","question":"Which program combines several object files and library routines into a single executable file?","options":["Assembler","Loader","Linker","Interpreter"],"answer":2,"explanation":"The linker joins object modules into one executable. The loader then places the executable in memory to run it; the assembler converts assembly into object code.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"कौन-सा प्रोग्राम कई ऑब्जेक्ट फ़ाइलों और लाइब्रेरी रूटीनों को जोड़कर एक एक्ज़ीक्यूटेबल फ़ाइल बनाता है?","optionsHi":["असेंबलर","लोडर","लिंकर","इंटरप्रेटर"],"explanationHi":"लिंकर ऑब्जेक्ट मॉड्यूलों को जोड़कर एक एक्ज़ीक्यूटेबल बनाता है। उसके बाद लोडर एक्ज़ीक्यूटेबल को चलाने के लिए मेमोरी में रखता है; असेंबलर असेंबली को ऑब्जेक्ट कोड में बदलता है।"},
  {"id":"comp-awareness-139","question":"TCP and UDP are protocols of which OSI layer, and which of them guarantees ordered, reliable delivery?","options":["Transport layer; TCP","Network layer; UDP","Transport layer; UDP","Session layer; TCP"],"answer":0,"explanation":"Both work at the Transport layer. TCP is connection-oriented with acknowledgements and ordering; UDP is connectionless and faster but unreliable.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"TCP और UDP किस OSI परत के प्रोटोकॉल हैं, और इनमें से कौन क्रमबद्ध, विश्वसनीय डिलीवरी की गारंटी देता है?","optionsHi":["ट्रांसपोर्ट परत; TCP","नेटवर्क परत; UDP","ट्रांसपोर्ट परत; UDP","सेशन परत; TCP"],"explanationHi":"दोनों ट्रांसपोर्ट परत पर काम करते हैं। TCP कनेक्शन-उन्मुख है और पावती तथा क्रम सुनिश्चित करता है; UDP कनेक्शन-रहित और तेज़ है, पर अविश्वसनीय है।"},
  {"id":"comp-awareness-140","question":"The Excess-3 code of the decimal digit 4 is:","options":["1000","0100","0011","0111"],"answer":3,"explanation":"Excess-3 adds 3 to the digit before converting: 4 + 3 = 7 = 0111. 0100 is plain BCD of 4.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"दशमलव अंक 4 का एक्सेस-3 कोड है:","optionsHi":["1000","0100","0011","0111"],"explanationHi":"एक्सेस-3 में अंक को बदलने से पहले उसमें 3 जोड़ा जाता है: 4 + 3 = 7 = 0111। 0100, 4 का सादा BCD है।"},
  {"id":"comp-awareness-141","question":"A processor negates the 8-bit value 00101100 using two's complement. Which bit pattern does it produce?","options":["11010011","11010100","11010101","10101100"],"answer":1,"explanation":"One's complement of 00101100 is 11010011; adding 1 gives 11010100. 11010011 is only the one's complement. Check: 00101100 + 11010100 = 1 00000000 (carry discarded).","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"एक प्रोसेसर 8-बिट मान 00101100 को टू’ज़ कॉम्प्लिमेंट से ऋणात्मक बनाता है। वह कौन-सा बिट पैटर्न देता है?","optionsHi":["11010011","11010100","11010101","10101100"],"explanationHi":"00101100 का वन’ज़ कॉम्प्लिमेंट 11010011 है; 1 जोड़ने पर 11010100 मिलता है। 11010011 केवल वन’ज़ कॉम्प्लिमेंट है। जाँच: 00101100 + 11010100 = 1 00000000 (कैरी छोड़ दी जाती है)।"},
  {"id":"comp-awareness-142","question":"The binary number 1011 converted into Gray code is:","options":["1011","1101","1110","0110"],"answer":2,"explanation":"Gray code: keep the MSB (1), then XOR each pair of adjacent bits: 1⊕0 = 1, 0⊕1 = 1, 1⊕1 = 0. Result 1110.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"बाइनरी संख्या 1011 को ग्रे कोड में बदलने पर प्राप्त होता है:","optionsHi":["1011","1101","1110","0110"],"explanationHi":"ग्रे कोड: MSB (1) को वैसा ही रखें, फिर आसन्न बिटों के प्रत्येक युग्म का XOR लें: 1⊕0 = 1, 0⊕1 = 1, 1⊕1 = 0। परिणाम 1110।"},
  {"id":"comp-awareness-143","question":"(FF)₁₆ + (1)₁₆ − (100)₈ equals which decimal number?","options":["156","256","192","200"],"answer":2,"explanation":"FF + 1 = 100₁₆ = 256; 100₈ = 64. 256 − 64 = 192. Reading 100₈ as 100 decimal gives the trap 156.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"(FF)₁₆ + (1)₁₆ − (100)₈ किस दशमलव संख्या के बराबर है?","optionsHi":["156","256","192","200"],"explanationHi":"FF + 1 = 100₁₆ = 256; 100₈ = 64। 256 − 64 = 192। 100₈ को दशमलव 100 पढ़ने पर जाल वाला उत्तर 156 आता है।"},
  {"id":"comp-awareness-144","question":"What is the product of the binary numbers 1010 and 111, expressed in binary?","options":["1010111","1000110","1000100","111110"],"answer":1,"explanation":"1010 = 10 and 111 = 7, so the product is 70 = 64 + 4 + 2 = 1000110. 1010111 simply joins the two numbers together, and 1000100 (68) comes from dropping a carry while adding the shifted partial products.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"बाइनरी संख्याओं 1010 और 111 का गुणनफल बाइनरी में क्या है?","optionsHi":["1010111","1000110","1000100","111110"],"explanationHi":"1010 = 10 और 111 = 7, इसलिए गुणनफल 70 = 64 + 4 + 2 = 1000110 है। 1010111 दोनों संख्याओं को केवल जोड़कर लिख देता है, और 1000100 (68) खिसकाए गए आंशिक गुणनफलों को जोड़ते समय कैरी छोड़ देने से आता है।"},
  {"id":"comp-awareness-145","question":"A network uses the subnet mask 255.255.255.192 (/26). How many usable host addresses does each subnet have?","options":["30","64","126","62"],"answer":3,"explanation":"/26 leaves 32 − 26 = 6 host bits: 2⁶ = 64 addresses minus network and broadcast = 62. 126 is for /25 and 30 for /27.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"एक नेटवर्क सबनेट मास्क 255.255.255.192 (/26) का प्रयोग करता है। प्रत्येक सबनेट में कितने प्रयोग-योग्य होस्ट पते होते हैं?","optionsHi":["30","64","126","62"],"explanationHi":"/26 में 32 − 26 = 6 होस्ट बिट बचते हैं: 2⁶ = 64 पते, घटाएँ नेटवर्क और ब्रॉडकास्ट = 62। 126 /25 के लिए और 30 /27 के लिए है।"},
  {"id":"comp-awareness-146","question":"A 32-bit memory address is written in hexadecimal. How many hexadecimal digits does it take, and what is the largest address?","options":["8 digits; FFFFFFFF","4 digits; FFFF","8 digits; 99999999","16 digits; FFFFFFFFFFFFFFFF"],"answer":0,"explanation":"Each hex digit stands for 4 bits, so 32 bits need 8 hex digits; the largest is all ones = FFFFFFFF. 99999999 is not the maximum since hex digits go up to F.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"32-बिट मेमोरी पता हेक्साडेसिमल में लिखा जाता है। इसमें कितने हेक्साडेसिमल अंक लगते हैं, और सबसे बड़ा पता क्या है?","optionsHi":["8 अंक; FFFFFFFF","4 अंक; FFFF","8 अंक; 99999999","16 अंक; FFFFFFFFFFFFFFFF"],"explanationHi":"प्रत्येक हेक्स अंक 4 बिट का प्रतिनिधित्व करता है, इसलिए 32 बिट के लिए 8 हेक्स अंक चाहिए; सबसे बड़ा पता सभी बिट 1 होने पर FFFFFFFF है। 99999999 अधिकतम नहीं है, क्योंकि हेक्स अंक F तक जाते हैं।"},
  {"id":"comp-awareness-147","question":"Convert (345)₈ directly into base 16.","options":["159","D5","E5","E9"],"answer":2,"explanation":"345₈ = 011 100 101 in binary = 1110 0101 regrouped in fours = E5₁₆. Check: 3×64 + 4×8 + 5 = 229 = 14×16 + 5. 159 is just a wrong regrouping.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"(345)₈ को सीधे आधार 16 में बदलिए।","optionsHi":["159","D5","E5","E9"],"explanationHi":"345₈ = बाइनरी में 011 100 101 = चार-चार के समूह में पुनः बाँटने पर 1110 0101 = E5₁₆। जाँच: 3×64 + 4×8 + 5 = 229 = 14×16 + 5। 159 केवल गलत पुनर्समूहन है।"},
  {"id":"comp-awareness-148","question":"In which of the following is the Boolean identity stated INCORRECTLY?","options":["A + A′·B = A·B","A·(A + B) = A","A + A′ = 1","(A′)′ = A"],"answer":0,"explanation":"A + A′B simplifies to A + B, not AB. The others are correct: absorption A(A+B) = A, the complement law A + A′ = 1, and double complement (A′)′ = A.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"निम्नलिखित में से किसमें बूलियन सर्वसमिका गलत कही गई है?","optionsHi":["A + A′·B = A·B","A·(A + B) = A","A + A′ = 1","(A′)′ = A"],"explanationHi":"A + A′B का सरलीकरण A + B होता है, AB नहीं। शेष सही हैं: अवशोषण A(A+B) = A, पूरक नियम A + A′ = 1, और दोहरा पूरक (A′)′ = A।"},
  {"id":"comp-awareness-149","question":"A NAND gate has its two inputs tied together and fed with the signal X. The output is:","options":["X (it acts as a buffer)","X′ (it acts as a NOT gate)","Always 1","Always 0"],"answer":1,"explanation":"(X·X)′ = X′, so a NAND with joined inputs is an inverter — the first step in showing NAND is universal. It is always 1 only when at least one input is 0.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"एक NAND गेट के दोनों इनपुट जोड़ दिए गए हैं और उनमें सिग्नल X दिया गया है। आउटपुट है:","optionsHi":["X (यह बफ़र की तरह कार्य करता है)","X′ (यह NOT गेट की तरह कार्य करता है)","सदैव 1","सदैव 0"],"explanationHi":"(X·X)′ = X′, इसलिए जुड़े इनपुट वाला NAND एक इन्वर्टर है — यह NAND के सार्वभौमिक होने को दिखाने का पहला चरण है। आउटपुट सदैव 1 तभी होता है जब कम से कम एक इनपुट 0 हो।"},
  {"id":"comp-awareness-150","question":"How many of these statements about computer memory are correct? I. SRAM is used for cache and does not need refreshing. II. EEPROM is erased by exposing the chip to ultraviolet light. III. Flash memory is a type of EEPROM. IV. Registers are slower than cache memory.","options":["Only one","Only two","All four","Only three"],"answer":1,"explanation":"I and III are correct. II is wrong: UV erasure is for EPROM; EEPROM is erased electrically. IV is wrong: registers inside the CPU are the fastest memory of all, faster than cache.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"कंप्यूटर मेमोरी के बारे में इनमें से कितने कथन सही हैं? I. SRAM कैश के लिए प्रयोग होती है और उसे रिफ़्रेश की आवश्यकता नहीं होती। II. EEPROM को चिप पर पराबैंगनी प्रकाश डालकर मिटाया जाता है। III. फ्लैश मेमोरी EEPROM का एक प्रकार है। IV. रजिस्टर कैश मेमोरी से धीमे होते हैं।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"I और III सही हैं। II गलत है: UV से मिटाना EPROM के लिए है; EEPROM विद्युत से मिटाई जाती है। IV गलत है: CPU के भीतर के रजिस्टर सबसे तेज़ मेमोरी हैं, कैश से भी तेज़।"},
  {"id":"comp-awareness-151","question":"A sound file is recorded at 44,100 samples per second, 16 bits per sample, in stereo (2 channels). Ignoring compression, how many bytes does one second of audio take?","options":["7,05,600 bytes","88,200 bytes","14,11,200 bytes","1,76,400 bytes"],"answer":3,"explanation":"44,100 × 16 × 2 = 14,11,200 bits per second; ÷ 8 = 1,76,400 bytes. 14,11,200 is the bit figure, a trap for forgetting to divide by 8; 88,200 forgets the second channel.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"एक ध्वनि फ़ाइल 44,100 नमूने प्रति सेकंड, प्रति नमूना 16 बिट, स्टीरियो (2 चैनल) में रिकॉर्ड की गई है। संपीड़न की उपेक्षा करने पर ऑडियो का एक सेकंड कितने बाइट लेता है?","optionsHi":["7,05,600 बाइट","88,200 बाइट","14,11,200 बाइट","1,76,400 बाइट"],"explanationHi":"44,100 × 16 × 2 = 14,11,200 बिट प्रति सेकंड; ÷ 8 = 1,76,400 बाइट। 14,11,200 बिट का आँकड़ा है, जो 8 से भाग देना भूलने का जाल है; 88,200 दूसरा चैनल भूल जाता है।"},
  {"id":"comp-awareness-152","question":"Which of these is the correct order of the OSI layers from the bottom (layer 1) up to layer 4?","options":["Data Link, Physical, Transport, Network","Physical, Network, Data Link, Transport","Physical, Data Link, Network, Transport","Physical, Data Link, Transport, Network"],"answer":2,"explanation":"Layer 1 Physical, 2 Data Link, 3 Network, 4 Transport, then Session, Presentation and Application.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"OSI परतों का सबसे नीचे (परत 1) से परत 4 तक का सही क्रम इनमें से कौन-सा है?","optionsHi":["डेटा लिंक, भौतिक, ट्रांसपोर्ट, नेटवर्क","भौतिक, नेटवर्क, डेटा लिंक, ट्रांसपोर्ट","भौतिक, डेटा लिंक, नेटवर्क, ट्रांसपोर्ट","भौतिक, डेटा लिंक, ट्रांसपोर्ट, नेटवर्क"],"explanationHi":"परत 1 भौतिक, 2 डेटा लिंक, 3 नेटवर्क, 4 ट्रांसपोर्ट, फिर सेशन, प्रेजेंटेशन और एप्लिकेशन।"},
  {"id":"comp-awareness-153","question":"How many of these statements about IPv4 addressing are correct? I. A class A address has a first octet from 1 to 126. II. 172.32.5.4 is a private address. III. 192.168.10.0/24 has 256 usable host addresses. IV. 255.255.255.255 is the loopback address.","options":["Only three","All four","Only two","Only one"],"answer":3,"explanation":"Only I is correct. The private block is 172.16.0.0–172.31.255.255, so 172.32.5.4 is public; a /24 has only 254 usable hosts; and 255.255.255.255 is the limited broadcast address, while loopback is 127.0.0.1.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"IPv4 पता-निर्धारण के बारे में इनमें से कितने कथन सही हैं? I. क्लास A पते का पहला ऑक्टेट 1 से 126 तक होता है। II. 172.32.5.4 एक निजी पता है। III. 192.168.10.0/24 में 256 प्रयोग-योग्य होस्ट पते होते हैं। IV. 255.255.255.255 लूपबैक पता है।","optionsHi":["केवल तीन","सभी चार","केवल दो","केवल एक"],"explanationHi":"केवल I सही है। निजी ब्लॉक 172.16.0.0–172.31.255.255 है, इसलिए 172.32.5.4 सार्वजनिक है; /24 में केवल 254 प्रयोग-योग्य होस्ट होते हैं; और 255.255.255.255 सीमित ब्रॉडकास्ट पता है, जबकि लूपबैक 127.0.0.1 है।"},
  {"id":"comp-awareness-154","question":"The decimal number 45 is stored as an 8-bit unsigned binary number and then shifted left by 2 bits (zeros entering from the right, no overflow). The new decimal value is:","options":["90","180","47","11"],"answer":1,"explanation":"45 = 00101101; shifting left by 2 gives 10110100 = 128 + 32 + 16 + 4 = 180. Each left shift doubles the value, so 45 × 4 = 180. 11 would come from a right shift by 2.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL","questionHi":"दशमलव संख्या 45 को 8-बिट अचिह्नित बाइनरी संख्या के रूप में संग्रहीत किया जाता है और फिर 2 बिट बाईं ओर खिसकाया जाता है (दाईं ओर से शून्य आते हैं, कोई ओवरफ़्लो नहीं)। नया दशमलव मान है:","optionsHi":["90","180","47","11"],"explanationHi":"45 = 00101101; 2 बिट बाएँ खिसकाने पर 10110100 = 128 + 32 + 16 + 4 = 180। प्रत्येक बायाँ खिसकाव मान को दोगुना करता है, इसलिए 45 × 4 = 180। 11, 2 बिट दाएँ खिसकाने से आता।"},
  {"id":"comp-awareness-155","question":"Convert the hexadecimal number (2F7)₁₆ directly into octal.","options":["(1367)₈","(1357)₈","(1377)₈","(2367)₈"],"answer":0,"explanation":"2F7 = 0010 1111 0111; regrouping in threes from the right gives 001 011 110 111 = 1 3 6 7, so (1367)₈ (= 759 in decimal).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"हेक्साडेसिमल संख्या (2F7)₁₆ को सीधे ऑक्टल में बदलिए।","optionsHi":["(1367)₈","(1357)₈","(1377)₈","(2367)₈"],"explanationHi":"2F7 = 0010 1111 0111; दाईं ओर से तीन-तीन के समूह बनाने पर 001 011 110 111 = 1 3 6 7, इसलिए (1367)₈ (= दशमलव में 759)।"},
  {"id":"comp-awareness-156","question":"A cache has an access time of 10 ns and main memory 100 ns. The cache is checked first and, on a miss, the word is then read from main memory, so a miss costs 10 + 100 ns. With a hit ratio of 90%, what is the average memory access time?","options":["19 ns","20 ns","91 ns","55 ns"],"answer":1,"explanation":"Average = 0.9 × 10 + 0.1 × (10 + 100) = 9 + 11 = 20 ns. 19 ns comes from wrongly charging a miss only 100 ns, as if both memories were searched in parallel.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"एक कैश का एक्सेस समय 10 ns और मुख्य मेमोरी का 100 ns है। पहले कैश की जाँच होती है और मिस होने पर शब्द मुख्य मेमोरी से पढ़ा जाता है, इसलिए एक मिस की लागत 10 + 100 ns है। 90% हिट अनुपात के साथ औसत मेमोरी एक्सेस समय क्या है?","optionsHi":["19 ns","20 ns","91 ns","55 ns"],"explanationHi":"औसत = 0.9 × 10 + 0.1 × (10 + 100) = 9 + 11 = 20 ns। 19 ns तब आता है जब मिस की लागत गलती से केवल 100 ns ली जाए, मानो दोनों मेमोरी में एक साथ खोज होती हो।"},
  {"id":"comp-awareness-157","question":"In the fetch phase of an instruction cycle, which register-to-register transfer happens first?","options":["The memory data register (MDR) is copied into the program counter (PC)","The instruction register (IR) is copied into the MDR","The program counter (PC) is copied into the memory address register (MAR)","The MAR is copied into the program counter (PC)"],"answer":2,"explanation":"The PC holds the address of the next instruction, so it is sent to the MAR to read memory; the fetched word arrives in the MDR and then moves to the IR.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"किसी निर्देश चक्र के फ़ेच चरण में कौन-सा रजिस्टर-से-रजिस्टर स्थानांतरण पहले होता है?","optionsHi":["मेमोरी डेटा रजिस्टर (MDR) प्रोग्राम काउंटर (PC) में कॉपी होता है","इंस्ट्रक्शन रजिस्टर (IR) MDR में कॉपी होता है","प्रोग्राम काउंटर (PC) मेमोरी एड्रेस रजिस्टर (MAR) में कॉपी होता है","MAR प्रोग्राम काउंटर (PC) में कॉपी होता है"],"explanationHi":"PC में अगले निर्देश का पता होता है, इसलिए मेमोरी पढ़ने के लिए उसे MAR में भेजा जाता है; फ़ेच किया गया शब्द MDR में आता है और फिर IR में जाता है।"},
  {"id":"comp-awareness-158","question":"A processor has a 20-bit address bus, and its memory is word-addressable with 16-bit (2-byte) words. What is the maximum memory it can address?","options":["1 MB","512 KB","16 MB","2 MB"],"answer":3,"explanation":"20 address lines select 2²⁰ words, and each word is 2 bytes, so 2²⁰ × 2 B = 2 MB. Answering 1 MB wrongly assumes each address holds one byte.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"एक प्रोसेसर में 20-बिट एड्रेस बस है, और उसकी मेमोरी 16-बिट (2-बाइट) शब्दों वाली शब्द-पता-योग्य है। वह अधिकतम कितनी मेमोरी का पता लगा सकता है?","optionsHi":["1 MB","512 KB","16 MB","2 MB"],"explanationHi":"20 एड्रेस लाइनें 2²⁰ शब्दों का चयन करती हैं, और प्रत्येक शब्द 2 बाइट का है, इसलिए 2²⁰ × 2 B = 2 MB। 1 MB का उत्तर गलती से मान लेता है कि प्रत्येक पते पर एक बाइट होता है।"},
  {"id":"comp-awareness-159","question":"A system uses 32-bit virtual addresses and a page size of 4 KB. How many bits of the address form the page number and how many the offset within the page?","options":["20-bit page number, 12-bit offset","12-bit page number, 20-bit offset","22-bit page number, 10-bit offset","24-bit page number, 8-bit offset"],"answer":0,"explanation":"4 KB = 2¹² bytes, so 12 bits are needed for the offset; the remaining 32 − 12 = 20 bits give the page number (2²⁰ pages).","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"एक प्रणाली 32-बिट वर्चुअल पते और 4 KB के पेज आकार का प्रयोग करती है। पते के कितने बिट पेज संख्या बनाते हैं और कितने पेज के भीतर ऑफ़सेट?","optionsHi":["20-बिट पेज संख्या, 12-बिट ऑफ़सेट","12-बिट पेज संख्या, 20-बिट ऑफ़सेट","22-बिट पेज संख्या, 10-बिट ऑफ़सेट","24-बिट पेज संख्या, 8-बिट ऑफ़सेट"],"explanationHi":"4 KB = 2¹² बाइट, इसलिए ऑफ़सेट के लिए 12 बिट चाहिए; शेष 32 − 12 = 20 बिट पेज संख्या देते हैं (2²⁰ पेज)।"},
  {"id":"comp-awareness-160","question":"Which of the following is NOT one of the four conditions that must all hold for a deadlock to occur?","options":["Mutual exclusion","Hold and wait","Circular wait","Pre-emption of resources"],"answer":3,"explanation":"The necessary conditions are mutual exclusion, hold and wait, NO pre-emption and circular wait. If resources can be pre-empted, deadlock can be broken, so pre-emption is not a condition for it.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"निम्नलिखित में से कौन-सी उन चार शर्तों में नहीं है जो डेडलॉक होने के लिए सभी एक साथ लागू होनी चाहिए?","optionsHi":["पारस्परिक अपवर्जन","होल्ड एंड वेट","चक्रीय प्रतीक्षा","संसाधनों का प्री-एम्प्शन"],"explanationHi":"आवश्यक शर्तें हैं: पारस्परिक अपवर्जन, होल्ड एंड वेट, प्री-एम्प्शन का न होना और चक्रीय प्रतीक्षा। यदि संसाधनों का प्री-एम्प्शन हो सके तो डेडलॉक तोड़ा जा सकता है, इसलिए प्री-एम्प्शन उसकी शर्त नहीं है।"},
  {"id":"comp-awareness-161","question":"Three processes arrive at time 0 in the order P1 (burst 10 ms), P2 (burst 4 ms) and P3 (burst 2 ms). By how much does the average waiting time under non-pre-emptive SJF fall compared with FCFS?","options":["8 ms","5.33 ms","2.67 ms","16 ms"],"answer":1,"explanation":"FCFS waits are 0, 10, 14 (average 8 ms); SJF runs P3, P2, P1 with waits 0, 2, 6 (average 2.67 ms). The fall is 8 − 2.67 = 5.33 ms; 16 ms is the fall in TOTAL waiting time, not the average.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"तीन प्रक्रियाएँ समय 0 पर इस क्रम में आती हैं: P1 (बर्स्ट 10 ms), P2 (बर्स्ट 4 ms) और P3 (बर्स्ट 2 ms)। FCFS की तुलना में नॉन-प्री-एम्प्टिव SJF में औसत प्रतीक्षा समय कितना घटता है?","optionsHi":["8 ms","5.33 ms","2.67 ms","16 ms"],"explanationHi":"FCFS में प्रतीक्षा समय 0, 10, 14 हैं (औसत 8 ms); SJF में P3, P2, P1 चलते हैं और प्रतीक्षा समय 0, 2, 6 हैं (औसत 2.67 ms)। कमी 8 − 2.67 = 5.33 ms है; 16 ms कुल प्रतीक्षा समय की कमी है, औसत की नहीं।"},
  {"id":"comp-awareness-162","question":"In a STUDENT table, both RollNo and Email can uniquely identify every row. The designer chooses RollNo as the primary key. What is Email now called?","options":["A foreign key","A composite key","An alternate key","A surrogate key"],"answer":2,"explanation":"Every minimal unique identifier is a candidate key; the candidate keys not chosen as the primary key are alternate keys. A surrogate key is an artificial system-generated id, which Email is not.","difficulty":"moderate","source":"IBPS SO IT · IBPS PO Mains","questionHi":"STUDENT तालिका में RollNo और Email दोनों प्रत्येक पंक्ति की अद्वितीय पहचान कर सकते हैं। डिज़ाइनर RollNo को प्राइमरी की चुनता है। अब Email क्या कहलाता है?","optionsHi":["फ़ॉरेन की","कंपोज़िट की","वैकल्पिक की (ऑल्टरनेट की)","सरोगेट की"],"explanationHi":"प्रत्येक न्यूनतम अद्वितीय पहचानकर्ता कैंडिडेट की होती है; जिन कैंडिडेट कीज़ को प्राइमरी की के रूप में नहीं चुना जाता, वे ऑल्टरनेट कीज़ होती हैं। सरोगेट की सिस्टम द्वारा बनाई गई कृत्रिम पहचान संख्या होती है, जो Email नहीं है।"},
  {"id":"comp-awareness-163","question":"A relation is in 1NF and its primary key consists of a single attribute. Which normal form is it then guaranteed to satisfy?","options":["2NF","3NF","BCNF","None beyond 1NF"],"answer":0,"explanation":"2NF forbids partial dependency on part of a composite key; with a single-attribute key there is no 'part', so the relation is automatically in 2NF. It can still have transitive dependencies, so 3NF is not guaranteed.","difficulty":"hard","source":"IBPS SO IT · SBI PO","questionHi":"कोई रिलेशन 1NF में है और उसकी प्राइमरी की में एक ही एट्रिब्यूट है। तब वह किस सामान्य रूप को निश्चित रूप से संतुष्ट करता है?","optionsHi":["2NF","3NF","BCNF","1NF से आगे कोई नहीं"],"explanationHi":"2NF संयुक्त कुंजी के किसी भाग पर आंशिक निर्भरता को रोकता है; एकल-एट्रिब्यूट कुंजी में कोई ‘भाग’ नहीं होता, इसलिए रिलेशन अपने आप 2NF में होता है। उसमें फिर भी संक्रामक निर्भरताएँ हो सकती हैं, इसलिए 3NF की गारंटी नहीं है।"},
  {"id":"comp-awareness-164","question":"A funds-transfer transaction commits successfully, and a second later the database server loses power. When it restarts, the transfer is still recorded. Which ACID property ensured this?","options":["Atomicity","Durability","Consistency","Isolation"],"answer":1,"explanation":"Durability guarantees that once a transaction commits, its changes survive later failures. Atomicity is about all-or-nothing execution before commit, not survival after it.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"एक धन-अंतरण लेन-देन सफलतापूर्वक कमिट होता है, और एक सेकंड बाद डेटाबेस सर्वर की बिजली चली जाती है। पुनः आरंभ होने पर अंतरण फिर भी दर्ज रहता है। इसे किस ACID गुण ने सुनिश्चित किया?","optionsHi":["परमाणुकता (एटॉमिसिटी)","टिकाऊपन (ड्यूरेबिलिटी)","संगतता (कंसिस्टेंसी)","पृथक्करण (आइसोलेशन)"],"explanationHi":"ड्यूरेबिलिटी गारंटी देती है कि लेन-देन के कमिट होने के बाद उसके परिवर्तन आगे की विफलताओं में भी बने रहते हैं। एटॉमिसिटी कमिट से पहले ‘सब या कुछ नहीं’ निष्पादन के बारे में है, उसके बाद बने रहने के बारे में नहीं।"},
  {"id":"comp-awareness-165","question":"Which network device is matched with the WRONG OSI layer at which it mainly operates?","options":["Hub — Physical layer","Bridge — Data Link layer","Router — Network layer","Repeater — Network layer"],"answer":3,"explanation":"A repeater only regenerates the electrical signal, so it works at the Physical layer (layer 1), not the Network layer. The other three pairs are correct.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"किस नेटवर्क उपकरण का मिलान उस OSI परत से गलत किया गया है जिस पर वह मुख्यतः कार्य करता है?","optionsHi":["हब — भौतिक परत","ब्रिज — डेटा लिंक परत","राउटर — नेटवर्क परत","रिपीटर — नेटवर्क परत"],"explanationHi":"रिपीटर केवल विद्युत सिग्नल को पुनः उत्पन्न करता है, इसलिए वह भौतिक परत (परत 1) पर कार्य करता है, नेटवर्क परत पर नहीं। शेष तीनों युग्म सही हैं।"},
  {"id":"comp-awareness-166","question":"An IPv6 address is written as colon-separated groups of hexadecimal digits. In full (uncompressed) form, how many groups are there and how many bits does each group carry?","options":["16 groups of 8 bits","4 groups of 32 bits","8 groups of 16 bits","6 groups of 16 bits"],"answer":2,"explanation":"IPv6 is 128 bits, written as 8 groups of 4 hex digits; 4 hex digits = 16 bits, and 8 × 16 = 128. Six groups is the pattern of a 48-bit MAC address, not IPv6.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"IPv6 पता हेक्साडेसिमल अंकों के कोलन-पृथक समूहों के रूप में लिखा जाता है। पूर्ण (असंपीड़ित) रूप में कितने समूह होते हैं और प्रत्येक समूह कितने बिट का होता है?","optionsHi":["16 समूह, प्रत्येक 8 बिट का","4 समूह, प्रत्येक 32 बिट का","8 समूह, प्रत्येक 16 बिट का","6 समूह, प्रत्येक 16 बिट का"],"explanationHi":"IPv6 128 बिट का होता है, जो 4 हेक्स अंकों के 8 समूहों के रूप में लिखा जाता है; 4 हेक्स अंक = 16 बिट, और 8 × 16 = 128। छह समूह 48-बिट MAC पते का प्रारूप है, IPv6 का नहीं।"},
  {"id":"comp-awareness-167","question":"In a 48-bit MAC address, what do the first 24 bits (the Organisationally Unique Identifier) identify?","options":["The network to which the device is connected","The manufacturer of the network interface","The subnet mask of the device","The country where the device was registered"],"answer":1,"explanation":"The OUI is assigned to the manufacturer (vendor); the last 24 bits are the serial number given by that vendor. MAC addresses carry no network or subnet information; that is the job of IP addressing.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"48-बिट MAC पते में पहले 24 बिट (ऑर्गनाइज़ेशनली यूनिक आइडेंटिफ़ायर) क्या पहचानते हैं?","optionsHi":["वह नेटवर्क जिससे उपकरण जुड़ा है","नेटवर्क इंटरफ़ेस का निर्माता","उपकरण का सबनेट मास्क","वह देश जहाँ उपकरण पंजीकृत हुआ"],"explanationHi":"OUI निर्माता (विक्रेता) को दिया जाता है; अंतिम 24 बिट उस विक्रेता द्वारा दिया गया क्रम-संख्या होते हैं। MAC पतों में नेटवर्क या सबनेट की कोई जानकारी नहीं होती; वह IP पता-निर्धारण का काम है।"},
  {"id":"comp-awareness-168","question":"The 8-bit pattern 11110110 stores a signed integer in two's complement form. What is its value?","options":["−118","246","−10","−9"],"answer":2,"explanation":"The MSB is 1, so it is negative; inverting and adding 1 gives 00001010 = 10, so the value is −10. −118 is the sign-magnitude reading, 246 the unsigned reading and −9 the one's-complement reading.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"8-बिट पैटर्न 11110110 एक चिह्नित पूर्णांक को टू’ज़ कॉम्प्लिमेंट रूप में संग्रहीत करता है। उसका मान क्या है?","optionsHi":["−118","246","−10","−9"],"explanationHi":"MSB 1 है, इसलिए संख्या ऋणात्मक है; बिट उलटकर 1 जोड़ने पर 00001010 = 10 मिलता है, इसलिए मान −10 है। −118 साइन-मैग्निट्यूड पाठ है, 246 अचिह्नित पाठ है और −9 वन’ज़ कॉम्प्लिमेंट पाठ है।"},
  {"id":"comp-awareness-169","question":"The Gray code 1101 is converted back into ordinary binary. What is the result?","options":["1011","1110","1101","1001"],"answer":3,"explanation":"Keep the first bit (1), then each binary bit = previous binary bit XOR current Gray bit: 1, 1⊕1 = 0, 0⊕0 = 0, 0⊕1 = 1, giving 1001. 1011 is what you get by converting binary to Gray instead.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"ग्रे कोड 1101 को वापस सामान्य बाइनरी में बदला जाता है। परिणाम क्या है?","optionsHi":["1011","1110","1101","1001"],"explanationHi":"पहला बिट (1) वैसा ही रखें, फिर प्रत्येक बाइनरी बिट = पिछला बाइनरी बिट XOR वर्तमान ग्रे बिट: 1, 1⊕1 = 0, 0⊕0 = 0, 0⊕1 = 1, जिससे 1001 मिलता है। 1011 तब मिलता है जब बाइनरी को ग्रे में बदला जाए।"},
  {"id":"comp-awareness-170","question":"What is (7A)₁₆ + (2C)₁₆, written in hexadecimal?","options":["A6","96","166","B6"],"answer":0,"explanation":"A + C = 10 + 12 = 22 = 16 + 6, so write 6 and carry 1; 7 + 2 + 1 = 10 = A, giving A6. 96 forgets the carry, and 166 is the decimal value of A6, not a hex result.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"(7A)₁₆ + (2C)₁₆ का मान हेक्साडेसिमल में लिखने पर क्या है?","optionsHi":["A6","96","166","B6"],"explanationHi":"A + C = 10 + 12 = 22 = 16 + 6, इसलिए 6 लिखें और 1 हासिल रखें; 7 + 2 + 1 = 10 = A, जिससे A6 मिलता है। 96 हासिल भूल जाता है, और 166, A6 का दशमलव मान है, हेक्स परिणाम नहीं।"},
  {"id":"comp-awareness-171","question":"How many of these gates are 'universal', i.e. able to build every other logic function on their own: NAND, NOR, XOR, AND?","options":["One","Three","Two","Four"],"answer":2,"explanation":"Only NAND and NOR are universal. AND alone cannot make NOT, and XOR alone cannot make AND, so they are not universal.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"इन गेटों में से कितने ‘सार्वभौमिक’ हैं, अर्थात् अकेले ही हर अन्य लॉजिक फ़ंक्शन बना सकते हैं: NAND, NOR, XOR, AND?","optionsHi":["एक","तीन","दो","चार"],"explanationHi":"केवल NAND और NOR सार्वभौमिक हैं। अकेला AND, NOT नहीं बना सकता और अकेला XOR, AND नहीं बना सकता, इसलिए वे सार्वभौमिक नहीं हैं।"},
  {"id":"comp-awareness-172","question":"Which type of ROM is erased by exposing the chip to ultraviolet light through a small quartz window on its package?","options":["EEPROM","PROM","Mask ROM","EPROM"],"answer":3,"explanation":"EPROM is erased with UV light and then reprogrammed. EEPROM (and flash) is erased electrically, while PROM is one-time programmable and mask ROM is fixed at manufacture.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"किस प्रकार की ROM को चिप के पैकेज पर बनी छोटी क्वार्ट्ज़ खिड़की से पराबैंगनी प्रकाश डालकर मिटाया जाता है?","optionsHi":["EEPROM","PROM","मास्क ROM","EPROM"],"explanationHi":"EPROM को UV प्रकाश से मिटाकर फिर से प्रोग्राम किया जाता है। EEPROM (और फ्लैश) विद्युत से मिटाई जाती है, जबकि PROM एक बार प्रोग्राम होने योग्य है और मास्क ROM निर्माण के समय ही स्थिर कर दी जाती है।"},
  {"id":"comp-awareness-173","question":"Assertion (A): Dynamic RAM must be refreshed thousands of times every second. Reason (R): DRAM stores each bit as charge in a tiny capacitor, and the charge leaks away.","options":["A is true but R is false","Both A and R are true, but R is not the correct explanation of A","A is false but R is true","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"DRAM cells are capacitors whose charge leaks within milliseconds, which is exactly why they must be refreshed. SRAM uses flip-flops and needs no refresh.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"अभिकथन (A): डायनेमिक RAM को प्रत्येक सेकंड हज़ारों बार रिफ़्रेश करना पड़ता है। कारण (R): DRAM प्रत्येक बिट को एक सूक्ष्म संधारित्र में आवेश के रूप में संग्रहीत करती है, और आवेश रिसता रहता है।","optionsHi":["A सही है, परंतु R गलत है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A गलत है, परंतु R सही है","A और R दोनों सही हैं, और R, A की सही व्याख्या है"],"explanationHi":"DRAM के सेल संधारित्र हैं जिनका आवेश मिलीसेकंड में रिस जाता है, और ठीक इसीलिए उन्हें रिफ़्रेश करना पड़ता है। SRAM फ्लिप-फ्लॉप का प्रयोग करती है और उसे रिफ़्रेश की आवश्यकता नहीं होती।"},
  {"id":"comp-awareness-174","question":"Which sequence correctly describes what happens when a PC is switched on?","options":["Power-on self-test (POST) → boot loader runs → operating system kernel loads → user login","Boot loader runs → POST → kernel loads → user login","Kernel loads → POST → boot loader runs → user login","POST → kernel loads → boot loader runs → user login"],"answer":0,"explanation":"Firmware (BIOS/UEFI) first runs the POST, then finds and runs the boot loader, which loads the OS kernel; only then is the user offered a login. The kernel cannot load before the boot loader that loads it.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"PC चालू करने पर जो होता है, उसे कौन-सा क्रम सही ढंग से बताता है?","optionsHi":["पावर-ऑन सेल्फ़-टेस्ट (POST) → बूट लोडर चलता है → ऑपरेटिंग सिस्टम कर्नेल लोड होता है → उपयोगकर्ता लॉगिन","बूट लोडर चलता है → POST → कर्नेल लोड होता है → उपयोगकर्ता लॉगिन","कर्नेल लोड होता है → POST → बूट लोडर चलता है → उपयोगकर्ता लॉगिन","POST → कर्नेल लोड होता है → बूट लोडर चलता है → उपयोगकर्ता लॉगिन"],"explanationHi":"फ़र्मवेयर (BIOS/UEFI) पहले POST चलाता है, फिर बूट लोडर को खोजकर चलाता है, जो OS कर्नेल को लोड करता है; उसके बाद ही उपयोगकर्ता को लॉगिन मिलता है। कर्नेल उस बूट लोडर से पहले लोड नहीं हो सकता जो उसे लोड करता है।"},
  {"id":"comp-awareness-175","question":"In which order does a compiler normally carry out these phases on a source program?","options":["Syntax analysis → lexical analysis → semantic analysis → code generation","Lexical analysis → semantic analysis → syntax analysis → code generation","Lexical analysis → syntax analysis → semantic analysis → code generation","Lexical analysis → syntax analysis → code generation → semantic analysis"],"answer":2,"explanation":"The source is first split into tokens (lexical), then tokens are arranged into a parse tree (syntax), then checked for meaning such as types (semantic), and only then is code generated.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"कंपाइलर किसी स्रोत प्रोग्राम पर इन चरणों को सामान्यतः किस क्रम में करता है?","optionsHi":["वाक्य-विन्यास विश्लेषण → शब्द-विश्लेषण → अर्थ-विश्लेषण → कोड निर्माण","शब्द-विश्लेषण → अर्थ-विश्लेषण → वाक्य-विन्यास विश्लेषण → कोड निर्माण","शब्द-विश्लेषण → वाक्य-विन्यास विश्लेषण → अर्थ-विश्लेषण → कोड निर्माण","शब्द-विश्लेषण → वाक्य-विन्यास विश्लेषण → कोड निर्माण → अर्थ-विश्लेषण"],"explanationHi":"स्रोत को पहले टोकन में बाँटा जाता है (शब्द-विश्लेषण), फिर टोकन को पार्स ट्री में व्यवस्थित किया जाता है (वाक्य-विन्यास), फिर अर्थ की जाँच की जाती है जैसे टाइप (अर्थ-विश्लेषण), और उसके बाद ही कोड बनाया जाता है।"},
  {"id":"comp-awareness-176","question":"A 5-stage instruction pipeline takes one clock cycle per stage and never stalls. How many clock cycles does it need to complete 100 instructions?","options":["500","104","105","100"],"answer":1,"explanation":"The first instruction needs 5 cycles to fill the pipeline, and each of the remaining 99 finishes one cycle later: 5 + 99 = 104. 500 is the count without pipelining.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"एक 5-चरण निर्देश पाइपलाइन प्रत्येक चरण के लिए एक क्लॉक चक्र लेती है और कभी रुकती नहीं। 100 निर्देश पूरे करने में उसे कितने क्लॉक चक्र चाहिए?","optionsHi":["500","104","105","100"],"explanationHi":"पाइपलाइन भरने के लिए पहले निर्देश को 5 चक्र चाहिए, और शेष 99 में से प्रत्येक एक चक्र बाद पूरा होता है: 5 + 99 = 104। 500 पाइपलाइन के बिना की गिनती है।"},
  {"id":"comp-awareness-177","question":"How many of these statements about RISC and CISC processors are correct? I. RISC designs usually use fixed-length instructions. II. CISC designs offer more addressing modes. III. RISC follows a load/store design, where only load and store instructions access memory. IV. Every CISC instruction completes in one clock cycle.","options":["One","Two","Four","Three"],"answer":3,"explanation":"I, II and III are correct. IV is false: complex CISC instructions often take many cycles; single-cycle execution is a RISC goal.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"RISC और CISC प्रोसेसरों के बारे में इनमें से कितने कथन सही हैं? I. RISC डिज़ाइन सामान्यतः निश्चित-लंबाई के निर्देश प्रयोग करते हैं। II. CISC डिज़ाइन में अधिक एड्रेसिंग मोड होते हैं। III. RISC लोड/स्टोर डिज़ाइन का अनुसरण करता है, जिसमें केवल लोड और स्टोर निर्देश ही मेमोरी तक पहुँचते हैं। IV. प्रत्येक CISC निर्देश एक क्लॉक चक्र में पूरा हो जाता है।","optionsHi":["एक","दो","चार","तीन"],"explanationHi":"I, II और III सही हैं। IV गलत है: जटिल CISC निर्देश अक्सर कई चक्र लेते हैं; एकल-चक्र निष्पादन RISC का लक्ष्य है।"},
  {"id":"comp-awareness-178","question":"The Boolean expression A'B + AB' + AB (where ' means NOT) simplifies to which single operation on A and B?","options":["A OR B","A XOR B","A AND B","NOT A OR NOT B"],"answer":0,"explanation":"AB' + AB = A(B' + B) = A, so the expression becomes A + A'B = A + B, i.e. A OR B. XOR would be only the first two terms; the extra AB term adds the case A = B = 1.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"बूलियन व्यंजक A'B + AB' + AB (जहाँ ' का अर्थ NOT है) A और B पर किस एकल संक्रिया में सरल हो जाता है?","optionsHi":["A OR B","A XOR B","A AND B","NOT A OR NOT B"],"explanationHi":"AB' + AB = A(B' + B) = A, इसलिए व्यंजक A + A'B = A + B बन जाता है, अर्थात् A OR B। XOR केवल पहले दो पदों से बनता; अतिरिक्त AB पद A = B = 1 की स्थिति जोड़ता है।"},
  {"id":"comp-awareness-179","question":"A hard disk spins at 7200 rpm and has an average seek time of 8 ms. Ignoring transfer and controller time, what is its average access time?","options":["16.33 ms","8.33 ms","12.17 ms","4.17 ms"],"answer":2,"explanation":"One rotation takes 60,000 ÷ 7200 = 8.33 ms, and on average the head waits half a rotation (4.17 ms). Access time = 8 + 4.17 ≈ 12.17 ms; 16.33 ms wrongly adds a full rotation.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"एक हार्ड डिस्क 7200 rpm पर घूमती है और उसका औसत सीक समय 8 ms है। स्थानांतरण और कंट्रोलर समय की उपेक्षा करने पर उसका औसत एक्सेस समय क्या है?","optionsHi":["16.33 ms","8.33 ms","12.17 ms","4.17 ms"],"explanationHi":"एक चक्कर में 60,000 ÷ 7200 = 8.33 ms लगते हैं, और औसतन हेड आधे चक्कर (4.17 ms) की प्रतीक्षा करता है। एक्सेस समय = 8 + 4.17 ≈ 12.17 ms; 16.33 ms गलती से पूरा एक चक्कर जोड़ देता है।"},
  {"id":"comp-awareness-180","question":"How many of these statements are correct? I. A solid-state drive has no moving read/write head. II. Flash memory cells can be rewritten only a limited number of times. III. SSDs should be defragmented regularly to keep them fast. IV. Random reads are much faster on an SSD than on a hard disk.","options":["Two","Three","One","Four"],"answer":1,"explanation":"I, II and IV are true. III is false: an SSD has no seek time, so fragmentation hardly slows it, and needless defragmentation only wears out its limited write cycles.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"इनमें से कितने कथन सही हैं? I. सॉलिड-स्टेट ड्राइव में कोई गतिशील रीड/राइट हेड नहीं होता। II. फ्लैश मेमोरी सेल को केवल सीमित बार ही पुनः लिखा जा सकता है। III. SSD को तेज़ बनाए रखने के लिए नियमित रूप से डीफ़्रैग्मेंट करना चाहिए। IV. SSD पर रैंडम रीड हार्ड डिस्क की तुलना में बहुत तेज़ होते हैं।","optionsHi":["दो","तीन","एक","चार"],"explanationHi":"I, II और IV सही हैं। III गलत है: SSD में सीक समय नहीं होता, इसलिए विखंडन उसे शायद ही धीमा करता है, और अनावश्यक डीफ़्रैग्मेंटेशन उसके सीमित राइट चक्रों को केवल घिसाता है।"},
  {"id":"comp-awareness-181","question":"In a virtual memory system, a 'page fault' occurs when a program refers to a page that:","options":["is not present in the cache memory","has no entry in the translation lookaside buffer (TLB)","belongs to the address space of another process","is not currently loaded in main memory"],"answer":3,"explanation":"A page fault means the page is on disk, not in RAM, so the OS must load it. A TLB miss only means the translation must be read from the page table; the page may well be in RAM.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"वर्चुअल मेमोरी प्रणाली में ‘पेज फ़ॉल्ट’ तब होता है जब कोई प्रोग्राम ऐसे पेज का संदर्भ देता है जो:","optionsHi":["कैश मेमोरी में उपस्थित नहीं है","जिसकी ट्रांसलेशन लुकसाइड बफ़र (TLB) में कोई प्रविष्टि नहीं है","किसी अन्य प्रक्रिया के एड्रेस स्पेस का है","वर्तमान में मुख्य मेमोरी में लोड नहीं है"],"explanationHi":"पेज फ़ॉल्ट का अर्थ है कि पेज डिस्क पर है, RAM में नहीं, इसलिए OS को उसे लोड करना पड़ता है। TLB मिस का अर्थ केवल इतना है कि अनुवाद पेज टेबल से पढ़ना होगा; पेज RAM में हो भी सकता है।"},
  {"id":"comp-awareness-182","question":"A program reads the elements of a large array one after another: a[0], a[1], a[2] and so on. Which property does the cache exploit to speed this up?","options":["Spatial locality","Temporal locality","Thrashing","Write-back"],"answer":0,"explanation":"Neighbouring addresses are used soon after one another, so loading a whole cache block at once helps: that is spatial locality. Temporal locality is reuse of the SAME address, such as a loop counter.","difficulty":"moderate","source":"IBPS SO IT · SBI PO","questionHi":"एक प्रोग्राम किसी बड़े ऐरे के तत्वों को एक के बाद एक पढ़ता है: a[0], a[1], a[2] और इसी तरह। इसे तेज़ करने के लिए कैश किस गुण का लाभ उठाता है?","optionsHi":["स्थानिक स्थानीयता (स्पेशियल लोकैलिटी)","कालिक स्थानीयता (टेम्पोरल लोकैलिटी)","थ्रैशिंग","राइट-बैक"],"explanationHi":"पास-पास के पते एक-दूसरे के तुरंत बाद प्रयोग होते हैं, इसलिए पूरा कैश ब्लॉक एक साथ लोड करना सहायक होता है: यही स्पेशियल लोकैलिटी है। टेम्पोरल लोकैलिटी एक ही पते का पुनः प्रयोग है, जैसे लूप काउंटर।"},
  {"id":"comp-awareness-183","question":"Under a write-back cache policy, when is a modified cache block written to main memory?","options":["Immediately, on every write to the block","Only when the block is about to be replaced, as shown by its dirty bit","Only when the program terminates","Never; main memory is updated by the DMA controller"],"answer":1,"explanation":"Write-back marks a changed block 'dirty' and copies it to memory only when it is evicted. Writing on every update is the write-through policy.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"राइट-बैक कैश नीति में, संशोधित कैश ब्लॉक मुख्य मेमोरी में कब लिखा जाता है?","optionsHi":["तुरंत, ब्लॉक पर प्रत्येक राइट के साथ","केवल तब जब ब्लॉक बदला जाने वाला हो, जैसा उसके डर्टी बिट से पता चलता है","केवल प्रोग्राम समाप्त होने पर","कभी नहीं; मुख्य मेमोरी DMA कंट्रोलर द्वारा अद्यतन होती है"],"explanationHi":"राइट-बैक बदले हुए ब्लॉक को ‘डर्टी’ चिह्नित करता है और उसे केवल निष्कासित होने पर मेमोरी में कॉपी करता है। प्रत्येक अद्यतन पर लिखना राइट-थ्रू नीति है।"},
  {"id":"comp-awareness-184","question":"How many of these statements about the system bus are correct? I. The address bus carries addresses from the CPU to memory, so it is unidirectional. II. The data bus is bidirectional. III. The width of the data bus decides how much memory can be addressed. IV. Read and write signals travel on the control bus.","options":["Three","Two","One","Four"],"answer":0,"explanation":"I, II and IV are correct. III is wrong: the ADDRESS bus width sets the addressable memory (n lines give 2ⁿ locations); the data bus width sets how many bits move at a time.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"सिस्टम बस के बारे में इनमें से कितने कथन सही हैं? I. एड्रेस बस CPU से मेमोरी तक पते ले जाती है, इसलिए वह एकदिशीय है। II. डेटा बस द्विदिशीय है। III. डेटा बस की चौड़ाई तय करती है कि कितनी मेमोरी का पता लगाया जा सकता है। IV. रीड और राइट सिग्नल कंट्रोल बस पर चलते हैं।","optionsHi":["तीन","दो","एक","चार"],"explanationHi":"I, II और IV सही हैं। III गलत है: पता-योग्य मेमोरी एड्रेस बस की चौड़ाई तय करती है (n लाइनें 2ⁿ स्थान देती हैं); डेटा बस की चौड़ाई तय करती है कि एक बार में कितने बिट जाते हैं।"},
  {"id":"comp-awareness-185","question":"Convert (563)₈ directly into hexadecimal.","options":["(371)₁₆","(1B3)₁₆","(163)₁₆","(173)₁₆"],"answer":3,"explanation":"563 = 101 110 011 in binary; regroup in fours from the right: 1 0111 0011 = 1 7 3, so (173)₁₆. 371 is the decimal value, not hex.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"(563)₈ को सीधे हेक्साडेसिमल में बदलिए।","optionsHi":["(371)₁₆","(1B3)₁₆","(163)₁₆","(173)₁₆"],"explanationHi":"563 = बाइनरी में 101 110 011; दाईं ओर से चार-चार के समूह बनाएँ: 1 0111 0011 = 1 7 3, इसलिए (173)₁₆। 371 दशमलव मान है, हेक्स नहीं।"},
  {"id":"comp-awareness-186","question":"The decimal number 156 is stored once in pure binary and once in 8421 BCD. How many more bits does the BCD form need?","options":["None","Two","Four","Three"],"answer":2,"explanation":"156 in binary is 10011100 (8 bits). BCD codes each digit in 4 bits: 0001 0101 0110 (12 bits). The difference is 4 bits.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"दशमलव संख्या 156 को एक बार शुद्ध बाइनरी में और एक बार 8421 BCD में संग्रहीत किया जाता है। BCD रूप को कितने अधिक बिट चाहिए?","optionsHi":["कोई नहीं","दो","चार","तीन"],"explanationHi":"156 का बाइनरी रूप 10011100 (8 बिट) है। BCD प्रत्येक अंक को 4 बिट में कोडित करता है: 0001 0101 0110 (12 बिट)। अंतर 4 बिट का है।"},
  {"id":"comp-awareness-187","question":"What is the largest unsigned number that 12 bits can hold, written in octal?","options":["(7777)₈","(4095)₈","(777)₈","(3777)₈"],"answer":0,"explanation":"The largest 12-bit value is 2¹² − 1 = 4095 = 111 111 111 111, and each group of three 1s is 7, giving (7777)₈. '4095' is the decimal value and is not even a valid octal numeral.","difficulty":"hard","source":"IBPS SO IT · SBI PO","questionHi":"12 बिट में समा सकने वाली सबसे बड़ी अचिह्नित संख्या ऑक्टल में क्या होगी?","optionsHi":["(7777)₈","(4095)₈","(777)₈","(3777)₈"],"explanationHi":"सबसे बड़ा 12-बिट मान 2¹² − 1 = 4095 = 111 111 111 111 है, और तीन 1 के प्रत्येक समूह का मान 7 है, जिससे (7777)₈ मिलता है। ‘4095’ दशमलव मान है और वह वैध ऑक्टल अंक-संख्या भी नहीं है।"},
  {"id":"comp-awareness-188","question":"Which of these IPv4 addresses is a PRIVATE address that cannot be routed on the public internet?","options":["172.32.1.1","192.169.1.1","172.20.5.4","11.0.0.1"],"answer":2,"explanation":"The private ranges are 10.0.0.0/8, 172.16.0.0–172.31.255.255 and 192.168.0.0/16. 172.20.5.4 lies inside 172.16–172.31; 172.32 is just outside it, and 192.169 and 11 are public.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"इन IPv4 पतों में से कौन-सा निजी पता है जिसे सार्वजनिक इंटरनेट पर रूट नहीं किया जा सकता?","optionsHi":["172.32.1.1","192.169.1.1","172.20.5.4","11.0.0.1"],"explanationHi":"निजी रेंज 10.0.0.0/8, 172.16.0.0–172.31.255.255 और 192.168.0.0/16 हैं। 172.20.5.4 172.16–172.31 के भीतर है; 172.32 उससे ठीक बाहर है, और 192.169 तथा 11 सार्वजनिक हैं।"},
  {"id":"comp-awareness-189","question":"Six computers are joined in a full mesh topology. How many cables are needed, and how many ports must each computer have?","options":["30 cables, 5 ports each","15 cables, 6 ports each","30 cables, 6 ports each","15 cables, 5 ports each"],"answer":3,"explanation":"Each pair needs one link: 6 × 5 ÷ 2 = 15 cables, and each computer connects to the other 5, so it needs 5 ports. 30 counts every cable twice.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"छह कंप्यूटर पूर्ण मेश टोपोलॉजी में जुड़े हैं। कितने केबल चाहिए, और प्रत्येक कंप्यूटर में कितने पोर्ट होने चाहिए?","optionsHi":["30 केबल, प्रत्येक में 5 पोर्ट","15 केबल, प्रत्येक में 6 पोर्ट","30 केबल, प्रत्येक में 6 पोर्ट","15 केबल, प्रत्येक में 5 पोर्ट"],"explanationHi":"प्रत्येक जोड़ी को एक लिंक चाहिए: 6 × 5 ÷ 2 = 15 केबल, और प्रत्येक कंप्यूटर शेष 5 से जुड़ता है, इसलिए उसे 5 पोर्ट चाहिए। 30 प्रत्येक केबल को दो बार गिनता है।"},
  {"id":"comp-awareness-190","question":"A bank must link two buildings that sit next to a power substation causing heavy electrical noise. Which cable is the best choice?","options":["Unshielded twisted pair","Coaxial cable","Optical fibre","Shielded twisted pair"],"answer":2,"explanation":"Optical fibre carries light, not electrical signals, so electromagnetic interference cannot affect it. Shielding on copper cables only reduces interference; it does not remove it.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"एक बैंक को दो ऐसी इमारतों को जोड़ना है जो बिजली सबस्टेशन के पास हैं और भारी विद्युत शोर पैदा होता है। कौन-सा केबल सर्वोत्तम विकल्प है?","optionsHi":["अशील्डित ट्विस्टेड पेयर","कोएक्सियल केबल","ऑप्टिकल फ़ाइबर","शील्डित ट्विस्टेड पेयर"],"explanationHi":"ऑप्टिकल फ़ाइबर विद्युत सिग्नल नहीं, प्रकाश ले जाता है, इसलिए विद्युत-चुंबकीय व्यतिकरण उस पर असर नहीं डाल सकता। तांबे के केबलों पर शील्डिंग व्यतिकरण को केवल घटाती है; पूरी तरह हटाती नहीं।"},
  {"id":"comp-awareness-191","question":"The 'ping' command checks whether a host can be reached. Which protocol do its echo request and echo reply messages use?","options":["ICMP","TCP","UDP","ARP"],"answer":0,"explanation":"Ping sends ICMP Echo Request messages and waits for Echo Replies. ICMP is a network-layer control protocol and uses no TCP or UDP port; ARP only maps IP to MAC on a LAN.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"‘ping’ कमांड जाँचती है कि कोई होस्ट पहुँच में है या नहीं। इसके इको रिक्वेस्ट और इको रिप्लाई संदेश किस प्रोटोकॉल का प्रयोग करते हैं?","optionsHi":["ICMP","TCP","UDP","ARP"],"explanationHi":"Ping ICMP इको रिक्वेस्ट संदेश भेजती है और इको रिप्लाई की प्रतीक्षा करती है। ICMP नेटवर्क-परत का नियंत्रण प्रोटोकॉल है और कोई TCP या UDP पोर्ट प्रयोग नहीं करता; ARP केवल LAN पर IP को MAC से जोड़ता है।"},
  {"id":"comp-awareness-192","question":"A walkie-talkie, a television broadcast and an ordinary telephone call are examples of which transmission modes, respectively?","options":["Simplex, half-duplex, full-duplex","Full-duplex, simplex, half-duplex","Half-duplex, simplex, full-duplex","Half-duplex, full-duplex, simplex"],"answer":2,"explanation":"Walkie-talkie users talk in turn (half-duplex), TV flows only one way (simplex), and both phone callers can speak at once (full-duplex).","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"वॉकी-टॉकी, टेलीविज़न प्रसारण और साधारण टेलीफ़ोन कॉल क्रमशः किन संचरण मोड के उदाहरण हैं?","optionsHi":["सिम्प्लेक्स, हाफ़-डुप्लेक्स, फ़ुल-डुप्लेक्स","फ़ुल-डुप्लेक्स, सिम्प्लेक्स, हाफ़-डुप्लेक्स","हाफ़-डुप्लेक्स, सिम्प्लेक्स, फ़ुल-डुप्लेक्स","हाफ़-डुप्लेक्स, फ़ुल-डुप्लेक्स, सिम्प्लेक्स"],"explanationHi":"वॉकी-टॉकी के उपयोगकर्ता बारी-बारी से बोलते हैं (हाफ़-डुप्लेक्स), टीवी केवल एक दिशा में चलता है (सिम्प्लेक्स), और फ़ोन के दोनों वक्ता एक साथ बोल सकते हैं (फ़ुल-डुप्लेक्स)।"},
  {"id":"comp-awareness-193","question":"Ten users must each be able to talk privately with every other user. How many keys are needed in total with symmetric-key encryption, and how many with public-key encryption?","options":["20 and 45","45 and 20","90 and 20","45 and 10"],"answer":1,"explanation":"Symmetric: one shared secret key per pair, 10 × 9 ÷ 2 = 45. Public-key: each user needs only one key pair, so 10 × 2 = 20 keys. 10 counts only the public keys.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"दस उपयोगकर्ताओं में से प्रत्येक को हर दूसरे उपयोगकर्ता से निजी बातचीत करने में सक्षम होना है। सममित-कुंजी एन्क्रिप्शन में कुल कितनी कुंजियाँ चाहिए, और सार्वजनिक-कुंजी एन्क्रिप्शन में कितनी?","optionsHi":["20 और 45","45 और 20","90 और 20","45 और 10"],"explanationHi":"सममित: प्रत्येक जोड़ी के लिए एक साझा गुप्त कुंजी, 10 × 9 ÷ 2 = 45। सार्वजनिक-कुंजी: प्रत्येक उपयोगकर्ता को केवल एक कुंजी-युग्म चाहिए, इसलिए 10 × 2 = 20 कुंजियाँ। 10 केवल सार्वजनिक कुंजियों को गिनता है।"},
  {"id":"comp-awareness-194","question":"A piece of malware copies itself from computer to computer across a network on its own, without attaching to any file or needing a user to run a program. It is a:","options":["Virus","Trojan horse","Worm","Logic bomb"],"answer":2,"explanation":"A worm is self-replicating and standalone. A virus needs a host file and some user action to spread, and a Trojan disguises itself as useful software but does not replicate.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"मैलवेयर का एक अंश नेटवर्क पर एक कंप्यूटर से दूसरे में अपने आप प्रतिलिपि बनाकर फैलता है, बिना किसी फ़ाइल से जुड़े और बिना उपयोगकर्ता द्वारा कोई प्रोग्राम चलाए। यह है एक:","optionsHi":["वायरस","ट्रोजन हॉर्स","वर्म","लॉजिक बम"],"explanationHi":"वर्म स्वयं की प्रतिकृति बनाने वाला और स्वतंत्र होता है। वायरस को फैलने के लिए होस्ट फ़ाइल और उपयोगकर्ता की किसी क्रिया की आवश्यकता होती है, और ट्रोजन उपयोगी सॉफ्टवेयर का वेश धरता है पर प्रतिकृति नहीं बनाता।"},
  {"id":"comp-awareness-195","question":"A bank publishes a value computed from a software installer so that customers can confirm the download has not been altered. The file itself stays readable by anyone. Which technique is this?","options":["Symmetric encryption","Steganography","Public-key encryption","Cryptographic hashing"],"answer":3,"explanation":"A hash (such as SHA-256) is a one-way fingerprint: any change to the file changes it, so it checks integrity. Encryption would hide the content, which is not the goal here.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक बैंक सॉफ्टवेयर इंस्टॉलर से निकाला गया एक मान प्रकाशित करता है ताकि ग्राहक पुष्टि कर सकें कि डाउनलोड में कोई बदलाव नहीं हुआ है। फ़ाइल स्वयं सबके लिए पठनीय रहती है। यह कौन-सी तकनीक है?","optionsHi":["सममित एन्क्रिप्शन","स्टेगनोग्राफ़ी","सार्वजनिक-कुंजी एन्क्रिप्शन","क्रिप्टोग्राफ़िक हैशिंग"],"explanationHi":"हैश (जैसे SHA-256) एकदिशीय फ़िंगरप्रिंट है: फ़ाइल में कोई भी परिवर्तन उसे बदल देता है, इसलिए वह अखंडता की जाँच करता है। एन्क्रिप्शन सामग्री को छिपाता, जो यहाँ उद्देश्य नहीं है।"},
  {"id":"comp-awareness-196","question":"On what basis does a simple packet-filtering firewall allow or block traffic?","options":["Source and destination IP addresses, ports and protocol in each packet header","The full content of e-mail attachments","The identity of the logged-in user on each PC","The reputation of the website's owner"],"answer":0,"explanation":"Packet filters look only at header fields such as IP addresses, port numbers and protocol. Inspecting content or user identity needs application-level or next-generation firewalls.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"एक साधारण पैकेट-फ़िल्टरिंग फ़ायरवॉल किस आधार पर ट्रैफ़िक को अनुमति देता या रोकता है?","optionsHi":["प्रत्येक पैकेट हेडर में स्रोत और गंतव्य IP पते, पोर्ट और प्रोटोकॉल","ई-मेल अनुलग्नकों की पूरी सामग्री","प्रत्येक PC पर लॉग-इन उपयोगकर्ता की पहचान","वेबसाइट के स्वामी की प्रतिष्ठा"],"explanationHi":"पैकेट फ़िल्टर केवल हेडर क्षेत्रों जैसे IP पते, पोर्ट संख्या और प्रोटोकॉल को देखते हैं। सामग्री या उपयोगकर्ता की पहचान की जाँच के लिए एप्लिकेशन-स्तर या नेक्स्ट-जनरेशन फ़ायरवॉल चाहिए।"},
  {"id":"comp-awareness-197","question":"Which SQL command removes all the rows of a table AND the table's definition, so the table no longer exists?","options":["TRUNCATE TABLE","DELETE FROM","DROP TABLE","ALTER TABLE"],"answer":2,"explanation":"DROP removes the data and the structure. TRUNCATE and DELETE without WHERE empty the table but leave its definition in place.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"कौन-सा SQL कमांड तालिका की सभी पंक्तियों और तालिका की परिभाषा, दोनों को हटा देता है, जिससे तालिका का अस्तित्व ही नहीं रहता?","optionsHi":["TRUNCATE TABLE","DELETE FROM","DROP TABLE","ALTER TABLE"],"explanationHi":"DROP डेटा और संरचना दोनों को हटाता है। बिना WHERE के TRUNCATE और DELETE तालिका को खाली कर देते हैं पर उसकी परिभाषा बनी रहती है।"},
  {"id":"comp-awareness-198","question":"An ORDERS table has CustomerID as a foreign key referring to CUSTOMER. A clerk tries to insert an order with CustomerID 9999, which does not exist in CUSTOMER. Which constraint is violated?","options":["Entity integrity","Domain integrity","Uniqueness of the primary key","Referential integrity"],"answer":3,"explanation":"Referential integrity requires every foreign-key value to match an existing primary key (or be NULL). Entity integrity concerns NULLs in the primary key of the same table.","difficulty":"hard","source":"IBPS SO IT · SBI PO","questionHi":"ORDERS तालिका में CustomerID एक फ़ॉरेन की है जो CUSTOMER को संदर्भित करती है। एक क्लर्क CustomerID 9999 वाला ऑर्डर डालने का प्रयास करता है, जो CUSTOMER में मौजूद नहीं है। कौन-सा प्रतिबंध भंग होता है?","optionsHi":["एंटिटी इंटेग्रिटी","डोमेन इंटेग्रिटी","प्राइमरी की की अद्वितीयता","रेफ़रेंशियल इंटेग्रिटी"],"explanationHi":"रेफ़रेंशियल इंटेग्रिटी के अनुसार प्रत्येक फ़ॉरेन-की मान किसी मौजूदा प्राइमरी की से मेल खाना चाहिए (या NULL होना चाहिए)। एंटिटी इंटेग्रिटी उसी तालिका की प्राइमरी की में NULL से संबंधित है।"},
  {"id":"comp-awareness-199","question":"Which SQL command is placed in the WRONG category?","options":["CREATE — Data Definition Language","GRANT — Data Control Language","UPDATE — Data Definition Language","SELECT — Data Query/Manipulation Language"],"answer":2,"explanation":"UPDATE changes the data inside a table, so it is DML. DDL commands (CREATE, ALTER, DROP, TRUNCATE) change the structure.","difficulty":"moderate","source":"IBPS SO IT · IBPS PO Mains","questionHi":"कौन-सा SQL कमांड गलत श्रेणी में रखा गया है?","optionsHi":["CREATE — डेटा डेफ़िनिशन लैंग्वेज","GRANT — डेटा कंट्रोल लैंग्वेज","UPDATE — डेटा डेफ़िनिशन लैंग्वेज","SELECT — डेटा क्वेरी/मैनिपुलेशन लैंग्वेज"],"explanationHi":"UPDATE तालिका के भीतर का डेटा बदलता है, इसलिए वह DML है। DDL कमांड (CREATE, ALTER, DROP, TRUNCATE) संरचना बदलते हैं।"},
  {"id":"comp-awareness-200","question":"Which of the following is NOT shared by the threads of one process?","options":["The program code","Global data","Open files","The stack"],"answer":3,"explanation":"Threads share their process's code, global data and open files, but each thread has its own stack and registers so it can run its own sequence of calls.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"निम्नलिखित में से कौन-सा एक प्रक्रिया के थ्रेडों द्वारा साझा नहीं किया जाता?","optionsHi":["प्रोग्राम कोड","ग्लोबल डेटा","खुली फ़ाइलें","स्टैक"],"explanationHi":"थ्रेड अपनी प्रक्रिया का कोड, ग्लोबल डेटा और खुली फ़ाइलें साझा करते हैं, परंतु प्रत्येक थ्रेड का अपना स्टैक और रजिस्टर होते हैं ताकि वह अपने कॉलों का अनुक्रम चला सके।"},
  {"id":"comp-awareness-201","question":"Print jobs from many users are first stored on disk and sent to a slow printer one by one, so the CPU can carry on with other work. This technique is called:","options":["Spooling","Paging","Thrashing","Swapping"],"answer":0,"explanation":"Spooling (Simultaneous Peripheral Operations On-Line) queues output for a slow device on disk. Paging and swapping move memory pages or processes, and thrashing is excessive paging.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"कई उपयोगकर्ताओं के प्रिंट कार्य पहले डिस्क पर संग्रहीत किए जाते हैं और एक-एक करके धीमे प्रिंटर को भेजे जाते हैं, ताकि CPU अन्य कार्य करता रह सके। इस तकनीक को कहते हैं:","optionsHi":["स्पूलिंग","पेजिंग","थ्रैशिंग","स्वैपिंग"],"explanationHi":"स्पूलिंग (Simultaneous Peripheral Operations On-Line) धीमे उपकरण के आउटपुट को डिस्क पर कतार में रखती है। पेजिंग और स्वैपिंग मेमोरी पेजों या प्रक्रियाओं को स्थानांतरित करती हैं, और थ्रैशिंग अत्यधिक पेजिंग है।"},
  {"id":"comp-awareness-202","question":"Which sequence correctly describes how a TCP connection is set up by the three-way handshake?","options":["Server sends SYN first, client replies with SYN-ACK, server finishes with ACK","Client sends SYN, server replies with SYN-ACK, client finishes with ACK","Client sends SYN, server replies with FIN, client finishes with ACK","Client sends SYN and ACK together, server replies with SYN, client sends nothing more"],"answer":1,"explanation":"The side opening the connection (client) sends SYN, the server answers SYN-ACK (its own SYN plus an acknowledgement), and the client confirms with ACK. FIN is used to CLOSE a connection.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"कौन-सा क्रम थ्री-वे हैंडशेक द्वारा TCP कनेक्शन स्थापित होने का सही वर्णन करता है?","optionsHi":["सर्वर पहले SYN भेजता है, क्लाइंट SYN-ACK से उत्तर देता है, सर्वर ACK से पूरा करता है","क्लाइंट SYN भेजता है, सर्वर SYN-ACK से उत्तर देता है, क्लाइंट ACK से पूरा करता है","क्लाइंट SYN भेजता है, सर्वर FIN से उत्तर देता है, क्लाइंट ACK से पूरा करता है","क्लाइंट SYN और ACK एक साथ भेजता है, सर्वर SYN से उत्तर देता है, क्लाइंट और कुछ नहीं भेजता"],"explanationHi":"कनेक्शन खोलने वाला पक्ष (क्लाइंट) SYN भेजता है, सर्वर SYN-ACK (अपने SYN के साथ पावती) से उत्तर देता है, और क्लाइंट ACK से पुष्टि करता है। FIN कनेक्शन को बंद करने के लिए प्रयोग होता है।"},
  {"id":"comp-awareness-203","question":"How does the Harvard architecture differ from the von Neumann architecture?","options":["It has no main memory, only registers","It keeps instructions and data in separate memories with separate buses","It stores programs on magnetic tape instead of RAM","It uses decimal rather than binary arithmetic"],"answer":1,"explanation":"Von Neumann machines share one memory and bus for code and data (causing the 'von Neumann bottleneck'); Harvard designs give instructions and data separate memories and paths so both can be fetched at once.","difficulty":"hard","source":"IBPS SO IT · SBI PO","questionHi":"हार्वर्ड आर्किटेक्चर वॉन न्यूमैन आर्किटेक्चर से कैसे भिन्न है?","optionsHi":["इसमें मुख्य मेमोरी नहीं होती, केवल रजिस्टर होते हैं","यह निर्देशों और डेटा को अलग-अलग बसों वाली अलग मेमोरी में रखता है","यह प्रोग्रामों को RAM के बजाय चुंबकीय टेप पर संग्रहीत करता है","यह बाइनरी के बजाय दशमलव अंकगणित का प्रयोग करता है"],"explanationHi":"वॉन न्यूमैन मशीनें कोड और डेटा के लिए एक ही मेमोरी और बस साझा करती हैं (जिससे ‘वॉन न्यूमैन बॉटलनेक’ बनता है); हार्वर्ड डिज़ाइन निर्देशों और डेटा को अलग मेमोरी और मार्ग देते हैं ताकि दोनों एक साथ लाए जा सकें।"},
  {"id":"comp-awareness-204","question":"A processor runs at 2 GHz. An instruction that needs 4 clock cycles takes how long to execute?","options":["8 ns","0.5 ns","2 ns","0.125 ns"],"answer":2,"explanation":"At 2 GHz one cycle lasts 1 ÷ (2 × 10⁹) s = 0.5 ns, so 4 cycles take 2 ns. 8 ns wrongly multiplies the frequency by the cycles.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक प्रोसेसर 2 GHz पर चलता है। जिस निर्देश को 4 क्लॉक चक्र चाहिए, उसके निष्पादन में कितना समय लगता है?","optionsHi":["8 ns","0.5 ns","2 ns","0.125 ns"],"explanationHi":"2 GHz पर एक चक्र 1 ÷ (2 × 10⁹) s = 0.5 ns का होता है, इसलिए 4 चक्र 2 ns लेते हैं। 8 ns गलती से आवृत्ति को चक्रों से गुणा कर देता है।"},
  {"id":"comp-awareness-205","question":"A 2 GHz processor needs on average 2.5 clock cycles per instruction (CPI). What is its speed in MIPS (million instructions per second)?","options":["5000 MIPS","800 MIPS","500 MIPS","1250 MIPS"],"answer":1,"explanation":"MIPS = clock rate ÷ (CPI × 10⁶) = 2000 MHz ÷ 2.5 = 800. Multiplying by the CPI instead of dividing gives the trap answer 5000.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"एक 2 GHz प्रोसेसर को औसतन 2.5 क्लॉक चक्र प्रति निर्देश (CPI) चाहिए। उसकी गति MIPS (मिलियन निर्देश प्रति सेकंड) में क्या है?","optionsHi":["5000 MIPS","800 MIPS","500 MIPS","1250 MIPS"],"explanationHi":"MIPS = क्लॉक दर ÷ (CPI × 10⁶) = 2000 MHz ÷ 2.5 = 800। भाग देने के बजाय CPI से गुणा करने पर जाल वाला उत्तर 5000 आता है।"},
  {"id":"comp-awareness-206","question":"A file system divides a 2 GB partition into blocks of 4 KB each (1 KB = 1024 bytes, 1 GB = 1024 MB). How many blocks are there?","options":["500,000","512,000","262,144","524,288"],"answer":3,"explanation":"2 GB = 2³¹ bytes and 4 KB = 2¹² bytes, so there are 2³¹ ÷ 2¹² = 2¹⁹ = 524,288 blocks. 500,000 comes from using powers of 10, which the question rules out.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"एक फ़ाइल सिस्टम 2 GB के पार्टिशन को 4 KB के ब्लॉकों में बाँटता है (1 KB = 1024 बाइट, 1 GB = 1024 MB)। कितने ब्लॉक होंगे?","optionsHi":["500,000","512,000","262,144","524,288"],"explanationHi":"2 GB = 2³¹ बाइट और 4 KB = 2¹² बाइट, इसलिए 2³¹ ÷ 2¹² = 2¹⁹ = 524,288 ब्लॉक होंगे। 500,000, 10 की घातों के प्रयोग से आता है, जिसे प्रश्न नकारता है।"},
  {"id":"comp-awareness-207","question":"An uncompressed image is 1920 × 1080 pixels with 24-bit colour. Taking 1 MB = 1024 × 1024 bytes, about how much storage does it need?","options":["About 47.5 MB","About 5.9 MB","About 2.0 MB","About 0.74 MB"],"answer":1,"explanation":"24 bits = 3 bytes per pixel: 1920 × 1080 × 3 = 6,220,800 bytes ≈ 5.93 MB. 47.5 MB forgets to convert bits to bytes, and 2.0 MB treats each pixel as 1 byte.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक असंपीड़ित छवि 1920 × 1080 पिक्सेल की है और 24-बिट रंग वाली है। 1 MB = 1024 × 1024 बाइट लेने पर, उसे लगभग कितना संग्रहण चाहिए?","optionsHi":["लगभग 47.5 MB","लगभग 5.9 MB","लगभग 2.0 MB","लगभग 0.74 MB"],"explanationHi":"24 बिट = 3 बाइट प्रति पिक्सेल: 1920 × 1080 × 3 = 6,220,800 बाइट ≈ 5.93 MB। 47.5 MB बिट को बाइट में बदलना भूल जाता है, और 2.0 MB प्रत्येक पिक्सेल को 1 बाइट मानता है।"},
  {"id":"comp-awareness-208","question":"A branch needs a printer that can print the original and carbon copies of a multi-part form in a single pass. Which printer suits this?","options":["Laser printer","Dot-matrix printer","Inkjet printer","Thermal printer"],"answer":1,"explanation":"Only an impact printer such as dot-matrix strikes the paper hard enough to mark the copies underneath. Laser, inkjet and thermal printers are non-impact.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"किसी शाखा को ऐसा प्रिंटर चाहिए जो बहु-भागीय फ़ॉर्म की मूल प्रति और कार्बन प्रतियाँ एक ही बार में छाप सके। कौन-सा प्रिंटर उपयुक्त है?","optionsHi":["लेज़र प्रिंटर","डॉट-मैट्रिक्स प्रिंटर","इंकजेट प्रिंटर","थर्मल प्रिंटर"],"explanationHi":"केवल डॉट-मैट्रिक्स जैसा इम्पैक्ट प्रिंटर कागज़ पर इतनी ज़ोर से प्रहार करता है कि नीचे की प्रतियों पर भी निशान पड़ें। लेज़र, इंकजेट और थर्मल प्रिंटर नॉन-इम्पैक्ट हैं।"},
  {"id":"comp-awareness-209","question":"Match each reader with its typical use: 1. MICR 2. OMR 3. OCR 4. Barcode reader; a. converting a scanned printed page into editable text b. reading the code line at the bottom of a cheque c. checking shaded bubbles on an exam answer sheet d. reading a product's price tag at a billing counter","options":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-a, 2-c, 3-b, 4-d"],"answer":1,"explanation":"MICR reads magnetic-ink characters on cheques, OMR detects pencil marks in fixed positions, OCR recognises printed characters, and barcode readers read product codes.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"प्रत्येक रीडर का उसके सामान्य प्रयोग से मिलान कीजिए: 1. MICR 2. OMR 3. OCR 4. बारकोड रीडर; a. स्कैन किए गए मुद्रित पृष्ठ को संपादन-योग्य पाठ में बदलना b. चेक के नीचे की कोड पंक्ति पढ़ना c. परीक्षा उत्तर-पत्रक पर भरे गए गोलों की जाँच करना d. बिलिंग काउंटर पर किसी उत्पाद का मूल्य-टैग पढ़ना","optionsHi":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-a, 2-c, 3-b, 4-d"],"explanationHi":"MICR चेकों पर चुंबकीय स्याही के अक्षर पढ़ता है, OMR निश्चित स्थानों पर पेंसिल के निशान पहचानता है, OCR मुद्रित अक्षरों को पहचानता है, और बारकोड रीडर उत्पाद कोड पढ़ते हैं।"},
  {"id":"comp-awareness-210","question":"Which port carries both high-definition digital video and multichannel audio over a single cable?","options":["VGA","PS/2","HDMI","DVI"],"answer":2,"explanation":"HDMI carries digital video and audio together. VGA is analogue video only, DVI is designed for video, and PS/2 connected keyboards and mice.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"कौन-सा पोर्ट एक ही केबल पर उच्च-परिभाषा डिजिटल वीडियो और बहु-चैनल ऑडियो दोनों ले जाता है?","optionsHi":["VGA","PS/2","HDMI","DVI"],"explanationHi":"HDMI डिजिटल वीडियो और ऑडियो दोनों साथ ले जाता है। VGA केवल एनालॉग वीडियो है, DVI वीडियो के लिए बना है, और PS/2 कीबोर्ड तथा माउस जोड़ता था।"},
  {"id":"comp-awareness-211","question":"How many of these statements about CPU cache levels are correct? I. L1 cache is the smallest and fastest. II. In multi-core processors, L3 cache is usually shared by all the cores. III. L2 cache is larger than L1 but slower. IV. If the data is not found in any cache level, it is fetched from main memory (RAM).","options":["Two","Three","Four","One"],"answer":2,"explanation":"All four are correct: L1 is the smallest and fastest, L2 is larger but slower, L3 is usually shared by all cores, and a miss at every cache level sends the request on to main memory.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"CPU कैश स्तरों के बारे में इनमें से कितने कथन सही हैं? I. L1 कैश सबसे छोटा और सबसे तेज़ होता है। II. बहु-कोर प्रोसेसरों में L3 कैश आमतौर पर सभी कोरों द्वारा साझा होता है। III. L2 कैश L1 से बड़ा पर धीमा होता है। IV. यदि डेटा किसी भी कैश स्तर में नहीं मिलता, तो उसे मुख्य मेमोरी (RAM) से लाया जाता है।","optionsHi":["दो","तीन","चार","एक"],"explanationHi":"चारों सही हैं: L1 सबसे छोटा और सबसे तेज़ है, L2 बड़ा पर धीमा है, L3 आमतौर पर सभी कोरों द्वारा साझा होता है, और हर कैश स्तर पर मिस होने पर अनुरोध मुख्य मेमोरी तक जाता है।"},
  {"id":"comp-awareness-212","question":"A disk controller copies a large block of data straight into RAM and interrupts the CPU only once, when the whole transfer is over. This technique is:","options":["Programmed I/O with polling","Interrupt-driven I/O, one interrupt per byte","Spooling","Direct Memory Access (DMA)"],"answer":3,"explanation":"With DMA the controller moves the data itself and signals the CPU only at the end, leaving the CPU free. In programmed and interrupt-driven I/O, the CPU handles every word.","difficulty":"hard","source":"IBPS SO IT · SBI PO","questionHi":"एक डिस्क कंट्रोलर डेटा का एक बड़ा ब्लॉक सीधे RAM में कॉपी करता है और पूरा स्थानांतरण समाप्त होने पर केवल एक बार CPU को इंटरप्ट करता है। यह तकनीक है:","optionsHi":["पोलिंग वाला प्रोग्राम्ड I/O","इंटरप्ट-चालित I/O, प्रति बाइट एक इंटरप्ट","स्पूलिंग","डायरेक्ट मेमोरी एक्सेस (DMA)"],"explanationHi":"DMA में कंट्रोलर स्वयं डेटा ले जाता है और केवल अंत में CPU को संकेत देता है, जिससे CPU मुक्त रहता है। प्रोग्राम्ड और इंटरप्ट-चालित I/O में CPU प्रत्येक शब्द संभालता है।"},
  {"id":"comp-awareness-213","question":"A server with four CPUs runs four different processes truly at the same instant. This is best described as:","options":["Multiprogramming","Multiprocessing","Time-sharing on a single processor","Batch processing"],"answer":1,"explanation":"Multiprocessing uses more than one processor, so several processes run in parallel. Multiprogramming and time-sharing on one CPU only interleave processes; they never run at the same instant.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"चार CPU वाला एक सर्वर चार भिन्न प्रक्रियाओं को वास्तव में एक ही क्षण में चलाता है। इसे सबसे उपयुक्त रूप से कहा जाएगा:","optionsHi":["मल्टीप्रोग्रामिंग","मल्टीप्रोसेसिंग","एकल प्रोसेसर पर टाइम-शेयरिंग","बैच प्रोसेसिंग"],"explanationHi":"मल्टीप्रोसेसिंग एक से अधिक प्रोसेसर का प्रयोग करती है, इसलिए कई प्रक्रियाएँ समानांतर चलती हैं। एक CPU पर मल्टीप्रोग्रामिंग और टाइम-शेयरिंग प्रक्रियाओं को केवल बारी-बारी से चलाती हैं; वे कभी एक ही क्षण में नहीं चलतीं।"},
  {"id":"comp-awareness-214","question":"A user program needs to read a file from disk, which only the operating system may do. How does it get the OS to do this?","options":["By making a system call, which switches the CPU into kernel mode","By writing directly to the disk controller's registers","By calling the BIOS from user mode","By raising its own process priority"],"answer":0,"explanation":"Protected operations run in kernel mode; a user program requests them through a system call (trap). Direct hardware access from user mode is blocked by the OS.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"किसी उपयोगकर्ता प्रोग्राम को डिस्क से फ़ाइल पढ़नी है, जो केवल ऑपरेटिंग सिस्टम कर सकता है। वह OS से यह कैसे करवाता है?","optionsHi":["सिस्टम कॉल करके, जो CPU को कर्नेल मोड में ले जाता है","डिस्क कंट्रोलर के रजिस्टरों में सीधे लिखकर","यूज़र मोड से BIOS को कॉल करके","अपनी प्रक्रिया प्राथमिकता बढ़ाकर"],"explanationHi":"संरक्षित संक्रियाएँ कर्नेल मोड में चलती हैं; उपयोगकर्ता प्रोग्राम उन्हें सिस्टम कॉल (ट्रैप) के माध्यम से माँगता है। यूज़र मोड से सीधी हार्डवेयर पहुँच को OS रोक देता है।"},
  {"id":"comp-awareness-215","question":"Which pairing of memory-management scheme and the kind of fragmentation it suffers from is correct?","options":["Paging — external; segmentation — internal","Paging — none; segmentation — none","Paging — internal; segmentation — external","Paging — internal; segmentation — internal"],"answer":2,"explanation":"Paging uses fixed-size frames, so space is wasted inside the last page (internal). Segments vary in size, leaving scattered free holes between them (external).","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"मेमोरी-प्रबंधन योजना और जिस प्रकार के विखंडन से वह ग्रस्त होती है, उसका कौन-सा युग्म सही है?","optionsHi":["पेजिंग — बाह्य; सेगमेंटेशन — आंतरिक","पेजिंग — कोई नहीं; सेगमेंटेशन — कोई नहीं","पेजिंग — आंतरिक; सेगमेंटेशन — बाह्य","पेजिंग — आंतरिक; सेगमेंटेशन — आंतरिक"],"explanationHi":"पेजिंग निश्चित आकार के फ़्रेम प्रयोग करती है, इसलिए अंतिम पेज के भीतर स्थान व्यर्थ जाता है (आंतरिक)। सेगमेंट आकार में भिन्न होते हैं, जिससे उनके बीच बिखरे खाली स्थान बचते हैं (बाह्य)।"},
  {"id":"comp-awareness-216","question":"A process has 3 page frames, all empty at first, and refers to pages in the order 5, 0, 3, 5, 1, 0, 5, 2, 0, 1, 3. How many page faults occur under FIFO and under LRU replacement?","options":["FIFO 8, LRU 9","FIFO 9, LRU 9","FIFO 9, LRU 8","FIFO 6, LRU 8"],"answer":2,"explanation":"FIFO faults on 5, 0, 3, 1, 5, 2, 0, 1, 3 = 9. LRU keeps 5 and 0 longer because they were just used and faults on 5, 0, 3, 1, 0, 2, 1, 3 = 8. Six is the count for the optimal policy.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"एक प्रक्रिया के पास 3 पेज फ़्रेम हैं, जो शुरू में सब खाली हैं, और वह पेजों का संदर्भ इस क्रम में देती है: 5, 0, 3, 5, 1, 0, 5, 2, 0, 1, 3। FIFO और LRU प्रतिस्थापन में कितने पेज फ़ॉल्ट होंगे?","optionsHi":["FIFO 8, LRU 9","FIFO 9, LRU 9","FIFO 9, LRU 8","FIFO 6, LRU 8"],"explanationHi":"FIFO में 5, 0, 3, 1, 5, 2, 0, 1, 3 पर फ़ॉल्ट = 9। LRU 5 और 0 को अधिक देर तक रखता है क्योंकि वे अभी प्रयोग हुए थे और 5, 0, 3, 1, 0, 2, 1, 3 पर फ़ॉल्ट = 8। छह इष्टतम नीति की गिनती है।"},
  {"id":"comp-awareness-217","question":"Arrange these networks from the smallest to the largest geographical coverage.","options":["LAN < PAN < MAN < WAN","PAN < LAN < WAN < MAN","PAN < MAN < LAN < WAN","PAN < LAN < MAN < WAN"],"answer":3,"explanation":"A PAN covers a person's surroundings (e.g. Bluetooth), a LAN a building, a MAN a city, and a WAN countries or the globe.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"इन नेटवर्कों को सबसे छोटे से सबसे बड़े भौगोलिक विस्तार के क्रम में व्यवस्थित कीजिए।","optionsHi":["LAN < PAN < MAN < WAN","PAN < LAN < WAN < MAN","PAN < MAN < LAN < WAN","PAN < LAN < MAN < WAN"],"explanationHi":"PAN किसी व्यक्ति के आसपास को कवर करता है (जैसे ब्लूटूथ), LAN एक इमारत को, MAN एक शहर को, और WAN देशों या पूरे विश्व को।"},
  {"id":"comp-awareness-218","question":"Under classful addressing, what is the default subnet mask of the host 150.10.5.7?","options":["255.0.0.0","255.255.0.0","255.255.255.0","255.255.255.255"],"answer":1,"explanation":"A first octet of 128–191 marks a class B address, whose default mask is 255.255.0.0. Class A (1–126) uses 255.0.0.0 and class C (192–223) uses 255.255.255.0.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"क्लासफ़ुल पता-निर्धारण में, होस्ट 150.10.5.7 का डिफ़ॉल्ट सबनेट मास्क क्या है?","optionsHi":["255.0.0.0","255.255.0.0","255.255.255.0","255.255.255.255"],"explanationHi":"पहले ऑक्टेट का 128–191 होना क्लास B पते को दर्शाता है, जिसका डिफ़ॉल्ट मास्क 255.255.0.0 है। क्लास A (1–126) 255.0.0.0 और क्लास C (192–223) 255.255.255.0 का प्रयोग करता है।"},
  {"id":"comp-awareness-219","question":"A host has the address 192.168.10.77/26. What are the network address and the broadcast address of its subnet?","options":["192.168.10.0 and 192.168.10.255","192.168.10.77 and 192.168.10.127","192.168.10.64 and 192.168.10.128","192.168.10.64 and 192.168.10.127"],"answer":3,"explanation":"/26 makes blocks of 64 addresses: 0–63, 64–127, 128–191, 192–255. 77 falls in 64–127, so the network is .64 and the broadcast is .127. The .0/.255 pair ignores the subnet mask.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"एक होस्ट का पता 192.168.10.77/26 है। उसके सबनेट का नेटवर्क पता और ब्रॉडकास्ट पता क्या हैं?","optionsHi":["192.168.10.0 और 192.168.10.255","192.168.10.77 और 192.168.10.127","192.168.10.64 और 192.168.10.128","192.168.10.64 और 192.168.10.127"],"explanationHi":"/26 से 64 पतों के ब्लॉक बनते हैं: 0–63, 64–127, 128–191, 192–255। 77, 64–127 में आता है, इसलिए नेटवर्क .64 और ब्रॉडकास्ट .127 है। .0/.255 का युग्म सबनेट मास्क की उपेक्षा करता है।"},
  {"id":"comp-awareness-220","question":"Which protocol transfers files securely by running over an SSH connection?","options":["SFTP","FTP","TFTP","SMTP"],"answer":0,"explanation":"SFTP (SSH File Transfer Protocol) uses SSH, by default on port 22, for encrypted transfer. FTP and TFTP send data in plain text, and SMTP sends e-mail.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"कौन-सा प्रोटोकॉल SSH कनेक्शन पर चलकर फ़ाइलें सुरक्षित रूप से स्थानांतरित करता है?","optionsHi":["SFTP","FTP","TFTP","SMTP"],"explanationHi":"SFTP (SSH फ़ाइल ट्रांसफर प्रोटोकॉल) एन्क्रिप्टेड स्थानांतरण के लिए SSH का प्रयोग करता है, डिफ़ॉल्ट रूप से पोर्ट 22 पर। FTP और TFTP डेटा सादे पाठ में भेजते हैं, और SMTP ई-मेल भेजता है।"},
  {"id":"comp-awareness-221","question":"A bank clerk logs in with a valid password but finds he can only view loan files, not approve them. The rule that limits what he may do after logging in is called:","options":["Authentication","Authorisation","Non-repudiation","Encryption"],"answer":1,"explanation":"Authentication proves WHO the user is (the password); authorisation decides WHAT that user may access or do. Non-repudiation stops someone denying an action they took.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक बैंक क्लर्क वैध पासवर्ड से लॉगिन करता है पर पाता है कि वह केवल ऋण फ़ाइलें देख सकता है, उन्हें स्वीकृत नहीं कर सकता। लॉगिन के बाद वह क्या कर सकता है, इसे सीमित करने वाला नियम कहलाता है:","optionsHi":["प्रमाणीकरण (ऑथेंटिकेशन)","प्राधिकरण (ऑथराइज़ेशन)","अस्वीकार-रोधन (नॉन-रिप्यूडिएशन)","एन्क्रिप्शन"],"explanationHi":"ऑथेंटिकेशन सिद्ध करता है कि उपयोगकर्ता कौन है (पासवर्ड); ऑथराइज़ेशन तय करता है कि वह उपयोगकर्ता क्या एक्सेस कर या कर सकता है। नॉन-रिप्यूडिएशन किसी को अपनी की हुई क्रिया से मुकरने से रोकता है।"},
  {"id":"comp-awareness-222","question":"An outsider without an access card walks into a bank's server room by closely following an employee through the secured door. This social-engineering trick is called:","options":["Shoulder surfing","Tailgating","Dumpster diving","Vishing"],"answer":1,"explanation":"Tailgating (piggybacking) means slipping into a restricted area behind someone authorised. Shoulder surfing is watching someone type, dumpster diving is searching discarded material, and vishing is voice phishing.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक बाहरी व्यक्ति, जिसके पास एक्सेस कार्ड नहीं है, किसी कर्मचारी के ठीक पीछे-पीछे सुरक्षित दरवाज़े से होकर बैंक के सर्वर रूम में घुस जाता है। इस सोशल-इंजीनियरिंग चाल को कहते हैं:","optionsHi":["शोल्डर सर्फ़िंग","टेलगेटिंग","डंपस्टर डाइविंग","विशिंग"],"explanationHi":"टेलगेटिंग (पिगीबैकिंग) का अर्थ है किसी अधिकृत व्यक्ति के पीछे से प्रतिबंधित क्षेत्र में घुस जाना। शोल्डर सर्फ़िंग किसी को टाइप करते देखना है, डंपस्टर डाइविंग फेंकी गई सामग्री में खोजना है, और विशिंग वॉइस फ़िशिंग है।"},
  {"id":"comp-awareness-223","question":"The word BANK is encrypted with a Caesar cipher that shifts each letter 3 places forward in the alphabet. What is the ciphertext?","options":["YXKH","EDQN","EDNQ","CBOL"],"answer":1,"explanation":"B→E, A→D, N→Q, K→N gives EDQN. YXKH shifts backwards, and CBOL shifts by only 1.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"शब्द BANK को सीज़र सिफ़र से एन्क्रिप्ट किया जाता है, जो प्रत्येक अक्षर को वर्णमाला में 3 स्थान आगे खिसकाता है। सिफ़रटेक्स्ट क्या है?","optionsHi":["YXKH","EDQN","EDNQ","CBOL"],"explanationHi":"B→E, A→D, N→Q, K→N से EDQN मिलता है। YXKH पीछे की ओर खिसकाता है, और CBOL केवल 1 स्थान खिसकाता है।"},
  {"id":"comp-awareness-224","question":"In SQL, which clause filters the groups produced by GROUP BY, for example to keep only branches whose total deposits exceed ₹1 crore?","options":["WHERE","ORDER BY","HAVING","DISTINCT"],"answer":2,"explanation":"WHERE filters individual rows BEFORE grouping and cannot use aggregates such as SUM(); HAVING filters the groups AFTER aggregation.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"SQL में कौन-सा क्लॉज़ GROUP BY से बने समूहों को फ़िल्टर करता है, जैसे केवल उन शाखाओं को रखने के लिए जिनकी कुल जमा राशि ₹1 करोड़ से अधिक है?","optionsHi":["WHERE","ORDER BY","HAVING","DISTINCT"],"explanationHi":"WHERE समूह बनाने से पहले अलग-अलग पंक्तियों को फ़िल्टर करता है और SUM() जैसे समुच्चय फ़ंक्शन का प्रयोग नहीं कर सकता; HAVING समुच्चयन के बाद समूहों को फ़िल्टर करता है।"},
  {"id":"comp-awareness-225","question":"A table CUSTOMER has 6 rows; the Phone column is NULL in 2 of them. What do COUNT(*) and COUNT(Phone) return?","options":["6 and 6","4 and 4","6 and 4","4 and 6"],"answer":2,"explanation":"COUNT(*) counts every row, including those with NULLs, so it gives 6; COUNT(column) ignores NULL values, so COUNT(Phone) gives 4.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"CUSTOMER तालिका में 6 पंक्तियाँ हैं; उनमें से 2 में Phone स्तंभ NULL है। COUNT(*) और COUNT(Phone) क्या लौटाते हैं?","optionsHi":["6 और 6","4 और 4","6 और 4","4 और 6"],"explanationHi":"COUNT(*) NULL वाली पंक्तियों सहित प्रत्येक पंक्ति गिनता है, इसलिए 6 देता है; COUNT(column) NULL मानों की उपेक्षा करता है, इसलिए COUNT(Phone) 4 देता है।"},
  {"id":"comp-awareness-226","question":"A bank allows joint accounts: one customer may hold several accounts, and one account may belong to several customers. What is the cardinality of the CUSTOMER–ACCOUNT relationship?","options":["One-to-one","One-to-many","Many-to-one","Many-to-many"],"answer":3,"explanation":"Both sides can have more than one partner, so it is many-to-many; in a relational design it needs a separate linking table such as DEPOSITOR(CustomerID, AccountNo).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"एक बैंक संयुक्त खातों की अनुमति देता है: एक ग्राहक के कई खाते हो सकते हैं, और एक खाता कई ग्राहकों का हो सकता है। CUSTOMER–ACCOUNT संबंध की कार्डिनैलिटी क्या है?","optionsHi":["एक-से-एक","एक-से-अनेक","अनेक-से-एक","अनेक-से-अनेक"],"explanationHi":"दोनों ओर एक से अधिक साझेदार हो सकते हैं, इसलिए यह अनेक-से-अनेक है; रिलेशनल डिज़ाइन में इसके लिए DEPOSITOR(CustomerID, AccountNo) जैसी अलग लिंकिंग तालिका चाहिए।"},
  {"id":"comp-awareness-227","question":"In an ER model, the entity DEPENDENT (an employee's family member) cannot be uniquely identified without the EMPLOYEE it belongs to. What is DEPENDENT, and how is it drawn?","options":["A weak entity, drawn as a double rectangle","A strong entity, drawn as a double rectangle","A derived attribute, drawn as a dashed ellipse","A weak entity, drawn as a dashed ellipse"],"answer":0,"explanation":"An entity with no key of its own, identified through an owner entity, is a weak entity and is shown with a double rectangle (its identifying relationship as a double diamond). A dashed ellipse marks a derived attribute.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"ER मॉडल में, एंटिटी DEPENDENT (कर्मचारी का परिवार-सदस्य) अपने EMPLOYEE के बिना अद्वितीय रूप से पहचानी नहीं जा सकती। DEPENDENT क्या है, और उसे कैसे बनाया जाता है?","optionsHi":["वीक एंटिटी, दोहरे आयत के रूप में बनाई जाती है","स्ट्रॉन्ग एंटिटी, दोहरे आयत के रूप में बनाई जाती है","व्युत्पन्न एट्रिब्यूट, बिंदीदार अंडाकार के रूप में बनाया जाता है","वीक एंटिटी, बिंदीदार अंडाकार के रूप में बनाई जाती है"],"explanationHi":"जिस एंटिटी की अपनी कोई की नहीं होती और जो स्वामी एंटिटी के माध्यम से पहचानी जाती है, वह वीक एंटिटी है और दोहरे आयत से दिखाई जाती है (उसका पहचान-संबंध दोहरे समचतुर्भुज से)। बिंदीदार अंडाकार व्युत्पन्न एट्रिब्यूट को दर्शाता है।"},
  {"id":"comp-awareness-228","question":"A database administrator moves a table to a faster disk and adds a new index. Neither the logical schema nor any application program has to change. This illustrates:","options":["Physical data independence","Logical data independence","Data redundancy","Referential integrity"],"answer":0,"explanation":"Changing how data is stored without affecting the logical (conceptual) schema is physical data independence. Logical data independence is changing the logical schema without affecting user views, which is harder to achieve.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"एक डेटाबेस प्रशासक किसी तालिका को तेज़ डिस्क पर ले जाता है और एक नया इंडेक्स जोड़ता है। न तार्किक स्कीमा बदलना पड़ता है, न कोई एप्लिकेशन प्रोग्राम। यह दर्शाता है:","optionsHi":["भौतिक डेटा स्वतंत्रता","तार्किक डेटा स्वतंत्रता","डेटा पुनरावृत्ति (रिडंडेंसी)","रेफ़रेंशियल इंटेग्रिटी"],"explanationHi":"तार्किक (संकल्पनात्मक) स्कीमा को प्रभावित किए बिना डेटा के संग्रहण का तरीका बदलना भौतिक डेटा स्वतंत्रता है। तार्किक डेटा स्वतंत्रता उपयोगकर्ता दृश्यों को प्रभावित किए बिना तार्किक स्कीमा बदलना है, जिसे प्राप्त करना कठिन है।"},
  {"id":"comp-awareness-229","question":"Assertion (A): Creating an index on a column makes searches on that column faster. Reason (R): Every INSERT or UPDATE on the table must also update the index.","options":["A is true but R is false","Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"Both statements are true, but R describes the COST of an index (slower writes), not why searches get faster. Searches speed up because the index is a sorted structure (such as a B-tree) that avoids scanning the whole table.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"अभिकथन (A): किसी स्तंभ पर इंडेक्स बनाने से उस स्तंभ पर खोज तेज़ हो जाती है। कारण (R): तालिका पर प्रत्येक INSERT या UPDATE को इंडेक्स भी अद्यतन करना पड़ता है।","optionsHi":["A सही है, परंतु R गलत है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सही हैं, और R, A की सही व्याख्या है","A गलत है, परंतु R सही है"],"explanationHi":"दोनों कथन सही हैं, पर R इंडेक्स की लागत (धीमे राइट) बताता है, यह नहीं कि खोज तेज़ क्यों होती है। खोज इसलिए तेज़ होती है कि इंडेक्स एक क्रमबद्ध संरचना (जैसे B-ट्री) है जो पूरी तालिका को स्कैन करने से बचाती है।"},
  {"id":"comp-awareness-230","question":"How many of these statements are correct? I. A table can have only one primary key. II. A primary key column can never hold NULL. III. A table can have several UNIQUE constraints. IV. A primary key may consist of more than one column.","options":["One","Two","Three","Four"],"answer":3,"explanation":"All four are correct: a table has one primary key, which is NOT NULL and unique, but it may be composite (several columns), and any number of other columns can carry UNIQUE constraints.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"इनमें से कितने कथन सही हैं? I. एक तालिका में केवल एक प्राइमरी की हो सकती है। II. प्राइमरी की स्तंभ में कभी NULL नहीं हो सकता। III. एक तालिका में कई UNIQUE प्रतिबंध हो सकते हैं। IV. प्राइमरी की में एक से अधिक स्तंभ हो सकते हैं।","optionsHi":["एक","दो","तीन","चार"],"explanationHi":"चारों सही हैं: तालिका में एक प्राइमरी की होती है, जो NOT NULL और अद्वितीय होती है, पर वह संयुक्त (कई स्तंभों वाली) हो सकती है, और कितने भी अन्य स्तंभों पर UNIQUE प्रतिबंध लग सकते हैं।"},
  {"id":"comp-awareness-231","question":"Two ATMs read a joint account's balance of ₹10,000 at the same moment. Each pays out ₹3,000 and writes back its own result. With no locking, what is this problem called and what balance is finally stored?","options":["A race condition (lost update); ₹7,000","A deadlock; ₹4,000","A race condition (lost update); ₹4,000","Starvation; ₹7,000"],"answer":0,"explanation":"Both ATMs compute 10,000 − 3,000 = 7,000, and the second write overwrites the first, so one withdrawal is lost and ₹7,000 is stored instead of ₹4,000. This lost update caused by uncontrolled concurrent access is a race condition.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"दो ATM एक ही क्षण में किसी संयुक्त खाते का शेष ₹10,000 पढ़ते हैं। प्रत्येक ₹3,000 निकालकर अपना परिणाम वापस लिखता है। बिना लॉकिंग के, इस समस्या को क्या कहते हैं और अंत में कौन-सा शेष संग्रहीत होता है?","optionsHi":["रेस कंडीशन (लॉस्ट अपडेट); ₹7,000","डेडलॉक; ₹4,000","रेस कंडीशन (लॉस्ट अपडेट); ₹4,000","स्टार्वेशन; ₹7,000"],"explanationHi":"दोनों ATM 10,000 − 3,000 = 7,000 की गणना करते हैं, और दूसरा राइट पहले को अधिलेखित कर देता है, इसलिए एक निकासी खो जाती है और ₹4,000 के बजाय ₹7,000 संग्रहीत होता है। अनियंत्रित समवर्ती पहुँच से होने वाला यह लॉस्ट अपडेट रेस कंडीशन है।"},
  {"id":"comp-awareness-232","question":"A pen drive shows 20 GB free, yet copying a single 6 GB video file to it fails. Which is the most likely reason?","options":["The drive is formatted as FAT32, which cannot store a single file larger than 4 GB","The drive is formatted as NTFS, which cannot store a single file larger than 4 GB","USB ports cannot transfer files larger than 4 GB","Video files cannot be copied to removable media"],"answer":0,"explanation":"FAT32 limits each file to just under 4 GB, whatever the free space; reformatting to NTFS or exFAT removes the limit. NTFS supports very large files.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक पेन ड्राइव में 20 GB खाली दिखता है, फिर भी 6 GB की एक वीडियो फ़ाइल कॉपी करना विफल हो जाता है। सबसे संभावित कारण कौन-सा है?","optionsHi":["ड्राइव FAT32 में फ़ॉर्मैट है, जो 4 GB से बड़ी एकल फ़ाइल संग्रहीत नहीं कर सकता","ड्राइव NTFS में फ़ॉर्मैट है, जो 4 GB से बड़ी एकल फ़ाइल संग्रहीत नहीं कर सकता","USB पोर्ट 4 GB से बड़ी फ़ाइलें स्थानांतरित नहीं कर सकते","वीडियो फ़ाइलें रिमूवेबल मीडिया पर कॉपी नहीं की जा सकतीं"],"explanationHi":"FAT32 प्रत्येक फ़ाइल को 4 GB से कुछ कम तक सीमित करता है, चाहे खाली स्थान कितना भी हो; NTFS या exFAT में फ़ॉर्मैट करने से सीमा हट जाती है। NTFS बहुत बड़ी फ़ाइलें सँभालता है।"},
  {"id":"comp-awareness-233","question":"The controller that fires a car's airbag must respond within a few milliseconds every single time. What kind of operating system does it need?","options":["A batch operating system","A time-sharing operating system","A hard real-time operating system","A network operating system"],"answer":2,"explanation":"A hard real-time OS guarantees a response within a fixed deadline, where a late answer counts as a failure. Time-sharing systems aim for fair sharing, not guaranteed deadlines.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"कार का एयरबैग चलाने वाले कंट्रोलर को हर बार कुछ मिलीसेकंड के भीतर प्रतिक्रिया देनी होती है। उसे किस प्रकार का ऑपरेटिंग सिस्टम चाहिए?","optionsHi":["बैच ऑपरेटिंग सिस्टम","टाइम-शेयरिंग ऑपरेटिंग सिस्टम","हार्ड रियल-टाइम ऑपरेटिंग सिस्टम","नेटवर्क ऑपरेटिंग सिस्टम"],"explanationHi":"हार्ड रियल-टाइम OS निश्चित समय-सीमा के भीतर प्रतिक्रिया की गारंटी देता है, जहाँ देर से आया उत्तर विफलता माना जाता है। टाइम-शेयरिंग प्रणालियाँ उचित बँटवारे का लक्ष्य रखती हैं, समय-सीमा की गारंटी का नहीं।"},
  {"id":"comp-awareness-234","question":"Which part of an operating system reads the commands a user types and passes them on to the kernel to be carried out?","options":["The BIOS","The compiler","The device driver","The shell"],"answer":3,"explanation":"The shell (command interpreter) is the interface between the user and the kernel. The kernel manages hardware and resources, but it does not read typed commands itself.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO","questionHi":"ऑपरेटिंग सिस्टम का कौन-सा भाग उपयोगकर्ता द्वारा टाइप किए गए कमांड पढ़ता है और उन्हें निष्पादित करने के लिए कर्नेल को सौंपता है?","optionsHi":["BIOS","कंपाइलर","डिवाइस ड्राइवर","शेल"],"explanationHi":"शेल (कमांड इंटरप्रेटर) उपयोगकर्ता और कर्नेल के बीच का इंटरफ़ेस है। कर्नेल हार्डवेयर और संसाधनों का प्रबंधन करता है, पर टाइप किए गए कमांड स्वयं नहीं पढ़ता।"},
  {"id":"comp-awareness-235","question":"A program can be downloaded and used at no cost for as long as you like, but its source code is kept secret and you may not modify it. It is:","options":["Freeware","Open-source software","Shareware","Copyleft software"],"answer":0,"explanation":"Freeware is free of charge but closed. Open-source and copyleft software make the source available to modify, and shareware is free only for a trial period or with limited features.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"कोई प्रोग्राम जब तक चाहें बिना शुल्क डाउनलोड और प्रयोग किया जा सकता है, पर उसका स्रोत कोड गुप्त रखा गया है और आप उसे संशोधित नहीं कर सकते। वह है:","optionsHi":["फ़्रीवेयर","ओपन-सोर्स सॉफ्टवेयर","शेयरवेयर","कॉपीलेफ़्ट सॉफ्टवेयर"],"explanationHi":"फ़्रीवेयर निःशुल्क होता है पर बंद (क्लोज़्ड) होता है। ओपन-सोर्स और कॉपीलेफ़्ट सॉफ्टवेयर संशोधन के लिए स्रोत उपलब्ध कराते हैं, और शेयरवेयर केवल परीक्षण अवधि के लिए या सीमित सुविधाओं के साथ निःशुल्क होता है।"},
  {"id":"comp-awareness-236","question":"Which system program copies an executable file from disk into main memory and prepares it to start running?","options":["Assembler","Linker","Loader","Compiler"],"answer":2,"explanation":"The loader places the program in memory (adjusting addresses if needed) and hands control to it. The linker runs earlier, joining object files into the executable.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"कौन-सा सिस्टम प्रोग्राम डिस्क से एक्ज़ीक्यूटेबल फ़ाइल को मुख्य मेमोरी में कॉपी करता है और उसे चलने के लिए तैयार करता है?","optionsHi":["असेंबलर","लिंकर","लोडर","कंपाइलर"],"explanationHi":"लोडर प्रोग्राम को मेमोरी में रखता है (आवश्यकता होने पर पते समायोजित करके) और नियंत्रण उसे सौंप देता है। लिंकर पहले चलता है, जो ऑब्जेक्ट फ़ाइलों को जोड़कर एक्ज़ीक्यूटेबल बनाता है।"},
  {"id":"comp-awareness-237","question":"Assertion (A): The decimal fraction 0.1 cannot be stored exactly in binary floating point. Reason (R): 1/10 has the factor 5 in its denominator, so its binary expansion repeats forever.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Only fractions whose denominator is a power of 2 terminate in binary. 0.1 = 1/(2 × 5) becomes 0.000110011… repeating, so it is rounded when stored; R gives exactly this reason.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"अभिकथन (A): दशमलव भिन्न 0.1 को बाइनरी फ़्लोटिंग पॉइंट में ठीक-ठीक संग्रहीत नहीं किया जा सकता। कारण (R): 1/10 के हर में गुणनखंड 5 है, इसलिए उसका बाइनरी प्रसार अनंत रूप से दोहराता रहता है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"बाइनरी में केवल वे भिन्न समाप्त होती हैं जिनका हर 2 की घात हो। 0.1 = 1/(2 × 5) का रूप 0.000110011… दोहराता है, इसलिए संग्रहण के समय उसे पूर्णांकित करना पड़ता है; R ठीक यही कारण देता है।"},
  {"id":"comp-awareness-238","question":"What is (1010.11)₂ + (3.25)₁₀, expressed in binary?","options":["(1101.11)₂","(1110.11)₂","(1101.01)₂","(1110)₂"],"answer":3,"explanation":"(1010.11)₂ = 8 + 2 + 0.5 + 0.25 = 10.75, and 10.75 + 3.25 = 14 = (1110)₂. The fractional parts add up to exactly 1, so no fraction is left.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"(1010.11)₂ + (3.25)₁₀ का मान बाइनरी में क्या होगा?","optionsHi":["(1101.11)₂","(1110.11)₂","(1101.01)₂","(1110)₂"],"explanationHi":"(1010.11)₂ = 8 + 2 + 0.5 + 0.25 = 10.75, और 10.75 + 3.25 = 14 = (1110)₂। भिन्नात्मक भाग मिलकर ठीक 1 हो जाते हैं, इसलिए कोई भिन्न शेष नहीं बचती।"},
  {"id":"comp-awareness-239","question":"If (121)_b = (49)₁₀, what is the base b?","options":["6","7","16","28"],"answer":0,"explanation":"(121)_b = b² + 2b + 1 = (b + 1)² = 49, so b + 1 = 7 and b = 6 (check: 36 + 12 + 1 = 49). Stopping at b + 1 gives 7, adding digit × b without powers (3b + 1 = 49) gives 16, and reading 49 as the base-b number and 121 as decimal (4b + 9 = 121) gives 28.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"यदि (121)_b = (49)₁₀ है, तो आधार b क्या है?","optionsHi":["6","7","16","28"],"explanationHi":"(121)_b = b² + 2b + 1 = (b + 1)² = 49, इसलिए b + 1 = 7 और b = 6 (जाँच: 36 + 12 + 1 = 49)। b + 1 पर रुकने से 7 आता है, घात के बिना अंक × b जोड़ने पर (3b + 1 = 49) 16 आता है, और 49 को आधार-b संख्या तथा 121 को दशमलव मानने पर (4b + 9 = 121) 28 आता है।"},
  {"id":"comp-awareness-240","question":"A 16-bit register holds (FFFF)₁₆, read as a two's-complement signed integer. What value does it hold?","options":["65535","−32768","−1","−32767"],"answer":2,"explanation":"All 16 bits are 1; inverting gives 0 and adding 1 gives 1, so the value is −1. 65535 is the unsigned reading, and −32768 is the pattern 8000.","difficulty":"hard","source":"IBPS SO IT · SBI PO","questionHi":"एक 16-बिट रजिस्टर में (FFFF)₁₆ है, जिसे टू’ज़-कॉम्प्लिमेंट चिह्नित पूर्णांक के रूप में पढ़ा जाता है। उसमें कौन-सा मान है?","optionsHi":["65535","−32768","−1","−32767"],"explanationHi":"सभी 16 बिट 1 हैं; उलटने पर 0 मिलता है और 1 जोड़ने पर 1, इसलिए मान −1 है। 65535 अचिह्नित पाठ है, और −32768 पैटर्न 8000 है।"},
  {"id":"comp-awareness-241","question":"Two 8-bit two's-complement numbers, 01100100 (100) and 00110010 (50), are added. What does the 8-bit result hold?","options":["10010110, which reads as −106: an overflow has occurred","10010110, which reads as 150: no overflow","01111111: the result is held at the maximum, 127","00010110 with a carry out of 1, which reads as 22"],"answer":0,"explanation":"The sum 150 exceeds the 8-bit signed maximum of 127. The bits 10010110 are produced, which in two's complement mean 150 − 256 = −106; adding two positives and getting a negative is the sign of overflow.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"दो 8-बिट टू’ज़-कॉम्प्लिमेंट संख्याएँ, 01100100 (100) और 00110010 (50), जोड़ी जाती हैं। 8-बिट परिणाम में क्या होता है?","optionsHi":["10010110, जो −106 पढ़ा जाता है: ओवरफ़्लो हुआ है","10010110, जो 150 पढ़ा जाता है: कोई ओवरफ़्लो नहीं","01111111: परिणाम अधिकतम 127 पर रोक दिया जाता है","00010110 और कैरी-आउट 1, जो 22 पढ़ा जाता है"],"explanationHi":"योग 150, 8-बिट चिह्नित अधिकतम 127 से अधिक है। बिट 10010110 बनते हैं, जिनका टू’ज़ कॉम्प्लिमेंट में अर्थ 150 − 256 = −106 है; दो धनात्मक संख्याएँ जोड़ने पर ऋणात्मक मिलना ओवरफ़्लो का संकेत है।"},
  {"id":"comp-awareness-242","question":"In a half adder, which gates produce the Sum and the Carry outputs?","options":["Sum from AND, Carry from XOR","Sum from XOR, Carry from AND","Sum from OR, Carry from AND","Sum from XNOR, Carry from OR"],"answer":1,"explanation":"Adding two bits gives Sum = 1 when exactly one input is 1 (XOR) and Carry = 1 only when both are 1 (AND).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"हाफ़ एडर में Sum और Carry आउटपुट कौन-से गेट उत्पन्न करते हैं?","optionsHi":["Sum AND से, Carry XOR से","Sum XOR से, Carry AND से","Sum OR से, Carry AND से","Sum XNOR से, Carry OR से"],"explanationHi":"दो बिट जोड़ने पर Sum = 1 तब होता है जब ठीक एक इनपुट 1 हो (XOR) और Carry = 1 तभी होता है जब दोनों 1 हों (AND)।"},
  {"id":"comp-awareness-243","question":"For how many of the 8 possible combinations of the inputs A, B and C does the circuit (A NAND B) NOR C output 1?","options":["7","3","5","1"],"answer":3,"explanation":"A NOR gate outputs 1 only when both its inputs are 0: A NAND B = 0 needs A = B = 1, and C must be 0. Only the combination A = 1, B = 1, C = 0 works.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"इनपुट A, B और C के 8 संभावित संयोजनों में से कितनों के लिए परिपथ (A NAND B) NOR C का आउटपुट 1 होता है?","optionsHi":["7","3","5","1"],"explanationHi":"NOR गेट तभी 1 देता है जब उसके दोनों इनपुट 0 हों: A NAND B = 0 के लिए A = B = 1 चाहिए, और C को 0 होना चाहिए। केवल संयोजन A = 1, B = 1, C = 0 काम करता है।"},
  {"id":"comp-awareness-244","question":"Twenty-four PCs are connected one to a port on a 24-port switch with no VLANs configured. How many collision domains and how many broadcast domains does this network have?","options":["24 collision domains, 1 broadcast domain","1 collision domain, 1 broadcast domain","1 collision domain, 24 broadcast domains","24 collision domains, 24 broadcast domains"],"answer":0,"explanation":"Each switch port is its own collision domain, but a switch forwards broadcasts to every port, so there is one broadcast domain; only a router (or VLANs) splits broadcast domains. With a hub, there would be 1 collision domain.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"चौबीस PC एक 24-पोर्ट स्विच के एक-एक पोर्ट से जुड़े हैं और कोई VLAN कॉन्फ़िगर नहीं है। इस नेटवर्क में कितने कोलिज़न डोमेन और कितने ब्रॉडकास्ट डोमेन हैं?","optionsHi":["24 कोलिज़न डोमेन, 1 ब्रॉडकास्ट डोमेन","1 कोलिज़न डोमेन, 1 ब्रॉडकास्ट डोमेन","1 कोलिज़न डोमेन, 24 ब्रॉडकास्ट डोमेन","24 कोलिज़न डोमेन, 24 ब्रॉडकास्ट डोमेन"],"explanationHi":"प्रत्येक स्विच पोर्ट अपना कोलिज़न डोमेन है, पर स्विच ब्रॉडकास्ट को सभी पोर्ट पर भेजता है, इसलिए एक ही ब्रॉडकास्ट डोमेन है; केवल राउटर (या VLAN) ब्रॉडकास्ट डोमेन को बाँटता है। हब होने पर 1 कोलिज़न डोमेन होता।"},
  {"id":"comp-awareness-245","question":"Bank staff working from home need to reach the office network over the public internet, with all traffic encrypted as if they were inside the office. Which technology provides this?","options":["Network Address Translation (NAT)","A proxy server","A virtual private network (VPN)","A demilitarised zone (DMZ)"],"answer":2,"explanation":"A VPN builds an encrypted tunnel across the public internet into the private network. NAT only maps private to public addresses, and a DMZ is a separate zone for public-facing servers.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"बैंक कर्मचारियों को घर से काम करते हुए सार्वजनिक इंटरनेट पर कार्यालय नेटवर्क तक पहुँचना है, जिसमें सारा ट्रैफ़िक ऐसे एन्क्रिप्टेड हो जैसे वे कार्यालय के भीतर हों। यह कौन-सी तकनीक देती है?","optionsHi":["नेटवर्क एड्रेस ट्रांसलेशन (NAT)","प्रॉक्सी सर्वर","वर्चुअल प्राइवेट नेटवर्क (VPN)","डिमिलिटराइज़्ड ज़ोन (DMZ)"],"explanationHi":"VPN सार्वजनिक इंटरनेट के पार निजी नेटवर्क तक एक एन्क्रिप्टेड सुरंग बनाता है। NAT केवल निजी पतों को सार्वजनिक पतों से जोड़ता है, और DMZ सार्वजनिक-सामने वाले सर्वरों के लिए अलग क्षेत्र है।"},
  {"id":"comp-awareness-246","question":"A bank rents virtual machines, storage and network capacity from a cloud provider, then installs and manages its own operating system and applications on them. Which cloud service model is this?","options":["Software as a Service (SaaS)","Infrastructure as a Service (IaaS)","Platform as a Service (PaaS)","Function as a Service (FaaS)"],"answer":1,"explanation":"In IaaS the provider supplies raw computing infrastructure and the customer manages the OS upwards. In PaaS the provider also manages the OS and runtime, and in SaaS the whole application.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"एक बैंक क्लाउड प्रदाता से वर्चुअल मशीनें, संग्रहण और नेटवर्क क्षमता किराये पर लेता है, फिर उन पर अपना ऑपरेटिंग सिस्टम और एप्लिकेशन स्वयं इंस्टॉल और प्रबंधित करता है। यह कौन-सा क्लाउड सेवा मॉडल है?","optionsHi":["सॉफ्टवेयर एज़ ए सर्विस (SaaS)","इन्फ्रास्ट्रक्चर एज़ ए सर्विस (IaaS)","प्लेटफ़ॉर्म एज़ ए सर्विस (PaaS)","फ़ंक्शन एज़ ए सर्विस (FaaS)"],"explanationHi":"IaaS में प्रदाता कच्चा कंप्यूटिंग इन्फ्रास्ट्रक्चर देता है और ग्राहक OS से ऊपर का प्रबंधन करता है। PaaS में प्रदाता OS और रनटाइम भी सँभालता है, और SaaS में पूरा एप्लिकेशन।"},
  {"id":"comp-awareness-247","question":"Match the IEEE standard with the technology: 1. IEEE 802.3 2. IEEE 802.11 3. IEEE 802.15; a. Wireless LAN (Wi-Fi) b. Wired Ethernet c. Wireless personal area network such as Bluetooth","options":["1-a, 2-b, 3-c","1-c, 2-a, 3-b","1-b, 2-c, 3-a","1-b, 2-a, 3-c"],"answer":3,"explanation":"802.3 is Ethernet, 802.11 is Wi-Fi and 802.15 covers wireless personal area networks, including Bluetooth (802.15.1).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains","questionHi":"IEEE मानक का प्रौद्योगिकी से मिलान कीजिए: 1. IEEE 802.3 2. IEEE 802.11 3. IEEE 802.15; a. वायरलेस LAN (Wi-Fi) b. वायर्ड ईथरनेट c. ब्लूटूथ जैसा वायरलेस पर्सनल एरिया नेटवर्क","optionsHi":["1-a, 2-b, 3-c","1-c, 2-a, 3-b","1-b, 2-c, 3-a","1-b, 2-a, 3-c"],"explanationHi":"802.3 ईथरनेट है, 802.11 Wi-Fi है और 802.15 वायरलेस पर्सनल एरिया नेटवर्क को कवर करता है, ब्लूटूथ (802.15.1) सहित।"},
  {"id":"comp-awareness-248","question":"A hypervisor installed directly on a server's hardware, with no host operating system beneath it, is called a:","options":["Type 1 (bare-metal) hypervisor","Type 2 (hosted) hypervisor","Container engine","Boot loader"],"answer":0,"explanation":"Type 1 hypervisors run straight on the hardware; Type 2 hypervisors run as an application on top of an ordinary host OS. Containers share the host kernel instead of virtualising hardware.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO","questionHi":"सर्वर के हार्डवेयर पर सीधे इंस्टॉल किया गया हाइपरवाइज़र, जिसके नीचे कोई होस्ट ऑपरेटिंग सिस्टम नहीं होता, कहलाता है:","optionsHi":["टाइप 1 (बेयर-मेटल) हाइपरवाइज़र","टाइप 2 (होस्टेड) हाइपरवाइज़र","कंटेनर इंजन","बूट लोडर"],"explanationHi":"टाइप 1 हाइपरवाइज़र सीधे हार्डवेयर पर चलते हैं; टाइप 2 हाइपरवाइज़र साधारण होस्ट OS के ऊपर एप्लिकेशन के रूप में चलते हैं। कंटेनर हार्डवेयर को वर्चुअलाइज़ करने के बजाय होस्ट कर्नेल साझा करते हैं।"},
  {"id":"comp-awareness-249","question":"The processing speed of supercomputers is usually compared using which unit?","options":["MIPS","Clock speed in GHz","FLOPS","Revolutions per minute (rpm)"],"answer":2,"explanation":"Supercomputers do heavy scientific calculations, so they are rated in floating-point operations per second (FLOPS), e.g. petaFLOPS. MIPS counts general instructions, and GHz alone ignores how much work each cycle does.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"सुपरकंप्यूटरों की प्रोसेसिंग गति की तुलना आमतौर पर किस इकाई से की जाती है?","optionsHi":["MIPS","GHz में क्लॉक गति","FLOPS","प्रति मिनट चक्कर (rpm)"],"explanationHi":"सुपरकंप्यूटर भारी वैज्ञानिक गणनाएँ करते हैं, इसलिए उन्हें फ़्लोटिंग-पॉइंट संक्रियाएँ प्रति सेकंड (FLOPS) में आँका जाता है, जैसे पेटाFLOPS। MIPS सामान्य निर्देश गिनता है, और अकेला GHz यह नहीं बताता कि प्रत्येक चक्र में कितना काम होता है।"},
  {"id":"comp-awareness-250","question":"Which pair consists ONLY of lossless compression formats, from which the original data can be rebuilt exactly?","options":["JPEG and MP3","PNG and JPEG","ZIP and MP3","ZIP and PNG"],"answer":3,"explanation":"ZIP archives and PNG images are lossless. JPEG and MP3 are lossy: they throw away detail the eye or ear is unlikely to notice, so the original cannot be restored exactly.","difficulty":"hard","source":"IBPS PO Mains · SBI PO","questionHi":"किस युग्म में केवल हानिरहित (लॉसलेस) संपीड़न फ़ॉर्मैट हैं, जिनसे मूल डेटा ठीक-ठीक पुनः बनाया जा सकता है?","optionsHi":["JPEG और MP3","PNG और JPEG","ZIP और MP3","ZIP और PNG"],"explanationHi":"ZIP संग्रह और PNG छवियाँ हानिरहित हैं। JPEG और MP3 हानिपूर्ण (लॉसी) हैं: वे वह विवरण त्याग देते हैं जिसे आँख या कान के पहचानने की संभावना कम है, इसलिए मूल को ठीक-ठीक वापस नहीं पाया जा सकता।"},
  {"id":"comp-awareness-251","question":"In the IEEE 754 single-precision (32-bit) floating-point format, how are the bits divided, and what is the exponent bias?","options":["1 sign, 8 exponent, 23 fraction bits; bias 128","1 sign, 11 exponent, 20 fraction bits; bias 1023","1 sign, 8 exponent, 23 fraction bits; bias 127","1 sign, 7 exponent, 24 fraction bits; bias 63"],"answer":2,"explanation":"Single precision is 1 + 8 + 23 = 32 bits with exponent bias 2⁷ − 1 = 127; 11 exponent bits and bias 1023 belong to the 64-bit double format.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL","questionHi":"IEEE 754 सिंगल-प्रिसिज़न (32-बिट) फ़्लोटिंग-पॉइंट प्रारूप में बिट कैसे बाँटे जाते हैं, और घातांक बायस क्या है?","optionsHi":["1 साइन, 8 घातांक, 23 भिन्न बिट; बायस 128","1 साइन, 11 घातांक, 20 भिन्न बिट; बायस 1023","1 साइन, 8 घातांक, 23 भिन्न बिट; बायस 127","1 साइन, 7 घातांक, 24 भिन्न बिट; बायस 63"],"explanationHi":"सिंगल प्रिसिज़न 1 + 8 + 23 = 32 बिट का है और घातांक बायस 2⁷ − 1 = 127 है; 11 घातांक बिट और बायस 1023 64-बिट डबल प्रारूप के हैं।"},
  {"id":"comp-awareness-252","question":"In IEEE 754 single precision, the number 6.5 is stored as which 32-bit pattern, written in hexadecimal?","options":["40D00000","41500000","40E80000","40C00000"],"answer":0,"explanation":"6.5 = 110.1₂ = 1.101 × 2²; sign 0, exponent 2 + 127 = 10000001, fraction 101 then zeros (the leading 1 is hidden), giving 0100 0000 1101 0000 … = 40D00000. Keeping the hidden 1 gives 40E80000.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"IEEE 754 सिंगल प्रिसिज़न में संख्या 6.5 किस 32-बिट पैटर्न के रूप में संग्रहीत होती है, जिसे हेक्साडेसिमल में लिखा गया है?","optionsHi":["40D00000","41500000","40E80000","40C00000"],"explanationHi":"6.5 = 110.1₂ = 1.101 × 2²; साइन 0, घातांक 2 + 127 = 10000001, भिन्न 101 और फिर शून्य (आरंभिक 1 छिपा रहता है), जिससे 0100 0000 1101 0000 … = 40D00000 मिलता है। छिपे 1 को रख लेने पर 40E80000 आता है।"},
  {"id":"comp-awareness-253","question":"In 8-bit one's complement representation, how many bit patterns stand for zero, and what range of integers can be stored?","options":["One pattern; −128 to +127","Two patterns; −128 to +127","One pattern; −127 to +127","Two patterns; −127 to +127"],"answer":3,"explanation":"Both 00000000 (+0) and 11111111 (−0) mean zero in one's complement, so the range is only −127 to +127; a single zero with −128 to +127 is two's complement.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL","questionHi":"8-बिट वन’ज़ कॉम्प्लिमेंट निरूपण में शून्य के लिए कितने बिट पैटर्न होते हैं, और पूर्णांकों की कौन-सी रेंज संग्रहीत हो सकती है?","optionsHi":["एक पैटर्न; −128 से +127","दो पैटर्न; −128 से +127","एक पैटर्न; −127 से +127","दो पैटर्न; −127 से +127"],"explanationHi":"वन’ज़ कॉम्प्लिमेंट में 00000000 (+0) और 11111111 (−0) दोनों शून्य का अर्थ रखते हैं, इसलिए रेंज केवल −127 से +127 है; एक शून्य के साथ −128 से +127 टू’ज़ कॉम्प्लिमेंट है।"},
  {"id":"comp-awareness-254","question":"The 8-bit pattern 10000101 is read as a sign-magnitude, a one's complement and a two's complement number. Which list gives its values in that order?","options":["−5, −123, −122","−5, −122, −123","−122, −5, −123","−123, −122, −5"],"answer":1,"explanation":"Sign-magnitude: sign 1, magnitude 0000101 = 5, so −5. One's complement: invert to 01111010 = 122, so −122. Two's complement: −128 + 5 = −123.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"8-बिट पैटर्न 10000101 को साइन-मैग्निट्यूड, वन’ज़ कॉम्प्लिमेंट और टू’ज़ कॉम्प्लिमेंट संख्या के रूप में पढ़ा जाता है। कौन-सी सूची उसके मान इसी क्रम में देती है?","optionsHi":["−5, −123, −122","−5, −122, −123","−122, −5, −123","−123, −122, −5"],"explanationHi":"साइन-मैग्निट्यूड: साइन 1, परिमाण 0000101 = 5, इसलिए −5। वन’ज़ कॉम्प्लिमेंट: उलटने पर 01111010 = 122, इसलिए −122। टू’ज़ कॉम्प्लिमेंट: −128 + 5 = −123।"},
  {"id":"comp-awareness-255","question":"A Hamming code must correct any single-bit error in a block of 12 data bits. What is the minimum number of check (parity) bits needed?","options":["4","5","6","3"],"answer":1,"explanation":"Check bits p must satisfy 2ᵖ ≥ m + p + 1. With m = 12, p = 4 gives 16 ≥ 17 (false) and p = 5 gives 32 ≥ 18, so 5 are needed; 4 suffice only up to 11 data bits.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"हैमिंग कोड को 12 डेटा बिट के ब्लॉक में किसी भी एकल-बिट त्रुटि को सुधारना है। न्यूनतम कितने चेक (पैरिटी) बिट चाहिए?","optionsHi":["4","5","6","3"],"explanationHi":"चेक बिट p को 2ᵖ ≥ m + p + 1 संतुष्ट करना चाहिए। m = 12 के साथ p = 4 पर 16 ≥ 17 (असत्य) है और p = 5 पर 32 ≥ 18, इसलिए 5 चाहिए; 4 केवल 11 डेटा बिट तक पर्याप्त हैं।"},
  {"id":"comp-awareness-256","question":"A sender appends an even-parity bit to every 7-bit character. Which received 8-bit word shows that an error has occurred?","options":["10110100","11100111","00000000","01011011"],"answer":3,"explanation":"Under even parity every valid word has an even count of 1s. 01011011 has five 1s, so a bit has flipped; the others have four, six and zero 1s.","difficulty":"hard","source":"SSC CGL · IBPS PO Mains","questionHi":"एक प्रेषक प्रत्येक 7-बिट वर्ण में सम-पैरिटी (ईवन पैरिटी) बिट जोड़ता है। कौन-सा प्राप्त 8-बिट शब्द दर्शाता है कि त्रुटि हुई है?","optionsHi":["10110100","11100111","00000000","01011011"],"explanationHi":"सम-पैरिटी में प्रत्येक वैध शब्द में 1 की संख्या सम होती है। 01011011 में पाँच 1 हैं, इसलिए कोई बिट पलट गया है; शेष में चार, छह और शून्य 1 हैं।"},
  {"id":"comp-awareness-257","question":"In ASCII the capital letter 'G' has the code 71 (decimal). What is the code of the small letter 'g', written in hexadecimal?","options":["67","47","77","57"],"answer":0,"explanation":"Small letters are 32 more than capitals, so 'g' = 71 + 32 = 103 = 6 × 16 + 7 = (67)₁₆. (47)₁₆ is the code of 'G' itself.","difficulty":"moderate","source":"SSC CGL · IBPS PO Mains","questionHi":"ASCII में बड़े अक्षर ‘G’ का कोड 71 (दशमलव) है। छोटे अक्षर ‘g’ का कोड हेक्साडेसिमल में लिखने पर क्या है?","optionsHi":["67","47","77","57"],"explanationHi":"छोटे अक्षर बड़े अक्षरों से 32 अधिक होते हैं, इसलिए ‘g’ = 71 + 32 = 103 = 6 × 16 + 7 = (67)₁₆। (47)₁₆ स्वयं ‘G’ का कोड है।"},
  {"id":"comp-awareness-258","question":"In ASCII, 'M' is 77 and 'm' is 109, so changing one into the other flips exactly one bit. What is the place value of that bit?","options":["16","64","32","128"],"answer":2,"explanation":"109 − 77 = 32 = 2⁵, so toggling bit 5 switches the case of any ASCII letter; 7-bit ASCII never uses the 128 bit at all.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL","questionHi":"ASCII में ‘M’ का मान 77 और ‘m’ का 109 है, इसलिए एक को दूसरे में बदलने पर ठीक एक बिट पलटता है। उस बिट का स्थानीय मान क्या है?","optionsHi":["16","64","32","128"],"explanationHi":"109 − 77 = 32 = 2⁵, इसलिए बिट 5 को पलटने से किसी भी ASCII अक्षर का केस बदल जाता है; 7-बिट ASCII में 128 वाला बिट कभी प्रयोग ही नहीं होता।"},
  {"id":"comp-awareness-259","question":"A text file is saved in UTF-8. How many bytes does the English letter 'A' take, and how many does a Devanagari letter such as 'क' take?","options":["1 byte and 2 bytes","2 bytes and 2 bytes","1 byte and 4 bytes","1 byte and 3 bytes"],"answer":3,"explanation":"UTF-8 keeps ASCII in one byte; code points U+0800 to U+FFFF, which include the Devanagari block (U+0900–U+097F), take three bytes. Two bytes reach only U+07FF.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक पाठ फ़ाइल UTF-8 में सहेजी गई है। अंग्रेज़ी अक्षर ‘A’ कितने बाइट लेता है, और ‘क’ जैसा देवनागरी अक्षर कितने?","optionsHi":["1 बाइट और 2 बाइट","2 बाइट और 2 बाइट","1 बाइट और 4 बाइट","1 बाइट और 3 बाइट"],"explanationHi":"UTF-8 ASCII को एक बाइट में रखता है; कोड बिंदु U+0800 से U+FFFF, जिनमें देवनागरी ब्लॉक (U+0900–U+097F) आता है, तीन बाइट लेते हैं। दो बाइट केवल U+07FF तक पहुँचते हैं।"},
  {"id":"comp-awareness-260","question":"In which number base is the statement 3 × 4 = 13 true?","options":["Base 8","Base 9","Base 7","Base 12"],"answer":1,"explanation":"3 × 4 = 12 in decimal, and 13 in base b means b + 3. So b + 3 = 12 gives b = 9.","difficulty":"moderate","source":"SSC CGL · IBPS PO Mains","questionHi":"किस संख्या आधार में कथन 3 × 4 = 13 सत्य है?","optionsHi":["आधार 8","आधार 9","आधार 7","आधार 12"],"explanationHi":"दशमलव में 3 × 4 = 12, और आधार b में 13 का अर्थ b + 3 है। इसलिए b + 3 = 12 से b = 9 मिलता है।"},
  {"id":"comp-awareness-261","question":"Three of these numbers are equal. Which one has a different value?","options":["(25)₁₆","(100110)₂","(46)₈","(38)₁₀"],"answer":0,"explanation":"(100110)₂ = 32 + 4 + 2 = 38 and (46)₈ = 32 + 6 = 38, but (25)₁₆ = 32 + 5 = 37; decimal 38 in hex is 26.","difficulty":"hard","source":"SSC CGL · IBPS PO Mains","questionHi":"इनमें से तीन संख्याएँ बराबर हैं। किसका मान भिन्न है?","optionsHi":["(25)₁₆","(100110)₂","(46)₈","(38)₁₀"],"explanationHi":"(100110)₂ = 32 + 4 + 2 = 38 और (46)₈ = 32 + 6 = 38, परंतु (25)₁₆ = 32 + 5 = 37; दशमलव 38 हेक्स में 26 है।"},
  {"id":"comp-awareness-262","question":"What is (A0)₁₆ − (3F)₁₆, written in hexadecimal?","options":["71","5F","61","6F"],"answer":2,"explanation":"A0 = 160 and 3F = 63, so the difference is 97 = 6 × 16 + 1 = (61)₁₆. Forgetting the borrow taken from the 16s place gives the trap answer 71.","difficulty":"hard","source":"SSC CGL · IBPS SO IT Officer","questionHi":"(A0)₁₆ − (3F)₁₆ का मान हेक्साडेसिमल में लिखने पर क्या है?","optionsHi":["71","5F","61","6F"],"explanationHi":"A0 = 160 और 3F = 63, इसलिए अंतर 97 = 6 × 16 + 1 = (61)₁₆ है। 16 वाले स्थान से लिया गया उधार भूलने पर जाल वाला उत्तर 71 आता है।"},
  {"id":"comp-awareness-263","question":"What is (567)₈ + (234)₈, written in octal?","options":["801","1013","1023","1033"],"answer":2,"explanation":"7 + 4 = 11 = 13₈ (write 3, carry 1); 6 + 3 + 1 = 10 = 12₈ (write 2, carry 1); 5 + 2 + 1 = 8 = 10₈. Result (1023)₈ = 531 = 375 + 156; 801 is plain decimal addition.","difficulty":"very-hard","source":"SSC CGL · IBPS SO IT Officer","questionHi":"(567)₈ + (234)₈ का मान ऑक्टल में लिखने पर क्या है?","optionsHi":["801","1013","1023","1033"],"explanationHi":"7 + 4 = 11 = 13₈ (3 लिखें, 1 हासिल); 6 + 3 + 1 = 10 = 12₈ (2 लिखें, 1 हासिल); 5 + 2 + 1 = 8 = 10₈। परिणाम (1023)₈ = 531 = 375 + 156; 801 सादा दशमलव जोड़ है।"},
  {"id":"comp-awareness-264","question":"When the digits 8 and 5 are added in 8421 BCD, the 4-bit sum 1101 is not a valid BCD digit. How is it corrected, and what is the final BCD result?","options":["Add 0110, giving 0001 0011","Add 0011, giving 0001 0011","Add 0110, giving 0000 1101","Add 1010, giving 0001 0011"],"answer":0,"explanation":"A BCD digit sum above 9 is corrected by adding 6 (0110): 1101 + 0110 = 1 0011, so the result is 0001 0011, i.e. 13. Adding 3 is the Excess-3 correction.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"8421 BCD में अंक 8 और 5 जोड़ने पर 4-बिट योग 1101 वैध BCD अंक नहीं है। इसे कैसे सुधारा जाता है, और अंतिम BCD परिणाम क्या है?","optionsHi":["0110 जोड़ें, जिससे 0001 0011 मिलता है","0011 जोड़ें, जिससे 0001 0011 मिलता है","0110 जोड़ें, जिससे 0000 1101 मिलता है","1010 जोड़ें, जिससे 0001 0011 मिलता है"],"explanationHi":"9 से अधिक BCD अंक-योग को 6 (0110) जोड़कर सुधारा जाता है: 1101 + 0110 = 1 0011, इसलिए परिणाम 0001 0011, अर्थात् 13 है। 3 जोड़ना एक्सेस-3 का सुधार है।"},
  {"id":"comp-awareness-265","question":"What is the minimum number of bits needed to store every whole number from 0 to 9999 in pure binary?","options":["13","16","15","14"],"answer":3,"explanation":"There are 10,000 values; 2¹³ = 8192 is too few but 2¹⁴ = 16,384 is enough, so 14 bits. Taking ⌊log₂ 9999⌋ = 13 forgets to round up, adding a sign bit gives 15, and 16 is what four BCD digits would need.","difficulty":"hard","source":"SSC CGL · IBPS PO Mains","questionHi":"0 से 9999 तक की प्रत्येक पूर्ण संख्या को शुद्ध बाइनरी में संग्रहीत करने के लिए न्यूनतम कितने बिट चाहिए?","optionsHi":["13","16","15","14"],"explanationHi":"10,000 मान हैं; 2¹³ = 8192 कम है पर 2¹⁴ = 16,384 पर्याप्त है, इसलिए 14 बिट। ⌊log₂ 9999⌋ = 13 लेना ऊपर पूर्णांकित करना भूल जाता है, साइन बिट जोड़ने पर 15 आता है, और 16 वह है जो चार BCD अंकों को चाहिए।"},
  {"id":"comp-awareness-266","question":"The value −6 is 1010 in 4-bit two's complement. When it is sign-extended to 8 bits, the result is:","options":["00001010","11111010","10001010","11110110"],"answer":1,"explanation":"Sign extension copies the sign bit into every new high position: 1111 1010, which is still −6. Padding with zeros would give +10, and 11110110 is −10.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"मान −6, 4-बिट टू’ज़ कॉम्प्लिमेंट में 1010 है। इसे 8 बिट तक साइन-एक्सटेंड करने पर परिणाम है:","optionsHi":["00001010","11111010","10001010","11110110"],"explanationHi":"साइन एक्सटेंशन साइन बिट को प्रत्येक नए उच्च स्थान में कॉपी करता है: 1111 1010, जो अब भी −6 है। शून्य भरने पर +10 मिलता, और 11110110 का मान −10 है।"},
  {"id":"comp-awareness-267","question":"The 8-bit two's-complement value 11101000 (−24) is shifted right by two places using an ARITHMETIC shift. What is the result?","options":["00111010","11111000","10100000","11111010"],"answer":3,"explanation":"An arithmetic right shift copies the sign bit into the vacated places: 11101000 → 11110100 → 11111010 = −6, i.e. −24 ÷ 4. A logical shift would insert zeros and give 00111010 = 58.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"8-बिट टू’ज़-कॉम्प्लिमेंट मान 11101000 (−24) को अंकगणितीय (ARITHMETIC) शिफ़्ट से दो स्थान दाईं ओर खिसकाया जाता है। परिणाम क्या है?","optionsHi":["00111010","11111000","10100000","11111010"],"explanationHi":"अंकगणितीय दायाँ शिफ़्ट साइन बिट को खाली हुए स्थानों में कॉपी करता है: 11101000 → 11110100 → 11111010 = −6, अर्थात् −24 ÷ 4। तार्किक शिफ़्ट शून्य डालता और 00111010 = 58 देता।"},
  {"id":"comp-awareness-268","question":"When two n-bit two's-complement numbers are added, overflow has occurred exactly when:","options":["Both operands have the same sign and the result has the opposite sign","A carry comes out of the most significant bit position during the addition","The operands have opposite signs and the result comes out negative","The sign bit of the result is 1, whatever the signs of the operands"],"answer":0,"explanation":"Overflow is possible only when both operands share a sign, and it shows as a result of the other sign. A carry out of the MSB alone is normal (e.g. −1 + 1) and is simply discarded.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"दो n-बिट टू’ज़-कॉम्प्लिमेंट संख्याएँ जोड़ने पर ओवरफ़्लो ठीक तब होता है जब:","optionsHi":["दोनों संकार्यों का चिह्न समान हो और परिणाम का चिह्न विपरीत हो","जोड़ते समय सबसे महत्वपूर्ण बिट स्थान से कैरी बाहर निकले","संकार्यों के चिह्न विपरीत हों और परिणाम ऋणात्मक आए","परिणाम का साइन बिट 1 हो, संकार्यों के चिह्न चाहे जो हों"],"explanationHi":"ओवरफ़्लो तभी संभव है जब दोनों संकार्यों का चिह्न समान हो, और यह विपरीत चिह्न के परिणाम के रूप में दिखता है। केवल MSB से कैरी निकलना सामान्य है (जैसे −1 + 1) और उसे छोड़ दिया जाता है।"},
  {"id":"comp-awareness-269","question":"Rotary shaft encoders and Karnaugh-map labels use Gray code mainly because:","options":["It needs fewer bits than pure binary to cover the same range","Successive values differ in exactly one bit, avoiding false readings","Each decimal digit is coded separately, which eases display output","It carries a built-in parity bit, so single-bit errors are detected"],"answer":1,"explanation":"Adjacent Gray codes differ in a single bit, so a sensor caught between two positions cannot produce a wildly wrong code. It uses as many bits as binary and has no parity bit.","difficulty":"moderate","source":"SSC CGL · IBPS SO IT Officer","questionHi":"रोटरी शाफ़्ट एनकोडर और कार्नो-मैप के लेबल मुख्यतः ग्रे कोड का प्रयोग क्यों करते हैं?","optionsHi":["यह उसी रेंज को कवर करने के लिए शुद्ध बाइनरी से कम बिट लेता है","क्रमागत मान ठीक एक बिट में भिन्न होते हैं, जिससे गलत पाठ्यांक से बचाव होता है","प्रत्येक दशमलव अंक अलग से कोडित होता है, जिससे डिस्प्ले आउटपुट आसान होता है","इसमें अंतर्निहित पैरिटी बिट होता है, इसलिए एकल-बिट त्रुटियाँ पकड़ी जाती हैं"],"explanationHi":"आसन्न ग्रे कोड एक ही बिट में भिन्न होते हैं, इसलिए दो स्थितियों के बीच फँसा सेंसर बहुत गलत कोड नहीं दे सकता। यह बाइनरी जितने ही बिट प्रयोग करता है और इसमें पैरिटी बिट नहीं होता।"},
  {"id":"comp-awareness-270","question":"Which code is self-complementing, so that inverting every bit of a digit's code gives the code of its 9's complement?","options":["8421 BCD","Gray code","Excess-3","7-bit ASCII"],"answer":2,"explanation":"Excess-3 codes digit d as d + 3; inverting gives 15 − (d + 3) = (9 − d) + 3, the Excess-3 code of 9 − d. For example 2 = 0101 inverts to 1010 = 7.","difficulty":"moderate","source":"IBPS SO IT Officer","questionHi":"कौन-सा कोड स्व-पूरक (सेल्फ़-कॉम्प्लिमेंटिंग) है, जिसमें अंक के कोड के प्रत्येक बिट को उलटने पर उसके 9 के पूरक का कोड मिलता है?","optionsHi":["8421 BCD","ग्रे कोड","एक्सेस-3","7-बिट ASCII"],"explanationHi":"एक्सेस-3 अंक d को d + 3 के रूप में कोडित करता है; उलटने पर 15 − (d + 3) = (9 − d) + 3 मिलता है, जो 9 − d का एक्सेस-3 कोड है। उदाहरण के लिए 2 = 0101 उलटकर 1010 = 7 होता है।"},
  {"id":"comp-awareness-271","question":"The hexadecimal number 3FA is written in binary without leading zeros. How many bits does it have?","options":["12","10","11","9"],"answer":1,"explanation":"3FA = 0011 1111 1010; dropping the two leading zeros leaves 11 1111 1010, which is 10 bits (value 1018, between 512 and 1023). Keeping all 12 bits forgets to drop leading zeros, and 9 wrongly converts each hex digit to 3 bits as if it were octal.","difficulty":"hard","source":"SSC CGL · IBPS PO Mains","questionHi":"हेक्साडेसिमल संख्या 3FA को आरंभिक शून्यों के बिना बाइनरी में लिखा जाता है। उसमें कितने बिट हैं?","optionsHi":["12","10","11","9"],"explanationHi":"3FA = 0011 1111 1010; दो आरंभिक शून्य हटाने पर 11 1111 1010 बचता है, जो 10 बिट है (मान 1018, 512 और 1023 के बीच)। सभी 12 बिट रखना आरंभिक शून्य हटाना भूल जाता है, और 9 प्रत्येक हेक्स अंक को ऑक्टल की तरह 3 बिट में बदल देता है।"},
  {"id":"comp-awareness-272","question":"The full contents of a 64-bit register are written out once in hexadecimal and once in octal. At most how many digits does each form need?","options":["16 and 22","16 and 21","8 and 22","16 and 24"],"answer":0,"explanation":"A hex digit holds 4 bits, so 64 ÷ 4 = 16; an octal digit holds 3 bits, so 64 ÷ 3 = 21.33, rounded up to 22 (the top octal digit holds just one bit).","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"64-बिट रजिस्टर की पूरी सामग्री एक बार हेक्साडेसिमल में और एक बार ऑक्टल में लिखी जाती है। प्रत्येक रूप में अधिकतम कितने अंक लगते हैं?","optionsHi":["16 और 22","16 और 21","8 और 22","16 और 24"],"explanationHi":"एक हेक्स अंक 4 बिट रखता है, इसलिए 64 ÷ 4 = 16; एक ऑक्टल अंक 3 बिट रखता है, इसलिए 64 ÷ 3 = 21.33, जिसे ऊपर पूर्णांकित करने पर 22 होता है (सबसे ऊपरी ऑक्टल अंक में केवल एक बिट होता है)।"},
  {"id":"comp-awareness-273","question":"725 − 248 is worked out by adding the 10's complement of 248 to 725 and dropping the end carry. What are the 10's complement and the final result?","options":["751 and 477","752 and 476","751 and 476","752 and 477"],"answer":3,"explanation":"10's complement of 248 = 1000 − 248 = 752; 725 + 752 = 1477, and dropping the end carry leaves 477. 751 is only the 9's complement.","difficulty":"very-hard","source":"SSC CGL · IBPS SO IT Officer","questionHi":"725 − 248 की गणना 248 का 10 का पूरक 725 में जोड़कर और अंतिम कैरी छोड़कर की जाती है। 10 का पूरक और अंतिम परिणाम क्या हैं?","optionsHi":["751 और 477","752 और 476","751 और 476","752 और 477"],"explanationHi":"248 का 10 का पूरक = 1000 − 248 = 752; 725 + 752 = 1477, और अंतिम कैरी छोड़ने पर 477 बचता है। 751 केवल 9 का पूरक है।"},
  {"id":"comp-awareness-274","question":"What is (0.8)₁₆ + (0.4)₈, written in decimal?","options":["1.2","0.75","1","0.625"],"answer":2,"explanation":"(0.8)₁₆ = 8/16 = 0.5 and (0.4)₈ = 4/8 = 0.5, so the sum is exactly 1; reading the digits as decimal gives the trap 1.2.","difficulty":"hard","source":"SSC CGL · IBPS SO IT Officer","questionHi":"(0.8)₁₆ + (0.4)₈ का मान दशमलव में लिखने पर क्या है?","optionsHi":["1.2","0.75","1","0.625"],"explanationHi":"(0.8)₁₆ = 8/16 = 0.5 और (0.4)₈ = 4/8 = 0.5, इसलिए योग ठीक 1 है; अंकों को दशमलव पढ़ने पर जाल वाला उत्तर 1.2 आता है।"},
  {"id":"comp-awareness-275","question":"What is the sum of the largest value a 4-bit UNSIGNED number can hold and the smallest value a 4-bit TWO'S-COMPLEMENT number can hold?","options":["23","7","−1","8"],"answer":1,"explanation":"Unsigned 4 bits go up to 1111 = 15; 4-bit two's complement goes down to 1000 = −8; 15 + (−8) = 7. Taking −7 or +8 by mistake gives 8 or 23.","difficulty":"hard","source":"SSC CGL · IBPS PO Mains","questionHi":"4-बिट अचिह्नित संख्या के सबसे बड़े मान और 4-बिट टू’ज़-कॉम्प्लिमेंट संख्या के सबसे छोटे मान का योग क्या है?","optionsHi":["23","7","−1","8"],"explanationHi":"4 बिट अचिह्नित 1111 = 15 तक जाता है; 4-बिट टू’ज़ कॉम्प्लिमेंट 1000 = −8 तक नीचे जाता है; 15 + (−8) = 7। भूल से −7 या +8 लेने पर 8 या 23 आता है।"},
  {"id":"comp-awareness-276","question":"A cache takes 5 ns per access and main memory 80 ns. The cache is always checked first, and on a miss main memory is then read, so a miss costs 85 ns. What hit ratio gives an average access time of 13 ns?","options":["0.85","0.95","0.80","0.90"],"answer":3,"explanation":"Average = 5 + (1 − h) × 80 = 13, so (1 − h) × 80 = 8 and h = 0.90. Treating a miss as only 80 ns (parallel lookup) would give about 0.89, not any other option.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक कैश प्रति एक्सेस 5 ns और मुख्य मेमोरी 80 ns लेती है। कैश की जाँच हमेशा पहले होती है और मिस होने पर मुख्य मेमोरी पढ़ी जाती है, इसलिए एक मिस की लागत 85 ns है। कौन-सा हिट अनुपात 13 ns का औसत एक्सेस समय देता है?","optionsHi":["0.85","0.95","0.80","0.90"],"explanationHi":"औसत = 5 + (1 − h) × 80 = 13, इसलिए (1 − h) × 80 = 8 और h = 0.90। मिस को केवल 80 ns मानने (समानांतर खोज) पर लगभग 0.89 आता, जो किसी अन्य विकल्प के बराबर नहीं है।"},
  {"id":"comp-awareness-277","question":"A direct-mapped cache has 128 lines. Main-memory block number 1000 is placed in which cache line (lines numbered from 0)?","options":["7","104","8","40"],"answer":1,"explanation":"Direct mapping uses line = block mod number of lines = 1000 mod 128 = 1000 − 896 = 104. The quotient 7 becomes part of the tag, not the line number.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक डायरेक्ट-मैप्ड कैश में 128 लाइनें हैं। मुख्य-मेमोरी ब्लॉक संख्या 1000 किस कैश लाइन में रखा जाता है (लाइनें 0 से क्रमांकित)?","optionsHi":["7","104","8","40"],"explanationHi":"डायरेक्ट मैपिंग में लाइन = ब्लॉक mod लाइनों की संख्या = 1000 mod 128 = 1000 − 896 = 104। भागफल 7 टैग का भाग बनता है, लाइन संख्या का नहीं।"},
  {"id":"comp-awareness-278","question":"A 64 KB direct-mapped cache uses 16-byte blocks, and the processor issues 32-bit byte addresses. How is each address split?","options":["Tag 12, index 16, offset 4","Tag 18, index 10, offset 4","Tag 16, index 12, offset 4","Tag 16, index 14, offset 2"],"answer":2,"explanation":"16-byte blocks need a 4-bit offset; 64 KB ÷ 16 B = 4096 lines need a 12-bit index; the tag is the remaining 32 − 12 − 4 = 16 bits.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक 64 KB डायरेक्ट-मैप्ड कैश 16-बाइट ब्लॉक प्रयोग करता है, और प्रोसेसर 32-बिट बाइट पते जारी करता है। प्रत्येक पता कैसे विभाजित होता है?","optionsHi":["टैग 12, इंडेक्स 16, ऑफ़सेट 4","टैग 18, इंडेक्स 10, ऑफ़सेट 4","टैग 16, इंडेक्स 12, ऑफ़सेट 4","टैग 16, इंडेक्स 14, ऑफ़सेट 2"],"explanationHi":"16-बाइट ब्लॉक को 4-बिट ऑफ़सेट चाहिए; 64 KB ÷ 16 B = 4096 लाइनों को 12-बिट इंडेक्स चाहिए; टैग शेष 32 − 12 − 4 = 16 बिट है।"},
  {"id":"comp-awareness-279","question":"Which cache-mapping technique lets any memory block be placed in any cache line, at the cost of comparing its tag with every line at once?","options":["Fully associative mapping","Direct mapping","2-way set-associative mapping","Write-through mapping"],"answer":0,"explanation":"Fully associative mapping allows any block anywhere, so all tags must be searched in parallel. Direct mapping fixes one line per block, and set-associative limits the choice to one set; write-through is a write policy, not a mapping.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"कौन-सी कैश-मैपिंग तकनीक किसी भी मेमोरी ब्लॉक को किसी भी कैश लाइन में रखने देती है, इस कीमत पर कि उसके टैग की तुलना एक साथ हर लाइन से करनी पड़ती है?","optionsHi":["फ़ुली एसोसिएटिव मैपिंग","डायरेक्ट मैपिंग","2-वे सेट-एसोसिएटिव मैपिंग","राइट-थ्रू मैपिंग"],"explanationHi":"फ़ुली एसोसिएटिव मैपिंग किसी भी ब्लॉक को कहीं भी रखने देती है, इसलिए सभी टैग समानांतर रूप से खोजने पड़ते हैं। डायरेक्ट मैपिंग प्रति ब्लॉक एक लाइन तय करती है, और सेट-एसोसिएटिव चयन को एक सेट तक सीमित करती है; राइट-थ्रू राइट नीति है, मैपिंग नहीं।"},
  {"id":"comp-awareness-280","question":"A loop counter is read and updated on every pass of a loop, and so it stays in the cache. Which property of programs does this exploit?","options":["Spatial locality","Temporal locality","Memory interleaving","Write-back buffering"],"answer":1,"explanation":"Temporal locality means an item used now is likely to be used again soon, as a loop counter is. Spatial locality concerns neighbouring addresses, such as successive array elements.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"किसी लूप के प्रत्येक चक्कर में लूप काउंटर को पढ़ा और अद्यतन किया जाता है, और इसलिए वह कैश में बना रहता है। यह प्रोग्रामों के किस गुण का लाभ उठाता है?","optionsHi":["स्थानिक स्थानीयता","कालिक स्थानीयता","मेमोरी इंटरलीविंग","राइट-बैक बफ़रिंग"],"explanationHi":"कालिक स्थानीयता का अर्थ है कि अभी प्रयोग हुई वस्तु के शीघ्र फिर प्रयोग होने की संभावना होती है, जैसे लूप काउंटर की। स्थानिक स्थानीयता पास-पास के पतों से संबंधित है, जैसे ऐरे के क्रमागत तत्व।"},
  {"id":"comp-awareness-281","question":"When the CPU reads a word from main memory, which two registers hold the address being accessed and the data that arrives?","options":["MDR holds the address; MAR receives the data","PC holds the address; IR receives the data","IR holds the address; the accumulator receives the data","MAR holds the address; MDR receives the data"],"answer":3,"explanation":"The Memory Address Register holds the location placed on the address bus, and the Memory Data (Buffer) Register latches the word that comes back. The PC only points to the next instruction.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL","questionHi":"जब CPU मुख्य मेमोरी से कोई शब्द पढ़ता है, तो कौन-से दो रजिस्टर क्रमशः एक्सेस किया जा रहा पता और आने वाला डेटा रखते हैं?","optionsHi":["MDR पता रखता है; MAR डेटा प्राप्त करता है","PC पता रखता है; IR डेटा प्राप्त करता है","IR पता रखता है; एक्युमुलेटर डेटा प्राप्त करता है","MAR पता रखता है; MDR डेटा प्राप्त करता है"],"explanationHi":"मेमोरी एड्रेस रजिस्टर वह स्थान रखता है जो एड्रेस बस पर रखा जाता है, और मेमोरी डेटा (बफ़र) रजिस्टर लौटकर आने वाले शब्द को लैच करता है। PC केवल अगले निर्देश की ओर संकेत करता है।"},
  {"id":"comp-awareness-282","question":"A processor has a 16-bit data bus and moves one word on each bus cycle at 8 MHz. What is the maximum data transfer rate?","options":["8 million bytes per second","16 million bytes per second","128 million bytes per second","32 million bytes per second"],"answer":1,"explanation":"Each cycle moves 16 bits = 2 bytes, so 8 × 10⁶ cycles/s × 2 bytes = 16 × 10⁶ bytes/s. 128 million is the figure in bits per second.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"एक प्रोसेसर की डेटा बस 16-बिट है और वह 8 MHz पर प्रत्येक बस चक्र में एक शब्द ले जाता है। अधिकतम डेटा स्थानांतरण दर क्या है?","optionsHi":["8 मिलियन बाइट प्रति सेकंड","16 मिलियन बाइट प्रति सेकंड","128 मिलियन बाइट प्रति सेकंड","32 मिलियन बाइट प्रति सेकंड"],"explanationHi":"प्रत्येक चक्र 16 बिट = 2 बाइट ले जाता है, इसलिए 8 × 10⁶ चक्र/सेकंड × 2 बाइट = 16 × 10⁶ बाइट/सेकंड। 128 मिलियन बिट प्रति सेकंड का आँकड़ा है।"},
  {"id":"comp-awareness-283","question":"A 4K × 8 memory is to be built from 1K × 4 RAM chips. How many chips are needed, and how many address lines does the full memory require?","options":["4 chips and 12 address lines","8 chips and 10 address lines","8 chips and 12 address lines","16 chips and 12 address lines"],"answer":2,"explanation":"Chips = (4K × 8) ÷ (1K × 4) = 8 (two side by side for 8-bit width, four rows for 4K words). 4K = 2¹² locations needs 12 address lines; 10 lines address only one 1K chip.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"4K × 8 मेमोरी को 1K × 4 RAM चिपों से बनाना है। कितने चिप चाहिए, और पूरी मेमोरी को कितनी एड्रेस लाइनें चाहिए?","optionsHi":["4 चिप और 12 एड्रेस लाइनें","8 चिप और 10 एड्रेस लाइनें","8 चिप और 12 एड्रेस लाइनें","16 चिप और 12 एड्रेस लाइनें"],"explanationHi":"चिप = (4K × 8) ÷ (1K × 4) = 8 (8-बिट चौड़ाई के लिए दो साथ-साथ, 4K शब्दों के लिए चार पंक्तियाँ)। 4K = 2¹² स्थानों को 12 एड्रेस लाइनें चाहिए; 10 लाइनें केवल एक 1K चिप को पता देती हैं।"},
  {"id":"comp-awareness-284","question":"Which pairing of ROM type and erasing method is WRONG?","options":["PROM – written once by the user and then cannot be erased","EPROM – erased by ultraviolet light through a quartz window","EEPROM – erased and rewritten electrically, byte by byte","Flash – erased only by ultraviolet light, whole chip at once"],"answer":3,"explanation":"Flash memory is a kind of EEPROM erased electrically, usually in blocks; only EPROM needs ultraviolet light. The other three pairings are correct.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"ROM के प्रकार और मिटाने की विधि का कौन-सा युग्म गलत है?","optionsHi":["PROM – उपयोगकर्ता द्वारा एक बार लिखी जाती है और फिर मिटाई नहीं जा सकती","EPROM – क्वार्ट्ज़ खिड़की से पराबैंगनी प्रकाश द्वारा मिटाई जाती है","EEPROM – विद्युत से, बाइट-दर-बाइट मिटाई और पुनः लिखी जाती है","फ्लैश – केवल पराबैंगनी प्रकाश से, पूरी चिप एक साथ मिटाई जाती है"],"explanationHi":"फ्लैश मेमोरी EEPROM का एक प्रकार है जो विद्युत से, सामान्यतः ब्लॉकों में, मिटाई जाती है; केवल EPROM को पराबैंगनी प्रकाश चाहिए। शेष तीनों युग्म सही हैं।"},
  {"id":"comp-awareness-285","question":"A hard disk has 4 platters with both surfaces used, 1000 tracks per surface, 500 sectors per track and 512 bytes per sector. What is its capacity?","options":["1,024,000,000 bytes","2,048,000,000 bytes","4,096,000,000 bytes","256,000,000 bytes"],"answer":1,"explanation":"4 platters × 2 surfaces = 8 surfaces; 8 × 1000 × 500 × 512 = 2,048,000,000 bytes. Counting only one surface per platter gives 1,024,000,000.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक हार्ड डिस्क में 4 प्लैटर हैं जिनकी दोनों सतहें प्रयोग होती हैं, प्रति सतह 1000 ट्रैक, प्रति ट्रैक 500 सेक्टर और प्रति सेक्टर 512 बाइट हैं। उसकी क्षमता क्या है?","optionsHi":["1,024,000,000 बाइट","2,048,000,000 बाइट","4,096,000,000 बाइट","256,000,000 बाइट"],"explanationHi":"4 प्लैटर × 2 सतहें = 8 सतहें; 8 × 1000 × 500 × 512 = 2,048,000,000 बाइट। प्रति प्लैटर केवल एक सतह गिनने पर 1,024,000,000 आता है।"},
  {"id":"comp-awareness-286","question":"On a multi-platter hard disk, a 'cylinder' is:","options":["The set of tracks at the same arm position on every surface","The set of sectors at the same angle on a single surface","One complete track on the top surface of the top platter","The group of sectors the OS handles as one allocation unit"],"answer":0,"explanation":"All heads move together, so the tracks under them at one arm position form a cylinder and can be read without a seek. A group of sectors used as an allocation unit is a cluster.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer","questionHi":"बहु-प्लैटर हार्ड डिस्क में ‘सिलिंडर’ क्या है?","optionsHi":["प्रत्येक सतह पर एक ही आर्म स्थिति के ट्रैकों का समूह","एकल सतह पर एक ही कोण के सेक्टरों का समूह","ऊपरी प्लैटर की ऊपरी सतह का एक पूरा ट्रैक","सेक्टरों का वह समूह जिसे OS एक आवंटन इकाई के रूप में संभालता है"],"explanationHi":"सभी हेड साथ-साथ चलते हैं, इसलिए एक आर्म स्थिति पर उनके नीचे के ट्रैक एक सिलिंडर बनाते हैं और बिना सीक किए पढ़े जा सकते हैं। आवंटन इकाई के रूप में प्रयुक्त सेक्टरों का समूह क्लस्टर है।"},
  {"id":"comp-awareness-287","question":"A Blu-ray disc holds several times more data than a DVD of the same size mainly because it:","options":["Spins much faster, so more data passes under the head","Records on both faces of the disc by default","Uses a shorter-wavelength blue-violet laser, allowing smaller pits","Stores data magnetically instead of as pits and lands"],"answer":2,"explanation":"A 405 nm blue-violet laser focuses to a smaller spot than a DVD's red laser, so pits and track spacing shrink and density rises. Speed and sides do not explain the basic capacity per layer.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"ब्लू-रे डिस्क उसी आकार की DVD से कई गुना अधिक डेटा मुख्यतः इसलिए रखती है क्योंकि वह:","optionsHi":["बहुत तेज़ घूमती है, इसलिए हेड के नीचे से अधिक डेटा गुज़रता है","डिफ़ॉल्ट रूप से डिस्क के दोनों फलकों पर रिकॉर्ड करती है","छोटी तरंगदैर्घ्य वाले नीले-बैंगनी लेज़र का प्रयोग करती है, जिससे छोटे पिट बन सकते हैं","डेटा को पिट और लैंड के बजाय चुंबकीय रूप से संग्रहीत करती है"],"explanationHi":"405 nm का नीले-बैंगनी रंग का लेज़र DVD के लाल लेज़र से छोटे बिंदु पर फ़ोकस होता है, इसलिए पिट और ट्रैक की दूरी घटती है और घनत्व बढ़ता है। गति और फलक प्रति परत की मूल क्षमता की व्याख्या नहीं करते।"},
  {"id":"comp-awareness-288","question":"A bank keeps nightly backups that are rarely read and are always restored in full. Which medium suits this, and why is it poor for frequent random lookups?","options":["SSD – its flash cells wear out after repeated random reads","Hard disk – its heads can only move from outer to inner tracks","Blu-ray – each disc can be read only a fixed number of times","Magnetic tape – it must be wound past earlier data to reach a record"],"answer":3,"explanation":"Tape is cheap, high-capacity sequential-access storage, ideal for bulk backup but slow to reach a single record. Flash wears out from writes, not reads, and disk heads seek in both directions.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक बैंक रात्रिकालीन बैकअप रखता है जो कभी-कभार ही पढ़े जाते हैं और हमेशा पूरे पुनर्स्थापित किए जाते हैं। कौन-सा माध्यम इसके अनुकूल है, और बार-बार रैंडम खोज के लिए यह खराब क्यों है?","optionsHi":["SSD – उसके फ्लैश सेल बार-बार रैंडम रीड से घिस जाते हैं","हार्ड डिस्क – उसके हेड केवल बाहरी से भीतरी ट्रैकों की ओर जा सकते हैं","ब्लू-रे – प्रत्येक डिस्क केवल निश्चित बार ही पढ़ी जा सकती है","मैग्नेटिक टेप – किसी रिकॉर्ड तक पहुँचने के लिए उसे पहले के डेटा से गुज़ारकर लपेटना पड़ता है"],"explanationHi":"टेप सस्ता, उच्च-क्षमता वाला अनुक्रमिक-पहुँच संग्रहण है, जो थोक बैकअप के लिए आदर्श पर किसी एकल रिकॉर्ड तक पहुँचने में धीमा है। फ्लैश राइट से घिसता है, रीड से नहीं, और डिस्क के हेड दोनों दिशाओं में सीक करते हैं।"},
  {"id":"comp-awareness-289","question":"A program executes 2 × 10⁹ instructions with an average of 1.5 clock cycles per instruction on a 3 GHz processor. How long does it take to run?","options":["1 second","0.67 second","1.5 seconds","4.5 seconds"],"answer":0,"explanation":"Time = instructions × CPI ÷ clock rate = 2 × 10⁹ × 1.5 ÷ (3 × 10⁹) = 1 s. Ignoring the CPI gives 0.67 s.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"एक प्रोग्राम 2 × 10⁹ निर्देश निष्पादित करता है, जिनमें औसतन 1.5 क्लॉक चक्र प्रति निर्देश लगते हैं, 3 GHz प्रोसेसर पर। उसे चलने में कितना समय लगता है?","optionsHi":["1 सेकंड","0.67 सेकंड","1.5 सेकंड","4.5 सेकंड"],"explanationHi":"समय = निर्देश × CPI ÷ क्लॉक दर = 2 × 10⁹ × 1.5 ÷ (3 × 10⁹) = 1 s। CPI की उपेक्षा करने पर 0.67 s आता है।"},
  {"id":"comp-awareness-290","question":"40% of a program's running time is spent in a routine that is then made 4 times faster; the rest is unchanged. By Amdahl's law, what is the overall speedup, to two decimals?","options":["1.60","2.50","1.43","1.30"],"answer":2,"explanation":"New time = 0.6 + 0.4 ÷ 4 = 0.7 of the old, so speedup = 1 ÷ 0.7 ≈ 1.43. The untouched 60% limits the gain no matter how fast the routine becomes.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"किसी प्रोग्राम के चलने के समय का 40% एक रूटीन में बीतता है, जिसे फिर 4 गुना तेज़ कर दिया जाता है; शेष अपरिवर्तित रहता है। एम्डाल के नियम से कुल गति-वृद्धि क्या है, दो दशमलव स्थानों तक?","optionsHi":["1.60","2.50","1.43","1.30"],"explanationHi":"नया समय = 0.6 + 0.4 ÷ 4 = पुराने का 0.7, इसलिए गति-वृद्धि = 1 ÷ 0.7 ≈ 1.43। अपरिवर्तित 60% लाभ को सीमित कर देता है, चाहे रूटीन कितना भी तेज़ हो जाए।"},
  {"id":"comp-awareness-291","question":"A keyboard controller alerts the CPU only when a key is actually pressed, instead of the CPU checking its status again and again. This technique is called:","options":["Programmed I/O (polling)","Direct memory access","Memory-mapped I/O","Interrupt-driven I/O"],"answer":3,"explanation":"In interrupt-driven I/O the device raises an interrupt when it needs service, so the CPU does other work meanwhile. Polling is the repeated checking that this avoids.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"कीबोर्ड कंट्रोलर CPU को केवल तब सचेत करता है जब कोई कुंजी वास्तव में दबाई गई हो, बजाय इसके कि CPU उसकी स्थिति बार-बार जाँचे। इस तकनीक को कहते हैं:","optionsHi":["प्रोग्राम्ड I/O (पोलिंग)","डायरेक्ट मेमोरी एक्सेस","मेमोरी-मैप्ड I/O","इंटरप्ट-चालित I/O"],"explanationHi":"इंटरप्ट-चालित I/O में उपकरण को सेवा की आवश्यकता होने पर इंटरप्ट उठाता है, इसलिए CPU इस बीच अन्य कार्य करता है। पोलिंग वह बार-बार जाँचना है जिससे यह बचाता है।"},
  {"id":"comp-awareness-292","question":"Which statement correctly describes memory-mapped I/O?","options":["Device registers get addresses in the memory space and are used with ordinary load/store instructions","Devices have a separate address space and need special IN and OUT instructions to be accessed","A device copies whole blocks into RAM without the CPU and interrupts only when finished","The CPU keeps reading a device's status register in a loop until the device is ready"],"answer":0,"explanation":"Memory-mapped I/O places device registers in the normal address space. Separate IN/OUT instructions describe isolated (port-mapped) I/O; the other two describe DMA and polling.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"कौन-सा कथन मेमोरी-मैप्ड I/O का सही वर्णन करता है?","optionsHi":["उपकरण रजिस्टरों को मेमोरी स्पेस में पते मिलते हैं और उन्हें सामान्य लोड/स्टोर निर्देशों से प्रयोग किया जाता है","उपकरणों का अलग एड्रेस स्पेस होता है और उन तक पहुँचने के लिए विशेष IN और OUT निर्देश चाहिए","उपकरण CPU के बिना पूरे ब्लॉक RAM में कॉपी करता है और समाप्त होने पर ही इंटरप्ट करता है","CPU उपकरण के स्थिति रजिस्टर को लूप में तब तक पढ़ता रहता है जब तक उपकरण तैयार न हो जाए"],"explanationHi":"मेमोरी-मैप्ड I/O उपकरण रजिस्टरों को सामान्य एड्रेस स्पेस में रखता है। अलग IN/OUT निर्देश आइसोलेटेड (पोर्ट-मैप्ड) I/O का वर्णन करते हैं; शेष दो DMA और पोलिंग का वर्णन करते हैं।"},
  {"id":"comp-awareness-293","question":"In a paged virtual-memory system, the translation lookaside buffer (TLB) holds:","options":["Recently used data words fetched from main memory","Recently used page-number-to-frame-number translations","Pages that have been swapped out to the disk","The list of free frames in main memory"],"answer":1,"explanation":"The TLB is a small fast cache of page-table entries, so most address translations skip the page-table lookup in memory. Data words are kept in the ordinary data cache.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"पेजयुक्त वर्चुअल-मेमोरी प्रणाली में ट्रांसलेशन लुकसाइड बफ़र (TLB) क्या रखता है?","optionsHi":["मुख्य मेमोरी से लाए गए हाल में प्रयुक्त डेटा शब्द","हाल में प्रयुक्त पेज-संख्या-से-फ़्रेम-संख्या अनुवाद","वे पेज जिन्हें डिस्क पर स्वैप-आउट किया गया है","मुख्य मेमोरी के खाली फ़्रेमों की सूची"],"explanationHi":"TLB पेज-टेबल प्रविष्टियों का छोटा तेज़ कैश है, इसलिए अधिकांश पता-अनुवाद मेमोरी में पेज-टेबल खोज को छोड़ देते हैं। डेटा शब्द सामान्य डेटा कैश में रखे जाते हैं।"},
  {"id":"comp-awareness-294","question":"A system has 32-bit virtual addresses, 4 KB pages and 4-byte page-table entries. How large is one process's single-level page table?","options":["1 MB","16 KB","4 MB","4 GB"],"answer":2,"explanation":"Offset = 12 bits, so there are 2³² ÷ 2¹² = 2²⁰ pages; 2²⁰ entries × 4 bytes = 4 MB. 1 MB counts entries instead of bytes.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक प्रणाली में 32-बिट वर्चुअल पते, 4 KB पेज और 4-बाइट पेज-टेबल प्रविष्टियाँ हैं। एक प्रक्रिया की एकल-स्तरीय पेज टेबल कितनी बड़ी है?","optionsHi":["1 MB","16 KB","4 MB","4 GB"],"explanationHi":"ऑफ़सेट = 12 बिट, इसलिए 2³² ÷ 2¹² = 2²⁰ पेज हैं; 2²⁰ प्रविष्टियाँ × 4 बाइट = 4 MB। 1 MB बाइट के बजाय प्रविष्टियाँ गिनता है।"},
  {"id":"comp-awareness-295","question":"A TLB lookup takes 10 ns and a memory access 100 ns, and the TLB hit ratio is 90%. With a single-level page table, what is the effective memory access time?","options":["110 ns","129 ns","210 ns","120 ns"],"answer":3,"explanation":"Hit: 10 + 100 = 110 ns; miss: 10 + 100 (page table) + 100 (data) = 210 ns. Average = 0.9 × 110 + 0.1 × 210 = 99 + 21 = 120 ns.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक TLB लुकअप 10 ns और एक मेमोरी एक्सेस 100 ns लेता है, और TLB हिट अनुपात 90% है। एकल-स्तरीय पेज टेबल के साथ प्रभावी मेमोरी एक्सेस समय क्या है?","optionsHi":["110 ns","129 ns","210 ns","120 ns"],"explanationHi":"हिट: 10 + 100 = 110 ns; मिस: 10 + 100 (पेज टेबल) + 100 (डेटा) = 210 ns। औसत = 0.9 × 110 + 0.1 × 210 = 99 + 21 = 120 ns।"},
  {"id":"comp-awareness-296","question":"The small coin-cell battery on a PC motherboard keeps power supplied to:","options":["The CMOS memory that holds the clock and BIOS settings","The BIOS program code stored in flash ROM","The L1 cache, so the processor starts faster","The RAM, so open files survive a shutdown"],"answer":0,"explanation":"Settings such as date, time and boot order sit in a tiny CMOS RAM with the real-time clock, which needs the battery; the BIOS code itself is in non-volatile flash.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"PC मदरबोर्ड पर लगी छोटी कॉइन-सेल बैटरी किसे बिजली देती रहती है?","optionsHi":["उस CMOS मेमोरी को जो घड़ी और BIOS सेटिंग रखती है","फ्लैश ROM में संग्रहीत BIOS प्रोग्राम कोड को","L1 कैश को, ताकि प्रोसेसर तेज़ शुरू हो","RAM को, ताकि खुली फ़ाइलें शटडाउन के बाद भी बनी रहें"],"explanationHi":"दिनांक, समय और बूट क्रम जैसी सेटिंग रियल-टाइम घड़ी के साथ एक छोटी CMOS RAM में रहती हैं, जिसे बैटरी चाहिए; BIOS कोड स्वयं अवाष्पशील फ्लैश में होता है।"},
  {"id":"comp-awareness-297","question":"Why can a disk partitioned with the older MBR scheme and 512-byte sectors use only about 2.2 TB of space?","options":["MBR allows only four primary partitions of 512 GB each","MBR stores sector numbers in 32 bits, and 2³² × 512 bytes ≈ 2.2 TB","MBR relies on FAT32, whose clusters cannot cover more than 2 TB","MBR stores sector numbers in 16 bits, and 2¹⁶ × 512 bytes ≈ 2.2 TB"],"answer":1,"explanation":"MBR partition entries keep 32-bit sector addresses, so 2³² × 512 B = 2,199,023,255,552 bytes is the ceiling; GPT uses 64-bit addresses. 2¹⁶ × 512 B is only 32 MB.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"पुरानी MBR योजना और 512-बाइट सेक्टरों से विभाजित डिस्क केवल लगभग 2.2 TB स्थान ही क्यों प्रयोग कर सकती है?","optionsHi":["MBR केवल चार प्राथमिक विभाजनों की अनुमति देता है, प्रत्येक 512 GB का","MBR सेक्टर संख्याएँ 32 बिट में रखता है, और 2³² × 512 बाइट ≈ 2.2 TB","MBR FAT32 पर निर्भर है, जिसके क्लस्टर 2 TB से अधिक को कवर नहीं कर सकते","MBR सेक्टर संख्याएँ 16 बिट में रखता है, और 2¹⁶ × 512 बाइट ≈ 2.2 TB"],"explanationHi":"MBR विभाजन प्रविष्टियाँ 32-बिट सेक्टर पते रखती हैं, इसलिए 2³² × 512 B = 2,199,023,255,552 बाइट ही सीमा है; GPT 64-बिट पते प्रयोग करता है। 2¹⁶ × 512 B केवल 32 MB है।"},
  {"id":"comp-awareness-298","question":"In a laser printer, the page image is first formed as:","options":["Ink droplets sprayed through tiny nozzles onto the paper","Heat applied to specially coated paper by a print head","An electrostatic charge pattern on a photosensitive drum","Pins striking an inked ribbon against the paper"],"answer":2,"explanation":"The laser discharges parts of a charged drum; toner sticks to that pattern, is transferred to paper and fused by heat. The other options describe inkjet, thermal and dot-matrix printers.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CGL","questionHi":"लेज़र प्रिंटर में पृष्ठ की छवि सबसे पहले किस रूप में बनती है?","optionsHi":["सूक्ष्म नोज़लों से कागज़ पर छिड़की गई स्याही की बूँदें","प्रिंट हेड द्वारा विशेष रूप से लेपित कागज़ पर लगाई गई ऊष्मा","प्रकाश-संवेदी ड्रम पर स्थिर-वैद्युत आवेश का पैटर्न","स्याही लगे रिबन को कागज़ पर दबाती पिनें"],"explanationHi":"लेज़र आवेशित ड्रम के कुछ भागों को निरावेशित करता है; टोनर उस पैटर्न से चिपकता है, कागज़ पर स्थानांतरित होता है और ऊष्मा से जमाया जाता है। शेष विकल्प इंकजेट, थर्मल और डॉट-मैट्रिक्स प्रिंटरों का वर्णन करते हैं।"},
  {"id":"comp-awareness-299","question":"Which touchscreen technology senses the electrical conductivity of a finger, and so does not respond to an ordinary plastic stylus?","options":["Resistive","Capacitive","Infrared grid","Optical camera-based"],"answer":1,"explanation":"A capacitive screen detects the change in charge caused by a conductive finger. Resistive screens react to pressure from anything, and infrared or optical screens detect any object breaking the light.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"कौन-सी टचस्क्रीन तकनीक उँगली की विद्युत चालकता को भाँपती है, और इसलिए साधारण प्लास्टिक स्टाइलस पर प्रतिक्रिया नहीं देती?","optionsHi":["रेज़िस्टिव","कैपेसिटिव","इन्फ्रारेड ग्रिड","ऑप्टिकल कैमरा-आधारित"],"explanationHi":"कैपेसिटिव स्क्रीन चालक उँगली से आवेश में होने वाले परिवर्तन को भाँपती है। रेज़िस्टिव स्क्रीन किसी भी वस्तु के दबाव पर प्रतिक्रिया देती हैं, और इन्फ्रारेड या ऑप्टिकल स्क्रीन प्रकाश को बाधित करने वाली किसी भी वस्तु को भाँपती हैं।"},
  {"id":"comp-awareness-300","question":"Which of these printers is an IMPACT printer?","options":["Laser printer","Inkjet printer","Thermal printer","Daisy-wheel printer"],"answer":3,"explanation":"A daisy-wheel printer strikes a character petal against an inked ribbon, like dot-matrix printers. Laser, inkjet and thermal printers form the image without striking the paper.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CGL","questionHi":"इनमें से कौन-सा इम्पैक्ट प्रिंटर है?","optionsHi":["लेज़र प्रिंटर","इंकजेट प्रिंटर","थर्मल प्रिंटर","डेज़ी-व्हील प्रिंटर"],"explanationHi":"डेज़ी-व्हील प्रिंटर डॉट-मैट्रिक्स प्रिंटरों की तरह वर्ण-पंखुड़ी को स्याही लगे रिबन पर प्रहार कराता है। लेज़र, इंकजेट और थर्मल प्रिंटर कागज़ पर प्रहार किए बिना छवि बनाते हैं।"},
  {"id":"comp-awareness-301","question":"A process that was blocked waiting for a disk read is told that the read has finished. To which state does it move next?","options":["Running","Ready","Terminated","New"],"answer":1,"explanation":"Completion of I/O moves a process from waiting to ready; it runs only when the scheduler dispatches it. It does not jump straight back to running.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"डिस्क रीड की प्रतीक्षा में ब्लॉक्ड एक प्रक्रिया को बताया जाता है कि रीड पूरी हो गई है। वह आगे किस अवस्था में जाती है?","optionsHi":["रनिंग","रेडी","टर्मिनेटेड","न्यू"],"explanationHi":"I/O पूरा होने पर प्रक्रिया वेटिंग से रेडी अवस्था में जाती है; वह तभी चलती है जब शेड्यूलर उसे डिस्पैच करे। वह सीधे रनिंग में नहीं कूदती।"},
  {"id":"comp-awareness-302","question":"Processes P1, P2 and P3 arrive at time 0 in that order with CPU bursts of 5, 3 and 1 ms. Under Round Robin with a time quantum of 2 ms, what is the average waiting time?","options":["7.33 ms","3.67 ms","4.33 ms","5.00 ms"],"answer":2,"explanation":"Order: P1 0–2, P2 2–4, P3 4–5, P1 5–7, P2 7–8, P1 8–9. Waiting = completion − burst: P1 9 − 5 = 4, P2 8 − 3 = 5, P3 5 − 1 = 4; average 13 ÷ 3 ≈ 4.33 ms. 7.33 is the average turnaround time.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"प्रक्रियाएँ P1, P2 और P3 समय 0 पर इसी क्रम में आती हैं और उनके CPU बर्स्ट क्रमशः 5, 3 और 1 ms हैं। 2 ms के टाइम क्वांटम वाले राउंड रॉबिन में औसत प्रतीक्षा समय क्या है?","optionsHi":["7.33 ms","3.67 ms","4.33 ms","5.00 ms"],"explanationHi":"क्रम: P1 0–2, P2 2–4, P3 4–5, P1 5–7, P2 7–8, P1 8–9। प्रतीक्षा = समापन − बर्स्ट: P1 9 − 5 = 4, P2 8 − 3 = 5, P3 5 − 1 = 4; औसत 13 ÷ 3 ≈ 4.33 ms। 7.33 औसत टर्नअराउंड समय है।"},
  {"id":"comp-awareness-303","question":"Four processes have (arrival, burst) times P1 (0, 7), P2 (2, 4), P3 (4, 1) and P4 (5, 4) in ms. Under pre-emptive Shortest Remaining Time First, what is the average waiting time?","options":["4 ms","3.5 ms","2.75 ms","3 ms"],"answer":3,"explanation":"Schedule: P1 0–2, P2 2–4, P3 4–5, P2 5–7, P4 7–11, P1 11–16. Waits: P1 9, P2 1, P3 0, P4 2, so the average is 12 ÷ 4 = 3 ms. Non-pre-emptive SJF would give 4 ms.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"चार प्रक्रियाओं के (आगमन, बर्स्ट) समय P1 (0, 7), P2 (2, 4), P3 (4, 1) और P4 (5, 4) ms में हैं। प्री-एम्प्टिव शॉर्टेस्ट रिमेनिंग टाइम फ़र्स्ट में औसत प्रतीक्षा समय क्या है?","optionsHi":["4 ms","3.5 ms","2.75 ms","3 ms"],"explanationHi":"समय-सारणी: P1 0–2, P2 2–4, P3 4–5, P2 5–7, P4 7–11, P1 11–16। प्रतीक्षा: P1 9, P2 1, P3 0, P4 2, इसलिए औसत 12 ÷ 4 = 3 ms है। नॉन-प्री-एम्प्टिव SJF में 4 ms आता।"},
  {"id":"comp-awareness-304","question":"Under priority scheduling, a low-priority process may wait for ever. Which technique fixes this by slowly raising the priority of processes that have waited long?","options":["Aging","Thrashing","Spooling","Swapping"],"answer":0,"explanation":"Aging increases a waiting process's priority over time, so starvation cannot last indefinitely. Thrashing is excessive paging; spooling and swapping are unrelated.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"प्राथमिकता शेड्यूलिंग में कम प्राथमिकता वाली प्रक्रिया सदा के लिए प्रतीक्षा में रह सकती है। कौन-सी तकनीक इसे लंबे समय से प्रतीक्षारत प्रक्रियाओं की प्राथमिकता धीरे-धीरे बढ़ाकर ठीक करती है?","optionsHi":["एजिंग","थ्रैशिंग","स्पूलिंग","स्वैपिंग"],"explanationHi":"एजिंग प्रतीक्षारत प्रक्रिया की प्राथमिकता समय के साथ बढ़ाती है, इसलिए स्टार्वेशन अनंत काल तक नहीं रह सकता। थ्रैशिंग अत्यधिक पेजिंग है; स्पूलिंग और स्वैपिंग असंबंधित हैं।"},
  {"id":"comp-awareness-305","question":"Many short processes sit idle behind one long CPU-bound process, lowering device and CPU utilisation. This 'convoy effect' is typical of which scheduling algorithm?","options":["Round Robin","Shortest Remaining Time First","First-Come, First-Served","Multilevel feedback queue"],"answer":2,"explanation":"Non-pre-emptive FCFS lets a long job hold the CPU while short jobs queue behind it. Round Robin and SRTF pre-empt, and feedback queues demote long jobs.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"कई छोटी प्रक्रियाएँ एक लंबी CPU-बद्ध प्रक्रिया के पीछे निष्क्रिय बैठी रहती हैं, जिससे उपकरण और CPU का उपयोग घटता है। यह ‘कॉन्वॉय प्रभाव’ किस शेड्यूलिंग एल्गोरिदम की विशेषता है?","optionsHi":["राउंड रॉबिन","शॉर्टेस्ट रिमेनिंग टाइम फ़र्स्ट","फ़र्स्ट-कम, फ़र्स्ट-सर्व्ड","मल्टीलेवल फ़ीडबैक क्यू"],"explanationHi":"नॉन-प्री-एम्प्टिव FCFS लंबे कार्य को CPU थामे रखने देता है जबकि छोटे कार्य उसके पीछे कतार में रहते हैं। राउंड रॉबिन और SRTF प्री-एम्प्ट करते हैं, और फ़ीडबैक क्यू लंबे कार्यों की प्राथमिकता घटाती हैं।"},
  {"id":"comp-awareness-306","question":"Which page-replacement algorithm can suffer from Belady's anomaly, where giving a process MORE frames produces MORE page faults?","options":["LRU","Optimal (OPT)","Both LRU and Optimal","FIFO"],"answer":3,"explanation":"FIFO is not a stack algorithm, so a larger memory need not contain the pages a smaller one holds, and faults can rise. LRU and Optimal are stack algorithms and never show the anomaly.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"कौन-सा पेज-प्रतिस्थापन एल्गोरिदम बेलैडी की विसंगति से ग्रस्त हो सकता है, जिसमें किसी प्रक्रिया को अधिक फ़्रेम देने पर अधिक पेज फ़ॉल्ट होते हैं?","optionsHi":["LRU","ऑप्टिमल (OPT)","LRU और ऑप्टिमल दोनों","FIFO"],"explanationHi":"FIFO स्टैक एल्गोरिदम नहीं है, इसलिए बड़ी मेमोरी में वे पेज होना आवश्यक नहीं जो छोटी में थे, और फ़ॉल्ट बढ़ सकते हैं। LRU और ऑप्टिमल स्टैक एल्गोरिदम हैं और कभी यह विसंगति नहीं दिखाते।"},
  {"id":"comp-awareness-307","question":"A process has 3 page frames, all empty at first, and refers to pages 7, 0, 1, 2, 0, 3, 0, 4, 2, 3. How many page faults occur under the Optimal (OPT) algorithm?","options":["7","6","8","9"],"answer":1,"explanation":"OPT evicts the page used farthest in future: faults on 7, 0, 1, 2 (evict 7), 3 (evict 1) and 4 (evict 0); the rest hit, so 6 faults. LRU gives 8 and FIFO 9 on this string.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक प्रक्रिया के पास 3 पेज फ़्रेम हैं, जो शुरू में सब खाली हैं, और वह पेजों 7, 0, 1, 2, 0, 3, 0, 4, 2, 3 का संदर्भ देती है। ऑप्टिमल (OPT) एल्गोरिदम में कितने पेज फ़ॉल्ट होंगे?","optionsHi":["7","6","8","9"],"explanationHi":"OPT उस पेज को हटाता है जो भविष्य में सबसे दूर प्रयोग होगा: फ़ॉल्ट 7, 0, 1, 2 (7 हटाएँ), 3 (1 हटाएँ) और 4 (0 हटाएँ) पर होते हैं; शेष हिट हैं, इसलिए 6 फ़ॉल्ट। इस स्ट्रिंग पर LRU 8 और FIFO 9 देता है।"},
  {"id":"comp-awareness-308","question":"A system has 12 tape drives. P0 holds 5 (maximum need 10), P1 holds 2 (maximum 4) and P2 holds 2 (maximum 9). Under the Banker's algorithm, which is a safe sequence?","options":["<P0, P1, P2>","<P2, P1, P0>","<P1, P0, P2>","No safe sequence exists"],"answer":2,"explanation":"Free = 12 − 9 = 3. P1 needs 2, finishes, free 5; P0 needs 5, finishes, free 10; P2 needs 7, finishes. P0 cannot go first (needs 5 with only 3 free), and P2 cannot run before P0.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक प्रणाली में 12 टेप ड्राइव हैं। P0 के पास 5 हैं (अधिकतम आवश्यकता 10), P1 के पास 2 (अधिकतम 4) और P2 के पास 2 (अधिकतम 9)। बैंकर के एल्गोरिदम में कौन-सा सुरक्षित अनुक्रम है?","optionsHi":["<P0, P1, P2>","<P2, P1, P0>","<P1, P0, P2>","कोई सुरक्षित अनुक्रम नहीं है"],"explanationHi":"खाली = 12 − 9 = 3। P1 को 2 चाहिए, वह पूरा होता है, खाली 5; P0 को 5 चाहिए, वह पूरा होता है, खाली 10; P2 को 7 चाहिए, वह पूरा होता है। P0 पहले नहीं जा सकता (3 खाली होने पर 5 चाहिए), और P2 P0 से पहले नहीं चल सकता।"},
  {"id":"comp-awareness-309","question":"Four processes share identical units of one resource, and each may need up to 3 units at once. What is the least number of units that guarantees no deadlock?","options":["8","12","10","9"],"answer":3,"explanation":"Worst case: each holds 2 units and waits for one more, using 4 × 2 = 8. One extra unit lets someone finish, so n(k − 1) + 1 = 4 × 2 + 1 = 9 units suffice.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"चार प्रक्रियाएँ एक संसाधन की समान इकाइयाँ साझा करती हैं, और प्रत्येक को एक साथ अधिकतम 3 इकाइयाँ चाहिए हो सकती हैं। डेडलॉक न होने की गारंटी देने वाली न्यूनतम इकाइयाँ कितनी हैं?","optionsHi":["8","12","10","9"],"explanationHi":"सबसे खराब स्थिति: प्रत्येक के पास 2 इकाइयाँ हैं और एक और की प्रतीक्षा है, जिनमें 4 × 2 = 8 लगीं। एक अतिरिक्त इकाई किसी को पूरा होने देती है, इसलिए n(k − 1) + 1 = 4 × 2 + 1 = 9 इकाइयाँ पर्याप्त हैं।"},
  {"id":"comp-awareness-310","question":"A counting semaphore starts at 7. Then 20 wait (P) operations and 15 signal (V) operations are performed on it. What is its final value?","options":["2","12","−8","5"],"answer":0,"explanation":"Each P subtracts 1 and each V adds 1: 7 − 20 + 15 = 2. A negative value would mean processes are blocked on it.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"एक काउंटिंग सेमाफ़ोर 7 से शुरू होता है। फिर उस पर 20 वेट (P) संक्रियाएँ और 15 सिग्नल (V) संक्रियाएँ की जाती हैं। उसका अंतिम मान क्या है?","optionsHi":["2","12","−8","5"],"explanationHi":"प्रत्येक P में से 1 घटता है और प्रत्येक V में 1 जुड़ता है: 7 − 20 + 15 = 2। ऋणात्मक मान का अर्थ होता कि प्रक्रियाएँ उस पर ब्लॉक्ड हैं।"},
  {"id":"comp-awareness-311","question":"Which of these is NOT one of the three requirements a correct critical-section solution must meet?","options":["Mutual exclusion","Progress","Bounded waiting","Equal CPU time for every process"],"answer":3,"explanation":"A critical-section solution must give mutual exclusion, progress and bounded waiting. Fair CPU sharing is a scheduling goal, not part of the critical-section problem.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"इनमें से कौन-सी उन तीन आवश्यकताओं में से नहीं है जिन्हें सही क्रिटिकल-सेक्शन समाधान को पूरा करना चाहिए?","optionsHi":["पारस्परिक अपवर्जन","प्रोग्रेस","बाउंडेड वेटिंग","प्रत्येक प्रक्रिया के लिए समान CPU समय"],"explanationHi":"क्रिटिकल-सेक्शन समाधान को पारस्परिक अपवर्जन, प्रोग्रेस और बाउंडेड वेटिंग देनी चाहिए। CPU का उचित बँटवारा शेड्यूलिंग का लक्ष्य है, क्रिटिकल-सेक्शन समस्या का भाग नहीं।"},
  {"id":"comp-awareness-312","question":"How does a microkernel operating system differ from a monolithic one?","options":["It runs drivers and file systems inside the kernel for maximum speed","It keeps only core services such as IPC and basic scheduling in kernel mode","It has no kernel mode at all, so every program runs with full privileges","It loads the whole operating system into ROM so it cannot be modified"],"answer":1,"explanation":"A microkernel keeps minimal services in kernel mode and runs drivers and file systems as user-space servers, gaining reliability at some speed cost. Putting everything in the kernel describes a monolithic design.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"माइक्रोकर्नेल ऑपरेटिंग सिस्टम मोनोलिथिक से कैसे भिन्न है?","optionsHi":["यह अधिकतम गति के लिए ड्राइवर और फ़ाइल सिस्टम को कर्नेल के भीतर चलाता है","यह केवल IPC और मूल शेड्यूलिंग जैसी मुख्य सेवाओं को कर्नेल मोड में रखता है","इसमें कर्नेल मोड होता ही नहीं, इसलिए प्रत्येक प्रोग्राम पूर्ण विशेषाधिकार से चलता है","यह पूरे ऑपरेटिंग सिस्टम को ROM में लोड करता है ताकि उसे बदला न जा सके"],"explanationHi":"माइक्रोकर्नेल न्यूनतम सेवाओं को कर्नेल मोड में रखता है और ड्राइवर तथा फ़ाइल सिस्टम को यूज़र-स्पेस सर्वर के रूप में चलाता है, जिससे कुछ गति गँवाकर विश्वसनीयता मिलती है। सब कुछ कर्नेल में रखना मोनोलिथिक डिज़ाइन का वर्णन है।"},
  {"id":"comp-awareness-313","question":"In the many-to-one threading model (many user-level threads mapped to one kernel thread), what happens when one thread makes a blocking system call?","options":["Only that thread blocks and the others keep running","The kernel creates a new kernel thread for the rest","The blocking call is converted into a non-blocking one","The whole process blocks until the call returns"],"answer":3,"explanation":"The kernel sees only one schedulable thread, so if it blocks, every user-level thread in the process stops. One-to-one models avoid this.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"मैनी-टू-वन थ्रेडिंग मॉडल में (कई यूज़र-स्तरीय थ्रेड एक कर्नेल थ्रेड से मैप्ड), जब कोई थ्रेड ब्लॉकिंग सिस्टम कॉल करता है तो क्या होता है?","optionsHi":["केवल वही थ्रेड ब्लॉक होता है और अन्य चलते रहते हैं","कर्नेल शेष के लिए नया कर्नेल थ्रेड बनाता है","ब्लॉकिंग कॉल को नॉन-ब्लॉकिंग में बदल दिया जाता है","कॉल लौटने तक पूरी प्रक्रिया ब्लॉक हो जाती है"],"explanationHi":"कर्नेल को केवल एक शेड्यूल-योग्य थ्रेड दिखता है, इसलिए वह ब्लॉक हो तो प्रक्रिया के सभी यूज़र-स्तरीय थ्रेड रुक जाते हैं। वन-टू-वन मॉडल इससे बचते हैं।"},
  {"id":"comp-awareness-314","question":"The main purpose of multiprogramming in an operating system is to:","options":["Keep the CPU busy by switching jobs when one waits for I/O","Run one program on several processors at once","Let one user run several windows on the same screen","Divide a large program into pages that fit in memory"],"answer":0,"explanation":"Several jobs are kept in memory; when one waits for I/O, the CPU switches to another, raising utilisation. Running on several processors is multiprocessing.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"ऑपरेटिंग सिस्टम में मल्टीप्रोग्रामिंग का मुख्य उद्देश्य है:","optionsHi":["जब कोई कार्य I/O की प्रतीक्षा करे तो कार्य बदलकर CPU को व्यस्त रखना","एक प्रोग्राम को एक साथ कई प्रोसेसरों पर चलाना","एक उपयोगकर्ता को उसी स्क्रीन पर कई विंडो चलाने देना","बड़े प्रोग्राम को पेजों में बाँटना जो मेमोरी में समा सकें"],"explanationHi":"कई कार्य मेमोरी में रखे जाते हैं; जब कोई I/O की प्रतीक्षा करता है तो CPU दूसरे पर चला जाता है, जिससे उपयोग बढ़ता है। कई प्रोसेसरों पर चलाना मल्टीप्रोसेसिंग है।"},
  {"id":"comp-awareness-315","question":"Which file-allocation method allows fast direct access to any block but suffers from external fragmentation?","options":["Linked allocation","Indexed allocation","Contiguous allocation","FAT-chained allocation"],"answer":2,"explanation":"Contiguous files let block k be found at start + k, but free space breaks into holes. Linked (and FAT-chained) allocation needs a chain walk, and indexed allocation avoids external fragmentation.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"कौन-सी फ़ाइल-आवंटन विधि किसी भी ब्लॉक तक तेज़ प्रत्यक्ष पहुँच देती है पर बाह्य विखंडन से ग्रस्त होती है?","optionsHi":["लिंक्ड आवंटन","इंडेक्स्ड आवंटन","कंटिगुअस आवंटन","FAT-शृंखलित आवंटन"],"explanationHi":"कंटिगुअस फ़ाइलों में ब्लॉक k प्रारंभ + k पर मिल जाता है, पर खाली स्थान छिद्रों में टूट जाता है। लिंक्ड (और FAT-शृंखलित) आवंटन में शृंखला पर चलना पड़ता है, और इंडेक्स्ड आवंटन बाह्य विखंडन से बचता है।"},
  {"id":"comp-awareness-316","question":"Which Windows file system supports file-level permissions, journaling for crash recovery and single files larger than 4 GB?","options":["FAT32","FAT16","exFAT","NTFS"],"answer":3,"explanation":"NTFS offers access-control lists, a journal and very large files. exFAT allows large files but has no permissions or journal; FAT32 caps files just under 4 GB.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer","questionHi":"कौन-सा Windows फ़ाइल सिस्टम फ़ाइल-स्तरीय अनुमतियाँ, क्रैश रिकवरी के लिए जर्नलिंग और 4 GB से बड़ी एकल फ़ाइलों का समर्थन करता है?","optionsHi":["FAT32","FAT16","exFAT","NTFS"],"explanationHi":"NTFS एक्सेस-कंट्रोल सूचियाँ, जर्नल और बहुत बड़ी फ़ाइलें प्रदान करता है। exFAT बड़ी फ़ाइलें अनुमति देता है पर उसमें अनुमतियाँ या जर्नल नहीं हैं; FAT32 फ़ाइलों को 4 GB से कुछ कम तक सीमित करता है।"},
  {"id":"comp-awareness-317","question":"In a UNIX-like file system, a file's inode stores all of the following EXCEPT the file's:","options":["Size","Name","Access permissions","Pointers to its data blocks"],"answer":1,"explanation":"Names live in directory entries that map a name to an inode number; that is why one inode can have several hard-linked names. Size, permissions and block pointers are in the inode.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"UNIX-जैसे फ़ाइल सिस्टम में, फ़ाइल का इनोड निम्नलिखित सब संग्रहीत करता है, सिवाय फ़ाइल के:","optionsHi":["आकार","नाम","एक्सेस अनुमतियाँ","उसके डेटा ब्लॉकों के पॉइंटर"],"explanationHi":"नाम डायरेक्टरी प्रविष्टियों में रहते हैं जो नाम को इनोड संख्या से जोड़ती हैं; इसीलिए एक इनोड के कई हार्ड-लिंक्ड नाम हो सकते हैं। आकार, अनुमतियाँ और ब्लॉक पॉइंटर इनोड में होते हैं।"},
  {"id":"comp-awareness-318","question":"A file report.txt has one hard link and one symbolic link pointing to it. The original name report.txt is then deleted. What happens?","options":["The symbolic link breaks, but the hard link still opens the data","The hard link breaks, but the symbolic link still opens the data","Both links break because the data is erased at once","Both links keep working because links copy the data"],"answer":0,"explanation":"A hard link is another name for the same inode, so the data survives while any hard link remains. A symbolic link stores only the path, which now points nowhere.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"फ़ाइल report.txt की ओर संकेत करने वाला एक हार्ड लिंक और एक सिंबॉलिक लिंक है। फिर मूल नाम report.txt हटा दिया जाता है। क्या होता है?","optionsHi":["सिंबॉलिक लिंक टूट जाता है, पर हार्ड लिंक अब भी डेटा खोलता है","हार्ड लिंक टूट जाता है, पर सिंबॉलिक लिंक अब भी डेटा खोलता है","दोनों लिंक टूट जाते हैं क्योंकि डेटा तुरंत मिट जाता है","दोनों लिंक चलते रहते हैं क्योंकि लिंक डेटा की प्रतिलिपि बनाते हैं"],"explanationHi":"हार्ड लिंक उसी इनोड का दूसरा नाम है, इसलिए कोई भी हार्ड लिंक बचा रहने तक डेटा बना रहता है। सिंबॉलिक लिंक केवल पथ रखता है, जो अब कहीं नहीं ले जाता।"},
  {"id":"comp-awareness-319","question":"In Linux, the command chmod 754 file gives the file which permission string?","options":["rwxrw-r--","rwxr-xr-x","r-xrwxr--","rwxr-xr--"],"answer":3,"explanation":"Each digit is r = 4, w = 2, x = 1 for owner, group and others: 7 = rwx, 5 = r-x, 4 = r--. 755 would give r-x to others as well.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"Linux में कमांड chmod 754 file फ़ाइल को कौन-सी अनुमति स्ट्रिंग देता है?","optionsHi":["rwxrw-r--","rwxr-xr-x","r-xrwxr--","rwxr-xr--"],"explanationHi":"स्वामी, समूह और अन्य के लिए प्रत्येक अंक में r = 4, w = 2, x = 1 होता है: 7 = rwx, 5 = r-x, 4 = r--। 755 अन्य को भी r-x देता।"},
  {"id":"comp-awareness-320","question":"Match the Windows shortcut with its action: 1. Windows + L 2. Windows + D 3. Alt + F4 4. Alt + Tab; a. Show the desktop b. Close the active window c. Switch between open windows d. Lock the computer","options":["1-a, 2-d, 3-b, 4-c","1-d, 2-a, 3-c, 4-b","1-d, 2-a, 3-b, 4-c","1-d, 2-b, 3-a, 4-c"],"answer":2,"explanation":"Windows + L locks, Windows + D shows the desktop, Alt + F4 closes the active window and Alt + Tab switches between open windows.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"Windows शॉर्टकट का उसकी क्रिया से मिलान कीजिए: 1. Windows + L 2. Windows + D 3. Alt + F4 4. Alt + Tab; a. डेस्कटॉप दिखाना b. सक्रिय विंडो बंद करना c. खुली विंडो के बीच बदलना d. कंप्यूटर को लॉक करना","optionsHi":["1-a, 2-d, 3-b, 4-c","1-d, 2-a, 3-c, 4-b","1-d, 2-a, 3-b, 4-c","1-d, 2-b, 3-a, 4-c"],"explanationHi":"Windows + L लॉक करता है, Windows + D डेस्कटॉप दिखाता है, Alt + F4 सक्रिय विंडो बंद करता है और Alt + Tab खुली विंडो के बीच बदलता है।"},
  {"id":"comp-awareness-321","question":"A program calls fork() three times in a row, with no conditions, and every call succeeds. How many processes exist in total, counting the original?","options":["8","6","4","7"],"answer":0,"explanation":"Each fork doubles the running processes: 1 → 2 → 4 → 8. Seven of them are children; 6 comes from wrongly adding 2 per call.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक प्रोग्राम बिना किसी शर्त के लगातार तीन बार fork() कॉल करता है, और प्रत्येक कॉल सफल होती है। मूल प्रक्रिया सहित कुल कितनी प्रक्रियाएँ होंगी?","optionsHi":["8","6","4","7"],"explanationHi":"प्रत्येक fork चल रही प्रक्रियाओं को दोगुना करता है: 1 → 2 → 4 → 8। इनमें से सात चाइल्ड हैं; 6 गलती से प्रति कॉल 2 जोड़ने से आता है।"},
  {"id":"comp-awareness-322","question":"A user program divides an integer by zero. What does the processor generate?","options":["A hardware interrupt from an external device controller","A trap (exception) raised by the CPU itself and handled by the OS","A system call deliberately requested by the program","A page fault serviced by loading a page from disk"],"answer":1,"explanation":"An error inside the running instruction raises a synchronous trap, and the OS's handler takes over (often ending the program). Interrupts come from external devices; a system call is a deliberate request.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"एक उपयोगकर्ता प्रोग्राम किसी पूर्णांक को शून्य से भाग देता है। प्रोसेसर क्या उत्पन्न करता है?","optionsHi":["बाहरी डिवाइस कंट्रोलर से हार्डवेयर इंटरप्ट","CPU द्वारा स्वयं उठाया गया ट्रैप (अपवाद), जिसे OS संभालता है","प्रोग्राम द्वारा जानबूझकर माँगी गई सिस्टम कॉल","पेज फ़ॉल्ट, जिसे डिस्क से पेज लोड करके सुलझाया जाता है"],"explanationHi":"चल रहे निर्देश के भीतर की त्रुटि समकालिक ट्रैप उठाती है, और OS का हैंडलर कमान सँभालता है (अक्सर प्रोग्राम को समाप्त कर देता है)। इंटरप्ट बाहरी उपकरणों से आते हैं; सिस्टम कॉल जानबूझकर किया गया अनुरोध है।"},
  {"id":"comp-awareness-323","question":"Why do processors provide separate user mode and kernel (supervisor) mode?","options":["To let user programs run faster by skipping security checks","To let two operating systems run at the same time on one CPU","To stop user programs from directly running privileged instructions","To keep a backup copy of the kernel in case the first one fails"],"answer":2,"explanation":"Instructions such as I/O or changing memory protection run only in kernel mode, so a faulty or malicious program must ask the OS through a system call instead.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"प्रोसेसर अलग यूज़र मोड और कर्नेल (सुपरवाइज़र) मोड क्यों देते हैं?","optionsHi":["ताकि सुरक्षा जाँच छोड़कर उपयोगकर्ता प्रोग्राम तेज़ चल सकें","ताकि एक CPU पर एक साथ दो ऑपरेटिंग सिस्टम चल सकें","ताकि उपयोगकर्ता प्रोग्राम विशेषाधिकार वाले निर्देश सीधे न चला सकें","ताकि पहला कर्नेल विफल होने पर कर्नेल की बैकअप प्रति रहे"],"explanationHi":"I/O या मेमोरी सुरक्षा बदलने जैसे निर्देश केवल कर्नेल मोड में चलते हैं, इसलिए दोषपूर्ण या दुर्भावनापूर्ण प्रोग्राम को सिस्टम कॉल के माध्यम से OS से माँगना पड़ता है।"},
  {"id":"comp-awareness-324","question":"Which scheduler swaps partly executed processes out of memory to the disk, and later back in, to adjust the degree of multiprogramming?","options":["Long-term scheduler","Medium-term scheduler","Short-term scheduler","Dispatcher"],"answer":1,"explanation":"The medium-term scheduler handles swapping. The long-term scheduler admits new jobs, and the short-term scheduler (with the dispatcher) picks the next ready process for the CPU.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"कौन-सा शेड्यूलर मल्टीप्रोग्रामिंग की मात्रा समायोजित करने के लिए आंशिक रूप से निष्पादित प्रक्रियाओं को मेमोरी से डिस्क पर और बाद में वापस स्वैप करता है?","optionsHi":["लॉन्ग-टर्म शेड्यूलर","मीडियम-टर्म शेड्यूलर","शॉर्ट-टर्म शेड्यूलर","डिस्पैचर"],"explanationHi":"मीडियम-टर्म शेड्यूलर स्वैपिंग संभालता है। लॉन्ग-टर्म शेड्यूलर नए कार्य प्रवेश देता है, और शॉर्ट-टर्म शेड्यूलर (डिस्पैचर के साथ) CPU के लिए अगली रेडी प्रक्रिया चुनता है।"},
  {"id":"comp-awareness-325","question":"Defragmenting a hard disk drive usually speeds up file access because it:","options":["Moves each file's blocks next to one another, cutting head movement","Compresses files so that fewer sectors have to be read","Removes viruses that hide in the unused sectors of the disk","Copies frequently used programs permanently into the RAM"],"answer":0,"explanation":"Scattered fragments force many seeks; placing a file's blocks contiguously reduces them. Defragmenting neither compresses data nor scans for viruses.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"हार्ड डिस्क ड्राइव को डीफ़्रैग्मेंट करने से फ़ाइल एक्सेस प्रायः तेज़ क्यों हो जाता है?","optionsHi":["यह प्रत्येक फ़ाइल के ब्लॉकों को एक-दूसरे के पास ले आता है, जिससे हेड की गति घटती है","यह फ़ाइलों को संपीड़ित करता है ताकि कम सेक्टर पढ़ने पड़ें","यह डिस्क के अप्रयुक्त सेक्टरों में छिपे वायरस हटाता है","यह बार-बार प्रयुक्त प्रोग्रामों को स्थायी रूप से RAM में कॉपी करता है"],"explanationHi":"बिखरे खंड कई सीक करवाते हैं; फ़ाइल के ब्लॉकों को सटाकर रखने से वे घटते हैं। डीफ़्रैग्मेंटेशन न डेटा संपीड़ित करता है, न वायरस की जाँच।"},
  {"id":"comp-awareness-326","question":"Match the OSI layer with the name of its data unit: 1. Transport 2. Network 3. Data link 4. Physical; a. Frame b. Bits c. Segment d. Packet","options":["1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":1,"explanation":"Transport layer data units are segments (datagrams for UDP), network layer units are packets, data link units are frames, and the physical layer carries bits.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"OSI परत का उसकी डेटा इकाई के नाम से मिलान कीजिए: 1. ट्रांसपोर्ट 2. नेटवर्क 3. डेटा लिंक 4. भौतिक; a. फ़्रेम b. बिट c. सेगमेंट d. पैकेट","optionsHi":["1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-c, 2-d, 3-b, 4-a"],"explanationHi":"ट्रांसपोर्ट परत की डेटा इकाइयाँ सेगमेंट हैं (UDP के लिए डेटाग्राम), नेटवर्क परत की इकाइयाँ पैकेट हैं, डेटा लिंक की इकाइयाँ फ़्रेम हैं, और भौतिक परत बिट ले जाती है।"},
  {"id":"comp-awareness-327","question":"The four-layer TCP/IP model has a single Application layer. Which OSI layers does it combine?","options":["Application, Presentation and Session","Application and Presentation only","Application, Session and Transport","Presentation, Session and Network"],"answer":0,"explanation":"TCP/IP's Application layer covers OSI layers 7, 6 and 5; Transport maps to OSI Transport, Internet to Network, and Network Access to Data Link plus Physical.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"चार-परत वाले TCP/IP मॉडल में एक ही एप्लिकेशन परत है। वह OSI की किन परतों को जोड़ती है?","optionsHi":["एप्लिकेशन, प्रेजेंटेशन और सेशन","केवल एप्लिकेशन और प्रेजेंटेशन","एप्लिकेशन, सेशन और ट्रांसपोर्ट","प्रेजेंटेशन, सेशन और नेटवर्क"],"explanationHi":"TCP/IP की एप्लिकेशन परत OSI की परत 7, 6 और 5 को समेटती है; ट्रांसपोर्ट OSI ट्रांसपोर्ट से, इंटरनेट नेटवर्क से, और नेटवर्क एक्सेस डेटा लिंक तथा भौतिक से मेल खाते हैं।"},
  {"id":"comp-awareness-328","question":"A computer knows the IP address of another machine on the same LAN but needs that machine's MAC address to send it a frame. Which protocol does it use?","options":["DNS","DHCP","ARP","RARP"],"answer":2,"explanation":"ARP broadcasts 'who has this IP?' and the owner replies with its MAC address. RARP works in the opposite direction, and DNS maps names to IP addresses.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS SO IT Officer","questionHi":"एक कंप्यूटर उसी LAN की किसी अन्य मशीन का IP पता जानता है, पर उसे फ़्रेम भेजने के लिए उस मशीन का MAC पता चाहिए। वह किस प्रोटोकॉल का प्रयोग करता है?","optionsHi":["DNS","DHCP","ARP","RARP"],"explanationHi":"ARP ‘इस IP का स्वामी कौन है?’ प्रसारित करता है और स्वामी अपने MAC पते से उत्तर देता है। RARP उलटी दिशा में काम करता है, और DNS नामों को IP पतों से जोड़ता है।"},
  {"id":"comp-awareness-329","question":"A home router lets ten devices with private IP addresses share a single public IP address on the internet. Which technique makes this possible?","options":["Dynamic Host Configuration Protocol","Network Address Translation","Address Resolution Protocol","Domain Name System"],"answer":1,"explanation":"NAT (port address translation) rewrites private source addresses to the one public address and uses port numbers to send replies back to the right device. DHCP only hands out the private addresses.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"एक घरेलू राउटर निजी IP पते वाले दस उपकरणों को इंटरनेट पर एक ही सार्वजनिक IP पता साझा करने देता है। यह किस तकनीक से संभव होता है?","optionsHi":["डायनेमिक होस्ट कॉन्फ़िगरेशन प्रोटोकॉल","नेटवर्क एड्रेस ट्रांसलेशन","एड्रेस रेज़ोल्यूशन प्रोटोकॉल","डोमेन नेम सिस्टम"],"explanationHi":"NAT (पोर्ट एड्रेस ट्रांसलेशन) निजी स्रोत पतों को एक सार्वजनिक पते में बदलता है और पोर्ट संख्याओं से उत्तर सही उपकरण तक भेजता है। DHCP केवल निजी पते बाँटता है।"},
  {"id":"comp-awareness-330","question":"The class C network 200.10.5.0 must be split into at least 6 subnets, each as large as possible. Which mask is used, and how many usable hosts does each subnet get?","options":["255.255.255.192 with 62 hosts each","255.255.255.240 with 14 hosts each","255.255.255.224 with 32 hosts each","255.255.255.224 with 30 hosts each"],"answer":3,"explanation":"6 subnets need 3 borrowed bits (2³ = 8), giving /27 = 255.255.255.224. That leaves 5 host bits: 2⁵ − 2 = 30 usable hosts; 32 forgets the network and broadcast addresses.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"क्लास C नेटवर्क 200.10.5.0 को कम से कम 6 सबनेट में बाँटना है, प्रत्येक यथासंभव बड़ा। कौन-सा मास्क प्रयोग होगा, और प्रत्येक सबनेट को कितने प्रयोग-योग्य होस्ट मिलेंगे?","optionsHi":["255.255.255.192, प्रत्येक में 62 होस्ट","255.255.255.240, प्रत्येक में 14 होस्ट","255.255.255.224, प्रत्येक में 32 होस्ट","255.255.255.224, प्रत्येक में 30 होस्ट"],"explanationHi":"6 सबनेट के लिए 3 उधार बिट चाहिए (2³ = 8), जिससे /27 = 255.255.255.224 मिलता है। इससे 5 होस्ट बिट बचते हैं: 2⁵ − 2 = 30 प्रयोग-योग्य होस्ट; 32 नेटवर्क और ब्रॉडकास्ट पते भूल जाता है।"},
  {"id":"comp-awareness-331","question":"How many usable host addresses does a /20 IPv4 network provide?","options":["4096","4094","2046","1022"],"answer":1,"explanation":"A /20 leaves 32 − 20 = 12 host bits: 2¹² = 4096 addresses, minus the network and broadcast addresses = 4094.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"/20 IPv4 नेटवर्क कितने प्रयोग-योग्य होस्ट पते देता है?","optionsHi":["4096","4094","2046","1022"],"explanationHi":"/20 में 32 − 20 = 12 होस्ट बिट बचते हैं: 2¹² = 4096 पते, घटाएँ नेटवर्क और ब्रॉडकास्ट पते = 4094।"},
  {"id":"comp-awareness-332","question":"Which single CIDR block covers exactly the four networks 192.168.8.0/24, 192.168.9.0/24, 192.168.10.0/24 and 192.168.11.0/24?","options":["192.168.8.0/21","192.168.0.0/22","192.168.8.0/22","192.168.8.0/23"],"answer":2,"explanation":"Third octets 8–11 are 000010xx, sharing their first 6 bits, so the prefix is 16 + 6 = 22 bits: 192.168.8.0/22. A /21 would also take in 12–15, and a /23 covers only two of them.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"कौन-सा एकल CIDR ब्लॉक ठीक चार नेटवर्कों 192.168.8.0/24, 192.168.9.0/24, 192.168.10.0/24 और 192.168.11.0/24 को कवर करता है?","optionsHi":["192.168.8.0/21","192.168.0.0/22","192.168.8.0/22","192.168.8.0/23"],"explanationHi":"तीसरे ऑक्टेट 8–11 का रूप 000010xx है, जिनके पहले 6 बिट समान हैं, इसलिए प्रीफ़िक्स 16 + 6 = 22 बिट है: 192.168.8.0/22। /21 में 12–15 भी आ जाते, और /23 उनमें से केवल दो को कवर करता है।"},
  {"id":"comp-awareness-333","question":"Which of these hosts is on the SAME subnet as 172.16.5.200/26?","options":["172.16.5.190","172.16.5.250","172.16.5.130","172.16.6.200"],"answer":1,"explanation":"A /26 splits the last octet into blocks of 64: 0–63, 64–127, 128–191 and 192–255. 200 and 250 both fall in 192–255; 190 and 130 are in 128–191, and 172.16.6.x is a different network.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"इनमें से कौन-सा होस्ट 172.16.5.200/26 के समान सबनेट पर है?","optionsHi":["172.16.5.190","172.16.5.250","172.16.5.130","172.16.6.200"],"explanationHi":"/26 अंतिम ऑक्टेट को 64 के ब्लॉकों में बाँटता है: 0–63, 64–127, 128–191 और 192–255। 200 और 250 दोनों 192–255 में आते हैं; 190 और 130 128–191 में हैं, और 172.16.6.x भिन्न नेटवर्क है।"},
  {"id":"comp-awareness-334","question":"The IPv4 address 224.0.0.5 belongs to which class, and what is that class used for?","options":["Class C – unicast hosts on small networks","Class E – reserved for experimental use","Class B – unicast hosts on medium networks","Class D – multicast to a group of hosts"],"answer":3,"explanation":"First octets 224–239 form class D, used for multicast groups. Class C runs from 192 to 223 and class E from 240 to 255.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"IPv4 पता 224.0.0.5 किस क्लास का है, और वह क्लास किसके लिए प्रयोग होती है?","optionsHi":["क्लास C – छोटे नेटवर्कों पर यूनिकास्ट होस्ट","क्लास E – प्रायोगिक उपयोग के लिए आरक्षित","क्लास B – मध्यम नेटवर्कों पर यूनिकास्ट होस्ट","क्लास D – होस्टों के समूह को मल्टीकास्ट"],"explanationHi":"पहले ऑक्टेट 224–239 क्लास D बनाते हैं, जो मल्टीकास्ट समूहों के लिए है। क्लास C 192 से 223 तक और क्लास E 240 से 255 तक चलती है।"},
  {"id":"comp-awareness-335","question":"A router has three interfaces, and each is connected to a separate switch serving 8 PCs, with no VLANs. How many broadcast domains are there?","options":["1","24","3","27"],"answer":2,"explanation":"Routers do not forward broadcasts, so each router interface marks off one broadcast domain: 3. Switches split collision domains, not broadcast domains.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"एक राउटर के तीन इंटरफ़ेस हैं, और प्रत्येक 8 PC को सेवा देने वाले अलग स्विच से जुड़ा है, कोई VLAN नहीं। कितने ब्रॉडकास्ट डोमेन हैं?","optionsHi":["1","24","3","27"],"explanationHi":"राउटर ब्रॉडकास्ट आगे नहीं भेजते, इसलिए प्रत्येक राउटर इंटरफ़ेस एक ब्रॉडकास्ट डोमेन की सीमा बनाता है: 3। स्विच कोलिज़न डोमेन बाँटते हैं, ब्रॉडकास्ट डोमेन नहीं।"},
  {"id":"comp-awareness-336","question":"Wired Ethernet uses CSMA/CD, but Wi-Fi uses CSMA/CA. What is the main reason?","options":["A wireless station cannot reliably sense a collision while it is transmitting","Radio signals never collide, so wireless stations only need to avoid queues","Wi-Fi passes a token between stations, so collision detection is not needed","Collision detection works only on fibre, which Wi-Fi access points do not use"],"answer":0,"explanation":"A radio's own strong transmission drowns out weaker signals, and hidden stations may be out of range, so collisions cannot be detected; Wi-Fi tries to avoid them with backoff and acknowledgements instead.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"वायर्ड ईथरनेट CSMA/CD प्रयोग करता है, पर Wi-Fi CSMA/CA। मुख्य कारण क्या है?","optionsHi":["वायरलेस स्टेशन संचारण करते समय टक्कर को विश्वसनीय रूप से भाँप नहीं सकता","रेडियो सिग्नल कभी नहीं टकराते, इसलिए वायरलेस स्टेशनों को केवल कतारों से बचना होता है","Wi-Fi स्टेशनों के बीच टोकन पास करता है, इसलिए टक्कर पहचान की आवश्यकता नहीं","टक्कर पहचान केवल फ़ाइबर पर काम करती है, जिसे Wi-Fi एक्सेस पॉइंट प्रयोग नहीं करते"],"explanationHi":"रेडियो का अपना प्रबल संचारण कमज़ोर सिग्नलों को दबा देता है, और छिपे स्टेशन सीमा से बाहर हो सकते हैं, इसलिए टक्कर पहचानी नहीं जा सकती; Wi-Fi उन्हें बैकऑफ़ और पावती से टालने का प्रयास करता है।"},
  {"id":"comp-awareness-337","question":"A file of 10⁶ bytes is sent over a 2 Mbps link whose propagation delay is 20 ms. Ignoring other overheads, how long after sending starts does the last bit arrive?","options":["0.52 s","4.2 s","4 s","4.02 s"],"answer":3,"explanation":"Transmission time = 8 × 10⁶ bits ÷ 2 × 10⁶ bps = 4 s; the last bit then needs 20 ms to travel, so 4.02 s. Using bytes instead of bits gives 0.52 s.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"10⁶ बाइट की एक फ़ाइल 2 Mbps लिंक पर भेजी जाती है जिसका संचरण विलंब 20 ms है। अन्य अतिरिक्त भार की उपेक्षा करने पर, भेजना शुरू होने के कितने समय बाद अंतिम बिट पहुँचता है?","optionsHi":["0.52 s","4.2 s","4 s","4.02 s"],"explanationHi":"संचारण समय = 8 × 10⁶ बिट ÷ 2 × 10⁶ bps = 4 s; फिर अंतिम बिट को यात्रा में 20 ms लगते हैं, इसलिए 4.02 s। बिट के बजाय बाइट लेने पर 0.52 s आता है।"},
  {"id":"comp-awareness-338","question":"How does single-mode optical fibre differ from multimode fibre?","options":["It has a wider core and carries many light paths, so it suits short links","It carries electrical signals instead of light, so it resists bending","It has a narrower core and carries one light path, so it suits long links","It works only with LEDs, which makes it cheaper over long distances"],"answer":2,"explanation":"Single-mode fibre's very thin core allows a single light mode, avoiding modal dispersion, so it carries signals far, usually with lasers. Multimode has a wider core and is used for short runs.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"सिंगल-मोड ऑप्टिकल फ़ाइबर मल्टीमोड फ़ाइबर से कैसे भिन्न है?","optionsHi":["इसका कोर चौड़ा होता है और यह कई प्रकाश-पथ ले जाता है, इसलिए छोटे लिंकों के लिए उपयुक्त है","यह प्रकाश के बजाय विद्युत सिग्नल ले जाता है, इसलिए मोड़ने पर टिकाऊ है","इसका कोर संकरा होता है और यह एक प्रकाश-पथ ले जाता है, इसलिए लंबे लिंकों के लिए उपयुक्त है","यह केवल LED के साथ काम करता है, जिससे लंबी दूरी पर सस्ता पड़ता है"],"explanationHi":"सिंगल-मोड फ़ाइबर का बहुत पतला कोर एक ही प्रकाश मोड की अनुमति देता है, जिससे मोडल प्रकीर्णन नहीं होता, इसलिए वह सिग्नल दूर तक ले जाता है, आमतौर पर लेज़र के साथ। मल्टीमोड का कोर चौड़ा होता है और छोटी दूरी में प्रयुक्त होता है।"},
  {"id":"comp-awareness-339","question":"Why are the pairs of wires in a twisted-pair cable twisted around each other?","options":["To make the cable stronger so it can be pulled through walls","To reduce electromagnetic interference and crosstalk between pairs","To let the same pair carry light as well as electrical signals","To increase the resistance of the wire and save power"],"answer":1,"explanation":"Twisting makes noise induce nearly equal and opposite effects in the two wires, which cancel at the receiver, and it limits crosstalk from neighbouring pairs.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"ट्विस्टेड-पेयर केबल में तारों के जोड़े एक-दूसरे पर क्यों लपेटे जाते हैं?","optionsHi":["केबल को मज़बूत बनाने के लिए ताकि उसे दीवारों से खींचा जा सके","विद्युत-चुंबकीय व्यतिकरण और जोड़ों के बीच क्रॉसटॉक घटाने के लिए","ताकि वही जोड़ा विद्युत सिग्नल के साथ प्रकाश भी ले जा सके","तार का प्रतिरोध बढ़ाकर बिजली बचाने के लिए"],"explanationHi":"लपेटने से शोर दोनों तारों में लगभग बराबर और विपरीत प्रभाव उत्पन्न करता है, जो रिसीवर पर कट जाते हैं, और यह पड़ोसी जोड़ों से क्रॉसटॉक को सीमित करता है।"},
  {"id":"comp-awareness-340","question":"Match the protocol with its default port: 1. SSH 2. Telnet 3. POP3 4. IMAP; a. 110 b. 143 c. 23 d. 22","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-a, 3-c, 4-b"],"answer":2,"explanation":"SSH uses 22 and the older unencrypted Telnet uses 23; POP3 uses 110 and IMAP uses 143.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"प्रोटोकॉल का उसके डिफ़ॉल्ट पोर्ट से मिलान कीजिए: 1. SSH 2. Telnet 3. POP3 4. IMAP; a. 110 b. 143 c. 23 d. 22","optionsHi":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-a, 3-c, 4-b"],"explanationHi":"SSH 22 और पुराना अनएन्क्रिप्टेड Telnet 23 प्रयोग करता है; POP3 110 और IMAP 143 प्रयोग करता है।"},
  {"id":"comp-awareness-341","question":"A manager reads e-mail on a phone and a laptop and wants both to show the same folders and the same read/unread status. Which protocol should the mail client use to retrieve mail?","options":["POP3","SMTP","IMAP","MIME"],"answer":2,"explanation":"IMAP keeps mail and folders on the server and syncs status to every device. POP3 typically downloads and removes mail, SMTP only sends, and MIME is a message format.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"एक प्रबंधक फ़ोन और लैपटॉप दोनों पर ई-मेल पढ़ता है और चाहता है कि दोनों में वही फ़ोल्डर और वही पढ़ा/अपठित स्थिति दिखे। मेल क्लाइंट को मेल प्राप्त करने के लिए कौन-सा प्रोटोकॉल प्रयोग करना चाहिए?","optionsHi":["POP3","SMTP","IMAP","MIME"],"explanationHi":"IMAP मेल और फ़ोल्डर सर्वर पर रखता है और स्थिति को हर उपकरण में सिंक करता है। POP3 सामान्यतः मेल डाउनलोड करके हटा देता है, SMTP केवल भेजता है, और MIME संदेश का प्रारूप है।"},
  {"id":"comp-awareness-342","question":"Which standard lets an e-mail carry attachments such as images, PDFs and text in non-English scripts?","options":["MIME","SNMP","POP3","SMTP"],"answer":0,"explanation":"Multipurpose Internet Mail Extensions define content types and encodings so binary files and non-ASCII text travel in mail. SMTP only transports the message.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"कौन-सा मानक ई-मेल को चित्र, PDF और गैर-अंग्रेज़ी लिपियों के पाठ जैसे अनुलग्नक ले जाने देता है?","optionsHi":["MIME","SNMP","POP3","SMTP"],"explanationHi":"मल्टीपर्पस इंटरनेट मेल एक्सटेंशन सामग्री-प्रकार और एन्कोडिंग परिभाषित करते हैं ताकि बाइनरी फ़ाइलें और गैर-ASCII पाठ मेल में जा सकें। SMTP केवल संदेश का परिवहन करता है।"},
  {"id":"comp-awareness-343","question":"In the URL https://www.example.co.in:8080/loans/apply.html?id=7, what are the port number used and the top-level domain?","options":["443 and .co.in","8080 and .co","80 and .in","8080 and .in"],"answer":3,"explanation":"An explicit ':8080' overrides HTTPS's default port 443. The top-level domain is the last label, .in; .co.in is a second-level domain under it.","difficulty":"very-hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"URL https://www.example.co.in:8080/loans/apply.html?id=7 में प्रयुक्त पोर्ट संख्या और टॉप-लेवल डोमेन क्या हैं?","optionsHi":["443 और .co.in","8080 और .co","80 और .in","8080 और .in"],"explanationHi":"स्पष्ट ‘:8080’ HTTPS के डिफ़ॉल्ट पोर्ट 443 को अधिभावी करता है। टॉप-लेवल डोमेन अंतिम लेबल .in है; .co.in उसके अंतर्गत द्वितीय-स्तरीय डोमेन है।"},
  {"id":"comp-awareness-344","question":"A browser shows 'HTTP 404'. What does this status code tell the user?","options":["The server could not be reached at all","The server was reached but the requested page was not found","The user is not allowed to view the requested page","The server crashed while it was handling the request"],"answer":1,"explanation":"4xx codes are client-side errors; 404 means the server answered but has nothing at that path. Forbidden is 403, a server failure is 5xx, and an unreachable server returns no HTTP code.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"ब्राउज़र ‘HTTP 404’ दिखाता है। यह स्थिति कोड उपयोगकर्ता को क्या बताता है?","optionsHi":["सर्वर तक पहुँचा ही नहीं जा सका","सर्वर तक पहुँचा गया पर अनुरोधित पृष्ठ नहीं मिला","उपयोगकर्ता को अनुरोधित पृष्ठ देखने की अनुमति नहीं है","अनुरोध संभालते समय सर्वर क्रैश हो गया"],"explanationHi":"4xx कोड क्लाइंट-पक्ष की त्रुटियाँ हैं; 404 का अर्थ है कि सर्वर ने उत्तर दिया पर उस पथ पर कुछ नहीं है। निषिद्ध 403 है, सर्वर की विफलता 5xx है, और पहुँच से बाहर सर्वर कोई HTTP कोड नहीं लौटाता।"},
  {"id":"comp-awareness-345","question":"Which DNS record type tells other mail servers which server accepts e-mail for a domain?","options":["A","CNAME","MX","PTR"],"answer":2,"explanation":"An MX (mail exchanger) record names a domain's mail server. A maps a name to an IPv4 address, CNAME makes an alias, and PTR does reverse lookups.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"कौन-सा DNS रिकॉर्ड प्रकार अन्य मेल सर्वरों को बताता है कि किसी डोमेन के लिए ई-मेल कौन-सा सर्वर स्वीकार करता है?","optionsHi":["A","CNAME","MX","PTR"],"explanationHi":"MX (मेल एक्सचेंजर) रिकॉर्ड किसी डोमेन के मेल सर्वर का नाम देता है। A नाम को IPv4 पते से जोड़ता है, CNAME उपनाम बनाता है, और PTR प्रतिलोम खोज करता है।"},
  {"id":"comp-awareness-346","question":"How does packet switching differ from circuit switching?","options":["A fixed path is reserved for the whole call before any data is sent","Data is sent in packets that may take different routes, with no path reserved","Every packet is sent to all nodes, and each node keeps only its own data","Data can be sent only when the line is idle for the entire session"],"answer":1,"explanation":"Packet switching shares links on demand and routes each packet independently, while circuit switching (like the old telephone network) reserves a dedicated path first.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"पैकेट स्विचिंग सर्किट स्विचिंग से कैसे भिन्न है?","optionsHi":["कोई भी डेटा भेजने से पहले पूरी कॉल के लिए एक निश्चित पथ आरक्षित कर लिया जाता है","डेटा पैकेटों में भेजा जाता है जो भिन्न मार्ग ले सकते हैं, कोई पथ आरक्षित नहीं होता","प्रत्येक पैकेट सभी नोडों को भेजा जाता है, और प्रत्येक नोड केवल अपना डेटा रखता है","डेटा केवल तभी भेजा जा सकता है जब पूरे सत्र में लाइन निष्क्रिय हो"],"explanationHi":"पैकेट स्विचिंग लिंकों को माँग पर साझा करती है और प्रत्येक पैकेट को स्वतंत्र रूप से रूट करती है, जबकि सर्किट स्विचिंग (पुराने टेलीफ़ोन नेटवर्क की तरह) पहले एक समर्पित पथ आरक्षित करती है।"},
  {"id":"comp-awareness-347","question":"Live video calls usually send their media over UDP rather than TCP. Why?","options":["UDP encrypts the stream, while TCP sends it as plain text","UDP guarantees delivery in order, which video needs","Retransmitting late packets is useless, and UDP avoids that delay","TCP cannot carry more than one stream on a connection"],"answer":2,"explanation":"A resent video frame arrives too late to play, and TCP's retransmission and in-order delivery add delay. UDP itself gives no ordering or delivery guarantee and no encryption.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"लाइव वीडियो कॉल आमतौर पर अपना मीडिया TCP के बजाय UDP पर भेजती हैं। क्यों?","optionsHi":["UDP स्ट्रीम को एन्क्रिप्ट करता है, जबकि TCP उसे सादे पाठ में भेजता है","UDP क्रम से डिलीवरी की गारंटी देता है, जो वीडियो को चाहिए","देर से आए पैकेटों को पुनः भेजना बेकार है, और UDP उस विलंब से बचाता है","TCP एक कनेक्शन पर एक से अधिक स्ट्रीम नहीं ले जा सकता"],"explanationHi":"दोबारा भेजा गया वीडियो फ़्रेम चलाने के लिए बहुत देर से पहुँचता है, और TCP का पुनः प्रेषण तथा क्रमबद्ध डिलीवरी विलंब जोड़ते हैं। UDP स्वयं क्रम या डिलीवरी की गारंटी और एन्क्रिप्शन नहीं देता।"},
  {"id":"comp-awareness-348","question":"What does the Time to Live (TTL) field in an IPv4 packet header do?","options":["Sets the clock time at which the packet must be delivered","Is reduced by one at each router; the packet is dropped at zero","Counts how many times the packet has been retransmitted by TCP","Tells the receiver how long to keep the packet in its cache"],"answer":1,"explanation":"Each router decrements TTL and discards the packet when it reaches 0, so packets caught in routing loops cannot circulate forever; traceroute relies on this.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"IPv4 पैकेट हेडर में टाइम टू लिव (TTL) क्षेत्र क्या करता है?","optionsHi":["वह घड़ी-समय तय करता है जब तक पैकेट पहुँचाना है","प्रत्येक राउटर पर एक से घटता है; शून्य होने पर पैकेट गिरा दिया जाता है","गिनता है कि TCP ने पैकेट को कितनी बार पुनः भेजा है","रिसीवर को बताता है कि पैकेट को अपने कैश में कितनी देर रखना है"],"explanationHi":"प्रत्येक राउटर TTL घटाता है और 0 पर पहुँचने पर पैकेट छोड़ देता है, ताकि रूटिंग लूप में फँसे पैकेट सदा चक्कर न लगाते रहें; traceroute इसी पर निर्भर है।"},
  {"id":"comp-awareness-349","question":"Tap-to-pay contactless cards and phones exchange data only within a few centimetres of the reader. Which technology do they use?","options":["Bluetooth","Infrared (IrDA)","Wi-Fi Direct","Near Field Communication"],"answer":3,"explanation":"NFC works over about 4 cm, which suits payments because accidental reading from far away is unlikely. Bluetooth and Wi-Fi Direct reach metres.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"टैप-टू-पे कॉन्टैक्टलेस कार्ड और फ़ोन रीडर से केवल कुछ सेंटीमीटर के भीतर डेटा का आदान-प्रदान करते हैं। वे कौन-सी तकनीक प्रयोग करते हैं?","optionsHi":["ब्लूटूथ","इन्फ्रारेड (IrDA)","Wi-Fi डायरेक्ट","नियर फ़ील्ड कम्युनिकेशन"],"explanationHi":"NFC लगभग 4 cm पर काम करता है, जो भुगतान के लिए उपयुक्त है क्योंकि दूर से आकस्मिक पठन की संभावना कम है। ब्लूटूथ और Wi-Fi डायरेक्ट मीटरों तक पहुँचते हैं।"},
  {"id":"comp-awareness-350","question":"How long is an IPv6 address, and how many times may the shorthand '::' (a run of zero groups) appear in one written address?","options":["128 bits; it may appear only once","128 bits; it may appear any number of times","64 bits; it may appear only once","256 bits; it may appear at most twice"],"answer":0,"explanation":"IPv6 addresses are 128 bits (8 groups of 16). '::' can be used only once, because with two of them the reader could not tell how many zero groups each one hides.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"IPv6 पता कितना लंबा होता है, और शॉर्टहैंड ‘::’ (शून्य समूहों की शृंखला) एक लिखे गए पते में कितनी बार आ सकता है?","optionsHi":["128 बिट; यह केवल एक बार आ सकता है","128 बिट; यह कितनी भी बार आ सकता है","64 बिट; यह केवल एक बार आ सकता है","256 बिट; यह अधिकतम दो बार आ सकता है"],"explanationHi":"IPv6 पते 128 बिट के होते हैं (16 के 8 समूह)। ‘::’ केवल एक बार प्रयोग हो सकता है, क्योंकि दो होने पर पाठक यह नहीं बता पाएगा कि प्रत्येक कितने शून्य समूह छिपाता है।"},
  {"id":"comp-awareness-351","question":"Asha wants to send Ravi a message that only Ravi can read AND that Ravi can prove came from her. Which keys does she use?","options":["Her private key to sign and Ravi's public key to encrypt","Her public key to sign and Ravi's private key to encrypt","Ravi's public key to sign and her private key to encrypt","Her private key both to sign and to encrypt the message"],"answer":0,"explanation":"Signing uses the sender's private key (anyone can verify with her public key); confidentiality needs the receiver's public key, so only his private key can decrypt. Encrypting with her private key hides nothing, since her public key is public.","difficulty":"very-hard","source":"IBPS SO IT Officer · IBPS PO Mains","questionHi":"आशा रवि को ऐसा संदेश भेजना चाहती है जिसे केवल रवि पढ़ सके और जिसे रवि सिद्ध कर सके कि वह आशा से आया है। वह कौन-सी कुंजियाँ प्रयोग करती है?","optionsHi":["हस्ताक्षर के लिए अपनी निजी कुंजी और एन्क्रिप्ट करने के लिए रवि की सार्वजनिक कुंजी","हस्ताक्षर के लिए अपनी सार्वजनिक कुंजी और एन्क्रिप्ट करने के लिए रवि की निजी कुंजी","हस्ताक्षर के लिए रवि की सार्वजनिक कुंजी और एन्क्रिप्ट करने के लिए अपनी निजी कुंजी","संदेश पर हस्ताक्षर और उसे एन्क्रिप्ट करने, दोनों के लिए अपनी निजी कुंजी"],"explanationHi":"हस्ताक्षर प्रेषक की निजी कुंजी से होता है (कोई भी उसकी सार्वजनिक कुंजी से सत्यापित कर सकता है); गोपनीयता के लिए प्राप्तकर्ता की सार्वजनिक कुंजी चाहिए, ताकि केवल उसकी निजी कुंजी ही डिक्रिप्ट कर सके। अपनी निजी कुंजी से एन्क्रिप्ट करने से कुछ छिपता नहीं, क्योंकि उसकी सार्वजनिक कुंजी सार्वजनिक है।"},
  {"id":"comp-awareness-352","question":"Which of these is an ASYMMETRIC (public-key) encryption algorithm?","options":["AES","DES","RSA","Triple DES"],"answer":2,"explanation":"RSA uses a public/private key pair. AES, DES and Triple DES are symmetric ciphers that use one shared secret key.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"इनमें से कौन-सा असममित (सार्वजनिक-कुंजी) एन्क्रिप्शन एल्गोरिदम है?","optionsHi":["AES","DES","RSA","ट्रिपल DES"],"explanationHi":"RSA सार्वजनिक/निजी कुंजी-युग्म का प्रयोग करता है। AES, DES और ट्रिपल DES सममित सिफ़र हैं जो एक साझा गुप्त कुंजी प्रयोग करते हैं।"},
  {"id":"comp-awareness-353","question":"Which property of a cryptographic hash function means it is practically impossible to find two different inputs that give the same hash value?","options":["Pre-image resistance","Collision resistance","Avalanche effect","Key exchange"],"answer":1,"explanation":"Collision resistance is about finding any two inputs with equal hashes. Pre-image resistance means you cannot work back from a hash to an input, and the avalanche effect is a small input change flipping many output bits.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"क्रिप्टोग्राफ़िक हैश फ़ंक्शन का कौन-सा गुण यह दर्शाता है कि समान हैश मान देने वाले दो भिन्न इनपुट खोजना व्यावहारिक रूप से असंभव है?","optionsHi":["प्री-इमेज प्रतिरोध","टक्कर प्रतिरोध (कोलिज़न रेज़िस्टेंस)","हिमस्खलन प्रभाव (एवलांच इफ़ेक्ट)","कुंजी विनिमय"],"explanationHi":"कोलिज़न रेज़िस्टेंस का संबंध समान हैश वाले किन्हीं दो इनपुट को खोजने से है। प्री-इमेज प्रतिरोध का अर्थ है कि हैश से लौटकर इनपुट तक नहीं पहुँचा जा सकता, और एवलांच इफ़ेक्ट इनपुट में छोटे परिवर्तन से आउटपुट के कई बिट पलटना है।"},
  {"id":"comp-awareness-354","question":"A distributed denial-of-service attack keeps a bank's website offline for hours. Which goal of the CIA security triad has mainly been attacked?","options":["Confidentiality","Integrity","Authentication","Availability"],"answer":3,"explanation":"DDoS floods stop legitimate users from reaching the service, an attack on availability; no data need be read (confidentiality) or altered (integrity). Authentication is not part of the triad.","difficulty":"moderate","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक वितरित सेवा-अवरोध (DDoS) हमला बैंक की वेबसाइट को घंटों तक ऑफ़लाइन रखता है। CIA सुरक्षा त्रिकोण के किस लक्ष्य पर मुख्यतः हमला हुआ है?","optionsHi":["गोपनीयता (कॉन्फ़िडेंशियलिटी)","अखंडता (इंटेग्रिटी)","प्रमाणीकरण (ऑथेंटिकेशन)","उपलब्धता (अवेलेबिलिटी)"],"explanationHi":"DDoS बाढ़ वैध उपयोगकर्ताओं को सेवा तक पहुँचने से रोकती है, जो उपलब्धता पर हमला है; किसी डेटा को पढ़ने (गोपनीयता) या बदलने (अखंडता) की आवश्यकता नहीं। प्रमाणीकरण त्रिकोण का भाग नहीं है।"},
  {"id":"comp-awareness-355","question":"Which login method is genuine two-factor authentication?","options":["A password plus an answer to a secret security question","A fingerprint scan plus a face scan from the same phone","A password plus a one-time code sent to the phone","A PIN plus the user's date of birth typed on the next page"],"answer":2,"explanation":"Two factors must come from different categories: something you know (password) and something you have (the phone receiving the OTP). Two knowledge items or two biometrics are still a single factor type.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"कौन-सी लॉगिन विधि वास्तविक टू-फ़ैक्टर ऑथेंटिकेशन है?","optionsHi":["पासवर्ड और किसी गुप्त सुरक्षा-प्रश्न का उत्तर","एक ही फ़ोन से फ़िंगरप्रिंट स्कैन और चेहरे का स्कैन","पासवर्ड और फ़ोन पर भेजा गया वन-टाइम कोड","PIN और अगले पृष्ठ पर टाइप की गई उपयोगकर्ता की जन्मतिथि"],"explanationHi":"दो कारक भिन्न श्रेणियों से होने चाहिए: कुछ जो आप जानते हैं (पासवर्ड) और कुछ जो आपके पास है (OTP पाने वाला फ़ोन)। दो ज्ञान-वस्तुएँ या दो बायोमेट्रिक अब भी एक ही प्रकार का कारक हैं।"},
  {"id":"comp-awareness-356","question":"Match the attack with its description: 1. Vishing 2. Smishing 3. Spear phishing 4. Whaling; a. Fraud carried out through SMS texts b. Fraud aimed at top executives c. Fraud by voice telephone calls d. Fraud tailored to one particular person or group","options":["1-c, 2-a, 3-d, 4-b","1-a, 2-c, 3-d, 4-b","1-c, 2-a, 3-b, 4-d","1-c, 2-d, 3-a, 4-b"],"answer":0,"explanation":"Vishing is voice phishing, smishing uses SMS, spear phishing is aimed at a chosen target, and whaling is spear phishing aimed at senior executives.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"हमले का उसके विवरण से मिलान कीजिए: 1. विशिंग 2. स्मिशिंग 3. स्पीयर फ़िशिंग 4. व्हेलिंग; a. SMS पाठ संदेशों के माध्यम से की गई धोखाधड़ी b. शीर्ष अधिकारियों को लक्षित धोखाधड़ी c. वॉइस टेलीफ़ोन कॉल से धोखाधड़ी d. किसी विशेष व्यक्ति या समूह के अनुरूप बनाई गई धोखाधड़ी","optionsHi":["1-c, 2-a, 3-d, 4-b","1-a, 2-c, 3-d, 4-b","1-c, 2-a, 3-b, 4-d","1-c, 2-d, 3-a, 4-b"],"explanationHi":"विशिंग वॉइस फ़िशिंग है, स्मिशिंग SMS का प्रयोग करती है, स्पीयर फ़िशिंग चुने हुए लक्ष्य पर केंद्रित होती है, और व्हेलिंग वरिष्ठ अधिकारियों पर लक्षित स्पीयर फ़िशिंग है।"},
  {"id":"comp-awareness-357","question":"Customers type their bank's correct web address but are silently taken to a fake site, because the DNS records they rely on have been tampered with. This attack is:","options":["Vishing","Pharming","Spear phishing","Keylogging"],"answer":1,"explanation":"Pharming redirects users through poisoned DNS or a modified hosts file, so even a correctly typed address leads to the fake site. Phishing, by contrast, needs the victim to click a misleading link.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"ग्राहक अपने बैंक का सही वेब पता टाइप करते हैं पर चुपचाप नकली साइट पर पहुँचा दिए जाते हैं, क्योंकि जिन DNS रिकॉर्डों पर वे निर्भर हैं उनके साथ छेड़छाड़ की गई है। यह हमला है:","optionsHi":["विशिंग","फ़ार्मिंग","स्पीयर फ़िशिंग","कीलॉगिंग"],"explanationHi":"फ़ार्मिंग विषाक्त DNS या बदली गई hosts फ़ाइल के माध्यम से उपयोगकर्ताओं को भटकाती है, इसलिए सही टाइप किया गया पता भी नकली साइट पर ले जाता है। इसके विपरीत फ़िशिंग में पीड़ित को भ्रामक लिंक पर क्लिक करना पड़ता है।"},
  {"id":"comp-awareness-358","question":"An employee hides code in the payroll system that will delete salary records only if his own name is ever removed from the staff list. This is a:","options":["Worm","Rootkit","Adware","Logic bomb"],"answer":3,"explanation":"A logic bomb lies dormant until a set condition (a date or event) occurs and then does damage. A worm spreads itself, a rootkit hides malware, and adware shows advertisements.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक कर्मचारी वेतन प्रणाली में ऐसा कोड छिपाता है जो वेतन रिकॉर्ड तभी मिटाएगा जब कभी कर्मचारी सूची से उसका अपना नाम हटाया जाए। यह है एक:","optionsHi":["वर्म","रूटकिट","एडवेयर","लॉजिक बम"],"explanationHi":"लॉजिक बम तब तक निष्क्रिय रहता है जब तक कोई निर्धारित शर्त (तिथि या घटना) पूरी न हो, और फिर नुकसान करता है। वर्म स्वयं फैलता है, रूटकिट मैलवेयर को छिपाता है, और एडवेयर विज्ञापन दिखाता है।"},
  {"id":"comp-awareness-359","question":"A programmer at a bank rounds down the interest on lakhs of accounts and quietly moves the tiny leftover fractions into his own account. This fraud is called a:","options":["Salami attack","Phishing attack","Denial-of-service attack","Trojan horse"],"answer":0,"explanation":"A salami attack steals amounts too small to notice on each account but large in total. It needs no fake messages (phishing) and does not stop the service.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक बैंक का प्रोग्रामर लाखों खातों पर ब्याज को नीचे की ओर पूर्णांकित करता है और बचे हुए छोटे अंशों को चुपचाप अपने खाते में डाल लेता है। इस धोखाधड़ी को कहते हैं:","optionsHi":["सलामी अटैक","फ़िशिंग अटैक","डिनायल-ऑफ़-सर्विस अटैक","ट्रोजन हॉर्स"],"explanationHi":"सलामी अटैक प्रत्येक खाते से इतनी छोटी रकम चुराता है जो नज़र न आए पर कुल मिलाकर बड़ी हो। इसमें नकली संदेश (फ़िशिंग) नहीं चाहिए और यह सेवा को रोकता नहीं।"},
  {"id":"comp-awareness-360","question":"Malware changes parts of the operating system so that its own files and processes do not appear in file listings or the task manager. It is best described as a:","options":["Macro virus","Rootkit","Worm","Adware"],"answer":1,"explanation":"A rootkit hides itself (and often other malware) by subverting the OS's own reporting tools. Worms spread themselves, and macro viruses live in documents.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"मैलवेयर ऑपरेटिंग सिस्टम के कुछ भागों को ऐसे बदल देता है कि उसकी अपनी फ़ाइलें और प्रक्रियाएँ फ़ाइल सूचियों या टास्क मैनेजर में दिखाई नहीं देतीं। इसका सबसे उपयुक्त वर्णन है:","optionsHi":["मैक्रो वायरस","रूटकिट","वर्म","एडवेयर"],"explanationHi":"रूटकिट OS के अपने रिपोर्टिंग उपकरणों को भ्रष्ट करके स्वयं को (और अक्सर अन्य मैलवेयर को) छिपाता है। वर्म स्वयं फैलते हैं, और मैक्रो वायरस दस्तावेज़ों में रहते हैं।"},
  {"id":"comp-awareness-361","question":"A virus rewrites its own code with a different encryption key on every infection, so that no fixed signature matches all its copies. It is a:","options":["Boot-sector virus","Macro virus","Polymorphic virus","Resident virus"],"answer":2,"explanation":"A polymorphic virus mutates its appearance to defeat signature-based scanners. Boot-sector and macro viruses are named for where they live, not how they disguise themselves.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"एक वायरस प्रत्येक संक्रमण पर अपना कोड भिन्न एन्क्रिप्शन कुंजी से फिर से लिखता है, ताकि कोई निश्चित हस्ताक्षर उसकी सभी प्रतियों से मेल न खाए। यह है एक:","optionsHi":["बूट-सेक्टर वायरस","मैक्रो वायरस","पॉलीमॉर्फ़िक वायरस","रेज़िडेंट वायरस"],"explanationHi":"पॉलीमॉर्फ़िक वायरस हस्ताक्षर-आधारित स्कैनरों को चकमा देने के लिए अपना रूप बदलता रहता है। बूट-सेक्टर और मैक्रो वायरस के नाम इस पर हैं कि वे कहाँ रहते हैं, इस पर नहीं कि वे कैसे छिपते हैं।"},
  {"id":"comp-awareness-362","question":"A virus spreads through word-processor documents and runs automatically when an infected document is opened. It is a:","options":["Macro virus","Boot-sector virus","Logic bomb","Rootkit"],"answer":0,"explanation":"Macro viruses are written in an application's macro language and run when the document opens; that is why office programs disable macros in files from the internet by default.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"एक वायरस वर्ड-प्रोसेसर दस्तावेज़ों के माध्यम से फैलता है और संक्रमित दस्तावेज़ खोलते ही अपने आप चलता है। यह है एक:","optionsHi":["मैक्रो वायरस","बूट-सेक्टर वायरस","लॉजिक बम","रूटकिट"],"explanationHi":"मैक्रो वायरस किसी एप्लिकेशन की मैक्रो भाषा में लिखे जाते हैं और दस्तावेज़ खुलते ही चलते हैं; इसीलिए ऑफ़िस प्रोग्राम इंटरनेट से आई फ़ाइलों में मैक्रो डिफ़ॉल्ट रूप से अक्षम रखते हैं।"},
  {"id":"comp-awareness-363","question":"Attackers exploit a software flaw that the vendor does not yet know about, so no patch exists. Such an attack is called a:","options":["Brute-force attack","Replay attack","Dictionary attack","Zero-day attack"],"answer":3,"explanation":"'Zero-day' means the defenders have had zero days to fix the flaw. Brute-force and dictionary attacks guess passwords, and a replay attack resends captured data.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"हमलावर किसी सॉफ्टवेयर त्रुटि का दोहन करते हैं जिसके बारे में विक्रेता को अभी पता नहीं है, इसलिए कोई पैच मौजूद नहीं है। ऐसा हमला कहलाता है:","optionsHi":["ब्रूट-फ़ोर्स अटैक","रीप्ले अटैक","डिक्शनरी अटैक","ज़ीरो-डे अटैक"],"explanationHi":"‘ज़ीरो-डे’ का अर्थ है कि रक्षकों को त्रुटि सुधारने के लिए शून्य दिन मिले। ब्रूट-फ़ोर्स और डिक्शनरी अटैक पासवर्ड का अनुमान लगाते हैं, और रीप्ले अटैक पकड़े गए डेटा को फिर भेजता है।"},
  {"id":"comp-awareness-364","question":"Typing ' OR '1'='1 into the password box of a poorly written login page logs the attacker in without a password. Which attack is this?","options":["Cross-site scripting","SQL injection","Buffer overflow","Brute-force attack"],"answer":1,"explanation":"The input changes the meaning of the SQL query so its WHERE condition is always true. Parameterised queries prevent this; cross-site scripting injects browser scripts instead.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"किसी खराब ढंग से लिखे गए लॉगिन पेज के पासवर्ड बॉक्स में ' OR '1'='1 टाइप करने से हमलावर बिना पासवर्ड के लॉग इन हो जाता है। यह कौन-सा हमला है?","optionsHi":["क्रॉस-साइट स्क्रिप्टिंग","SQL इंजेक्शन","बफ़र ओवरफ़्लो","ब्रूट-फ़ोर्स अटैक"],"explanationHi":"इनपुट SQL क्वेरी का अर्थ बदल देता है, जिससे उसकी WHERE शर्त सदा सत्य हो जाती है। पैरामीटरयुक्त क्वेरी इसे रोकती हैं; क्रॉस-साइट स्क्रिप्टिंग इसके बजाय ब्राउज़र स्क्रिप्ट डालती है।"},
  {"id":"comp-awareness-365","question":"An attacker posts a comment containing JavaScript on a forum, and the script then runs in the browser of everyone who views that page. This is:","options":["SQL injection","Session fixation","Cross-site scripting","Clickjacking"],"answer":2,"explanation":"Stored cross-site scripting (XSS) makes the site deliver the attacker's script to other visitors, where it can steal session cookies. SQL injection targets the database, not the browser.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"एक हमलावर फ़ोरम पर JavaScript वाली टिप्पणी पोस्ट करता है, और फिर वह स्क्रिप्ट उस पृष्ठ को देखने वाले प्रत्येक व्यक्ति के ब्राउज़र में चलती है। यह है:","optionsHi":["SQL इंजेक्शन","सेशन फ़िक्सेशन","क्रॉस-साइट स्क्रिप्टिंग","क्लिकजैकिंग"],"explanationHi":"स्टोर्ड क्रॉस-साइट स्क्रिप्टिंग (XSS) साइट से हमलावर की स्क्रिप्ट अन्य आगंतुकों तक पहुँचवाती है, जहाँ वह सेशन कुकी चुरा सकती है। SQL इंजेक्शन डेटाबेस को लक्षित करता है, ब्राउज़र को नहीं।"},
  {"id":"comp-awareness-366","question":"On a café's open Wi-Fi, an attacker secretly relays all traffic between a customer and her bank, reading and changing it on the way. This is a:","options":["Man-in-the-middle attack","Denial-of-service attack","Brute-force attack","Salami attack"],"answer":0,"explanation":"In a man-in-the-middle attack both sides think they talk directly to each other while the attacker sits between them. HTTPS with certificate checks is the main defence.","difficulty":"moderate","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी कैफ़े के खुले Wi-Fi पर एक हमलावर ग्राहक और उसके बैंक के बीच का सारा ट्रैफ़िक चुपचाप आगे भेजता है, रास्ते में उसे पढ़ता और बदलता है। यह है एक:","optionsHi":["मैन-इन-द-मिडल अटैक","डिनायल-ऑफ़-सर्विस अटैक","ब्रूट-फ़ोर्स अटैक","सलामी अटैक"],"explanationHi":"मैन-इन-द-मिडल अटैक में दोनों पक्ष सोचते हैं कि वे सीधे एक-दूसरे से बात कर रहे हैं जबकि हमलावर उनके बीच बैठा होता है। प्रमाणपत्र जाँच वाला HTTPS मुख्य बचाव है।"},
  {"id":"comp-awareness-367","question":"A machine can try 1000 PINs per second. In the worst case, about how long does it take to find a 6-digit numeric PIN by trying every possibility?","options":["About 1.7 minutes","About 2.8 hours","About 10 seconds","About 16.7 minutes"],"answer":3,"explanation":"There are 10⁶ six-digit PINs; 10⁶ ÷ 1000 = 1000 s ≈ 16.7 minutes. This is why systems lock the account after a few wrong tries.","difficulty":"hard","source":"IBPS PO Mains · IBPS SO IT Officer","questionHi":"एक मशीन प्रति सेकंड 1000 PIN आज़मा सकती है। सबसे खराब स्थिति में, प्रत्येक संभावना आज़माकर 6-अंकीय संख्यात्मक PIN खोजने में लगभग कितना समय लगता है?","optionsHi":["लगभग 1.7 मिनट","लगभग 2.8 घंटे","लगभग 10 सेकंड","लगभग 16.7 मिनट"],"explanationHi":"6-अंकीय PIN 10⁶ हैं; 10⁶ ÷ 1000 = 1000 s ≈ 16.7 मिनट। इसीलिए प्रणालियाँ कुछ गलत प्रयासों के बाद खाता लॉक कर देती हैं।"},
  {"id":"comp-awareness-368","question":"How does an intrusion prevention system (IPS) differ from an intrusion detection system (IDS)?","options":["An IPS sits inline and can block suspicious traffic, not just raise an alert","An IPS only records traffic for analysis later and never raises any alert","An IPS checks e-mail attachments, while an IDS checks only web pages","An IPS works on the user's PC, while an IDS works only on routers"],"answer":0,"explanation":"An IDS monitors and alerts; an IPS sits in the traffic path and drops or blocks what it judges malicious. Neither is limited to e-mail, web pages or a particular device.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"इंट्रूज़न प्रिवेंशन सिस्टम (IPS) इंट्रूज़न डिटेक्शन सिस्टम (IDS) से कैसे भिन्न है?","optionsHi":["IPS इनलाइन रहता है और संदिग्ध ट्रैफ़िक को केवल चेतावनी देने के बजाय रोक सकता है","IPS ट्रैफ़िक को केवल बाद के विश्लेषण के लिए रिकॉर्ड करता है और कभी चेतावनी नहीं देता","IPS ई-मेल अनुलग्नक जाँचता है, जबकि IDS केवल वेब पृष्ठ जाँचता है","IPS उपयोगकर्ता के PC पर काम करता है, जबकि IDS केवल राउटरों पर काम करता है"],"explanationHi":"IDS निगरानी करता और चेतावनी देता है; IPS ट्रैफ़िक के मार्ग में बैठता है और जिसे दुर्भावनापूर्ण मानता है उसे गिरा या रोक देता है। दोनों में से कोई ई-मेल, वेब पृष्ठों या किसी विशेष उपकरण तक सीमित नहीं है।"},
  {"id":"comp-awareness-369","question":"A security team sets up a deliberately weak-looking decoy server, with no real data, to attract attackers and study their methods. It is a:","options":["Proxy server","Honeypot","Firewall","Sandbox"],"answer":1,"explanation":"A honeypot lures attackers so their tools and behaviour can be watched without risk to real systems. A sandbox isolates suspicious programs, and a firewall filters traffic.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"एक सुरक्षा दल जानबूझकर कमज़ोर दिखने वाला नकली सर्वर बनाता है, जिसमें कोई वास्तविक डेटा नहीं है, ताकि हमलावरों को आकर्षित करे और उनके तरीकों का अध्ययन करे। यह है एक:","optionsHi":["प्रॉक्सी सर्वर","हनीपॉट","फ़ायरवॉल","सैंडबॉक्स"],"explanationHi":"हनीपॉट हमलावरों को लुभाता है ताकि वास्तविक प्रणालियों को जोखिम दिए बिना उनके उपकरण और व्यवहार देखे जा सकें। सैंडबॉक्स संदिग्ध प्रोग्रामों को अलग रखता है, और फ़ायरवॉल ट्रैफ़िक को फ़िल्टर करता है।"},
  {"id":"comp-awareness-370","question":"A full backup is taken every Sunday night and an INCREMENTAL backup every other night. The disk fails on Thursday morning. Which backups are needed to restore the latest data?","options":["Sunday's full backup and Wednesday's incremental backup only","Wednesday's incremental backup only","Sunday's full backup and the Monday, Tuesday and Wednesday incrementals","Sunday's full backup only, since incrementals are never restored"],"answer":2,"explanation":"Each incremental holds only changes since the previous backup, so the full backup and every incremental after it are needed in order. Full + latest only works for differential backups.","difficulty":"very-hard","source":"IBPS SO IT Officer · IBPS PO Mains","questionHi":"प्रत्येक रविवार रात पूर्ण बैकअप लिया जाता है और हर अन्य रात इन्क्रीमेंटल बैकअप। गुरुवार सुबह डिस्क विफल हो जाती है। नवीनतम डेटा पुनर्स्थापित करने के लिए कौन-से बैकअप चाहिए?","optionsHi":["केवल रविवार का पूर्ण बैकअप और बुधवार का इन्क्रीमेंटल बैकअप","केवल बुधवार का इन्क्रीमेंटल बैकअप","रविवार का पूर्ण बैकअप और सोमवार, मंगलवार तथा बुधवार के इन्क्रीमेंटल","केवल रविवार का पूर्ण बैकअप, क्योंकि इन्क्रीमेंटल कभी पुनर्स्थापित नहीं किए जाते"],"explanationHi":"प्रत्येक इन्क्रीमेंटल में केवल पिछले बैकअप के बाद के परिवर्तन होते हैं, इसलिए पूर्ण बैकअप और उसके बाद के प्रत्येक इन्क्रीमेंटल क्रम से चाहिए। पूर्ण + केवल नवीनतम डिफ़रेंशियल बैकअप के लिए चलता है।"},
  {"id":"comp-awareness-371","question":"A browser shows a padlock for https://example-bank.in. What does this padlock actually guarantee?","options":["The site is run by a genuine, licensed bank and is safe for all payments","The site has been scanned by the browser and found free of all malware","Traffic to the site is encrypted, and it holds a valid certificate for that domain","The site will never store or share any of your personal data"],"answer":2,"explanation":"TLS proves only that the connection is encrypted and that the server controls the domain named in its certificate; a phishing site can have a padlock too.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक ब्राउज़र https://example-bank.in के लिए पैडलॉक दिखाता है। यह पैडलॉक वास्तव में क्या गारंटी देता है?","optionsHi":["साइट असली, लाइसेंसशुदा बैंक द्वारा चलाई जाती है और सभी भुगतानों के लिए सुरक्षित है","साइट को ब्राउज़र ने स्कैन किया है और वह सभी मैलवेयर से मुक्त पाई गई है","साइट का ट्रैफ़िक एन्क्रिप्टेड है, और उसके पास उस डोमेन का वैध प्रमाणपत्र है","साइट आपके किसी भी निजी डेटा को कभी संग्रहीत या साझा नहीं करेगी"],"explanationHi":"TLS केवल यह सिद्ध करता है कि कनेक्शन एन्क्रिप्टेड है और सर्वर अपने प्रमाणपत्र में नामित डोमेन को नियंत्रित करता है; फ़िशिंग साइट पर भी पैडलॉक हो सकता है।"},
  {"id":"comp-awareness-372","question":"Which body issues and digitally signs the certificates that bind a public key to a website or a person?","options":["Domain name registrar","Internet service provider","Certificate Authority","Web browser maker"],"answer":2,"explanation":"A Certificate Authority verifies identity and signs the certificate with its own private key; browsers trust certificates that chain back to a trusted CA. A registrar only records domain ownership.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"कौन-सी संस्था वे प्रमाणपत्र जारी करती और डिजिटल रूप से हस्ताक्षरित करती है जो सार्वजनिक कुंजी को किसी वेबसाइट या व्यक्ति से बाँधते हैं?","optionsHi":["डोमेन नेम रजिस्ट्रार","इंटरनेट सेवा प्रदाता","प्रमाणन प्राधिकरण (सर्टिफ़िकेट अथॉरिटी)","वेब ब्राउज़र निर्माता"],"explanationHi":"सर्टिफ़िकेट अथॉरिटी पहचान सत्यापित करती है और प्रमाणपत्र पर अपनी निजी कुंजी से हस्ताक्षर करती है; ब्राउज़र उन प्रमाणपत्रों पर भरोसा करते हैं जो किसी विश्वसनीय CA तक जाते हैं। रजिस्ट्रार केवल डोमेन स्वामित्व दर्ज करता है।"},
  {"id":"comp-awareness-373","question":"A bank makes its fingerprint scanner's matching threshold stricter. What is the expected effect?","options":["False acceptances rise and false rejections fall","Both false acceptances and false rejections fall","Both false acceptances and false rejections rise","False acceptances fall and false rejections rise"],"answer":3,"explanation":"A stricter threshold lets fewer impostors through (lower FAR) but also turns away more genuine users (higher FRR); the two rates trade off against each other.","difficulty":"very-hard","source":"IBPS SO IT Officer · IBPS PO Mains","questionHi":"एक बैंक अपने फ़िंगरप्रिंट स्कैनर की मिलान-सीमा को अधिक कठोर बना देता है। अपेक्षित प्रभाव क्या है?","optionsHi":["झूठी स्वीकृतियाँ बढ़ती हैं और झूठे अस्वीकरण घटते हैं","झूठी स्वीकृतियाँ और झूठे अस्वीकरण दोनों घटते हैं","झूठी स्वीकृतियाँ और झूठे अस्वीकरण दोनों बढ़ते हैं","झूठी स्वीकृतियाँ घटती हैं और झूठे अस्वीकरण बढ़ते हैं"],"explanationHi":"अधिक कठोर सीमा कम धोखेबाज़ों को आने देती है (कम FAR) पर वास्तविक उपयोगकर्ताओं को भी अधिक लौटाती है (अधिक FRR); दोनों दरों में आपस में समझौता (ट्रेड-ऑफ़) होता है।"},
  {"id":"comp-awareness-374","question":"Ransomware has encrypted every file on a branch's computers. What best lets the branch recover without paying the ransom?","options":["Running a disk defragmenter on the affected drives","Keeping recent backups stored offline, away from the network","Changing the passwords of every user account","Reinstalling the antivirus program on each computer"],"answer":1,"explanation":"Only a clean, recent backup the malware could not reach restores the data; new passwords or antivirus stop future damage but cannot decrypt files already encrypted.","difficulty":"moderate","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"रैनसमवेयर ने किसी शाखा के कंप्यूटरों की प्रत्येक फ़ाइल एन्क्रिप्ट कर दी है। फ़िरौती दिए बिना शाखा को सबसे अच्छा क्या पुनर्प्राप्त करा सकता है?","optionsHi":["प्रभावित ड्राइवों पर डिस्क डीफ़्रैग्मेंटर चलाना","नवीनतम बैकअप को नेटवर्क से दूर ऑफ़लाइन रखना","प्रत्येक उपयोगकर्ता खाते के पासवर्ड बदलना","प्रत्येक कंप्यूटर पर एंटीवायरस प्रोग्राम पुनः इंस्टॉल करना"],"explanationHi":"केवल स्वच्छ, हाल का बैकअप, जहाँ मैलवेयर नहीं पहुँच सका, डेटा पुनर्स्थापित करता है; नए पासवर्ड या एंटीवायरस आगे की क्षति रोकते हैं पर पहले से एन्क्रिप्ट हुई फ़ाइलों को डिक्रिप्ट नहीं कर सकते।"},
  {"id":"comp-awareness-375","question":"Hiding a secret message inside the pixel values of an ordinary-looking photograph, so that nobody suspects a message exists, is called:","options":["Cryptanalysis","Hashing","Steganography","Tokenisation"],"answer":2,"explanation":"Steganography conceals the existence of a message; cryptography conceals its meaning. Cryptanalysis is code-breaking, and hashing makes a fixed-size digest.","difficulty":"hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"किसी साधारण दिखने वाली फ़ोटो के पिक्सेल मानों में गुप्त संदेश छिपाना, ताकि किसी को संदेश के अस्तित्व का संदेह ही न हो, कहलाता है:","optionsHi":["क्रिप्टएनालिसिस","हैशिंग","स्टेगनोग्राफ़ी","टोकनाइज़ेशन"],"explanationHi":"स्टेगनोग्राफ़ी संदेश के अस्तित्व को छिपाती है; क्रिप्टोग्राफ़ी उसके अर्थ को छिपाती है। क्रिप्टएनालिसिस कोड तोड़ना है, और हैशिंग निश्चित आकार का डाइजेस्ट बनाती है।"},
  {"id":"comp-awareness-376","question":"A relation R(A, B, C, D) has the functional dependencies AB → C, C → D and D → A. Which are ALL its candidate keys?","options":["AB, BC and BD","AB only","AB and BC only","B only"],"answer":0,"explanation":"B appears on no right side, so every key contains B, but B alone gives only B. AB → C → D gives ABCD; BC → D → A gives ABCD; BD → A, then AB → C gives ABCD. So AB, BC and BD are all minimal keys.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"रिलेशन R(A, B, C, D) में फ़ंक्शनल निर्भरताएँ AB → C, C → D और D → A हैं। इसकी सभी कैंडिडेट कीज़ कौन-सी हैं?","optionsHi":["AB, BC और BD","केवल AB","केवल AB और BC","केवल B"],"explanationHi":"B किसी दाएँ पक्ष में नहीं है, इसलिए प्रत्येक की में B होता है, पर अकेला B केवल B देता है। AB → C → D से ABCD मिलता है; BC → D → A से ABCD; BD → A, फिर AB → C से ABCD। इसलिए AB, BC और BD सभी न्यूनतम कीज़ हैं।"},
  {"id":"comp-awareness-377","question":"EMPLOYEE(EmpID, Name, DeptID, DeptName) has key EmpID, and DeptID → DeptName also holds. All values are atomic. What is the highest normal form the table satisfies?","options":["1NF","3NF","BCNF","2NF"],"answer":3,"explanation":"A single-attribute key rules out partial dependencies, so it is in 2NF. But EmpID → DeptID → DeptName is a transitive dependency of a non-key attribute, which breaks 3NF.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"EMPLOYEE(EmpID, Name, DeptID, DeptName) की की EmpID है, और DeptID → DeptName भी लागू है। सभी मान परमाणु हैं। तालिका जिस उच्चतम सामान्य रूप को संतुष्ट करती है वह क्या है?","optionsHi":["1NF","3NF","BCNF","2NF"],"explanationHi":"एकल-एट्रिब्यूट वाली की आंशिक निर्भरताओं को रोकती है, इसलिए यह 2NF में है। परंतु EmpID → DeptID → DeptName एक गैर-की एट्रिब्यूट की संक्रामक निर्भरता है, जो 3NF को भंग करती है।"},
  {"id":"comp-awareness-378","question":"A relation is in Boyce–Codd Normal Form (BCNF) when:","options":["Every non-key attribute depends on the whole of every candidate key","For every non-trivial dependency X → Y, X is a superkey","No non-key attribute depends on another non-key attribute","Every attribute holds only atomic, single values"],"answer":1,"explanation":"BCNF demands that every determinant be a superkey, which is stricter than 3NF (3NF also allows X → Y when Y is a prime attribute). The other options describe 2NF, 3NF and 1NF ideas.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"कोई रिलेशन बॉयस–कॉड सामान्य रूप (BCNF) में तब होता है जब:","optionsHi":["प्रत्येक गैर-की एट्रिब्यूट प्रत्येक कैंडिडेट की के संपूर्ण भाग पर निर्भर हो","प्रत्येक अतुच्छ निर्भरता X → Y के लिए X एक सुपरकी हो","कोई गैर-की एट्रिब्यूट किसी अन्य गैर-की एट्रिब्यूट पर निर्भर न हो","प्रत्येक एट्रिब्यूट में केवल परमाणु, एकल मान हों"],"explanationHi":"BCNF की माँग है कि प्रत्येक निर्धारक सुपरकी हो, जो 3NF से अधिक कठोर है (3NF में Y के प्राइम एट्रिब्यूट होने पर X → Y भी स्वीकार्य है)। अन्य विकल्प 2NF, 3NF और 1NF की धारणाओं का वर्णन करते हैं।"},
  {"id":"comp-awareness-379","question":"A CUSTOMER table keeps several phone numbers in one Phone column, separated by commas (for example '98xxxxxx01, 98xxxxxx02'). Which normal form does this break?","options":["Second normal form","Third normal form","Boyce–Codd normal form","First normal form"],"answer":3,"explanation":"1NF requires every column value to be atomic; a list of phone numbers in one cell is a repeating group. The fix is a separate CUSTOMER_PHONE table.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"CUSTOMER तालिका एक ही Phone स्तंभ में कई फ़ोन नंबर अल्पविराम से अलग करके रखती है (उदाहरण के लिए '98xxxxxx01, 98xxxxxx02')। यह किस सामान्य रूप को भंग करता है?","optionsHi":["द्वितीय सामान्य रूप","तृतीय सामान्य रूप","बॉयस–कॉड सामान्य रूप","प्रथम सामान्य रूप"],"explanationHi":"1NF की माँग है कि प्रत्येक स्तंभ का मान परमाणु हो; एक सेल में फ़ोन नंबरों की सूची दोहराव वाला समूह है। समाधान अलग CUSTOMER_PHONE तालिका है।"},
  {"id":"comp-awareness-380","question":"A relation R(A, B, C) has A as its only candidate key. How many superkeys does R have?","options":["4","3","7","1"],"answer":0,"explanation":"A superkey is any attribute set containing a key. Sets containing A: {A}, {A,B}, {A,C}, {A,B,C}, which makes 4. 7 counts every non-empty subset.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"रिलेशन R(A, B, C) की एकमात्र कैंडिडेट की A है। R की कितनी सुपरकीज़ हैं?","optionsHi":["4","3","7","1"],"explanationHi":"सुपरकी कोई भी एट्रिब्यूट-समुच्चय है जिसमें की शामिल हो। A वाले समुच्चय: {A}, {A,B}, {A,C}, {A,B,C}, जो 4 होते हैं। 7 प्रत्येक अरिक्त उपसमुच्चय को गिनता है।"},
  {"id":"comp-awareness-381","question":"Table ACCOUNT has 5 rows and table NOMINEE has 4 rows. Three accounts match exactly one nominee each, and two accounts match none. How many rows does ACCOUNT LEFT OUTER JOIN NOMINEE on the account number return?","options":["3","20","7","5"],"answer":3,"explanation":"A left join keeps every row of the left table: 3 matched rows plus 2 unmatched rows padded with NULLs = 5. An inner join would return 3, and a cross join 20.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"तालिका ACCOUNT में 5 पंक्तियाँ और तालिका NOMINEE में 4 पंक्तियाँ हैं। तीन खाते प्रत्येक ठीक एक नामांकित से मेल खाते हैं, और दो खाते किसी से नहीं। खाता संख्या पर ACCOUNT LEFT OUTER JOIN NOMINEE कितनी पंक्तियाँ लौटाता है?","optionsHi":["3","20","7","5"],"explanationHi":"लेफ़्ट जॉइन बाईं तालिका की प्रत्येक पंक्ति रखता है: 3 मिलान वाली पंक्तियाँ और NULL से भरी 2 बेमेल पंक्तियाँ = 5। इनर जॉइन 3 लौटाता, और क्रॉस जॉइन 20।"},
  {"id":"comp-awareness-382","question":"Table A has 6 rows and 3 columns, and table B has 4 rows and 2 columns. What does SELECT * FROM A, B (with no WHERE clause) return?","options":["10 rows and 5 columns","24 rows and 5 columns","24 rows and 6 columns","10 rows and 6 columns"],"answer":1,"explanation":"Listing two tables without a join condition forms the Cartesian product: 6 × 4 = 24 rows, each with 3 + 2 = 5 columns.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"तालिका A में 6 पंक्तियाँ और 3 स्तंभ हैं, और तालिका B में 4 पंक्तियाँ और 2 स्तंभ हैं। SELECT * FROM A, B (बिना WHERE क्लॉज़ के) क्या लौटाता है?","optionsHi":["10 पंक्तियाँ और 5 स्तंभ","24 पंक्तियाँ और 5 स्तंभ","24 पंक्तियाँ और 6 स्तंभ","10 पंक्तियाँ और 6 स्तंभ"],"explanationHi":"जॉइन शर्त के बिना दो तालिकाएँ लिखने से कार्तीय गुणनफल बनता है: 6 × 4 = 24 पंक्तियाँ, प्रत्येक में 3 + 2 = 5 स्तंभ।"},
  {"id":"comp-awareness-383","question":"A column Bonus holds the values 10, 20, NULL and 30 in four rows. What does SELECT AVG(Bonus) return?","options":["20","15","NULL","60"],"answer":0,"explanation":"Aggregate functions skip NULLs, so AVG = (10 + 20 + 30) ÷ 3 = 20. Treating NULL as 0 and dividing by 4 gives the trap 15.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"चार पंक्तियों में Bonus स्तंभ के मान 10, 20, NULL और 30 हैं। SELECT AVG(Bonus) क्या लौटाता है?","optionsHi":["20","15","NULL","60"],"explanationHi":"समुच्चय फ़ंक्शन NULL को छोड़ देते हैं, इसलिए AVG = (10 + 20 + 30) ÷ 3 = 20। NULL को 0 मानकर 4 से भाग देने पर जाल वाला उत्तर 15 आता है।"},
  {"id":"comp-awareness-384","question":"Which statement about DELETE and TRUNCATE in SQL is correct?","options":["TRUNCATE can remove selected rows with WHERE; DELETE always empties the whole table","DELETE removes the table structure as well, while TRUNCATE keeps the structure","DELETE can remove selected rows using WHERE; TRUNCATE empties the table but keeps its structure","Both DELETE and TRUNCATE remove the table's structure along with all its data"],"answer":2,"explanation":"DELETE is a DML command that may take a WHERE clause; TRUNCATE is a DDL command that removes all rows at once and keeps the table definition. Only DROP removes the structure.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"SQL में DELETE और TRUNCATE के बारे में कौन-सा कथन सही है?","optionsHi":["TRUNCATE WHERE से चुनी हुई पंक्तियाँ हटा सकता है; DELETE सदा पूरी तालिका खाली करता है","DELETE तालिका की संरचना भी हटा देता है, जबकि TRUNCATE संरचना रखता है","DELETE WHERE का प्रयोग करके चुनी हुई पंक्तियाँ हटा सकता है; TRUNCATE तालिका खाली करता है पर उसकी संरचना रखता है","DELETE और TRUNCATE दोनों तालिका की संरचना को उसके सारे डेटा के साथ हटा देते हैं"],"explanationHi":"DELETE एक DML कमांड है जिसमें WHERE क्लॉज़ हो सकता है; TRUNCATE एक DDL कमांड है जो सभी पंक्तियाँ एक साथ हटाता है और तालिका की परिभाषा रखता है। केवल DROP संरचना हटाता है।"},
  {"id":"comp-awareness-385","question":"In which order does a database logically process the clauses of a SELECT statement?","options":["SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY","FROM → GROUP BY → WHERE → HAVING → SELECT → ORDER BY","FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY","FROM → WHERE → HAVING → GROUP BY → ORDER BY → SELECT"],"answer":2,"explanation":"Rows are taken FROM the tables, filtered by WHERE, grouped, filtered as groups by HAVING, then the SELECT list is computed and finally sorted. That is why WHERE cannot use aggregates but HAVING can.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"डेटाबेस SELECT कथन के क्लॉज़ों को तार्किक रूप से किस क्रम में संसाधित करता है?","optionsHi":["SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY","FROM → GROUP BY → WHERE → HAVING → SELECT → ORDER BY","FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY","FROM → WHERE → HAVING → GROUP BY → ORDER BY → SELECT"],"explanationHi":"पंक्तियाँ तालिकाओं से FROM द्वारा ली जाती हैं, WHERE से फ़िल्टर होती हैं, समूहित होती हैं, HAVING से समूहों के रूप में फ़िल्टर होती हैं, फिर SELECT सूची की गणना होती है और अंत में क्रमबद्ध की जाती हैं। इसीलिए WHERE समुच्चय का प्रयोग नहीं कर सकता पर HAVING कर सकता है।"},
  {"id":"comp-awareness-386","question":"The condition WHERE Salary BETWEEN 20000 AND 30000 selects rows whose salary is:","options":["From 20000 to 30000, including both 20000 and 30000","Above 20000 and below 30000, excluding both limits","From 20000 up to but not including 30000","Above 20000 and up to and including 30000"],"answer":0,"explanation":"BETWEEN is inclusive at both ends: it means Salary >= 20000 AND Salary <= 30000.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer","questionHi":"शर्त WHERE Salary BETWEEN 20000 AND 30000 उन पंक्तियों को चुनती है जिनका वेतन है:","optionsHi":["20000 से 30000 तक, 20000 और 30000 दोनों सहित","20000 से अधिक और 30000 से कम, दोनों सीमाओं को छोड़कर","20000 से शुरू होकर, 30000 को छोड़कर","20000 से अधिक और ऊपरी सीमा 30000 सहित"],"explanationHi":"BETWEEN दोनों सिरों पर समावेशी है: इसका अर्थ है Salary >= 20000 AND Salary <= 30000।"},
  {"id":"comp-awareness-387","question":"A query must list the customers who have no phone number recorded (the Phone column is NULL). Which condition works?","options":["WHERE Phone = NULL","WHERE Phone = ''","WHERE Phone IS NULL","WHERE Phone = 0"],"answer":2,"explanation":"Any comparison with NULL using = yields UNKNOWN, so 'Phone = NULL' returns no rows; IS NULL is the correct test. An empty string or 0 is a real value, not NULL.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"एक क्वेरी को उन ग्राहकों की सूची बनानी है जिनका कोई फ़ोन नंबर दर्ज नहीं है (Phone स्तंभ NULL है)। कौन-सी शर्त काम करती है?","optionsHi":["WHERE Phone = NULL","WHERE Phone = ''","WHERE Phone IS NULL","WHERE Phone = 0"],"explanationHi":"= से NULL की किसी भी तुलना का परिणाम UNKNOWN होता है, इसलिए ‘Phone = NULL’ कोई पंक्ति नहीं लौटाता; IS NULL सही परीक्षण है। रिक्त स्ट्रिंग या 0 वास्तविक मान हैं, NULL नहीं।"},
  {"id":"comp-awareness-388","question":"A City column holds Delhi, Pune, Delhi, NULL, Pune, NULL in six rows. What does SELECT COUNT(DISTINCT City) return?","options":["3","4","6","2"],"answer":3,"explanation":"COUNT ignores NULLs, and DISTINCT keeps one copy of each value, leaving Delhi and Pune: 2. Counting NULL as a value gives 3; COUNT(City) would give 4.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"छह पंक्तियों में City स्तंभ में Delhi, Pune, Delhi, NULL, Pune, NULL हैं। SELECT COUNT(DISTINCT City) क्या लौटाता है?","optionsHi":["3","4","6","2"],"explanationHi":"COUNT NULL की उपेक्षा करता है, और DISTINCT प्रत्येक मान की एक प्रति रखता है, जिससे Delhi और Pune बचते हैं: 2। NULL को मान गिनने पर 3 आता है; COUNT(City) 4 देता।"},
  {"id":"comp-awareness-389","question":"A transaction runs: INSERT row 1; SAVEPOINT s1; INSERT row 2; ROLLBACK TO s1; COMMIT. Which of the inserted rows are in the table afterwards?","options":["Row 1 only","Row 2 only","Both row 1 and row 2","Neither row"],"answer":0,"explanation":"ROLLBACK TO s1 undoes only the work done after the savepoint (row 2); row 1 stays, and COMMIT makes it permanent. A plain ROLLBACK would have undone both.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक लेन-देन चलता है: पंक्ति 1 INSERT करें; SAVEPOINT s1; पंक्ति 2 INSERT करें; ROLLBACK TO s1; COMMIT। बाद में तालिका में डाली गई पंक्तियों में से कौन-सी होंगी?","optionsHi":["केवल पंक्ति 1","केवल पंक्ति 2","पंक्ति 1 और पंक्ति 2 दोनों","कोई नहीं"],"explanationHi":"ROLLBACK TO s1 केवल सेवपॉइंट के बाद किया गया कार्य (पंक्ति 2) पूर्ववत करता है; पंक्ति 1 रहती है, और COMMIT उसे स्थायी बना देता है। सादा ROLLBACK दोनों को पूर्ववत कर देता।"},
  {"id":"comp-awareness-390","question":"A transfer debits Account A, but the system crashes before Account B is credited. On restart, the debit is undone, so it is as if the transfer never began. Which ACID property is at work?","options":["Consistency","Atomicity","Isolation","Durability"],"answer":1,"explanation":"Atomicity means a transaction happens completely or not at all, so a half-done transfer is rolled back. Durability concerns committed work surviving a crash.","difficulty":"hard","source":"IBPS SO IT Officer · IBPS PO Mains","questionHi":"एक अंतरण खाता A को डेबिट करता है, पर खाता B के क्रेडिट होने से पहले प्रणाली क्रैश हो जाती है। पुनः आरंभ होने पर डेबिट पूर्ववत हो जाता है, मानो अंतरण कभी शुरू ही न हुआ हो। कौन-सा ACID गुण काम कर रहा है?","optionsHi":["संगतता (कंसिस्टेंसी)","परमाणुकता (एटॉमिसिटी)","पृथक्करण (आइसोलेशन)","टिकाऊपन (ड्यूरेबिलिटी)"],"explanationHi":"एटॉमिसिटी का अर्थ है कि लेन-देन या तो पूरा होता है या बिल्कुल नहीं, इसलिए अधूरा अंतरण रोलबैक हो जाता है। ड्यूरेबिलिटी कमिट हुए कार्य के क्रैश में बचे रहने से संबंधित है।"},
  {"id":"comp-awareness-391","question":"Two transactions run at the same time on the same accounts, yet the final result is the same as if one had run fully before the other. Which ACID property ensures this?","options":["Atomicity","Durability","Consistency","Isolation"],"answer":3,"explanation":"Isolation makes concurrent transactions behave as though they ran one after another (serially), so neither sees the other's half-finished changes.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"दो लेन-देन एक ही खातों पर एक साथ चलते हैं, फिर भी अंतिम परिणाम वही है जो एक के पूरी तरह चलने के बाद दूसरे के चलने पर होता। यह कौन-सा ACID गुण सुनिश्चित करता है?","optionsHi":["परमाणुकता (एटॉमिसिटी)","टिकाऊपन (ड्यूरेबिलिटी)","संगतता (कंसिस्टेंसी)","पृथक्करण (आइसोलेशन)"],"explanationHi":"आइसोलेशन समवर्ती लेन-देन को ऐसे व्यवहार कराता है मानो वे एक के बाद एक (क्रमिक रूप से) चले हों, इसलिए कोई भी दूसरे के अधूरे परिवर्तन नहीं देखता।"},
  {"id":"comp-awareness-392","question":"A database stores records as a tree in which every child record has exactly one parent, as in a company → department → employee chart. Which data model is this?","options":["Hierarchical model","Network model","Relational model","Object-oriented model"],"answer":0,"explanation":"The hierarchical model allows one parent per child. The network model allows a record many parents, and the relational model uses tables linked by keys.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"एक डेटाबेस रिकॉर्डों को वृक्ष के रूप में संग्रहीत करता है जिसमें प्रत्येक चाइल्ड रिकॉर्ड का ठीक एक पैरेंट होता है, जैसे कंपनी → विभाग → कर्मचारी चार्ट में। यह कौन-सा डेटा मॉडल है?","optionsHi":["हाइरार्किकल मॉडल","नेटवर्क मॉडल","रिलेशनल मॉडल","ऑब्जेक्ट-ओरिएंटेड मॉडल"],"explanationHi":"हाइरार्किकल मॉडल प्रत्येक चाइल्ड के लिए एक पैरेंट की अनुमति देता है। नेटवर्क मॉडल रिकॉर्ड के कई पैरेंट की अनुमति देता है, और रिलेशनल मॉडल कुंजियों से जुड़ी तालिकाएँ प्रयोग करता है।"},
  {"id":"comp-awareness-393","question":"In the three-schema (ANSI/SPARC) architecture, the part of the database that one user group sees, such as the loan officers' view, is defined at the:","options":["Internal level","Conceptual level","Physical level","External level"],"answer":3,"explanation":"The external level holds the individual user views; the conceptual level describes the whole database's logical structure; the internal (physical) level describes storage.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"थ्री-स्कीमा (ANSI/SPARC) आर्किटेक्चर में, डेटाबेस का वह भाग जो किसी एक उपयोगकर्ता समूह को दिखता है, जैसे ऋण अधिकारियों का दृश्य, किस स्तर पर परिभाषित होता है?","optionsHi":["आंतरिक स्तर","संकल्पनात्मक स्तर","भौतिक स्तर","बाह्य स्तर"],"explanationHi":"बाह्य स्तर पर व्यक्तिगत उपयोगकर्ता दृश्य होते हैं; संकल्पनात्मक स्तर पूरे डेटाबेस की तार्किक संरचना का वर्णन करता है; आंतरिक (भौतिक) स्तर संग्रहण का वर्णन करता है।"},
  {"id":"comp-awareness-394","question":"A table has 8 columns and 120 rows. What are its degree and its cardinality?","options":["Degree 120, cardinality 8","Degree 8, cardinality 960","Degree 8, cardinality 120","Degree 128, cardinality 8"],"answer":2,"explanation":"Degree is the number of attributes (columns) and cardinality is the number of tuples (rows): 8 and 120.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"एक तालिका में 8 स्तंभ और 120 पंक्तियाँ हैं। उसकी डिग्री और कार्डिनैलिटी क्या हैं?","optionsHi":["डिग्री 120, कार्डिनैलिटी 8","डिग्री 8, कार्डिनैलिटी 960","डिग्री 8, कार्डिनैलिटी 120","डिग्री 128, कार्डिनैलिटी 8"],"explanationHi":"डिग्री एट्रिब्यूट (स्तंभ) की संख्या है और कार्डिनैलिटी टपल (पंक्ति) की संख्या: 8 और 120।"},
  {"id":"comp-awareness-395","question":"Which relational algebra operation picks out chosen COLUMNS of a relation and removes any duplicate rows that result?","options":["Selection (σ)","Projection (π)","Cartesian product (×)","Union (∪)"],"answer":1,"explanation":"Projection keeps the listed attributes, and since a relation is a set, duplicate tuples disappear. Selection picks rows that satisfy a condition.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"कौन-सी रिलेशनल बीजगणित संक्रिया किसी रिलेशन के चुने हुए स्तंभ निकालती है और परिणामी दोहराई गई पंक्तियाँ हटा देती है?","optionsHi":["सेलेक्शन (σ)","प्रोजेक्शन (π)","कार्तीय गुणनफल (×)","यूनियन (∪)"],"explanationHi":"प्रोजेक्शन सूचीबद्ध एट्रिब्यूट रखता है, और चूँकि रिलेशन एक समुच्चय है, दोहराए गए टपल लुप्त हो जाते हैं। सेलेक्शन शर्त पूरी करने वाली पंक्तियाँ चुनता है।"},
  {"id":"comp-awareness-396","question":"A data warehouse, unlike a bank's day-to-day transaction database, is mainly designed for:","options":["Recording thousands of small deposits and withdrawals each second","Analysing large volumes of historical data for reports and decisions","Storing user passwords securely in encrypted form","Running the operating system's file and memory management"],"answer":1,"explanation":"A warehouse collects historical data from many sources for analysis (OLAP). Many small live transactions are the job of an OLTP database.","difficulty":"moderate","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"डेटा वेयरहाउस, बैंक के दैनिक लेन-देन डेटाबेस के विपरीत, मुख्यतः किसके लिए बनाया जाता है?","optionsHi":["प्रति सेकंड हज़ारों छोटी जमा और निकासी दर्ज करना","रिपोर्टों और निर्णयों के लिए ऐतिहासिक डेटा की बड़ी मात्रा का विश्लेषण करना","उपयोगकर्ता पासवर्ड को एन्क्रिप्टेड रूप में सुरक्षित संग्रहीत करना","ऑपरेटिंग सिस्टम का फ़ाइल और मेमोरी प्रबंधन चलाना"],"explanationHi":"वेयरहाउस विश्लेषण (OLAP) के लिए कई स्रोतों से ऐतिहासिक डेटा एकत्र करता है। कई छोटे जीवंत लेन-देन OLTP डेटाबेस का काम हैं।"},
  {"id":"comp-awareness-397","question":"Which statement about a view in SQL is correct?","options":["It is a physical copy of a table, refreshed once a day","It is an index that makes searches on a column faster","It is a backup of the table kept in a separate file","It is a stored query that appears to users as a virtual table"],"answer":3,"explanation":"A view stores the SELECT, not the data; each use runs the query on the base tables. Views can hide columns and simplify complex joins for users.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"SQL में व्यू के बारे में कौन-सा कथन सही है?","optionsHi":["यह तालिका की भौतिक प्रति है जो दिन में एक बार रिफ़्रेश होती है","यह एक इंडेक्स है जो किसी स्तंभ पर खोज तेज़ करता है","यह अलग फ़ाइल में रखा तालिका का बैकअप है","यह एक संग्रहीत क्वेरी है जो उपयोगकर्ताओं को वर्चुअल तालिका जैसी दिखती है"],"explanationHi":"व्यू SELECT को संग्रहीत करता है, डेटा को नहीं; प्रत्येक प्रयोग पर क्वेरी आधार तालिकाओं पर चलती है। व्यू स्तंभों को छिपा सकते हैं और उपयोगकर्ताओं के लिए जटिल जॉइन सरल कर सकते हैं।"},
  {"id":"comp-awareness-398","question":"A bank wants a log entry to be written automatically whenever a row in the ACCOUNTS table is updated, without the application doing it. Which database object does this?","options":["A view","An index","A trigger","A cursor"],"answer":2,"explanation":"A trigger is code the DBMS runs automatically on an INSERT, UPDATE or DELETE event. A cursor steps through query results one row at a time.","difficulty":"moderate","source":"IBPS SO IT Officer","questionHi":"एक बैंक चाहता है कि ACCOUNTS तालिका की किसी पंक्ति के अद्यतन होने पर लॉग प्रविष्टि अपने आप लिखी जाए, एप्लिकेशन के किए बिना। यह कौन-सा डेटाबेस ऑब्जेक्ट करता है?","optionsHi":["व्यू","इंडेक्स","ट्रिगर","कर्सर"],"explanationHi":"ट्रिगर वह कोड है जिसे DBMS INSERT, UPDATE या DELETE घटना पर अपने आप चलाता है। कर्सर क्वेरी परिणामों को एक-एक पंक्ति करके पार करता है।"},
  {"id":"comp-awareness-399","question":"ORDERS.CustomerID is a foreign key to CUSTOMER, declared with ON DELETE CASCADE. What happens when a customer row is deleted?","options":["The delete is refused while any order for that customer exists","The customer's orders are deleted automatically along with it","The CustomerID in that customer's orders is set to NULL","The orders are kept unchanged and point to a missing customer"],"answer":1,"explanation":"CASCADE propagates the delete to the referencing rows. Refusing the delete is the default (RESTRICT/NO ACTION) and setting NULL is ON DELETE SET NULL.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"ORDERS.CustomerID, CUSTOMER की फ़ॉरेन की है, जो ON DELETE CASCADE के साथ घोषित है। ग्राहक की पंक्ति हटाने पर क्या होता है?","optionsHi":["उस ग्राहक का कोई भी ऑर्डर रहने तक हटाना अस्वीकार कर दिया जाता है","ग्राहक के ऑर्डर उसके साथ अपने आप हट जाते हैं","उस ग्राहक के ऑर्डरों में CustomerID NULL कर दिया जाता है","ऑर्डर अपरिवर्तित रहते हैं और अनुपस्थित ग्राहक की ओर संकेत करते हैं"],"explanationHi":"CASCADE हटाने को संदर्भित पंक्तियों तक फैलाता है। हटाने को अस्वीकार करना डिफ़ॉल्ट (RESTRICT/NO ACTION) है और NULL करना ON DELETE SET NULL है।"},
  {"id":"comp-awareness-400","question":"In ENROLMENT(StudentID, CourseID, Grade), a student takes many courses and a course has many students, but a student takes a course only once. What is the primary key?","options":["StudentID on its own","CourseID on its own","The pair (StudentID, Grade)","The pair (StudentID, CourseID)"],"answer":3,"explanation":"Neither ID alone is unique, since both repeat; together they identify one enrolment. A key made of two or more attributes is a composite key.","difficulty":"moderate","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"ENROLMENT(StudentID, CourseID, Grade) में एक छात्र कई पाठ्यक्रम लेता है और एक पाठ्यक्रम में कई छात्र होते हैं, पर कोई छात्र एक पाठ्यक्रम केवल एक बार लेता है। प्राइमरी की क्या है?","optionsHi":["अकेला StudentID","अकेला CourseID","युग्म (StudentID, Grade)","युग्म (StudentID, CourseID)"],"explanationHi":"कोई भी ID अकेली अद्वितीय नहीं है, क्योंकि दोनों दोहराई जाती हैं; साथ मिलकर वे एक नामांकन की पहचान करती हैं। दो या अधिक एट्रिब्यूट से बनी की कंपोज़िट की कहलाती है।"},
  {"id":"comp-awareness-401","question":"Which pairing of computer generation and its key technology is WRONG?","options":["Fourth generation – artificial intelligence as its basic technology","First generation – vacuum tubes and machine language","Second generation – transistors and assembly language","Third generation – integrated circuits and operating systems"],"answer":0,"explanation":"The fourth generation is defined by the VLSI microprocessor; artificial intelligence is the aim of the fifth generation. The other three pairings are correct.","difficulty":"very-hard","source":"SBI Clerk Mains · SSC CGL","questionHi":"कंप्यूटर की पीढ़ी और उसकी प्रमुख तकनीक का कौन-सा युग्म गलत है?","optionsHi":["चतुर्थ पीढ़ी – कृत्रिम बुद्धिमत्ता उसकी मूल तकनीक के रूप में","प्रथम पीढ़ी – निर्वात नलिकाएँ और मशीन भाषा","द्वितीय पीढ़ी – ट्रांजिस्टर और असेंबली भाषा","तृतीय पीढ़ी – एकीकृत परिपथ और ऑपरेटिंग सिस्टम"],"explanationHi":"चतुर्थ पीढ़ी की पहचान VLSI माइक्रोप्रोसेसर से होती है; कृत्रिम बुद्धिमत्ता पाँचवीं पीढ़ी का लक्ष्य है। शेष तीनों युग्म सही हैं।"},
  {"id":"comp-awareness-402","question":"ENIAC, completed in 1945 to compute artillery firing tables, was built with which technology and which number system?","options":["Vacuum tubes; it worked in binary","Vacuum tubes; it worked in decimal","Transistors; it worked in binary","Electromechanical relays; it worked in decimal"],"answer":1,"explanation":"ENIAC used about 18,000 vacuum tubes and did decimal arithmetic with ten-position ring counters; binary stored-program designs such as EDVAC came after it.","difficulty":"very-hard","source":"SSC CGL · IBPS PO Mains","questionHi":"1945 में पूर्ण हुआ ENIAC, जिसे तोपख़ाने की फ़ायरिंग तालिकाएँ गणना करने के लिए बनाया गया था, किस तकनीक और किस संख्या पद्धति से बना था?","optionsHi":["निर्वात नलिकाएँ; यह बाइनरी में काम करता था","निर्वात नलिकाएँ; यह दशमलव में काम करता था","ट्रांजिस्टर; यह बाइनरी में काम करता था","विद्युत-यांत्रिक रिले; यह दशमलव में काम करता था"],"explanationHi":"ENIAC में लगभग 18,000 निर्वात नलिकाएँ थीं और वह दस-स्थान वाले रिंग काउंटरों से दशमलव अंकगणित करता था; EDVAC जैसे बाइनरी संग्रहीत-प्रोग्राम डिज़ाइन उसके बाद आए।"},
  {"id":"comp-awareness-403","question":"The 'stored-program' concept, in which a computer's instructions are kept in the same memory as its data, is chiefly associated with:","options":["Charles Babbage","Herman Hollerith","Blaise Pascal","John von Neumann"],"answer":3,"explanation":"Von Neumann's 1945 EDVAC report set out the stored-program design that most computers still follow. Babbage designed the Analytical Engine, and Hollerith built punched-card tabulators.","difficulty":"moderate","source":"SSC CGL · SBI Clerk Mains","questionHi":"‘संग्रहीत-प्रोग्राम’ अवधारणा, जिसमें कंप्यूटर के निर्देश उसके डेटा वाली ही मेमोरी में रखे जाते हैं, मुख्यतः किससे जुड़ी है?","optionsHi":["चार्ल्स बैबेज","हरमन होलेरिथ","ब्लेज़ पास्कल","जॉन वॉन न्यूमैन"],"explanationHi":"वॉन न्यूमैन की 1945 की EDVAC रिपोर्ट ने वह संग्रहीत-प्रोग्राम डिज़ाइन रखा जिसका अधिकांश कंप्यूटर आज भी अनुसरण करते हैं। बैबेज ने एनालिटिकल इंजन की रचना की, और होलेरिथ ने पंच-कार्ड सारणीकरण मशीनें बनाईं।"},
  {"id":"comp-awareness-404","question":"Herman Hollerith's punched-card tabulating machine, whose company later grew into IBM, was first used on a large scale for:","options":["The 1890 United States census","Breaking German codes in the Second World War","Calculating artillery tables in 1945","Controlling the patterns on weaving looms"],"answer":0,"explanation":"Hollerith's machines processed the 1890 US census far faster than hand counting. Punched cards for looms came earlier from Jacquard, and code-breaking was the work of machines such as Colossus.","difficulty":"hard","source":"SSC CGL · SBI Clerk Mains","questionHi":"हरमन होलेरिथ की पंच-कार्ड सारणीकरण मशीन, जिसकी कंपनी आगे चलकर IBM बनी, पहली बार बड़े पैमाने पर किसके लिए प्रयोग हुई?","optionsHi":["1890 की संयुक्त राज्य अमेरिका की जनगणना","द्वितीय विश्वयुद्ध में जर्मन कोड तोड़ना","1945 में तोपख़ाने की तालिकाओं की गणना","बुनाई करघों के पैटर्न नियंत्रित करना"],"explanationHi":"होलेरिथ की मशीनों ने 1890 की अमेरिकी जनगणना को हाथ से गिनने की तुलना में कहीं तेज़ी से संसाधित किया। करघों के लिए पंच कार्ड पहले जैकार्ड से आए थे, और कोड तोड़ना कोलोसस जैसी मशीनों का काम था।"},
  {"id":"comp-awareness-405","question":"Which early mechanical calculator could multiply, by repeated addition using a stepped drum, and not just add and subtract?","options":["Pascal's Pascaline adding machine","Napier's bones multiplying rods","Leibniz's Stepped Reckoner","The Chinese abacus"],"answer":2,"explanation":"Leibniz's Stepped Reckoner (late 1600s) added a stepped drum for multiplication and division. The Pascaline only added and subtracted, and Napier's bones were rods for manual multiplication.","difficulty":"hard","source":"SSC CGL · SBI Clerk Mains","questionHi":"कौन-सा प्रारंभिक यांत्रिक कैलकुलेटर स्टेप्ड ड्रम का प्रयोग करके बार-बार जोड़ द्वारा गुणा भी कर सकता था, केवल जोड़-घटाव ही नहीं?","optionsHi":["पास्कल की पास्कलाइन जोड़ने वाली मशीन","नेपियर की हड्डियाँ (गुणा की छड़ें)","लाइबनिट्ज़ का स्टेप्ड रेकनर","चीनी अबेकस"],"explanationHi":"लाइबनिट्ज़ के स्टेप्ड रेकनर (1600 के दशक के उत्तरार्ध) ने गुणा और भाग के लिए स्टेप्ड ड्रम जोड़ा। पास्कलाइन केवल जोड़ और घटा सकती थी, और नेपियर की हड्डियाँ हाथ से गुणा करने की छड़ें थीं।"},
  {"id":"comp-awareness-406","question":"Who is regarded as the first computer programmer for her notes containing an algorithm for Charles Babbage's Analytical Engine?","options":["Ada Lovelace","Grace Hopper","Mary Somerville","Hedy Lamarr"],"answer":0,"explanation":"Ada Lovelace published an algorithm to compute Bernoulli numbers on the Analytical Engine in 1843. Grace Hopper came a century later and developed early compilers.","difficulty":"moderate","source":"SSC CGL · SBI Clerk Mains","questionHi":"चार्ल्स बैबेज के एनालिटिकल इंजन के लिए एल्गोरिदम वाले अपने नोट्स के कारण पहला कंप्यूटर प्रोग्रामर किसे माना जाता है?","optionsHi":["एडा लवलेस","ग्रेस हॉपर","मैरी समरविल","हेडी लामार"],"explanationHi":"एडा लवलेस ने 1843 में एनालिटिकल इंजन पर बर्नूली संख्याओं की गणना करने का एल्गोरिदम प्रकाशित किया। ग्रेस हॉपर एक सदी बाद आईं और उन्होंने प्रारंभिक कंपाइलर विकसित किए।"},
  {"id":"comp-awareness-407","question":"The Intel 4004 of 1971, the first commercially sold single-chip microprocessor, processed data in units of how many bits?","options":["8 bits","16 bits","4 bits","32 bits"],"answer":2,"explanation":"The 4004 was a 4-bit processor designed for a calculator; the 8-bit 8008 and 8080 followed it.","difficulty":"very-hard","source":"SSC CGL · SBI Clerk Mains","questionHi":"1971 का Intel 4004, पहला व्यावसायिक रूप से बिका एकल-चिप माइक्रोप्रोसेसर, डेटा को कितने बिट की इकाइयों में संसाधित करता था?","optionsHi":["8 बिट","16 बिट","4 बिट","32 बिट"],"explanationHi":"4004 एक 4-बिट प्रोसेसर था जिसे कैलकुलेटर के लिए बनाया गया था; 8-बिट 8008 और 8080 उसके बाद आए।"},
  {"id":"comp-awareness-408","question":"The Turing Test, proposed by Alan Turing in 1950, checks whether:","options":["A program always halts on every possible input","A machine solves any problem a human can solve faster","A machine's replies in conversation cannot be told apart from a human's","A computer can be built from a tape, a head and a table of rules"],"answer":2,"explanation":"In the 'imitation game' a judge chats by text; if the judge cannot reliably tell the machine from a human, it passes. The tape-and-head model is the Turing machine, and halting is a separate problem.","difficulty":"hard","source":"SSC CGL · IBPS PO Mains","questionHi":"एलन ट्यूरिंग द्वारा 1950 में प्रस्तावित ट्यूरिंग टेस्ट जाँचता है कि:","optionsHi":["क्या कोई प्रोग्राम प्रत्येक संभव इनपुट पर सदा रुक जाता है","क्या कोई मशीन वह प्रत्येक समस्या अधिक तेज़ी से हल करती है जिसे मनुष्य हल कर सकता है","क्या बातचीत में किसी मशीन के उत्तर मनुष्य के उत्तरों से अलग पहचाने नहीं जा सकते","क्या कंप्यूटर को टेप, हेड और नियमों की तालिका से बनाया जा सकता है"],"explanationHi":"‘इमिटेशन गेम’ में न्यायाधीश पाठ द्वारा बातचीत करता है; यदि वह मशीन को मनुष्य से विश्वसनीय रूप से अलग नहीं कर पाता तो मशीन उत्तीर्ण होती है। टेप-और-हेड मॉडल ट्यूरिंग मशीन है, और रुकना (हॉल्टिंग) एक अलग समस्या है।"},
  {"id":"comp-awareness-409","question":"SQL, in which a user states what data is wanted rather than how to fetch it step by step, is usually classed as which generation of programming language?","options":["Second generation (2GL)","Third generation (3GL)","Fifth generation (5GL)","Fourth generation (4GL)"],"answer":3,"explanation":"1GL is machine code, 2GL assembly, 3GL procedural languages such as C, and 4GL non-procedural languages such as SQL. 5GL describes logic languages like Prolog.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer","questionHi":"SQL, जिसमें उपयोगकर्ता बताता है कि कौन-सा डेटा चाहिए, न कि उसे चरण-दर-चरण कैसे लाया जाए, सामान्यतः प्रोग्रामिंग भाषा की किस पीढ़ी में वर्गीकृत है?","optionsHi":["द्वितीय पीढ़ी (2GL)","तृतीय पीढ़ी (3GL)","पाँचवीं पीढ़ी (5GL)","चतुर्थ पीढ़ी (4GL)"],"explanationHi":"1GL मशीन कोड है, 2GL असेंबली, 3GL C जैसी प्रक्रियात्मक भाषाएँ, और 4GL SQL जैसी अप्रक्रियात्मक भाषाएँ। 5GL Prolog जैसी लॉजिक भाषाओं का वर्णन करती है।"},
  {"id":"comp-awareness-410","question":"Prolog, long used in artificial intelligence, is an example of which programming style?","options":["Logic programming, based on facts and rules","Procedural programming, based on step-by-step commands","Assembly programming, based on processor mnemonics","Markup, based on tags that describe document layout"],"answer":0,"explanation":"A Prolog program states facts and rules, and the system infers answers to queries. It is not procedural like C, and markup languages like HTML are not programming languages at all.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer","questionHi":"कृत्रिम बुद्धिमत्ता में लंबे समय से प्रयुक्त Prolog किस प्रोग्रामिंग शैली का उदाहरण है?","optionsHi":["लॉजिक प्रोग्रामिंग, जो तथ्यों और नियमों पर आधारित है","प्रक्रियात्मक प्रोग्रामिंग, जो चरण-दर-चरण आदेशों पर आधारित है","असेंबली प्रोग्रामिंग, जो प्रोसेसर निमोनिक पर आधारित है","मार्कअप, जो दस्तावेज़ लेआउट वर्णित करने वाले टैगों पर आधारित है"],"explanationHi":"Prolog प्रोग्राम तथ्य और नियम बताता है, और प्रणाली प्रश्नों के उत्तर अनुमानित करती है। यह C जैसी प्रक्रियात्मक नहीं है, और HTML जैसी मार्कअप भाषाएँ प्रोग्रामिंग भाषाएँ ही नहीं हैं।"},
  {"id":"comp-awareness-411","question":"A compiler translates a C source file. What is its output called, before the linker combines it with library code?","options":["Executable code","Object code","Byte code","Source code"],"answer":1,"explanation":"The compiler produces object code, machine code with unresolved references; the linker joins object files and libraries into an executable. Byte code is the output of compilers for virtual machines such as Java's.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer","questionHi":"एक कंपाइलर C स्रोत फ़ाइल का अनुवाद करता है। लिंकर द्वारा उसे लाइब्रेरी कोड से जोड़ने से पहले उसके आउटपुट को क्या कहते हैं?","optionsHi":["एक्ज़ीक्यूटेबल कोड","ऑब्जेक्ट कोड","बाइट कोड","स्रोत कोड"],"explanationHi":"कंपाइलर ऑब्जेक्ट कोड बनाता है, जो अनसुलझे संदर्भों वाला मशीन कोड है; लिंकर ऑब्जेक्ट फ़ाइलों और लाइब्रेरियों को जोड़कर एक्ज़ीक्यूटेबल बनाता है। बाइट कोड Java जैसी वर्चुअल मशीनों के कंपाइलरों का आउटपुट है।"},
  {"id":"comp-awareness-412","question":"Match the flowchart symbol with its use: 1. Diamond 2. Parallelogram 3. Oval 4. Rectangle; a. Start or end b. Processing step c. Decision d. Input or output","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-c, 2-a, 3-d, 4-b"],"answer":0,"explanation":"A diamond holds a yes/no decision, a parallelogram input or output, an oval (terminal) the start or end, and a rectangle a processing step.","difficulty":"hard","source":"SBI Clerk Mains · SSC CGL","questionHi":"फ़्लोचार्ट प्रतीक का उसके प्रयोग से मिलान कीजिए: 1. समचतुर्भुज (डायमंड) 2. समांतर चतुर्भुज 3. अंडाकार 4. आयत; a. आरंभ या अंत b. प्रक्रमण चरण c. निर्णय d. इनपुट या आउटपुट","optionsHi":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-c, 2-a, 3-d, 4-b"],"explanationHi":"समचतुर्भुज में हाँ/नहीं का निर्णय होता है, समांतर चतुर्भुज में इनपुट या आउटपुट, अंडाकार (टर्मिनल) में आरंभ या अंत, और आयत में प्रक्रमण चरण।"},
  {"id":"comp-awareness-413","question":"A company modifies a program released under the GNU GPL and distributes the modified version to customers. What does the GPL require?","options":["It must pay the original authors a royalty on every copy sold","It must make the modified source code available under the GPL too","It may keep its changes secret as long as it credits the authors","It may distribute only the compiled program, never the source"],"answer":1,"explanation":"The GPL is a 'copyleft' licence: anyone who distributes a modified version must release its source under the same terms. It does not require royalties; selling copies is allowed.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक कंपनी GNU GPL के अंतर्गत जारी किसी प्रोग्राम को संशोधित करती है और संशोधित संस्करण ग्राहकों को वितरित करती है। GPL क्या अपेक्षा करता है?","optionsHi":["उसे बेची गई प्रत्येक प्रति पर मूल लेखकों को रॉयल्टी देनी होगी","उसे संशोधित स्रोत कोड भी GPL के अंतर्गत उपलब्ध कराना होगा","जब तक वह लेखकों को श्रेय देती है, वह अपने परिवर्तन गुप्त रख सकती है","वह केवल संकलित प्रोग्राम वितरित कर सकती है, स्रोत कभी नहीं"],"explanationHi":"GPL ‘कॉपीलेफ़्ट’ लाइसेंस है: संशोधित संस्करण वितरित करने वाले को उसका स्रोत उन्हीं शर्तों पर जारी करना होगा। इसमें रॉयल्टी आवश्यक नहीं; प्रतियाँ बेचना अनुमत है।"},
  {"id":"comp-awareness-414","question":"Software that is stored permanently in a device's ROM or flash memory and directly controls its hardware, such as the BIOS or a router's control program, is called:","options":["Firmware","Middleware","Shareware","Freeware"],"answer":0,"explanation":"Firmware sits between hardware and higher software and survives power-off. Middleware connects applications; shareware and freeware are distribution models.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"वह सॉफ्टवेयर जो किसी उपकरण की ROM या फ्लैश मेमोरी में स्थायी रूप से संग्रहीत रहता है और उसके हार्डवेयर को सीधे नियंत्रित करता है, जैसे BIOS या राउटर का नियंत्रण प्रोग्राम, कहलाता है:","optionsHi":["फ़र्मवेयर","मिडलवेयर","शेयरवेयर","फ़्रीवेयर"],"explanationHi":"फ़र्मवेयर हार्डवेयर और उच्च-स्तरीय सॉफ्टवेयर के बीच रहता है और बिजली बंद होने पर भी बना रहता है। मिडलवेयर एप्लिकेशनों को जोड़ता है; शेयरवेयर और फ़्रीवेयर वितरण मॉडल हैं।"},
  {"id":"comp-awareness-415","question":"Which of these is utility software rather than application software?","options":["A spreadsheet program","A disk defragmenter","A web browser","A presentation program"],"answer":1,"explanation":"Utilities maintain and tune the computer itself, such as defragmenters, backup tools and antivirus. Spreadsheets, browsers and presentation programs do the user's own tasks.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CGL","questionHi":"इनमें से कौन-सा एप्लिकेशन सॉफ्टवेयर के बजाय यूटिलिटी सॉफ्टवेयर है?","optionsHi":["स्प्रेडशीट प्रोग्राम","डिस्क डीफ़्रैग्मेंटर","वेब ब्राउज़र","प्रेज़ेंटेशन प्रोग्राम"],"explanationHi":"यूटिलिटी कंप्यूटर के रखरखाव और ट्यूनिंग का काम करती हैं, जैसे डीफ़्रैग्मेंटर, बैकअप उपकरण और एंटीवायरस। स्प्रेडशीट, ब्राउज़र और प्रेज़ेंटेशन प्रोग्राम उपयोगकर्ता के अपने कार्य करते हैं।"},
  {"id":"comp-awareness-416","question":"Which single logic gate can act as a 1-bit equality comparator, giving 1 exactly when its two inputs are the same?","options":["XOR","NAND","XNOR","OR"],"answer":2,"explanation":"XNOR outputs 1 for inputs 00 and 11 and 0 otherwise, so it signals equality. XOR does the opposite, signalling a difference.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL","questionHi":"कौन-सा एकल लॉजिक गेट 1-बिट समानता तुलनित्र का कार्य कर सकता है, जो ठीक तभी 1 देता है जब उसके दोनों इनपुट समान हों?","optionsHi":["XOR","NAND","XNOR","OR"],"explanationHi":"XNOR इनपुट 00 और 11 पर 1 और अन्यथा 0 देता है, इसलिए वह समानता का संकेत देता है। XOR इसके उलट, अंतर का संकेत देता है।"},
  {"id":"comp-awareness-417","question":"How is a full adder usually built from half adders?","options":["Two half adders, with their carry outputs joined by an AND gate","Three half adders, with no extra gate needed","Two half adders, with their carry outputs joined by an OR gate","One half adder with an extra XOR gate on its carry output"],"answer":2,"explanation":"The first half adder adds A and B, the second adds that sum to Cin; the final carry is 1 if either half adder produced a carry, so the two carries go through an OR gate.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"फ़ुल एडर सामान्यतः हाफ़ एडरों से कैसे बनता है?","optionsHi":["दो हाफ़ एडर, जिनके कैरी आउटपुट AND गेट से जुड़े हों","तीन हाफ़ एडर, किसी अतिरिक्त गेट की आवश्यकता नहीं","दो हाफ़ एडर, जिनके कैरी आउटपुट OR गेट से जुड़े हों","एक हाफ़ एडर, जिसके कैरी आउटपुट पर एक अतिरिक्त XOR गेट हो"],"explanationHi":"पहला हाफ़ एडर A और B जोड़ता है, दूसरा उस योग में Cin जोड़ता है; अंतिम कैरी 1 होता है यदि किसी भी हाफ़ एडर ने कैरी उत्पन्न की, इसलिए दोनों कैरी OR गेट से गुज़रती हैं।"},
  {"id":"comp-awareness-418","question":"A 32-to-1 multiplexer must be built using only 8-to-1 multiplexers. What is the least number of 8-to-1 multiplexers needed?","options":["4","6","8","5"],"answer":3,"explanation":"Four 8-to-1 units take the 32 inputs and give 4 outputs; one more 8-to-1 unit (using 4 of its inputs) selects among them, so 5 in all, controlled by 5 select lines.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"32-टू-1 मल्टीप्लेक्सर को केवल 8-टू-1 मल्टीप्लेक्सरों से बनाना है। न्यूनतम कितने 8-टू-1 मल्टीप्लेक्सर चाहिए?","optionsHi":["4","6","8","5"],"explanationHi":"चार 8-टू-1 इकाइयाँ 32 इनपुट लेकर 4 आउटपुट देती हैं; एक और 8-टू-1 इकाई (अपने 4 इनपुट प्रयोग करके) उनमें से चयन करती है, इसलिए कुल 5, जो 5 सेलेक्ट लाइनों से नियंत्रित होते हैं।"},
  {"id":"comp-awareness-419","question":"In which flip-flop is the input combination 1, 1 not allowed, because it leaves the outputs in an invalid state?","options":["JK flip-flop","D flip-flop","T flip-flop","SR flip-flop"],"answer":3,"explanation":"Setting S = R = 1 on an SR flip-flop forces both outputs to the same value, which is forbidden. The JK flip-flop turns 1, 1 into a toggle instead.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"किस फ़्लिप-फ़्लॉप में इनपुट संयोजन 1, 1 अनुमत नहीं है, क्योंकि वह आउटपुट को अवैध अवस्था में छोड़ देता है?","optionsHi":["JK फ़्लिप-फ़्लॉप","D फ़्लिप-फ़्लॉप","T फ़्लिप-फ़्लॉप","SR फ़्लिप-फ़्लॉप"],"explanationHi":"SR फ़्लिप-फ़्लॉप में S = R = 1 रखने पर दोनों आउटपुट एक ही मान पर चले जाते हैं, जो वर्जित है। JK फ़्लिप-फ़्लॉप 1, 1 को टॉगल में बदल देता है।"},
  {"id":"comp-awareness-420","question":"How many different Boolean functions of two input variables are possible?","options":["4","16","8","256"],"answer":1,"explanation":"Two inputs give 2² = 4 truth-table rows, and each row's output can be 0 or 1, so there are 2⁴ = 16 functions. 4 counts only the rows, and 256 is the count for three inputs' 8 rows.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"दो इनपुट चरों के कितने भिन्न बूलियन फ़ंक्शन संभव हैं?","optionsHi":["4","16","8","256"],"explanationHi":"दो इनपुट से 2² = 4 सत्य-सारणी पंक्तियाँ बनती हैं, और प्रत्येक पंक्ति का आउटपुट 0 या 1 हो सकता है, इसलिए 2⁴ = 16 फ़ंक्शन हैं। 4 केवल पंक्तियाँ गिनता है, और 256 तीन इनपुटों की 8 पंक्तियों की गिनती है।"},
  {"id":"comp-awareness-421","question":"The Boolean expression (A + B)(A + C) simplifies to:","options":["A + BC","AB + AC","A + B + C","AB + C"],"answer":0,"explanation":"Expanding gives A·A + A·C + A·B + B·C = A(1 + C + B) + BC = A + BC. This is the distributive law of OR over AND, which has no counterpart in ordinary algebra.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"बूलियन व्यंजक (A + B)(A + C) सरल होकर बनता है:","optionsHi":["A + BC","AB + AC","A + B + C","AB + C"],"explanationHi":"प्रसार करने पर A·A + A·C + A·B + B·C = A(1 + C + B) + BC = A + BC मिलता है। यह OR का AND पर वितरण नियम है, जिसका साधारण बीजगणित में कोई समतुल्य नहीं है।"},
  {"id":"comp-awareness-422","question":"A NOR gate has a signal A on one input and its complement A′ on the other. What is the output?","options":["Always 0","Always 1","Equal to A","Equal to NOT A"],"answer":0,"explanation":"A + A′ is always 1, so its NOR, the complement, is always 0, whatever A is.","difficulty":"hard","source":"IBPS SO IT Officer · SSC CGL","questionHi":"एक NOR गेट के एक इनपुट पर सिग्नल A और दूसरे पर उसका पूरक A′ है। आउटपुट क्या है?","optionsHi":["सदैव 0","सदैव 1","A के बराबर","NOT A के बराबर"],"explanationHi":"A + A′ सदैव 1 होता है, इसलिए उसका NOR, अर्थात् पूरक, A चाहे जो हो सदैव 0 होता है।"},
  {"id":"comp-awareness-423","question":"In a 4-variable Karnaugh map, a valid group of 8 adjacent 1s gives a product term with how many literals?","options":["3","2","8","1"],"answer":3,"explanation":"A group of 2ᵏ cells removes k variables; 8 = 2³ removes 3 of the 4, leaving a single literal. A group of 4 would leave 2 literals.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"4-चर कार्नो मैप में 8 आसन्न 1 का वैध समूह कितने लिटरल वाला गुणन-पद देता है?","optionsHi":["3","2","8","1"],"explanationHi":"2ᵏ सेलों का समूह k चर हटाता है; 8 = 2³ चारों में से 3 हटाता है, जिससे एक ही लिटरल बचता है। 4 का समूह 2 लिटरल छोड़ता।"},
  {"id":"comp-awareness-424","question":"An ICU machine measures continuous signals such as heartbeat and blood pressure and converts them into numbers for digital processing and display. What kind of computer is it?","options":["Analog computer","Digital computer","Hybrid computer","Mainframe computer"],"answer":2,"explanation":"It takes analog inputs and processes them digitally, combining both kinds of computer. A purely analog or purely digital machine would do only one of these.","difficulty":"moderate","source":"SBI Clerk Mains · SSC CGL","questionHi":"एक ICU मशीन हृदय-गति और रक्तचाप जैसे सतत सिग्नल मापती है और उन्हें डिजिटल प्रक्रमण और प्रदर्शन के लिए संख्याओं में बदलती है। यह किस प्रकार का कंप्यूटर है?","optionsHi":["एनालॉग कंप्यूटर","डिजिटल कंप्यूटर","हाइब्रिड कंप्यूटर","मेनफ़्रेम कंप्यूटर"],"explanationHi":"यह एनालॉग इनपुट लेकर उन्हें डिजिटल रूप से प्रक्रमित करता है, यानी दोनों प्रकार के कंप्यूटरों को जोड़ता है। विशुद्ध एनालॉग या विशुद्ध डिजिटल मशीन इनमें से केवल एक ही करती।"},
  {"id":"comp-awareness-425","question":"A large bank's central computer supports thousands of terminals and processes millions of transactions a day with very high reliability. It is best classed as a:","options":["Supercomputer","Minicomputer","Workstation","Mainframe"],"answer":3,"explanation":"Mainframes are built for huge volumes of simultaneous transactions and users. Supercomputers are built for raw calculation speed on scientific problems, not transaction processing.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"किसी बड़े बैंक का केंद्रीय कंप्यूटर हज़ारों टर्मिनलों को सहारा देता है और अत्यंत उच्च विश्वसनीयता के साथ प्रतिदिन लाखों लेन-देन संसाधित करता है। इसे सबसे उपयुक्त रूप से क्या वर्गीकृत किया जाएगा?","optionsHi":["सुपरकंप्यूटर","मिनीकंप्यूटर","वर्कस्टेशन","मेनफ़्रेम"],"explanationHi":"मेनफ़्रेम एक साथ भारी मात्रा में लेन-देन और उपयोगकर्ताओं के लिए बनाए जाते हैं। सुपरकंप्यूटर वैज्ञानिक समस्याओं पर कच्ची गणना-गति के लिए बने हैं, लेन-देन प्रसंस्करण के लिए नहीं।"},
  {"id":"comp-awareness-426","question":"In a pipelined processor, an instruction needs the result of the instruction just ahead of it, but that result has not yet been written back. What kind of hazard is this?","options":["Structural hazard","Control hazard","Data hazard","Cache-miss penalty"],"answer":2,"explanation":"A data hazard arises when an instruction depends on a result still in the pipeline; forwarding or stalls fix it. Structural hazards are clashes over hardware, and control hazards come from branches.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"पाइपलाइन प्रोसेसर में, एक निर्देश को अपने ठीक आगे वाले निर्देश का परिणाम चाहिए, पर वह परिणाम अभी वापस लिखा नहीं गया है। यह किस प्रकार का हैज़र्ड है?","optionsHi":["स्ट्रक्चरल हैज़र्ड","कंट्रोल हैज़र्ड","डेटा हैज़र्ड","कैश-मिस दंड"],"explanationHi":"डेटा हैज़र्ड तब होता है जब कोई निर्देश ऐसे परिणाम पर निर्भर हो जो अभी पाइपलाइन में है; फ़ॉरवर्डिंग या स्टॉल इसे सुलझाते हैं। स्ट्रक्चरल हैज़र्ड हार्डवेयर पर टकराव हैं, और कंट्रोल हैज़र्ड ब्रांच से आते हैं।"},
  {"id":"comp-awareness-427","question":"What value does the MS Excel formula =2+3*2^2 return?","options":["20","14","100","38"],"answer":1,"explanation":"Excel applies ^ first, then *, then +: 2^2 = 4, 3 × 4 = 12, 2 + 12 = 14. Working left to right gives (2 + 3) × 2² = 20.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"MS Excel का सूत्र =2+3*2^2 क्या मान लौटाता है?","optionsHi":["20","14","100","38"],"explanationHi":"Excel पहले ^, फिर *, फिर + लगाता है: 2^2 = 4, 3 × 4 = 12, 2 + 12 = 14। बाएँ से दाएँ चलने पर (2 + 3) × 2² = 20 आता है।"},
  {"id":"comp-awareness-428","question":"A disk spins at 6000 rpm and every track holds 500 equal sectors. Ignoring seek time and rotational delay, how long does it take to read one sector as it passes under the head?","options":["20 µs","10 ms","5 ms","2 µs"],"answer":0,"explanation":"6000 rpm = 100 rotations per second, so one rotation takes 10 ms; one sector passes in 10 ms ÷ 500 = 0.02 ms = 20 µs. 5 ms is the average rotational latency, a different delay.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक डिस्क 6000 rpm पर घूमती है और प्रत्येक ट्रैक में 500 समान सेक्टर हैं। सीक समय और घूर्णी विलंब की उपेक्षा करने पर, हेड के नीचे से गुज़रते समय एक सेक्टर पढ़ने में कितना समय लगता है?","optionsHi":["20 µs","10 ms","5 ms","2 µs"],"explanationHi":"6000 rpm = प्रति सेकंड 100 चक्कर, इसलिए एक चक्कर में 10 ms लगते हैं; एक सेक्टर 10 ms ÷ 500 = 0.02 ms = 20 µs में गुज़रता है। 5 ms औसत घूर्णी विलंब है, जो अलग विलंब है।"},
  {"id":"comp-awareness-429","question":"A system uses 16-bit virtual addresses and a page size of 1 KB. How many pages does the virtual address space have, and how many bits form the page offset?","options":["1024 pages, 6-bit offset","16 pages, 10-bit offset","64 pages, 6-bit offset","64 pages, 10-bit offset"],"answer":3,"explanation":"1 KB = 2¹⁰ bytes needs a 10-bit offset, leaving 16 − 10 = 6 bits for the page number, so 2⁶ = 64 pages.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"एक प्रणाली 16-बिट वर्चुअल पते और 1 KB पेज आकार का प्रयोग करती है। वर्चुअल एड्रेस स्पेस में कितने पेज हैं, और पेज ऑफ़सेट कितने बिट का है?","optionsHi":["1024 पेज, 6-बिट ऑफ़सेट","16 पेज, 10-बिट ऑफ़सेट","64 पेज, 6-बिट ऑफ़सेट","64 पेज, 10-बिट ऑफ़सेट"],"explanationHi":"1 KB = 2¹⁰ बाइट को 10-बिट ऑफ़सेट चाहिए, जिससे पेज संख्या के लिए 16 − 10 = 6 बिट बचते हैं, इसलिए 2⁶ = 64 पेज।"},
  {"id":"comp-awareness-430","question":"Match the MS Excel error value with its usual cause: 1. #DIV/0! 2. #N/A 3. #REF! 4. #NAME?; a. A lookup value was not found b. The formula refers to a deleted cell c. A function name is misspelt d. A number is divided by zero or an empty cell","options":["1-d, 2-b, 3-a, 4-c","1-d, 2-a, 3-b, 4-c","1-a, 2-d, 3-b, 4-c","1-d, 2-a, 3-c, 4-b"],"answer":1,"explanation":"#DIV/0! comes from division by zero, #N/A from a lookup that finds nothing, #REF! from an invalid (often deleted) reference, and #NAME? from text Excel does not recognise, such as =SUMM(A1:A3).","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"MS Excel त्रुटि मान का उसके सामान्य कारण से मिलान कीजिए: 1. #DIV/0! 2. #N/A 3. #REF! 4. #NAME?; a. लुकअप मान नहीं मिला b. सूत्र किसी हटाए गए सेल को संदर्भित करता है c. किसी फ़ंक्शन का नाम गलत लिखा गया है d. किसी संख्या को शून्य या खाली सेल से भाग दिया गया है","optionsHi":["1-d, 2-b, 3-a, 4-c","1-d, 2-a, 3-b, 4-c","1-a, 2-d, 3-b, 4-c","1-d, 2-a, 3-c, 4-b"],"explanationHi":"#DIV/0! शून्य से भाग से आता है, #N/A ऐसे लुकअप से जो कुछ नहीं पाता, #REF! अमान्य (प्रायः हटाए गए) संदर्भ से, और #NAME? ऐसे पाठ से जिसे Excel नहीं पहचानता, जैसे =SUMM(A1:A3)।"},
  {"id":"comp-awareness-431","question":"A company holds the block 172.16.0.0/16 and splits it into equal subnets that must each hold at least 500 hosts. At most how many such subnets can it make?","options":["64","256","512","128"],"answer":3,"explanation":"500 hosts need 9 host bits (2⁹ − 2 = 510), so each subnet is a /23. That leaves 23 − 16 = 7 subnet bits, giving 2⁷ = 128 subnets. 8 host bits allow only 254 hosts.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक कंपनी के पास ब्लॉक 172.16.0.0/16 है और वह उसे समान सबनेटों में बाँटती है जिनमें प्रत्येक में कम से कम 500 होस्ट आ सकें। वह अधिकतम कितने ऐसे सबनेट बना सकती है?","optionsHi":["64","256","512","128"],"explanationHi":"500 होस्ट के लिए 9 होस्ट बिट चाहिए (2⁹ − 2 = 510), इसलिए प्रत्येक सबनेट /23 है। इससे 23 − 16 = 7 सबनेट बिट बचते हैं, जिनसे 2⁷ = 128 सबनेट बनते हैं। 8 होस्ट बिट केवल 254 होस्ट की अनुमति देते हैं।"},
  {"id":"comp-awareness-432","question":"In MS Excel, which entry puts today's date into a cell as a FIXED value that will not change tomorrow?","options":["Typing the formula =TODAY()","Pressing Ctrl + ;","Pressing Ctrl + Shift + ;","Pressing Ctrl + D"],"answer":1,"explanation":"Ctrl + ; types the current date as a constant. =TODAY() recalculates every day, Ctrl + Shift + ; inserts the current time, and Ctrl + D fills down.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"MS Excel में कौन-सी प्रविष्टि आज की तिथि को सेल में निश्चित मान के रूप में डालती है जो कल नहीं बदलेगा?","optionsHi":["सूत्र =TODAY() टाइप करना","Ctrl + ; दबाना","Ctrl + Shift + ; दबाना","Ctrl + D दबाना"],"explanationHi":"Ctrl + ; वर्तमान तिथि को स्थिरांक के रूप में टाइप करता है। =TODAY() प्रतिदिन पुनर्गणना करता है, Ctrl + Shift + ; वर्तमान समय डालता है, और Ctrl + D नीचे भरता है।"},
  {"id":"comp-awareness-433","question":"Match the MS Word shortcut with the paragraph alignment it applies: 1. Ctrl + E 2. Ctrl + J 3. Ctrl + L 4. Ctrl + R; a. Right b. Centre c. Left d. Justify","options":["1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-c, 4-a","1-b, 2-c, 3-d, 4-a","1-b, 2-d, 3-a, 4-c"],"answer":0,"explanation":"Ctrl + E centres (C is taken by Copy), Ctrl + J justifies, Ctrl + L aligns left and Ctrl + R aligns right.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"MS Word शॉर्टकट का उस अनुच्छेद संरेखण से मिलान कीजिए जो वह लगाता है: 1. Ctrl + E 2. Ctrl + J 3. Ctrl + L 4. Ctrl + R; a. दाएँ b. मध्य c. बाएँ d. दोनों ओर (जस्टिफ़ाई)","optionsHi":["1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-c, 4-a","1-b, 2-c, 3-d, 4-a","1-b, 2-d, 3-a, 4-c"],"explanationHi":"Ctrl + E मध्य में करता है (C कॉपी के पास है), Ctrl + J जस्टिफ़ाई करता है, Ctrl + L बाएँ संरेखित करता है और Ctrl + R दाएँ संरेखित करता है।"},
  {"id":"comp-awareness-434","question":"A branch must print a personalised letter for each of 500 customers whose names and addresses are stored in an Excel sheet. Which MS Word feature does this?","options":["Track Changes","Mail Merge","Macros","Find and Replace"],"answer":1,"explanation":"Mail Merge combines one main document with a data source and produces one copy per record, filling in each customer's fields.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"एक शाखा को Excel शीट में संग्रहीत नामों और पतों वाले 500 ग्राहकों में से प्रत्येक के लिए वैयक्तिकृत पत्र छापना है। MS Word की कौन-सी सुविधा यह करती है?","optionsHi":["ट्रैक चेंजेज़","मेल मर्ज","मैक्रोज़","फ़ाइंड एंड रिप्लेस"],"explanationHi":"मेल मर्ज एक मुख्य दस्तावेज़ को डेटा स्रोत से जोड़ता है और प्रत्येक रिकॉर्ड के लिए एक प्रति बनाता है, जिसमें प्रत्येक ग्राहक के फ़ील्ड भरे जाते हैं।"},
  {"id":"comp-awareness-435","question":"A server’s two 1 TB disks are set up as RAID 1. How much usable space results, and what does this arrangement provide?","options":["2 TB, with blocks striped across both disks for speed","2 TB, with parity blocks spread over both disks","1 TB, with blocks striped across both disks for speed","1 TB, with every block mirrored on both disks"],"answer":3,"explanation":"RAID 1 mirrors the disks, so either one can fail without data loss, but usable space is that of one disk. Striping for speed with no redundancy is RAID 0.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"किसी सर्वर की दो 1 TB डिस्कों को RAID 1 के रूप में सेट किया गया है। कितना प्रयोग-योग्य स्थान मिलता है, और यह व्यवस्था क्या प्रदान करती है?","optionsHi":["2 TB, गति के लिए ब्लॉक दोनों डिस्कों में स्ट्राइप किए जाते हैं","2 TB, दोनों डिस्कों में पैरिटी ब्लॉक फैले होते हैं","1 TB, गति के लिए ब्लॉक दोनों डिस्कों में स्ट्राइप किए जाते हैं","1 TB, प्रत्येक ब्लॉक दोनों डिस्कों पर मिरर होता है"],"explanationHi":"RAID 1 डिस्कों को मिरर करता है, इसलिए कोई भी एक विफल हो तो डेटा नहीं खोता, पर प्रयोग-योग्य स्थान एक डिस्क जितना होता है। बिना अतिरिक्तता के गति के लिए स्ट्राइपिंग RAID 0 है।"},
  {"id":"comp-awareness-436","question":"Why does defragmenting a solid-state drive (SSD) give little or no speed benefit?","options":["Its controller always stores each file in one contiguous block","It can only be formatted with FAT32, which never fragments","Its controller compresses every file, so fragments disappear","It has no moving head, so access time does not depend on position"],"answer":3,"explanation":"Defragmenting helps hard disks by cutting seek and rotation delays; an SSD reads any block equally fast, and extra rewrites only add wear. SSD files can still be fragmented.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"सॉलिड-स्टेट ड्राइव (SSD) को डीफ़्रैग्मेंट करने से गति में कम या कोई लाभ क्यों नहीं मिलता?","optionsHi":["उसका कंट्रोलर प्रत्येक फ़ाइल को सदा एक सटे हुए ब्लॉक में रखता है","उसे केवल FAT32 में फ़ॉर्मैट किया जा सकता है, जो कभी विखंडित नहीं होता","उसका कंट्रोलर प्रत्येक फ़ाइल को संपीड़ित करता है, इसलिए खंड लुप्त हो जाते हैं","उसमें कोई गतिशील हेड नहीं होता, इसलिए एक्सेस समय स्थिति पर निर्भर नहीं करता"],"explanationHi":"डीफ़्रैग्मेंटेशन हार्ड डिस्कों में सीक और घूर्णन विलंब घटाकर मदद करता है; SSD किसी भी ब्लॉक को समान गति से पढ़ती है, और अतिरिक्त पुनर्लेखन केवल घिसाव बढ़ाते हैं। SSD की फ़ाइलें फिर भी विखंडित हो सकती हैं।"},
  {"id":"comp-awareness-437","question":"A 40-slide PowerPoint presentation needs every slide title changed to a new font in one step. What should be edited?","options":["The Slide Master","The Notes Page","The Slide Sorter view","The Handout Master"],"answer":0,"explanation":"Formatting set on the Slide Master flows to every slide based on its layouts. Slide Sorter only rearranges slides, and the Notes and Handout masters affect printouts.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"40 स्लाइड वाली PowerPoint प्रस्तुति में प्रत्येक स्लाइड के शीर्षक का फ़ॉन्ट एक ही चरण में बदलना है। किसे संपादित करना चाहिए?","optionsHi":["स्लाइड मास्टर","नोट्स पेज","स्लाइड सॉर्टर व्यू","हैंडआउट मास्टर"],"explanationHi":"स्लाइड मास्टर पर किया गया फ़ॉर्मैटिंग उसके लेआउट पर आधारित प्रत्येक स्लाइड तक पहुँचता है। स्लाइड सॉर्टर केवल स्लाइडों को पुनर्व्यवस्थित करता है, और नोट्स तथा हैंडआउट मास्टर प्रिंटआउट को प्रभावित करते हैं।"},
  {"id":"comp-awareness-438","question":"In MS Excel, =VLOOKUP(A2, D2:F100, 3) is entered with NO fourth argument. How does it search?","options":["Exact match only, returning #N/A if A2 is missing","Approximate match, which needs column D to be sorted in ascending order","Exact match, but ignoring the difference between capitals and small letters","Approximate match, which needs column F to be sorted in descending order"],"answer":1,"explanation":"Leaving out range_lookup means TRUE, an approximate match that assumes the first column of the table is sorted ascending; unsorted data can give silently wrong results. Use FALSE for an exact match.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"MS Excel में =VLOOKUP(A2, D2:F100, 3) बिना चौथे तर्क के दर्ज किया गया है। यह कैसे खोजता है?","optionsHi":["केवल सटीक मिलान, A2 न मिलने पर #N/A लौटाता है","अनुमानित मिलान, जिसके लिए स्तंभ D का आरोही क्रम में होना आवश्यक है","सटीक मिलान, पर बड़े और छोटे अक्षरों के अंतर की उपेक्षा करते हुए","अनुमानित मिलान, जिसके लिए स्तंभ F का अवरोही क्रम में होना आवश्यक है"],"explanationHi":"range_lookup छोड़ने का अर्थ TRUE है, यानी अनुमानित मिलान जो मानता है कि तालिका का पहला स्तंभ आरोही क्रम में है; अक्रमित डेटा चुपचाप गलत परिणाम दे सकता है। सटीक मिलान के लिए FALSE प्रयोग करें।"},
  {"id":"comp-awareness-439","question":"The 32-bit value 0x12345678 is stored starting at address 100 on a little-endian machine. Which byte is at address 100?","options":["78","12","34","56"],"answer":0,"explanation":"Little-endian stores the least significant byte at the lowest address, so 78 sits at 100, then 56, 34 and 12. A big-endian machine would put 12 at address 100.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"32-बिट मान 0x12345678 को लिटिल-एंडियन मशीन पर पता 100 से आरंभ करके संग्रहीत किया जाता है। पता 100 पर कौन-सा बाइट है?","optionsHi":["78","12","34","56"],"explanationHi":"लिटिल-एंडियन सबसे कम महत्वपूर्ण बाइट को सबसे निचले पते पर रखता है, इसलिए 78 पता 100 पर होता है, फिर 56, 34 और 12। बिग-एंडियन मशीन 12 को पता 100 पर रखती।"},
  {"id":"comp-awareness-440","question":"A 4-way set-associative cache has 256 lines in total. How many sets does it have, and how many address bits select the set?","options":["256 sets, 8 index bits","64 sets, 6 index bits","4 sets, 2 index bits","64 sets, 8 index bits"],"answer":1,"explanation":"Each set holds 4 lines, so 256 ÷ 4 = 64 sets, chosen by log₂ 64 = 6 index bits. 256 sets would be a direct-mapped cache.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक 4-वे सेट-एसोसिएटिव कैश में कुल 256 लाइनें हैं। उसमें कितने सेट हैं, और सेट का चयन कितने एड्रेस बिट करते हैं?","optionsHi":["256 सेट, 8 इंडेक्स बिट","64 सेट, 6 इंडेक्स बिट","4 सेट, 2 इंडेक्स बिट","64 सेट, 8 इंडेक्स बिट"],"explanationHi":"प्रत्येक सेट में 4 लाइनें हैं, इसलिए 256 ÷ 4 = 64 सेट, जिनका चयन log₂ 64 = 6 इंडेक्स बिट करते हैं। 256 सेट डायरेक्ट-मैप्ड कैश में होते।"},
  {"id":"comp-awareness-441","question":"In which pair is the expansion of the abbreviation WRONG?","options":["VLSI – Very Large Scale Integration","EEPROM – Electrically Erasable Programmable Read-Only Memory","ALU – Arithmetic Logic Unit","CMOS – Central Memory Operating System"],"answer":3,"explanation":"CMOS stands for Complementary Metal-Oxide Semiconductor, the chip technology used for the small settings memory on a motherboard. The other three expansions are correct.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"किस युग्म में संक्षिप्त रूप का विस्तार गलत है?","optionsHi":["VLSI – Very Large Scale Integration","EEPROM – Electrically Erasable Programmable Read-Only Memory","ALU – Arithmetic Logic Unit","CMOS – Central Memory Operating System"],"explanationHi":"CMOS का अर्थ Complementary Metal-Oxide Semiconductor है, जो मदरबोर्ड की छोटी सेटिंग मेमोरी में प्रयुक्त चिप तकनीक है। शेष तीनों विस्तार सही हैं।"},
  {"id":"comp-awareness-442","question":"Which abbreviation is expanded CORRECTLY?","options":["DSL – Data Subscriber Link over Copper Wire","VoIP – Video over Internet Protocol","ISDN – Integrated Services Digital Network","NIC – Network Internet Controller"],"answer":2,"explanation":"ISDN is Integrated Services Digital Network. DSL is Digital Subscriber Line, VoIP is Voice over Internet Protocol, and NIC is Network Interface Card.","difficulty":"very-hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"कौन-सा संक्षिप्त रूप सही विस्तारित किया गया है?","optionsHi":["DSL – Data Subscriber Link over Copper Wire","VoIP – Video over Internet Protocol","ISDN – Integrated Services Digital Network","NIC – Network Internet Controller"],"explanationHi":"ISDN का अर्थ Integrated Services Digital Network है। DSL Digital Subscriber Line है, VoIP Voice over Internet Protocol है, और NIC Network Interface Card है।"},
  {"id":"comp-awareness-443","question":"How many of these expansions are correct? I. RAM – Random Access Memory II. CD-R – Compact Disc Rewritable III. DPI – Display Pixels per Inch IV. BIOS – Basic Integrated Operating System","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is right. CD-R is Compact Disc Recordable (Rewritable is CD-RW), DPI is Dots Per Inch, and BIOS is Basic Input/Output System.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"इनमें से कितने विस्तार सही हैं? I. RAM – Random Access Memory II. CD-R – Compact Disc Rewritable III. DPI – Display Pixels per Inch IV. BIOS – Basic Integrated Operating System","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है। CD-R का अर्थ Compact Disc Recordable है (Rewritable CD-RW है), DPI का अर्थ Dots Per Inch है, और BIOS का अर्थ Basic Input/Output System है।"},
  {"id":"comp-awareness-444","question":"A fintech's developers upload their code, and the cloud provider supplies and manages the servers, operating system, runtime and database. Which service model is this?","options":["Infrastructure as a Service","Software as a Service","Platform as a Service","Network as a Service"],"answer":2,"explanation":"PaaS gives a ready platform to deploy code without managing servers or the OS. IaaS would leave the OS and runtime to the customer, and SaaS delivers a finished application.","difficulty":"hard","source":"IBPS SO IT Officer · IBPS PO Mains","questionHi":"एक फ़िनटेक के डेवलपर अपना कोड अपलोड करते हैं, और क्लाउड प्रदाता सर्वर, ऑपरेटिंग सिस्टम, रनटाइम और डेटाबेस उपलब्ध कराता और प्रबंधित करता है। यह कौन-सा सेवा मॉडल है?","optionsHi":["इन्फ्रास्ट्रक्चर एज़ ए सर्विस","सॉफ्टवेयर एज़ ए सर्विस","प्लेटफ़ॉर्म एज़ ए सर्विस","नेटवर्क एज़ ए सर्विस"],"explanationHi":"PaaS सर्वर या OS का प्रबंधन किए बिना कोड तैनात करने के लिए तैयार प्लेटफ़ॉर्म देता है। IaaS में OS और रनटाइम ग्राहक पर छोड़े जाते, और SaaS बना-बनाया एप्लिकेशन देता है।"},
  {"id":"comp-awareness-445","question":"Several banks with the same regulatory and security needs share one cloud infrastructure that is closed to the general public. Which deployment model is this?","options":["Community cloud","Public cloud","Private cloud","Hybrid cloud"],"answer":0,"explanation":"A community cloud serves a group of organisations with shared concerns. A private cloud serves a single organisation, and a hybrid cloud mixes private and public clouds.","difficulty":"hard","source":"IBPS SO IT Officer · IBPS PO Mains","questionHi":"समान नियामक और सुरक्षा आवश्यकताओं वाले कई बैंक एक ही क्लाउड इन्फ्रास्ट्रक्चर साझा करते हैं जो आम जनता के लिए बंद है। यह कौन-सा परिनियोजन मॉडल है?","optionsHi":["कम्युनिटी क्लाउड","पब्लिक क्लाउड","प्राइवेट क्लाउड","हाइब्रिड क्लाउड"],"explanationHi":"कम्युनिटी क्लाउड साझा चिंताओं वाले संगठनों के समूह की सेवा करता है। प्राइवेट क्लाउड एक ही संगठन की सेवा करता है, और हाइब्रिड क्लाउड निजी और सार्वजनिक क्लाउडों को मिलाता है।"},
  {"id":"comp-awareness-446","question":"Which HTML tag creates a clickable hyperlink to another page?","options":["<link>","<href>","<a>","<hl>"],"answer":2,"explanation":"The anchor tag <a href='…'> makes a hyperlink. <link> connects resources such as stylesheets in the head, and href is an attribute, not a tag.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer","questionHi":"कौन-सा HTML टैग किसी अन्य पृष्ठ से क्लिक-योग्य हाइपरलिंक बनाता है?","optionsHi":["<link>","<href>","<a>","<hl>"],"explanationHi":"एंकर टैग <a href='…'> हाइपरलिंक बनाता है। <link> हेड में स्टाइलशीट जैसे संसाधनों को जोड़ता है, और href टैग नहीं, एट्रिब्यूट है।"},
  {"id":"comp-awareness-447","question":"Clearing a web browser's cache mainly removes:","options":["Stored copies of pages and images kept to load sites faster","The list of websites saved as bookmarks or favourites","The browser's installed extensions and add-ons","Passwords saved in the operating system's key store"],"answer":0,"explanation":"The cache holds local copies of web content so repeat visits load faster; clearing it forces fresh downloads. Bookmarks and extensions are kept separately.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"वेब ब्राउज़र का कैश साफ़ करने से मुख्यतः क्या हटता है?","optionsHi":["साइटों को तेज़ लोड करने के लिए रखी गई पृष्ठों और चित्रों की संग्रहीत प्रतियाँ","बुकमार्क या पसंदीदा के रूप में सहेजी गई वेबसाइटों की सूची","ब्राउज़र के इंस्टॉल किए गए एक्सटेंशन और ऐड-ऑन","ऑपरेटिंग सिस्टम के की स्टोर में सहेजे गए पासवर्ड"],"explanationHi":"कैश वेब सामग्री की स्थानीय प्रतियाँ रखता है ताकि दोबारा जाने पर साइटें तेज़ लोड हों; उसे साफ़ करने पर ताज़ा डाउनलोड करने पड़ते हैं। बुकमार्क और एक्सटेंशन अलग से रखे जाते हैं।"},
  {"id":"comp-awareness-448","question":"In e-mail, which action sends the original message's attachments along to a new recipient by default?","options":["Reply","Reply All","Forward","Adding the person in CC of the reply"],"answer":2,"explanation":"Forward includes the original attachments; Reply and Reply All normally drop them, since the sender already has them.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"ई-मेल में कौन-सी क्रिया मूल संदेश के अनुलग्नकों को डिफ़ॉल्ट रूप से नए प्राप्तकर्ता तक भेजती है?","optionsHi":["रिप्लाई","रिप्लाई ऑल","फ़ॉरवर्ड","उत्तर में उस व्यक्ति को CC में जोड़ना"],"explanationHi":"फ़ॉरवर्ड में मूल अनुलग्नक शामिल होते हैं; रिप्लाई और रिप्लाई ऑल सामान्यतः उन्हें छोड़ देते हैं, क्योंकि प्रेषक के पास वे पहले से हैं।"},
  {"id":"comp-awareness-449","question":"Four 2 TB disks are combined in RAID 5. What is the usable storage capacity?","options":["8 TB","4 TB","6 TB","2 TB"],"answer":2,"explanation":"RAID 5 spreads parity over all disks, using the space of one disk for it: (4 − 1) × 2 TB = 6 TB, and any single disk can fail without data loss.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"चार 2 TB डिस्कों को RAID 5 में जोड़ा गया है। प्रयोग-योग्य संग्रहण क्षमता क्या है?","optionsHi":["8 TB","4 TB","6 TB","2 TB"],"explanationHi":"RAID 5 पैरिटी को सभी डिस्कों में फैलाता है, जिसमें एक डिस्क जितना स्थान लगता है: (4 − 1) × 2 TB = 6 TB, और कोई भी एक डिस्क विफल हो तो डेटा नहीं खोता।"},
  {"id":"comp-awareness-450","question":"In Windows, what does pressing Shift + Delete on a selected file do?","options":["Moves the file to the Recycle Bin so it can be restored later","Deletes the file at once, without sending it to the Recycle Bin","Hides the file from view in File Explorer without deleting it","Deletes only the file's shortcut, leaving the file"],"answer":1,"explanation":"Shift + Delete bypasses the Recycle Bin (after a confirmation), so the file cannot be restored from there; plain Delete moves it to the Recycle Bin.","difficulty":"hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"Windows में चयनित फ़ाइल पर Shift + Delete दबाने से क्या होता है?","optionsHi":["फ़ाइल रीसायकल बिन में चली जाती है ताकि बाद में पुनर्स्थापित की जा सके","फ़ाइल तुरंत हट जाती है, रीसायकल बिन में भेजे बिना","फ़ाइल हटाए बिना File Explorer में दृश्य से छिप जाती है","केवल फ़ाइल का शॉर्टकट हटता है, फ़ाइल रहती है"],"explanationHi":"Shift + Delete रीसायकल बिन को दरकिनार करता है (पुष्टि के बाद), इसलिए फ़ाइल वहाँ से पुनर्स्थापित नहीं हो सकती; साधारण Delete उसे रीसायकल बिन में भेजता है।"},
  {"id":"comp-awareness-451","question":"A frame arrives on one port of an ordinary network hub. What does the hub do with it?","options":["Repeats it out of every other port, since it cannot read addresses","Sends it only to the port where the destination MAC address lives","Drops it unless the destination IP address is on the same subnet","Stores it and forwards it after checking the frame for errors"],"answer":0,"explanation":"A hub is a physical-layer multiport repeater: it regenerates the signal to all other ports, so every device shares one collision domain. Forwarding by MAC address is what a switch does.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"एक साधारण नेटवर्क हब के एक पोर्ट पर फ़्रेम आता है। हब उसका क्या करता है?","optionsHi":["उसे हर अन्य पोर्ट से दोहरा देता है, क्योंकि वह पते नहीं पढ़ सकता","उसे केवल उसी पोर्ट पर भेजता है जहाँ गंतव्य MAC पता है","उसे तब तक गिरा देता है जब तक गंतव्य IP पता उसी सबनेट पर न हो","उसे संग्रहीत करता है और फ़्रेम में त्रुटियाँ जाँचकर आगे भेजता है"],"explanationHi":"हब भौतिक-परत का बहु-पोर्ट रिपीटर है: वह सिग्नल को सभी अन्य पोर्ट पर पुनः उत्पन्न करता है, इसलिए सभी उपकरण एक ही कोलिज़न डोमेन साझा करते हैं। MAC पते के अनुसार भेजना स्विच का काम है।"},
  {"id":"comp-awareness-452","question":"Which of these link speeds is the FASTEST?","options":["100 MBps","900 Mbps","0.1 GBps","1 Gbps"],"answer":3,"explanation":"A capital B means bytes: 100 MBps = 800 Mbps and 0.1 GBps = 800 Mbps. So 1 Gbps = 1000 Mbps is the fastest, ahead of 900 Mbps.","difficulty":"very-hard","source":"IBPS PO Mains · IBPS SO IT Officer","questionHi":"इन लिंक गतियों में सबसे तेज़ कौन-सी है?","optionsHi":["100 MBps","900 Mbps","0.1 GBps","1 Gbps"],"explanationHi":"बड़ा B बाइट दर्शाता है: 100 MBps = 800 Mbps और 0.1 GBps = 800 Mbps। इसलिए 1 Gbps = 1000 Mbps सबसे तेज़ है, 900 Mbps से आगे।"},
  {"id":"comp-awareness-453","question":"A modem sends 2400 symbols per second, and each symbol carries 4 bits (16 signal states). What is its bit rate?","options":["9600 bps","2400 bps","600 bps","38,400 bps"],"answer":0,"explanation":"Bit rate = baud × bits per symbol = 2400 × 4 = 9600 bps; 16 states give log₂ 16 = 4 bits per symbol. Baud and bit rate are equal only for 2-level signalling.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक मॉडेम प्रति सेकंड 2400 प्रतीक भेजता है, और प्रत्येक प्रतीक 4 बिट ले जाता है (16 सिग्नल अवस्थाएँ)। उसकी बिट दर क्या है?","optionsHi":["9600 bps","2400 bps","600 bps","38,400 bps"],"explanationHi":"बिट दर = बॉड × बिट प्रति प्रतीक = 2400 × 4 = 9600 bps; 16 अवस्थाएँ log₂ 16 = 4 बिट प्रति प्रतीक देती हैं। बॉड और बिट दर केवल 2-स्तरीय सिग्नलिंग में बराबर होते हैं।"},
  {"id":"comp-awareness-454","question":"A noiseless channel has a bandwidth of 3000 Hz and uses 4 signal levels. By Nyquist's formula, what is its maximum data rate?","options":["6000 bps","24,000 bps","12,000 bps","3000 bps"],"answer":2,"explanation":"Nyquist: C = 2B log₂ L = 2 × 3000 × log₂ 4 = 2 × 3000 × 2 = 12,000 bps. Dropping the factor 2 gives 6000 bps.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक शोर-रहित चैनल की बैंडविड्थ 3000 Hz है और वह 4 सिग्नल स्तर प्रयोग करता है। नाइक्विस्ट सूत्र से उसकी अधिकतम डेटा दर क्या है?","optionsHi":["6000 bps","24,000 bps","12,000 bps","3000 bps"],"explanationHi":"नाइक्विस्ट: C = 2B log₂ L = 2 × 3000 × log₂ 4 = 2 × 3000 × 2 = 12,000 bps। गुणक 2 छोड़ने पर 6000 bps आता है।"},
  {"id":"comp-awareness-455","question":"Which error-detecting technique treats the data bits as a polynomial, divides by a fixed generator and appends the remainder, as Ethernet frames do?","options":["Single parity bit","Cyclic redundancy check","Hamming code","Two-dimensional parity"],"answer":1,"explanation":"CRC appends the remainder of polynomial division, and the receiver repeats the division to check it. It catches burst errors far better than parity; Hamming code is mainly for correction.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"कौन-सी त्रुटि-पहचान तकनीक डेटा बिटों को बहुपद मानती है, उसे निश्चित जनक से भाग देती है और शेषफल जोड़ देती है, जैसा ईथरनेट फ़्रेम करते हैं?","optionsHi":["एकल पैरिटी बिट","साइक्लिक रिडंडेंसी चेक","हैमिंग कोड","द्वि-आयामी पैरिटी"],"explanationHi":"CRC बहुपद विभाजन का शेषफल जोड़ता है, और रिसीवर जाँचने के लिए वही विभाजन दोहराता है। यह पैरिटी की तुलना में बर्स्ट त्रुटियाँ कहीं बेहतर पकड़ता है; हैमिंग कोड मुख्यतः सुधार के लिए है।"},
  {"id":"comp-awareness-456","question":"A frame is sent to the MAC address FF:FF:FF:FF:FF:FF. Which devices accept it?","options":["Only the default router of the LAN","Only the device whose MAC address was looked up last","Every device on the same LAN (broadcast domain)","Every device on the internet that is switched on"],"answer":2,"explanation":"All-ones is the Ethernet broadcast address, accepted by every NIC in the broadcast domain; routers do not forward it beyond the LAN. ARP requests use it.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"एक फ़्रेम MAC पते FF:FF:FF:FF:FF:FF पर भेजा जाता है। कौन-से उपकरण उसे स्वीकार करते हैं?","optionsHi":["केवल LAN का डिफ़ॉल्ट राउटर","केवल वह उपकरण जिसका MAC पता अंतिम बार खोजा गया था","उसी LAN (ब्रॉडकास्ट डोमेन) का प्रत्येक उपकरण","इंटरनेट पर चालू प्रत्येक उपकरण"],"explanationHi":"सभी-1 ईथरनेट ब्रॉडकास्ट पता है, जिसे ब्रॉडकास्ट डोमेन का प्रत्येक NIC स्वीकार करता है; राउटर उसे LAN से आगे नहीं भेजते। ARP अनुरोध इसी का प्रयोग करते हैं।"},
  {"id":"comp-awareness-457","question":"A PC can reach other computers on its own subnet but nothing outside it, including websites by IP address. Which setting is most likely missing or wrong?","options":["The DNS server address","The default gateway","The MAC address","The subnet's broadcast address"],"answer":1,"explanation":"Traffic for other networks goes to the default gateway (router); without it only local hosts are reachable. A DNS fault would still let sites be reached by IP address.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"एक PC अपने सबनेट के अन्य कंप्यूटरों तक पहुँच सकता है पर उसके बाहर कुछ नहीं, IP पते से वेबसाइटें भी नहीं। कौन-सी सेटिंग सबसे संभावित रूप से अनुपस्थित या गलत है?","optionsHi":["DNS सर्वर का पता","डिफ़ॉल्ट गेटवे","MAC पता","सबनेट का ब्रॉडकास्ट पता"],"explanationHi":"अन्य नेटवर्कों का ट्रैफ़िक डिफ़ॉल्ट गेटवे (राउटर) के पास जाता है; उसके बिना केवल स्थानीय होस्ट तक पहुँचा जा सकता है। DNS की खराबी में IP पते से साइटें फिर भी पहुँच में रहतीं।"},
  {"id":"comp-awareness-458","question":"A bank's employees browse the web through a server that sends requests on their behalf, caches common pages and hides internal addresses from websites. This server is a:","options":["Proxy server","Mail server","DHCP server","File server"],"answer":0,"explanation":"A forward proxy stands between users and the internet, filtering and caching traffic. A DHCP server hands out addresses and a mail server handles e-mail.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"किसी बैंक के कर्मचारी ऐसे सर्वर के माध्यम से वेब ब्राउज़ करते हैं जो उनकी ओर से अनुरोध भेजता है, आम पृष्ठों को कैश करता है और आंतरिक पते वेबसाइटों से छिपाता है। यह सर्वर है एक:","optionsHi":["प्रॉक्सी सर्वर","मेल सर्वर","DHCP सर्वर","फ़ाइल सर्वर"],"explanationHi":"फ़ॉरवर्ड प्रॉक्सी उपयोगकर्ताओं और इंटरनेट के बीच खड़ा होकर ट्रैफ़िक को फ़िल्टर और कैश करता है। DHCP सर्वर पते बाँटता है और मेल सर्वर ई-मेल संभालता है।"},
  {"id":"comp-awareness-459","question":"Which protocol is used to monitor and manage network devices such as routers, switches and printers, for example to read their traffic counters?","options":["SMTP","SNMP","NTP","ICMP"],"answer":1,"explanation":"Simple Network Management Protocol lets a manager query and configure device agents. SMTP sends mail, NTP synchronises clocks and ICMP carries error and echo messages.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"राउटर, स्विच और प्रिंटर जैसे नेटवर्क उपकरणों की निगरानी और प्रबंधन के लिए, जैसे उनके ट्रैफ़िक काउंटर पढ़ने के लिए, कौन-सा प्रोटोकॉल प्रयोग होता है?","optionsHi":["SMTP","SNMP","NTP","ICMP"],"explanationHi":"सिंपल नेटवर्क मैनेजमेंट प्रोटोकॉल प्रबंधक को उपकरण एजेंटों से क्वेरी करने और उन्हें कॉन्फ़िगर करने देता है। SMTP मेल भेजता है, NTP घड़ियाँ सिंक करता है और ICMP त्रुटि तथा इको संदेश ले जाता है।"},
  {"id":"comp-awareness-460","question":"The pair made of an IP address and a port number, such as 192.168.1.5:443, which marks one end of a network connection, is called a:","options":["MAC address","Socket","Subnet","Domain"],"answer":1,"explanation":"A socket is identified by IP address plus port, and a TCP connection by the pair of sockets at its two ends. The port alone picks the application on the host.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"IP पते और पोर्ट संख्या का वह युग्म, जैसे 192.168.1.5:443, जो नेटवर्क कनेक्शन का एक सिरा दर्शाता है, कहलाता है:","optionsHi":["MAC पता","सॉकेट","सबनेट","डोमेन"],"explanationHi":"सॉकेट की पहचान IP पता और पोर्ट से होती है, और TCP कनेक्शन की पहचान उसके दोनों सिरों के सॉकेटों के युग्म से। अकेला पोर्ट होस्ट पर एप्लिकेशन चुनता है।"},
  {"id":"comp-awareness-461","question":"The 'well-known' port numbers, reserved for standard services such as HTTP, FTP and DNS, fall in which range?","options":["1024 to 49151","49152 to 65535","0 to 255","0 to 1023"],"answer":3,"explanation":"Well-known ports are 0–1023, registered ports 1024–49151, and dynamic or private ports 49152–65535. Port numbers are 16-bit, so 65535 is the top.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"HTTP, FTP और DNS जैसी मानक सेवाओं के लिए आरक्षित ‘सुप्रसिद्ध’ पोर्ट संख्याएँ किस रेंज में आती हैं?","optionsHi":["1024 से 49151","49152 से 65535","0 से 255","0 से 1023"],"explanationHi":"सुप्रसिद्ध पोर्ट 0–1023, पंजीकृत पोर्ट 1024–49151, और डायनेमिक या निजी पोर्ट 49152–65535 हैं। पोर्ट संख्याएँ 16-बिट की होती हैं, इसलिए 65535 सबसे ऊपर है।"},
  {"id":"comp-awareness-462","question":"Memory location 2000 holds the value 3000, and location 3000 holds 45. An instruction loads register R1 from address 2000 using INDIRECT addressing. What does R1 receive?","options":["45","3000","2000","2045"],"answer":0,"explanation":"In indirect addressing the instruction's address (2000) holds the address of the operand (3000), so R1 gets memory[3000] = 45. Direct addressing would load 3000, and immediate addressing 2000.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"मेमोरी स्थान 2000 में मान 3000 है, और स्थान 3000 में 45 है। एक निर्देश इनडायरेक्ट (अप्रत्यक्ष) एड्रेसिंग का प्रयोग करके पता 2000 से रजिस्टर R1 लोड करता है। R1 को क्या मिलता है?","optionsHi":["45","3000","2000","2045"],"explanationHi":"अप्रत्यक्ष एड्रेसिंग में निर्देश का पता (2000) संकार्य का पता (3000) रखता है, इसलिए R1 को memory[3000] = 45 मिलता है। प्रत्यक्ष एड्रेसिंग 3000 लोड करती, और इमीडिएट एड्रेसिंग 2000।"},
  {"id":"comp-awareness-463","question":"An empty stack receives PUSH 5, PUSH 8, POP, PUSH 3, PUSH 9, POP, POP. What will the NEXT pop return?","options":["8","3","9","5"],"answer":3,"explanation":"After PUSH 5, 8 the POP removes 8; PUSH 3, 9 then two POPs remove 9 and 3, leaving only 5. A stack is last-in, first-out.","difficulty":"very-hard","source":"IBPS SO IT Officer · SSC CGL","questionHi":"एक खाली स्टैक को PUSH 5, PUSH 8, POP, PUSH 3, PUSH 9, POP, POP मिलते हैं। अगला POP क्या लौटाएगा?","optionsHi":["8","3","9","5"],"explanationHi":"PUSH 5, 8 के बाद POP 8 हटाता है; फिर PUSH 3, 9 और दो POP 9 तथा 3 हटाते हैं, जिससे केवल 5 बचता है। स्टैक अंतिम-अंदर, पहला-बाहर (LIFO) होता है।"},
  {"id":"comp-awareness-464","question":"Graphics processors (GPUs) are widely used to train machine-learning models mainly because they:","options":["Run a single instruction stream much faster than any CPU core can","Have thousands of simple cores working on many data items at once","Store the whole training data set permanently in their own memory","Can run training programs without any operating system or driver"],"answer":1,"explanation":"Training is dominated by matrix arithmetic that splits into many identical independent operations, which suits a GPU's massive data parallelism. A single CPU core is faster on one sequential stream.","difficulty":"hard","source":"IBPS SO IT Officer · IBPS PO Mains","questionHi":"ग्राफ़िक्स प्रोसेसर (GPU) मशीन-लर्निंग मॉडल प्रशिक्षित करने में मुख्यतः इसलिए व्यापक रूप से प्रयुक्त होते हैं क्योंकि वे:","optionsHi":["एकल निर्देश-धारा को किसी भी CPU कोर से बहुत तेज़ चलाते हैं","हज़ारों सरल कोर रखते हैं जो एक साथ कई डेटा वस्तुओं पर काम करते हैं","पूरा प्रशिक्षण डेटा सेट अपनी मेमोरी में स्थायी रूप से संग्रहीत रखते हैं","बिना किसी ऑपरेटिंग सिस्टम या ड्राइवर के प्रशिक्षण प्रोग्राम चला सकते हैं"],"explanationHi":"प्रशिक्षण में आव्यूह अंकगणित हावी होता है जो कई समान स्वतंत्र संक्रियाओं में बँट जाता है, जो GPU के व्यापक डेटा-समांतरता के अनुकूल है। एकल अनुक्रमिक धारा पर एक CPU कोर तेज़ होता है।"},
  {"id":"comp-awareness-465","question":"A hard disk is sold as '500 GB', yet Windows reports its size as about 465 GB. Why?","options":["About 35 GB is hidden for the operating system's recovery files","The maker counts 1 GB as 10⁹ bytes, while Windows divides by 2³⁰","Formatting with NTFS always takes 7% of a disk for the file table","Bad sectors found at the factory are subtracted from the total"],"answer":1,"explanation":"500 × 10⁹ bytes ÷ 2³⁰ (1,073,741,824) ≈ 465.7, which Windows labels GB though it is really GiB. No space is missing; the units differ.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"एक हार्ड डिस्क ‘500 GB’ के रूप में बिकती है, फिर भी Windows उसका आकार लगभग 465 GB बताता है। ऐसा क्यों?","optionsHi":["लगभग 35 GB ऑपरेटिंग सिस्टम की रिकवरी फ़ाइलों के लिए छिपा होता है","निर्माता 1 GB को 10⁹ बाइट गिनता है, जबकि Windows 2³⁰ से भाग देता है","NTFS से फ़ॉर्मैट करने पर फ़ाइल तालिका के लिए सदा डिस्क का 7% लग जाता है","कारख़ाने में मिले खराब सेक्टर कुल से घटा दिए जाते हैं"],"explanationHi":"500 × 10⁹ बाइट ÷ 2³⁰ (1,073,741,824) ≈ 465.7, जिसे Windows GB लिखता है यद्यपि वह वास्तव में GiB है। कोई स्थान गायब नहीं है; इकाइयाँ भिन्न हैं।"},
  {"id":"comp-awareness-466","question":"A 4 × 6 inch photograph is scanned at 300 dpi. How many pixels does the scanned image contain?","options":["7,200","21,600","2,160,000","720,000"],"answer":2,"explanation":"4 in × 300 = 1200 pixels and 6 in × 300 = 1800 pixels; 1200 × 1800 = 2,160,000. Multiplying area (24 sq in) by 300 just once gives 7,200.","difficulty":"very-hard","source":"IBPS PO Mains · SBI Clerk Mains","questionHi":"4 × 6 इंच की एक फ़ोटो 300 dpi पर स्कैन की जाती है। स्कैन की गई छवि में कितने पिक्सेल होते हैं?","optionsHi":["7,200","21,600","2,160,000","720,000"],"explanationHi":"4 इंच × 300 = 1200 पिक्सेल और 6 इंच × 300 = 1800 पिक्सेल; 1200 × 1800 = 2,160,000। क्षेत्रफल (24 वर्ग इंच) को केवल एक बार 300 से गुणा करने पर 7,200 आता है।"},
  {"id":"comp-awareness-467","question":"How many times larger is the key space of a 128-bit key than that of a 64-bit key?","options":["2 times","64 times","2⁶⁴ times","2¹²⁸ times"],"answer":2,"explanation":"2¹²⁸ ÷ 2⁶⁴ = 2⁶⁴. Every extra key bit doubles the brute-force effort, so doubling the length does far more than double it.","difficulty":"very-hard","source":"IBPS SO IT Officer · IBPS PO Mains","questionHi":"128-बिट कुंजी का कुंजी-स्थान 64-बिट कुंजी के कुंजी-स्थान से कितने गुना बड़ा है?","optionsHi":["2 गुना","64 गुना","2⁶⁴ गुना","2¹²⁸ गुना"],"explanationHi":"2¹²⁸ ÷ 2⁶⁴ = 2⁶⁴। कुंजी का प्रत्येक अतिरिक्त बिट ब्रूट-फ़ोर्स प्रयास को दोगुना करता है, इसलिए लंबाई दोगुनी करने से प्रयास दोगुने से कहीं अधिक बढ़ता है।"},
  {"id":"comp-awareness-468","question":"SHA-256 hashes are computed for a 1-byte file and a 1 GB file. How long are the two hash values?","options":["Both are exactly 256 bits","1 byte and 1 GB respectively","256 bits and 256 bytes respectively","They vary with the data, about 1% of the file size"],"answer":0,"explanation":"A hash function gives a fixed-length digest whatever the input size: SHA-256 always outputs 256 bits (64 hex characters).","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"1-बाइट की फ़ाइल और 1 GB की फ़ाइल के लिए SHA-256 हैश निकाले जाते हैं। दोनों हैश मान कितने लंबे होते हैं?","optionsHi":["दोनों ठीक 256 बिट के","क्रमशः 1 बाइट और 1 GB","क्रमशः 256 बिट और 256 बाइट","वे डेटा के अनुसार बदलते हैं, फ़ाइल के आकार का लगभग 1%"],"explanationHi":"हैश फ़ंक्शन इनपुट के आकार से निरपेक्ष निश्चित-लंबाई का डाइजेस्ट देता है: SHA-256 सदा 256 बिट (64 हेक्स अक्षर) आउटपुट देता है।"},
  {"id":"comp-awareness-469","question":"In a one-address (accumulator-based) machine, what does the instruction ADD X do?","options":["Adds X to itself and stores the result back at address X","Adds the contents of address X to the accumulator, leaving the result there","Adds the number X to the program counter to jump ahead","Adds the accumulator to address X and stores the result at X"],"answer":1,"explanation":"With one explicit address, the accumulator is the implied second operand and destination: ACC ← ACC + M[X].","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"एक-पता (एक्युमुलेटर-आधारित) मशीन में निर्देश ADD X क्या करता है?","optionsHi":["X को स्वयं में जोड़ता है और परिणाम वापस पता X पर रखता है","पता X की सामग्री को एक्युमुलेटर में जोड़ता है, परिणाम वहीं छोड़ता है","संख्या X को प्रोग्राम काउंटर में जोड़कर आगे कूदता है","एक्युमुलेटर को पता X में जोड़ता है और परिणाम X पर रखता है"],"explanationHi":"एक स्पष्ट पते के साथ, एक्युमुलेटर निहित दूसरा संकार्य और गंतव्य होता है: ACC ← ACC + M[X]।"},
  {"id":"comp-awareness-470","question":"A child process has finished running, but its parent has not yet read its exit status, so its entry stays in the process table. Such a process is called:","options":["An orphan process","A daemon process","A zombie process","A blocked process"],"answer":2,"explanation":"A zombie has terminated but keeps a process-table entry until the parent calls wait(). An orphan is a still-running child whose parent has already exited.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक चाइल्ड प्रक्रिया चल चुकी है, पर उसके पैरेंट ने अभी उसकी निकास-स्थिति नहीं पढ़ी है, इसलिए उसकी प्रविष्टि प्रक्रिया तालिका में बनी रहती है। ऐसी प्रक्रिया कहलाती है:","optionsHi":["ऑर्फ़न प्रक्रिया","डेमन प्रक्रिया","ज़ॉम्बी प्रक्रिया","ब्लॉक्ड प्रक्रिया"],"explanationHi":"ज़ॉम्बी समाप्त हो चुकी होती है पर पैरेंट के wait() कॉल करने तक प्रक्रिया-तालिका में प्रविष्टि रखती है। ऑर्फ़न वह चल रही चाइल्ड है जिसका पैरेंट पहले ही बाहर निकल चुका है।"},
  {"id":"comp-awareness-471","question":"Pages are 4 KB (4096 bytes) and a process needs 10,300 bytes. How many pages are allocated, and how much internal fragmentation results?","options":["3 pages; 1988 bytes wasted","2 pages; 2108 bytes wasted","3 pages; 2108 bytes wasted","3 pages; no space wasted"],"answer":0,"explanation":"10,300 ÷ 4096 ≈ 2.5, so 3 pages (12,288 bytes) are needed; the unused part of the last page is 12,288 − 10,300 = 1988 bytes. 2108 is the part of the third page actually used.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"पेज 4 KB (4096 बाइट) के हैं और एक प्रक्रिया को 10,300 बाइट चाहिए। कितने पेज आवंटित होते हैं, और कितना आंतरिक विखंडन होता है?","optionsHi":["3 पेज; 1988 बाइट व्यर्थ","2 पेज; 2108 बाइट व्यर्थ","3 पेज; 2108 बाइट व्यर्थ","3 पेज; कोई स्थान व्यर्थ नहीं"],"explanationHi":"10,300 ÷ 4096 ≈ 2.5, इसलिए 3 पेज (12,288 बाइट) चाहिए; अंतिम पेज का अप्रयुक्त भाग 12,288 − 10,300 = 1988 बाइट है। 2108 तीसरे पेज का वास्तव में प्रयुक्त भाग है।"},
  {"id":"comp-awareness-472","question":"A disk head is at cylinder 50, and requests wait for cylinders 82, 170, 43, 140, 24, 16 and 190. Under Shortest Seek Time First, what is the total head movement?","options":["642 cylinders","174 cylinders","240 cylinders","208 cylinders"],"answer":3,"explanation":"SSTF visits 43, 24, 16, 82, 140, 170, 190: 7 + 19 + 8 + 66 + 58 + 30 + 20 = 208. Serving them in arrival order (FCFS) would cost 642.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक डिस्क हेड सिलिंडर 50 पर है, और अनुरोध सिलिंडर 82, 170, 43, 140, 24, 16 और 190 के लिए प्रतीक्षा में हैं। शॉर्टेस्ट सीक टाइम फ़र्स्ट में कुल हेड गति क्या है?","optionsHi":["642 सिलिंडर","174 सिलिंडर","240 सिलिंडर","208 सिलिंडर"],"explanationHi":"SSTF 43, 24, 16, 82, 140, 170, 190 पर जाता है: 7 + 19 + 8 + 66 + 58 + 30 + 20 = 208। उन्हें आगमन क्रम (FCFS) में सेवित करने पर 642 लगता।"},
  {"id":"comp-awareness-473","question":"Table A has 5 rows and table B has 4 rows with the same columns, and exactly 2 rows appear in both; neither table has duplicates of its own. How many rows do A UNION B and A UNION ALL B return?","options":["7 and 9","9 and 7","9 and 9","5 and 4"],"answer":0,"explanation":"UNION removes duplicates: 5 + 4 − 2 = 7 rows. UNION ALL keeps every row: 5 + 4 = 9.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"तालिका A में 5 पंक्तियाँ और तालिका B में 4 पंक्तियाँ हैं, स्तंभ वही हैं, और ठीक 2 पंक्तियाँ दोनों में आती हैं; किसी तालिका में अपनी कोई दोहराई पंक्ति नहीं है। A UNION B और A UNION ALL B कितनी पंक्तियाँ लौटाते हैं?","optionsHi":["7 और 9","9 और 7","9 और 9","5 और 4"],"explanationHi":"UNION दोहराव हटाता है: 5 + 4 − 2 = 7 पंक्तियाँ। UNION ALL हर पंक्ति रखता है: 5 + 4 = 9।"},
  {"id":"comp-awareness-474","question":"How many bits hold the fraction (mantissa) in IEEE 754 double precision, and about how many significant decimal digits does that give?","options":["23 bits; about 7 digits","52 bits; about 7 digits","64 bits; about 19 digits","52 bits; about 15–16 digits"],"answer":3,"explanation":"Double precision uses 1 sign, 11 exponent and 52 fraction bits; with the hidden bit that is 53 bits ≈ 15–16 decimal digits. 23 bits and about 7 digits describe single precision.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"IEEE 754 डबल प्रिसिज़न में भिन्न (मैंटिसा) कितने बिट रखता है, और इससे लगभग कितने सार्थक दशमलव अंक मिलते हैं?","optionsHi":["23 बिट; लगभग 7 अंक","52 बिट; लगभग 7 अंक","64 बिट; लगभग 19 अंक","52 बिट; लगभग 15–16 अंक"],"explanationHi":"डबल प्रिसिज़न 1 साइन, 11 घातांक और 52 भिन्न बिट प्रयोग करता है; छिपे बिट सहित यह 53 बिट ≈ 15–16 दशमलव अंक है। 23 बिट और लगभग 7 अंक सिंगल प्रिसिज़न का वर्णन करते हैं।"},
  {"id":"comp-awareness-475","question":"In an ER model, CUSTOMER and ACCOUNT have a one-to-many relationship (one customer, many accounts; each account has one customer). When converted to tables, where does the foreign key go?","options":["In CUSTOMER, holding the account number","In a third table that is required for every relationship","In ACCOUNT, holding the customer's ID","In both tables, each pointing to the other"],"answer":2,"explanation":"The foreign key goes on the 'many' side: each account row stores its one customer's ID. A separate linking table is needed only for many-to-many relationships.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"ER मॉडल में CUSTOMER और ACCOUNT में एक-से-अनेक संबंध है (एक ग्राहक, कई खाते; प्रत्येक खाते का एक ग्राहक)। तालिकाओं में बदलने पर फ़ॉरेन की कहाँ जाती है?","optionsHi":["CUSTOMER में, जो खाता संख्या रखे","तीसरी तालिका में, जो प्रत्येक संबंध के लिए आवश्यक है","ACCOUNT में, जो ग्राहक की ID रखे","दोनों तालिकाओं में, प्रत्येक दूसरी की ओर संकेत करे"],"explanationHi":"फ़ॉरेन की ‘अनेक’ वाले पक्ष में जाती है: प्रत्येक खाता-पंक्ति अपने एक ग्राहक की ID रखती है। अलग लिंकिंग तालिका केवल अनेक-से-अनेक संबंधों के लिए चाहिए।"},
  {"id":"comp-awareness-476","question":"A device joins two LAN segments, learns which MAC addresses sit on each side, and forwards a frame across only when its destination is on the other side. It is a:","options":["Bridge","Repeater","Router","Modem"],"answer":0,"explanation":"A bridge filters frames by MAC address at the data link layer, splitting collision domains; a switch is essentially a many-port bridge. A repeater just regenerates signals, and a router works with IP addresses.","difficulty":"hard","source":"SBI Clerk Mains · IBPS SO IT Officer","questionHi":"एक उपकरण दो LAN खंडों को जोड़ता है, सीखता है कि प्रत्येक ओर कौन-से MAC पते हैं, और फ़्रेम को तभी पार भेजता है जब उसका गंतव्य दूसरी ओर हो। यह है एक:","optionsHi":["ब्रिज","रिपीटर","राउटर","मॉडेम"],"explanationHi":"ब्रिज डेटा लिंक परत पर MAC पते से फ़्रेम फ़िल्टर करता है और कोलिज़न डोमेन बाँटता है; स्विच मूलतः बहु-पोर्ट ब्रिज है। रिपीटर केवल सिग्नल पुनः उत्पन्न करता है, और राउटर IP पतों से काम करता है।"},
  {"id":"comp-awareness-477","question":"Bank servers must agree on the exact time so that transaction logs and security certificates check correctly. Which protocol keeps their clocks synchronised?","options":["SNMP","NTP","SMTP","ARP"],"answer":1,"explanation":"The Network Time Protocol synchronises clocks across a network, typically to within milliseconds. SNMP manages devices, and ARP maps IP to MAC addresses.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"बैंक के सर्वरों को ठीक समय पर सहमत होना होता है ताकि लेन-देन लॉग और सुरक्षा प्रमाणपत्र सही जाँचें। कौन-सा प्रोटोकॉल उनकी घड़ियाँ सिंक्रनाइज़ रखता है?","optionsHi":["SNMP","NTP","SMTP","ARP"],"explanationHi":"नेटवर्क टाइम प्रोटोकॉल नेटवर्क पर घड़ियाँ सिंक करता है, सामान्यतः मिलीसेकंड के भीतर तक। SNMP उपकरणों का प्रबंधन करता है, और ARP IP को MAC पतों से जोड़ता है।"},
  {"id":"comp-awareness-478","question":"A bank lets selected outside vendors and partner firms log in securely to part of its private internal network to share orders and documents. That arrangement is an:","options":["Intranet","Internet","Extranet","Ethernet"],"answer":2,"explanation":"An extranet extends part of an intranet to authorised outsiders. An intranet is for the organisation's own staff, and Ethernet is a LAN technology.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"एक बैंक चुने हुए बाहरी विक्रेताओं और साझेदार फ़र्मों को अपने निजी आंतरिक नेटवर्क के एक भाग में सुरक्षित रूप से लॉग इन करने देता है ताकि वे ऑर्डर और दस्तावेज़ साझा कर सकें। यह व्यवस्था है एक:","optionsHi":["इंट्रानेट","इंटरनेट","एक्स्ट्रानेट","ईथरनेट"],"explanationHi":"एक्स्ट्रानेट इंट्रानेट के एक भाग को अधिकृत बाहरी लोगों तक बढ़ाता है। इंट्रानेट संगठन के अपने कर्मचारियों के लिए है, और ईथरनेट LAN तकनीक है।"},
  {"id":"comp-awareness-479","question":"'Big data' is commonly described by three Vs. Which set is it?","options":["Volume, Velocity and Variety","Value, Visibility and Validity","Volume, Virtualisation and Vision","Velocity, Verification and Version"],"answer":0,"explanation":"Big data means huge Volume, arriving at high Velocity, in great Variety (structured, text, images, logs). Later lists add Veracity and Value, but the original three are these.","difficulty":"hard","source":"IBPS PO Mains · IBPS SO IT Officer","questionHi":"‘बिग डेटा’ को सामान्यतः तीन V से वर्णित किया जाता है। वह कौन-सा समूह है?","optionsHi":["वॉल्यूम, वेलोसिटी और वैरायटी","वैल्यू, विज़िबिलिटी और वैलिडिटी","वॉल्यूम, वर्चुअलाइज़ेशन और विज़न","वेलोसिटी, वेरिफ़िकेशन और वर्ज़न"],"explanationHi":"बिग डेटा का अर्थ है विशाल वॉल्यूम, उच्च वेलोसिटी से आता हुआ, बड़ी वैरायटी में (संरचित, पाठ, चित्र, लॉग)। बाद की सूचियाँ वेरेसिटी और वैल्यू जोड़ती हैं, पर मूल तीन ये हैं।"},
  {"id":"comp-awareness-480","question":"In a blockchain, every block stores the hash of the block before it. What happens if someone alters a transaction in an old block?","options":["Only that block's timestamp changes, so nobody can notice","The block is automatically encrypted again with a new key","Its hash changes, breaking the link stored in every later block","The transaction is copied to the newest block and accepted"],"answer":2,"explanation":"Changing data changes the block's hash, which no longer matches the previous-hash field in the next block, so the tampering shows unless every later block is redone, which consensus makes infeasible.","difficulty":"hard","source":"IBPS PO Mains · IBPS SO IT Officer","questionHi":"ब्लॉकचेन में प्रत्येक ब्लॉक अपने से पहले वाले ब्लॉक का हैश संग्रहीत करता है। यदि कोई किसी पुराने ब्लॉक में लेन-देन बदल दे तो क्या होता है?","optionsHi":["केवल उस ब्लॉक का टाइमस्टैम्प बदलता है, इसलिए कोई नहीं जान पाता","ब्लॉक नई कुंजी से अपने आप फिर एन्क्रिप्ट हो जाता है","उसका हैश बदल जाता है, जिससे प्रत्येक बाद के ब्लॉक में संग्रहीत कड़ी टूट जाती है","लेन-देन नवीनतम ब्लॉक में कॉपी होकर स्वीकार हो जाता है"],"explanationHi":"डेटा बदलने से ब्लॉक का हैश बदलता है, जो अगले ब्लॉक के पिछले-हैश क्षेत्र से मेल नहीं खाता, इसलिए छेड़छाड़ दिख जाती है जब तक कि प्रत्येक बाद का ब्लॉक फिर से न बनाया जाए, जिसे सर्वसम्मति (कंसेंसस) असंभव बना देती है।"},
  {"id":"comp-awareness-481","question":"A bank trains a model on past loan applications, each labelled 'repaid' or 'defaulted', so that it can predict the outcome for new applicants. What kind of machine learning is this?","options":["Unsupervised learning","Reinforcement learning","Clustering","Supervised learning"],"answer":3,"explanation":"Learning from examples that carry known answers (labels) is supervised learning, here a classification task. Unsupervised learning and clustering find patterns in unlabelled data.","difficulty":"hard","source":"IBPS PO Mains · IBPS SO IT Officer","questionHi":"एक बैंक पिछले ऋण आवेदनों पर मॉडल प्रशिक्षित करता है, जिनमें प्रत्येक पर ‘चुकाया’ या ‘चूक’ का लेबल है, ताकि वह नए आवेदकों के परिणाम की भविष्यवाणी कर सके। यह किस प्रकार की मशीन लर्निंग है?","optionsHi":["अनसुपरवाइज़्ड लर्निंग","रीइन्फ़ोर्समेंट लर्निंग","क्लस्टरिंग","सुपरवाइज़्ड लर्निंग"],"explanationHi":"ज्ञात उत्तरों (लेबल) वाले उदाहरणों से सीखना सुपरवाइज़्ड लर्निंग है, जो यहाँ वर्गीकरण कार्य है। अनसुपरवाइज़्ड लर्निंग और क्लस्टरिंग बिना लेबल वाले डेटा में पैटर्न खोजते हैं।"},
  {"id":"comp-awareness-482","question":"If the time quantum in Round Robin scheduling is made larger than every process's CPU burst, the algorithm behaves exactly like:","options":["Shortest Job First","Priority scheduling","First-Come, First-Served","Shortest Remaining Time First"],"answer":2,"explanation":"Every process then finishes within its first quantum, in arrival order, with no pre-emption, which is FCFS. A very small quantum instead causes heavy context-switch overhead.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"यदि राउंड रॉबिन शेड्यूलिंग में टाइम क्वांटम को प्रत्येक प्रक्रिया के CPU बर्स्ट से बड़ा कर दिया जाए, तो एल्गोरिदम ठीक किसके समान व्यवहार करता है?","optionsHi":["शॉर्टेस्ट जॉब फ़र्स्ट","प्राथमिकता शेड्यूलिंग","फ़र्स्ट-कम, फ़र्स्ट-सर्व्ड","शॉर्टेस्ट रिमेनिंग टाइम फ़र्स्ट"],"explanationHi":"तब प्रत्येक प्रक्रिया अपने पहले क्वांटम में ही आगमन क्रम से पूरी हो जाती है, बिना प्री-एम्प्शन के, जो FCFS है। बहुत छोटा क्वांटम इसके बजाय भारी कॉन्टेक्स्ट-स्विच ओवरहेड पैदा करता है।"},
  {"id":"comp-awareness-483","question":"Why are B+ trees preferred for database indexes that must also answer range queries such as 'balance between 10,000 and 50,000'?","options":["They store records in hash buckets, so each lookup takes one step","All records sit in linked, ordered leaves, so a range is read leaf by leaf","They keep every record in the root node, so no disk access is needed","They are unbalanced, so recent keys are found faster than old ones"],"answer":1,"explanation":"A B+ tree keeps data pointers only in leaves, which are chained in key order; after finding the first key, the scan just follows the leaf links. Hash indexes cannot do ranges.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"डेटाबेस इंडेक्स के लिए B+ ट्री को वरीयता क्यों दी जाती है जिन्हें ‘शेष 10,000 और 50,000 के बीच’ जैसे रेंज क्वेरी भी हल करनी होती हैं?","optionsHi":["वे रिकॉर्ड हैश बकेट में रखते हैं, इसलिए प्रत्येक खोज में एक चरण लगता है","सभी रिकॉर्ड जुड़े, क्रमबद्ध पत्तों में रहते हैं, इसलिए रेंज पत्ता-दर-पत्ता पढ़ी जाती है","वे प्रत्येक रिकॉर्ड को रूट नोड में रखते हैं, इसलिए डिस्क एक्सेस की आवश्यकता नहीं","वे असंतुलित होते हैं, इसलिए हाल की कुंजियाँ पुरानी से तेज़ मिलती हैं"],"explanationHi":"B+ ट्री डेटा पॉइंटर केवल पत्तों में रखता है, जो कुंजी क्रम में जंजीर की तरह जुड़े होते हैं; पहली कुंजी मिलने के बाद स्कैन केवल पत्ता-लिंकों का अनुसरण करता है। हैश इंडेक्स रेंज नहीं कर सकते।"},
  {"id":"comp-awareness-484","question":"Two parties who have never met want to agree on a shared secret key over an open network that eavesdroppers can watch. Which method is designed for this?","options":["Diffie–Hellman exchange","Caesar shift cipher","SHA-256 hash function","Base64 text encoding"],"answer":0,"explanation":"Diffie–Hellman lets both sides derive the same secret from publicly exchanged values without sending the key itself. Hashing gives no shared secret, and Base64 is not encryption at all.","difficulty":"hard","source":"IBPS SO IT Officer","questionHi":"दो पक्ष जो कभी मिले नहीं हैं, ऐसे खुले नेटवर्क पर, जिसे जासूस देख सकते हैं, साझा गुप्त कुंजी पर सहमत होना चाहते हैं। इसके लिए कौन-सी विधि बनी है?","optionsHi":["डिफ़ी–हेलमैन विनिमय","सीज़र शिफ़्ट सिफ़र","SHA-256 हैश फ़ंक्शन","बेस64 पाठ एन्कोडिंग"],"explanationHi":"डिफ़ी–हेलमैन दोनों पक्षों को सार्वजनिक रूप से आदान-प्रदान किए गए मानों से वही गुप्त मान निकालने देता है, बिना कुंजी स्वयं भेजे। हैशिंग कोई साझा गुप्त नहीं देती, और बेस64 एन्क्रिप्शन है ही नहीं।"},
  {"id":"comp-awareness-485","question":"Assertion (A): Virtual memory lets a program larger than the physical RAM run. Reason (R): Only the pages a program currently needs must be in RAM; the rest can stay on disk until used.","options":["A is true but R is false","A is false but R is true","Both A and R are true, but R does not explain A","Both A and R are true, and R explains A"],"answer":3,"explanation":"Demand paging brings in pages only when referenced, which is exactly why a program larger than RAM can run, so R correctly explains A.","difficulty":"hard","source":"IBPS SO IT Officer · SBI Clerk Mains","questionHi":"अभिकथन (A): वर्चुअल मेमोरी भौतिक RAM से बड़े प्रोग्राम को चलने देती है। कारण (R): प्रोग्राम को वर्तमान में जिन पेजों की आवश्यकता है केवल वही RAM में होने चाहिए; शेष प्रयोग होने तक डिस्क पर रह सकते हैं।","optionsHi":["A सही है, परंतु R गलत है","A गलत है, परंतु R सही है","A और R दोनों सही हैं, परंतु R, A की व्याख्या नहीं करता","A और R दोनों सही हैं, और R, A की व्याख्या करता है"],"explanationHi":"डिमांड पेजिंग पेजों को केवल संदर्भित होने पर लाती है, और ठीक इसीलिए RAM से बड़ा प्रोग्राम चल सकता है, इसलिए R सही ढंग से A की व्याख्या करता है।"},
  {"id":"comp-awareness-486","question":"An online platform lets individuals list their used phones and furniture and sell them directly to other individuals. Which e-commerce model is this?","options":["B2B","B2C","C2C","B2G"],"answer":2,"explanation":"Consumer-to-consumer platforms connect private sellers with private buyers; the platform only hosts the listings. B2C is a firm selling to consumers.","difficulty":"moderate","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"एक ऑनलाइन प्लेटफ़ॉर्म व्यक्तियों को अपने पुराने फ़ोन और फ़र्नीचर सूचीबद्ध करने और सीधे अन्य व्यक्तियों को बेचने देता है। यह कौन-सा ई-कॉमर्स मॉडल है?","optionsHi":["B2B","B2C","C2C","B2G"],"explanationHi":"कंज़्यूमर-टू-कंज़्यूमर प्लेटफ़ॉर्म निजी विक्रेताओं को निजी खरीदारों से जोड़ते हैं; प्लेटफ़ॉर्म केवल सूचियाँ होस्ट करता है। B2C वह है जिसमें कोई फ़र्म उपभोक्ताओं को बेचती है।"},
  {"id":"comp-awareness-487","question":"What is 0101 − 0111 in 4-bit two's-complement arithmetic?","options":["1110","0010","1010","1101"],"answer":0,"explanation":"Add the two's complement of 0111 (which is 1001): 0101 + 1001 = 1110, which is −2, matching 5 − 7. 0010 is +2, the sign error.","difficulty":"very-hard","source":"IBPS SO IT Officer · SSC CGL","questionHi":"4-बिट टू’ज़-कॉम्प्लिमेंट अंकगणित में 0101 − 0111 क्या है?","optionsHi":["1110","0010","1010","1101"],"explanationHi":"0111 का टू’ज़ कॉम्प्लिमेंट (जो 1001 है) जोड़ें: 0101 + 1001 = 1110, जो −2 है, 5 − 7 से मेल खाता है। 0010 +2 है, जो चिह्न की भूल है।"},
  {"id":"comp-awareness-488","question":"A device's memory occupies the addresses 0x8000 to 0xBFFF, inclusive, with one byte at each address. How much memory is that?","options":["32 KB","8 KB","48 KB","16 KB"],"answer":3,"explanation":"0xBFFF − 0x8000 + 1 = 0x4000 = 16,384 bytes = 16 KB. Forgetting the +1 gives 16,383, and reading 0xC000 as the size gives 48 KB.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"किसी उपकरण की मेमोरी पते 0x8000 से 0xBFFF तक, दोनों सहित, घेरती है, और प्रत्येक पते पर एक बाइट है। वह कितनी मेमोरी है?","optionsHi":["32 KB","8 KB","48 KB","16 KB"],"explanationHi":"0xBFFF − 0x8000 + 1 = 0x4000 = 16,384 बाइट = 16 KB। +1 भूलने पर 16,383 आता है, और 0xC000 को आकार पढ़ने पर 48 KB आता है।"},
  {"id":"comp-awareness-489","question":"What is the largest 3-digit hexadecimal number minus the largest 3-digit octal number, in decimal?","options":["3584","222","4095","3072"],"answer":0,"explanation":"(FFF)₁₆ = 16³ − 1 = 4095 and (777)₈ = 8³ − 1 = 511, so the difference is 3584. Treating both as decimal gives 999 − 777 = 222.","difficulty":"very-hard","source":"SSC CGL · IBPS SO IT Officer","questionHi":"सबसे बड़ी 3-अंकीय हेक्साडेसिमल संख्या में से सबसे बड़ी 3-अंकीय ऑक्टल संख्या घटाने पर दशमलव में क्या मिलता है?","optionsHi":["3584","222","4095","3072"],"explanationHi":"(FFF)₁₆ = 16³ − 1 = 4095 और (777)₈ = 8³ − 1 = 511, इसलिए अंतर 3584 है। दोनों को दशमलव मानने पर 999 − 777 = 222 आता है।"},
  {"id":"comp-awareness-490","question":"What is 11011011 XOR 10101110?","options":["10001010","01110101","11111111","01110100"],"answer":1,"explanation":"XOR gives 1 where the bits differ: 11011011 ⊕ 10101110 = 01110101. 10001010 is the AND of the two.","difficulty":"very-hard","source":"IBPS SO IT Officer · SSC CGL","questionHi":"11011011 XOR 10101110 क्या है?","optionsHi":["10001010","01110101","11111111","01110100"],"explanationHi":"XOR वहाँ 1 देता है जहाँ बिट भिन्न हों: 11011011 ⊕ 10101110 = 01110101। 10001010 दोनों का AND है।"},
  {"id":"comp-awareness-491","question":"A program must clear the lowest 4 bits of a byte to 0 while keeping the upper 4 bits unchanged. With which mask, written in hexadecimal, should the byte be ANDed?","options":["0F","FF","00","F0"],"answer":3,"explanation":"AND with 1 keeps a bit and AND with 0 clears it, so the mask is 1111 0000 = F0. ANDing with 0F would keep the low bits and clear the high ones instead.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक प्रोग्राम को बाइट के निचले 4 बिट 0 करने हैं और ऊपरी 4 बिट अपरिवर्तित रखने हैं। हेक्साडेसिमल में लिखे किस मास्क से बाइट का AND लेना चाहिए?","optionsHi":["0F","FF","00","F0"],"explanationHi":"1 से AND बिट को रखता है और 0 से AND उसे मिटाता है, इसलिए मास्क 1111 0000 = F0 है। 0F से AND निचले बिट रखता और ऊपरी मिटा देता।"},
  {"id":"comp-awareness-492","question":"Which address can be assigned to a host in the subnet 10.0.0.4/30?","options":["10.0.0.4","10.0.0.7","10.0.0.6","10.0.0.8"],"answer":2,"explanation":"A /30 block holds 4 addresses: 10.0.0.4 (network), .5 and .6 (hosts) and .7 (broadcast). 10.0.0.8 begins the next subnet.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"सबनेट 10.0.0.4/30 में किसी होस्ट को कौन-सा पता दिया जा सकता है?","optionsHi":["10.0.0.4","10.0.0.7","10.0.0.6","10.0.0.8"],"explanationHi":"/30 ब्लॉक में 4 पते होते हैं: 10.0.0.4 (नेटवर्क), .5 और .6 (होस्ट) तथा .7 (ब्रॉडकास्ट)। 10.0.0.8 अगले सबनेट को आरंभ करता है।"},
  {"id":"comp-awareness-493","question":"Relation R(A, B, C) has the composite key AB and the dependency B → C. What is the highest normal form R satisfies?","options":["1NF","2NF","3NF","BCNF"],"answer":0,"explanation":"C depends on B, only part of the key AB, which is a partial dependency and breaks 2NF. So R is only in 1NF; splitting out (B, C) fixes it.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"रिलेशन R(A, B, C) की कंपोज़िट की AB है और निर्भरता B → C है। R जिस उच्चतम सामान्य रूप को संतुष्ट करता है वह क्या है?","optionsHi":["1NF","2NF","3NF","BCNF"],"explanationHi":"C, B पर निर्भर है, जो की AB का केवल एक भाग है, यानी आंशिक निर्भरता, जो 2NF को भंग करती है। इसलिए R केवल 1NF में है; (B, C) को अलग करने से यह ठीक हो जाता है।"},
  {"id":"comp-awareness-494","question":"Each process in memory spends 80% of its time waiting for I/O. With three such independent processes in memory, about what fraction of time is the CPU busy?","options":["20%","51%","60%","49%"],"answer":3,"explanation":"The CPU is idle only when all three wait at once: 0.8³ = 0.512, so utilisation = 1 − 0.512 ≈ 49%. Adding 20% per process gives the trap 60%, and 51% is the idle fraction.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"मेमोरी में प्रत्येक प्रक्रिया अपना 80% समय I/O की प्रतीक्षा में बिताती है। मेमोरी में तीन ऐसी स्वतंत्र प्रक्रियाएँ होने पर, CPU लगभग कितने समय के अंश तक व्यस्त रहता है?","optionsHi":["20%","51%","60%","49%"],"explanationHi":"CPU केवल तभी निष्क्रिय रहता है जब तीनों एक साथ प्रतीक्षा करें: 0.8³ = 0.512, इसलिए उपयोग = 1 − 0.512 ≈ 49%। प्रति प्रक्रिया 20% जोड़ने पर जाल वाला उत्तर 60% आता है, और 51% निष्क्रिय अंश है।"},
  {"id":"comp-awareness-495","question":"A DBA adds a new column to a table's conceptual schema, and the existing application programs and user views keep working unchanged. This shows:","options":["Logical data independence","Physical data independence","Referential integrity","Data redundancy"],"answer":0,"explanation":"Logical data independence shields the external level from changes to the conceptual (logical) schema. Physical data independence covers changes to storage, such as new indexes.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक DBA तालिका की संकल्पनात्मक स्कीमा में नया स्तंभ जोड़ता है, और मौजूदा एप्लिकेशन प्रोग्राम तथा उपयोगकर्ता दृश्य बिना बदले काम करते रहते हैं। यह दर्शाता है:","optionsHi":["तार्किक डेटा स्वतंत्रता","भौतिक डेटा स्वतंत्रता","रेफ़रेंशियल इंटेग्रिटी","डेटा पुनरावृत्ति (रिडंडेंसी)"],"explanationHi":"तार्किक डेटा स्वतंत्रता बाह्य स्तर को संकल्पनात्मक (तार्किक) स्कीमा के परिवर्तनों से बचाती है। भौतिक डेटा स्वतंत्रता संग्रहण के परिवर्तनों, जैसे नए इंडेक्स, को कवर करती है।"},
  {"id":"comp-awareness-496","question":"Arrange in chronological order: 1. Delivery of UNIVAC I 2. Release of the Intel 4004 microprocessor 3. Completion of ENIAC 4. First message sent over ARPANET","options":["3, 4, 1, 2","1, 3, 4, 2","3, 1, 4, 2","3, 1, 2, 4"],"answer":2,"explanation":"ENIAC was completed in 1945, UNIVAC I delivered in 1951, the first ARPANET message sent in 1969 and the Intel 4004 released in 1971.","difficulty":"very-hard","source":"SSC CGL · SBI Clerk Mains","questionHi":"कालक्रम में व्यवस्थित कीजिए: 1. UNIVAC I की सुपुर्दगी 2. Intel 4004 माइक्रोप्रोसेसर का जारी होना 3. ENIAC का पूर्ण होना 4. ARPANET पर पहला संदेश भेजा जाना","optionsHi":["3, 4, 1, 2","1, 3, 4, 2","3, 1, 4, 2","3, 1, 2, 4"],"explanationHi":"ENIAC 1945 में पूर्ण हुआ, UNIVAC I की सुपुर्दगी 1951 में हुई, ARPANET पर पहला संदेश 1969 में भेजा गया और Intel 4004 1971 में जारी हुआ।"},
  {"id":"comp-awareness-497","question":"Asha sends an e-mail from her laptop's mail client; Ravi, on another provider, reads it on his phone and keeps it synced on the server. Which protocols carry it at each step?","options":["SMTP to her server, SMTP between the servers, IMAP to Ravi's phone","SMTP to her server, IMAP between the servers, POP3 to Ravi's phone","IMAP to her server, SMTP between the servers, SMTP to Ravi's phone","HTTP to her server, POP3 between the servers, IMAP to Ravi's phone"],"answer":0,"explanation":"SMTP pushes mail from client to server and from server to server; the recipient fetches it with IMAP (synced) or POP3. IMAP and POP3 never move mail between servers.","difficulty":"very-hard","source":"SBI Clerk Mains · IBPS SO IT Officer","questionHi":"आशा अपने लैपटॉप के मेल क्लाइंट से ई-मेल भेजती है; दूसरे प्रदाता पर रवि उसे अपने फ़ोन पर पढ़ता है और सर्वर पर सिंक रखता है। प्रत्येक चरण पर कौन-से प्रोटोकॉल इसे ले जाते हैं?","optionsHi":["उसके सर्वर तक SMTP, सर्वरों के बीच SMTP, रवि के फ़ोन तक IMAP","उसके सर्वर तक SMTP, सर्वरों के बीच IMAP, रवि के फ़ोन तक POP3","उसके सर्वर तक IMAP, सर्वरों के बीच SMTP, रवि के फ़ोन तक SMTP","उसके सर्वर तक HTTP, सर्वरों के बीच POP3, रवि के फ़ोन तक IMAP"],"explanationHi":"SMTP मेल को क्लाइंट से सर्वर और सर्वर से सर्वर तक पहुँचाता है; प्राप्तकर्ता उसे IMAP (सिंक के साथ) या POP3 से लाता है। IMAP और POP3 सर्वरों के बीच कभी मेल नहीं ले जाते।"},
  {"id":"comp-awareness-498","question":"A recursive DNS resolver has nothing cached and must find the IP address of www.example.in. In which order does it query the servers?","options":["Authoritative server for example.in, then .in TLD server, then root server","Root server, then authoritative server for example.in, then .in TLD server","The .in TLD server, then root server, then authoritative server for example.in","Root server, then .in TLD server, then authoritative server for example.in"],"answer":3,"explanation":"The root points to the .in TLD servers, which point to example.in's authoritative server, which gives the final address; each step narrows the name from the right.","difficulty":"very-hard","source":"IBPS SO IT Officer","questionHi":"एक रिकर्सिव DNS रिज़ॉल्वर के पास कुछ कैश नहीं है और उसे www.example.in का IP पता खोजना है। वह सर्वरों से किस क्रम में क्वेरी करता है?","optionsHi":["example.in का ऑथोरिटेटिव सर्वर, फिर .in TLD सर्वर, फिर रूट सर्वर","रूट सर्वर, फिर example.in का ऑथोरिटेटिव सर्वर, फिर .in TLD सर्वर","पहले .in TLD सर्वर, फिर रूट सर्वर, फिर example.in का ऑथोरिटेटिव सर्वर","रूट सर्वर, फिर .in TLD सर्वर, फिर example.in का ऑथोरिटेटिव सर्वर"],"explanationHi":"रूट .in TLD सर्वरों की ओर संकेत करता है, जो example.in के ऑथोरिटेटिव सर्वर की ओर संकेत करते हैं, जो अंतिम पता देता है; प्रत्येक चरण नाम को दाईं ओर से संकुचित करता है।"},
  {"id":"comp-awareness-499","question":"How many of these statements are correct? I. Cache memory is faster than CPU registers. II. SRAM stores each bit in a flip-flop. III. EEPROM can be erased electrically. IV. Virtual memory adds to the physical RAM installed.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and III are true. Registers are faster than cache (I is false), and virtual memory uses disk to extend the address space without adding physical RAM (IV is false).","difficulty":"very-hard","source":"SBI Clerk Mains · IBPS PO Mains","questionHi":"इनमें से कितने कथन सही हैं? I. कैश मेमोरी CPU रजिस्टरों से तेज़ होती है। II. SRAM प्रत्येक बिट को फ़्लिप-फ़्लॉप में संग्रहीत करती है। III. EEPROM को विद्युत से मिटाया जा सकता है। IV. वर्चुअल मेमोरी इंस्टॉल की गई भौतिक RAM में वृद्धि करती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II और III सही हैं। रजिस्टर कैश से तेज़ होते हैं (I गलत है), और वर्चुअल मेमोरी भौतिक RAM जोड़े बिना डिस्क से एड्रेस स्पेस बढ़ाती है (IV गलत है)।"},
  {"id":"comp-awareness-500","question":"What is (101101)₂ ÷ (101)₂, written in binary?","options":["1011","1101","1001","111"],"answer":2,"explanation":"101101 = 45 and 101 = 5; 45 ÷ 5 = 9 = (1001)₂, with no remainder.","difficulty":"very-hard","source":"SSC CGL · IBPS SO IT Officer","questionHi":"(101101)₂ ÷ (101)₂ का मान बाइनरी में क्या है?","optionsHi":["1011","1101","1001","111"],"explanationHi":"101101 = 45 और 101 = 5; 45 ÷ 5 = 9 = (1001)₂, कोई शेषफल नहीं।"},
];

export default questions;
